"""The AuraBridge suite zoo: seven kinds of real-world page shapes.

S1 nesting/scope   - repeated structures inside repeated structures (within=…)
S2 containers      - shadow DOM, 900-element pages, 3-level frames, virtual list
S3 dynamic         - re-render loops, late content, transient toasts, skeletons
S4 flows           - wizards, search->list->detail, row actions + pagination, late validation
S5 widgets         - ARIA combobox, div-select, hover menu, drag sort
S6 dialogs         - native, portal modal (backdrop + scroll lock), nested confirm,
                     drawer, shadow modal, iframe modal, overlay covering a button
S7 anti-detection  - trusted-only handlers, honeypot, webdriver fingerprint readout

Run:  python tests/serve_suites.py 8790
"""
from __future__ import annotations

import json
import sys
import time
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import urlparse, parse_qs

CSS = """
<style>
 body{font-family:system-ui;margin:16px;max-width:900px}
 .card{border:1px solid #999;padding:10px;margin:8px 0;border-radius:8px}
 .card .card{background:#f6f6f6}
 .row{display:flex;gap:8px;padding:4px 0;border-bottom:1px solid #eee}
 .backdrop{position:fixed;inset:0;background:rgba(0,0,0,.45)}
 .modal{position:fixed;left:50%;top:14%;transform:translateX(-50%);background:#fff;padding:16px;border-radius:10px;min-width:280px;box-shadow:0 10px 40px rgba(0,0,0,.3)}
 .drawer{position:fixed;right:0;top:0;bottom:0;width:260px;background:#fff;box-shadow:-10px 0 30px rgba(0,0,0,.25);padding:16px}
 .toast{position:fixed;left:50%;bottom:24px;transform:translateX(-50%);background:#222;color:#fff;padding:8px 14px;border-radius:6px}
 .listbox{position:absolute;background:#fff;border:1px solid #888;box-shadow:0 4px 16px rgba(0,0,0,.2)}
 .skeleton{background:linear-gradient(90deg,#eee,#ddd,#eee);height:16px;margin:6px 0;border-radius:4px}
 .honeypot{position:absolute;left:-9999px;top:-9999px}
