def s23_record() -> bytes:
    """Every click here is one recorded step, and every step must keep its picture.

    WHY THIS PAGE EXISTS (round R1, the "screenshots without a limit" surface). The zoo could
    already record a flow (`s18_tree`), but no fixture let a suite drive steps BACK TO BACK as fast
    as the bridge can take them, which is the only way the per-second limit of
    `chrome.tabs.captureVisibleTab` is felt at all: at human speed every step's first attempt lands
    in a fresh window, so a lane that drops a frame for a rate limit looks exactly like a lane that
    keeps it. A human opening this page sees six numbered controls and this note.

    THE CYAN MARKER IS THE PICTURE'S OWN TESTIMONY. It sits at a fixed place in the viewport
    (see `S23_BAND_CSS` below), so a suite can decode a delivered PNG and count the cyan pixels: a
    blank, foreign or placeholder frame has none of it. The buttons are red on purpose - that is what
    `red_ink` measures on other pages - so the marker is a colour nothing else on this page uses.

    THE BAND IS FURNITURE, NOT A CONTROL (measured 2026-09-22, R1's first real run): it used to sit
    at `left:4vw;top:30vh;width:34vw;height:22vh`, and that box covers the click point of the SIXTH
    control - so the last recorded step was refused with 「目标被弹窗/遮罩挡住了」, the page never saw
    the click, and the suite read that as a broken recorder. The same box also overlapped the last
    two buttons, so a person opening the page saw the marker sitting on top of the controls it asks
    them to click. It now lies across the bottom of the viewport (below every control) and carries
    `pointer-events:none`: a marker overlaid on a page must never be a hit target, whatever the
    page's layout does later.
    """
    return page("S23 连续录制", """
<h1>S23 · 连续录制：六步，一张图都不能少</h1>
<p>快速点下面这几下（这一步是录制的 1..6），然后看交付文件夹里是不是 6 张图、
每张图都能说出是哪条车道拍的。</p>
<button id="a" data-testid="s23-a">1 · 点我</button>
<input id="t" data-testid="s23-t" aria-label="第 2 步：在这里打字" placeholder="第 2 步：在这里打字">
<div id="scroller" style="height:320px;overflow:auto;border:1px solid #999">
  <div style="height:1200px">第 3 步：滚动这里（页面自己会记一笔）</div>
</div>
<button id="h" data-testid="s23-h">5 · 把鼠标移上来</button>
<button id="b" data-testid="s23-b">6 · 再点一次</button>
<pre id="log">idle</pre>
<div id="band" style="position:fixed;left:0;right:0;bottom:0;height:14vh;background:#00d5ff;pointer-events:none"></div>
<script>
window.__s23 = 0;
function note(line) { window.__s23 += 1; document.getElementById('log').textContent = line + ' / 第 ' + window.__s23 + ' 次'; }
document.getElementById('a').addEventListener('click', () => note('click'));
var s = document.getElementById('scroller');
s.addEventListener('scroll', () => note('scroll'));
document.getElementById('h').addEventListener('mouseover', () => note('hover'));
document.getElementById('b').addEventListener('click', () => note('click2'));
document.addEventListener('keydown', (e) => { if (e.key === 'End') note('keydown'); });
document.getElementById('t').addEventListener('input', () => note('typed'));
</script>""")


#: The cyan marker's box, in viewport units, and how the two tab pages are told apart.
#: Bottom strip of the viewport: below h1/p/#scroller/the buttons/#log, so it can never cover a
#: control's centre (a covered centre is a refused click - see s23_record's docstring).
S23_BAND_CSS = "left:0;right:0;bottom:0;height:14vh"
S23_TAB_COLOURS = {"/s24/alpha": "alpha-blue", "/s24/beta": "beta-red"}


def s24_tab(path: str) -> bytes:
    """One window, two tabs, ONE marker colour each - whose pixels did the shutter catch?

    WHY THIS PAGE EXISTS (round R1, the P2-2 surface): `chrome.tabs.captureVisibleTab`
    photographs the ACTIVE tab of a WINDOW, not the tab the command addressed, so a step can carry
    another tab's pixels while its receipt names the right tab and `error: null`. Nothing in the
    zoo could catch that, because every fixture page looks different in ways a PNG cannot be
    interrogated for.

    `path` is `/s24/alpha` or `/s24/beta` (see `S24_TAB_COLOURS`): each page paints its own colour
    over most of the viewport and says its own name in the heading, so a decoded screenshot proves
    WHICH page it is a picture of. A human opening either page sees which one it is immediately.
    """
    if path == "/s24/alpha":
        name, colour, bg = "alpha", "#0a46e4", "alpha-blue"
    elif path == "/s24/beta":
        name, colour, bg = "beta", "#ff2d2d", "beta-red"
    else:
        raise ValueError(f"s24_tab: unknown page {path!r} (want /s24/alpha or /s24/beta)")
    return page(f"S24 {name}", f"""
<h1>S24 · 标签页 {name}：这张图必须只可能是这一页</h1>
<p>这一页整片刷成 <b>{colour}</b>（<code>{name}</code>）。另一页是另一种颜色，
所以「拍到的到底是谁的像素」这件事，可以靠数颜色来回答。</p>
<div id="paint" style="width:72vw;height:62vh;background:{colour}"></div>
<pre id="log">page={name} colour={colour} marker={bg}</pre>
<script>window.__s24 = {bg!r};</script>""")


