def page(title: str, body: str, head: str = "") -> bytes:
    """A fixture page. `head` is for the rare page that must say something in <head> - today only the
    strict-CSP fixture, whose meta tag has to be parsed BEFORE its scripts (a meta CSP applies from
    the point it appears, so a tag after the script would leave that script covered by nothing).
    """
    return (f"<!doctype html><html><head><meta charset='utf-8'><title>{title}</title>{head}{CSS}</head>"
            f"<body>{body}</body></html>").encode("utf-8")


