class QuietServer(ThreadingHTTPServer):
    """A fixture server that does not shout about the browser's own aborted connections.

    WHY (runtime audit, 2026-09-18): navigating away from a fixture page aborts the in-flight
    request, and `socketserver` answers every abort with a full traceback -
    `ConnectionResetError: [WinError 10054]` lines sprayed through the middle of a zoo run whose
    scoreboard is the actual evidence (and they pushed the interesting lines off the screen). A
    dropped connection to a throwaway fixture server is not news; everything else still gets
    reported, unchanged.
    """

    def handle_error(self, request, client_address):
        exc = sys.exc_info()[1]
        if isinstance(exc, (ConnectionResetError, ConnectionAbortedError, BrokenPipeError)):
            return
        super().handle_error(request, client_address)


