"""R3 靶场（s29/s30/s31）的**仪器自检**：把 Probe 跑在一个假桥上，看断言是不是接在该接的字段上。

WHY THIS FILE EXISTS（本会话不许跑浏览器）：
    R3 的三组靶场只有真浏览器能给出判定，但「Python 控制流有没有写错」「断言读的是不是那个字段」
    这两件事不需要浏览器。这里用一份显式的页面模型当桥：页面模型说什么，回执就说什么。

WHAT IT PROVES, AND WHAT IT DOES NOT：
    ✅ 证明：断言连着它自己声称的那个字段（改页面模型 → 那一条必须红）；
    ❌ 不证明：产品对错。这里的「产品」是这个文件的 stub。

    python audit/tmp/p_r3_selfrun.py honest      # 诚实的 stub：三组应当全绿
    python audit/tmp/p_r3_selfrun.py refappend   # 注入 s29 的那个缺陷：ref 车道把旧值+新值拼起来
    python audit/tmp/p_r3_selfrun.py errpage     # 注入「ok:true + 一张错误页」
    python audit/tmp/p_r3_selfrun.py bucket      # 注入「合法重复调用被记成迟到结果」
    python audit/tmp/p_r3_selfrun.py doublefire  # 注入「一次调用点两下」
    python audit/tmp/p_r3_selfrun.py ghostwrite  # 注入「失败的写其实留下了痕迹」
    python audit/tmp/p_r3_selfrun.py nosnap      # 注入「aura_snapshot 回了 ok:true 但没有元素清单」
    python audit/tmp/p_r3_selfrun.py stale       # 注入「快照一直是导航前那一页的」（ref 永远取不到）
    python audit/tmp/p_r3_selfrun.py stale_once  # 注入「只有紧跟在导航后那一份快照是旧的」（有界重读该救回来）
    python audit/tmp/p_r3_selfrun.py no_status   # 注入「守护进程 /v1/status 读不到」（计数没有判据）
    python audit/tmp/p_r3_selfrun.py hang_reach  # 真实浏览器在「挂住不回」上的样子：地址停在旧页，
                                                # 但它**真的连了**那个坏端点（F3 要的证据就在套接字上）
    python audit/tmp/p_r3_selfrun.py hang_noreach  # 桥根本没去碰那个端点（回执却说成功）：先证仪器必须红
    python audit/tmp/p_r3_selfrun.py notestid    # 夹具不再写 data-testid（名字回退到 innerText）：
                                                # 「按快照真名认元素」那一条必须红
"""
from __future__ import annotations

import socket
import sys
import threading
import time
from pathlib import Path

REPO = Path(__file__).resolve().parents[2]
sys.path.insert(0, str(REPO))
sys.path.insert(0, str(REPO / "tests"))

import suite_probe  # noqa: E402

MODE = sys.argv[1] if len(sys.argv) > 1 else "honest"

PAGE = {"trap": "s26-未改", "tags": 0, "typed": 0, "removed": 0}
STATE = {"tab": 7, "late": 0, "dup": 0, "late_ok": 0, "seen_status": 0, "clicks": 0,
         "url": "http://127.0.0.1:9/s26/rollback"}

#: 忠实一点（单 S 的 F1）：快照的命名链是 aria-label → … → data-testid → … → innerText 兜底
#: （`extension/background.js:4728-4732`），而夹具那两颗按钮带了 data-testid ⇒ 快照里叫
#: `s26-tag` / `s26-kill`，**行里没有「对照组」「立刻撤掉靶子」**。#trap 有 aria-label ⇒ s26-trap。
SNAP = ('@e2 textbox "s26-trap"\n'
        '@e3 button "s26-tag"\n'
        '@e4 button "s26-kill"\n'
        '@e5 textbox "s26-keep"')
#: notestid：夹具不再写 data-testid 时的样子（名字回退到 innerText），用来验证「按快照真名认元素」
#: 那一条先证仪器真的会红。
NO_TESTID_SNAP = ('@e2 textbox "s26-trap"\n'
                  '@e3 button "对照组：点我（成功动作必须留下痕迹）"\n'
                  '@e4 button "立刻撤掉靶子"\n'
                  '@e5 textbox "s26-keep"')
#: 导航前那一页的元素清单（只有标题行 —— 那颗按钮当然找不到）。
STALE_SNAP = '@e1 heading "S26 · 写动作失败撤回"'
#: stale_once：下一份快照是不是还该是旧的（每次导航之后置 1，由 snapshot 消费掉）。
WANT_STALE = [1]
REF_KIND = {"e2": "trap", "e3": "tag", "e4": "kill", "e5": "keep"}


def mirror() -> str:
    return (f"s26-mirror trap={PAGE['trap']} keep=s26-锚点 typed={PAGE['typed']} focused=0 "
            f"removed={PAGE['removed']} tags={PAGE['tags']} notes=0 armed=0 dpr=1 focus=body ls=s26-ls")


def no_working_tab():
    """忠实一点：真扩展在没有工作标签页时是 `requireAgentTab` 抛错，不是照点不误。"""
    return {"ok": False, "error": "no working tab yet for caller agent - call aura_navigate first, "
                                  "or pass tab_id from aura_tabs", "next": "先 aura_navigate 打开目标站点"}


def post(action: str, **args):
    r = args.pop("_args", None) or args
    if action == "aura_status":
        # 忠实一点（单 S 的 F2）：`aura_status` 是**扩展**的回执，守护进程只往里加 capabilities；
        # duplicate_results / late_results / late_results_ok 是守护进程自己的计数，只出现在
        # `/v1/status` 上。所以这里**不**报它们 —— 一个把它们放进动作回执的假桥，会让
        # 「套件读错了路径」在自检里永远绿。
        out = {"access": "readwrite", "agentTab": STATE["tab"],
               "agentTabUrl": "" if STATE["tab"] is None else STATE["url"],
               "lane": ("dom (no debug banner)" if MODE == "lostinput_dom"
                        else "cdp (trusted input)")}
        if MODE == "no_status":
            # no_status 模式：动作回执里**有**这三个数字（一个把进程计数错放进扩展回执的桥就是这么
            # 回事），而守护进程 /v1/status 读不到 —— 套件必须报「读不到」，而不是把动作回执当账本。
            out.update({"duplicate_results": STATE["dup"], "late_results": STATE["late"],
                        "late_results_ok": STATE["late_ok"]})
        return {"ok": True, "result": out}
    if action == "aura_console":
        return {"ok": True, "result": {"errors": []}}
    if action == "aura_snapshot":
        if MODE == "nosnap":
            # 注入：envelope 说成功，而元素清单是空的（R5 实测的 s29 症状就是这一种：
            # ref='' 行='' —— 而它同时可能是「读不到元素」也可能是「没有这颗按钮」）。
            return {"ok": True, "result": {"elements": ""}}
        if MODE == "stale":
            # 注入：快照永远是导航前那一页的（持续故障：有界重读不该把它藏起来）。
            return {"ok": True, "result": {"elements": STALE_SNAP}}
        if MODE == "notestid":
            # 注入：夹具不写 data-testid 了（命名链回退到 innerText）—— 「按快照真名认元素」那一条
            # 必须红，而靠文案那个兜底 needle 让 ref 还能取到（所以红的是「仪器前提」而不是两条都红）。
            return {"ok": True, "result": {"elements": NO_TESTID_SNAP}}
        if MODE == "stale_once":
            _snap = STALE_SNAP if WANT_STALE[0] else SNAP
            print(f"      [harness] snapshot: WANT_STALE={WANT_STALE[0]} -> "
                  f"{_snap.splitlines()[0][:60]!r}", flush=True)
            sys.stderr.write(f"STUB staleness={WANT_STALE[0]}\n")
        if MODE == "stale_once" and WANT_STALE[0]:
            # 注入：只有紧跟在导航之后的那一份是旧的（仪器时序，不是产品缺陷）。
            WANT_STALE[0] = 0
            return {"ok": True, "result": {"elements": STALE_SNAP}}
        return {"ok": True, "result": {"elements": SNAP}}
    if action == "aura_read":
        return {"ok": True, "result": {"text": "S26 · 写动作失败撤回 现场 …\n" + mirror()}}
    if action == "aura_tabs":
        return {"ok": True, "result": {"tabs": [{"id": STATE["tab"] or 7, "url": STATE["url"],
                                                 "active": True}]}}
    if action == "aura_navigate":
        url = str(r.get("url") or "")
        if "/hang" in url and MODE in ("hang_reach", "hang_noreach"):
            # 真实浏览器在这里的样子（R5 实测）：回执说 ok:true，而**浏览器自己说的地址还是导航前
            # 那一页**（settle 满足在旧文档上）—— 但它是**真的连过**那个端点的。所以「这一次真的
            # 去碰了」只能由套接字说；这个模式就是那一条证据的反例模型。
            port = int(url.split(":")[2].split("/")[0])

            def reach() -> None:
                try:
                    c = socket.create_connection(("127.0.0.1", port), timeout=3)
                    c.sendall(b"GET /hang HTTP/1.1\r\nHost: 127.0.0.1\r\n\r\n")
                    time.sleep(2.0)          # 对端一个字都不回：连接就挂在那里
                    c.close()
                except OSError:
                    pass

            if MODE == "hang_reach":
                threading.Thread(target=reach, daemon=True).start()
            # hang_noreach：桥根本没去碰那个端点（回执却说成功、地址还是旧页）—— 「先证仪器」
            # 那一条必须在这里红。这就是「套件没测到」与「产品没去」必须被分开的那个样子。
            return {"ok": True, "result": {"tab": {"id": 7, "url": STATE["url"]},
                                           "settle": {"met": True, "waited_ms": 63, "polls": 2},
                                           "text": "S26 · 写动作失败撤回"}}
        if "/refused" in url or "/cut" in url or "/hang" in url:
            if MODE == "errpage":
                STATE["url"] = url
                return {"ok": True, "result": {"tab": {"id": 7, "url": url},
                                               "settle": {"met": True, "waited_ms": 20}}}
            if MODE == "allowlist":
                return {"ok": False, "error": f"host {url.split('/')[2]} is not on the allowlist",
                        "result": {"refused": action, "reason": "allowlist"}}
            return {"ok": False, "infra": True,
                    "error": f"navigation landed on a non-scriptable page: "
                             f"chrome-error://chromewebdata/ ({url})",
                    "next": "换一个普通 http(s) 地址再导航",
                    "result": {"refused": action, "reason": "not_scriptable"}}
        STATE["url"] = url
        WANT_STALE[0] = 1
        PAGE.update({"trap": "s26-未改", "tags": 0, "typed": 0, "removed": 0})
        return {"ok": True, "result": {"tab": {"id": 7, "url": url},
                                       "settle": {"met": True, "waited_ms": 30},
                                       "text": "S26 · 写动作失败撤回"}}
    if action == "aura_type":
        if STATE["tab"] is None:
            return no_working_tab()
        text = str(r.get("text") or "")
        if r.get("ref"):
            if MODE in ("lostinput", "lostinput_dom"):
                return {"ok": False, "error": "真实输入没有到达页面（事件探针 0 命中）",
                        "next": "把浏览器窗口露到前台再重试",
                        "result": {"via": "cdp-type", "ref": str(r["ref"]).lstrip("@"),
                                   "input_delivered": False}}
            PAGE["trap"] = (PAGE["trap"] + text) if MODE == "refappend" else text
            PAGE["typed"] += 1
            return {"ok": True, "result": {"via": "cdp-type", "ref": str(r["ref"]).lstrip("@"),
                                           "chars": len(text), "input_delivered": True}}
        PAGE["trap"] = text
        PAGE["typed"] += 1
        return {"ok": True, "result": {"via": "cdp", "matched": "s26-trap", "chars": len(text),
                                       "input_delivered": True}}
    if action == "aura_set":
        if STATE["tab"] is None:
            return no_working_tab()
        PAGE["trap"] = str(r.get("value") or "")
        return {"ok": True, "result": {"via": "dom", "value": PAGE["trap"], "tag": "input"}}
    if action == "aura_click":
        if STATE["tab"] is None:
            return no_working_tab()
        if r.get("ref"):
            kind = REF_KIND.get(str(r["ref"]).lstrip("@"), "?")
            if kind == "tag":
                PAGE["tags"] += 2 if MODE == "doublefire" else 1
            elif kind == "kill":
                PAGE["removed"] = 1
            return {"ok": True, "result": {"via": "cdp", "input_delivered": True, "ref": str(r["ref"])}}
        target = str(r.get("target") or "")
        if "不存在" in target:
            if MODE == "ghostwrite":
                PAGE["tags"] += 1
            return {"ok": False, "error": f"没有匹配「{target}」的元素", "next": "aura_find 看一下"}
        PAGE["tags"] += 2 if MODE == "doublefire" else 1
        return {"ok": True, "result": {"via": "cdp", "input_delivered": True}}
    if action == "aura_tab_new":
        STATE["tab"] = 8
        return {"ok": True, "result": {"tab": {"id": 8, "url": str(r.get("url") or "")}}}
    if action == "aura_tab_close":
        closed = STATE["tab"]
        STATE["tab"] = None
        return {"ok": True, "result": {"closed": closed}}
    return {"ok": True, "result": {}}


def daemon_status() -> dict:
    """假桥的 `/v1/status`：守护进程自己那份状态（三个计数桶 + 迟到动作清单）。

    `no_status` 模式让它读不到 —— 那一条也必须红：一个自检必须证明「读不到计数」不会
    被当成「计数没动」。
    """
    if MODE == "no_status":
        return {"error": "ConnectionRefusedError: [WinError 10061] 目标计算机积极拒绝"}
    return {"duplicate_results": STATE["dup"], "late_results": STATE["late"],
            "late_results_ok": STATE["late_ok"], "late_result_actions": []}


def main() -> int:
    def counted(action: str, **args):
        out = post(action, **args)
        if action == "aura_status":
            STATE["seen_status"] += 1
        if action == "aura_click":
            # 注入（bucket）：s30 那一串里的第二次点击被记成「迟到结果」。真守护进程的计数是**命令
            # 跑完**才写进 status() 的，所以这里必须错开一步 —— 基线那一次读之前不计，之后才计。
            STATE["clicks"] += 1
            if MODE == "bucket" and STATE["clicks"] > 1:
                STATE["late"] += 1
        return out



    probe = suite_probe.Probe(post=counted, base="http://127.0.0.1:9",
                              power=(MODE != "lostinput_dom"), status_call=daemon_status)
    passed, failed, skipped = probe.run(["s29", "s30", "s31"])
    print()
    print(f"=== MODE={MODE}: {passed} PASS / {len(failed)} FAIL / {len(skipped)} SKIP ===")
    for f in failed:
        print(f"  - {f}")
    return 0


if __name__ == "__main__":

