"""The rule the total guard (selftest_anchors) will enforce, applied to every anchor today.

RULE: a literal anchor that is written as one or more COMPLETE source lines - i.e. its text is
byte-identical to a run of whole lines of some .py/.js file in the repository - makes the mutation's
ability to land depend on the WHOLE SPELLING of that line. It must be located by content
(`line_with`) instead, or declared in ANCHOR_LINES_THAT_ARE_THE_CONTRACT with a reason.

File-agnostic on purpose: the guard must classify an anchor without knowing which file the section
read, because half the sections read a STAGED copy (so the path expression names a scratch dir).
Matching whole lines including indentation is what makes it precise - an anchor written without its
indentation is a line FRAGMENT and survives a rewrite that keeps the fragment.

Excluded by the rule, and why: `out`/`real`/`ready_body` are guard OUTPUT, not source; and .md
files are what the docs SAY (the mutation changes those words, which is the point of the check).
"""
from __future__ import annotations

import ast
import pathlib
import sys

REPO = pathlib.Path(__file__).resolve().parent.parent.parent
GS = REPO / "tests" / "guard_selftest.py"
SKIP_PARTS = {".git", "node_modules", "audit", "__pycache__", ".venv", "dist"}
NON_SOURCE = {"out", "real", "ready_body", "guide", "docs"}      # output, or prose


def literal_of(node):
    if isinstance(node, ast.Constant) and isinstance(node.value, str):
        return node.value
    if isinstance(node, ast.BinOp) and isinstance(node.op, ast.Add):
        left, right = literal_of(node.left), literal_of(node.right)
        if left is not None and right is not None:
            return left + right
    return None


class Finder(ast.NodeVisitor):
    def __init__(self) -> None:
        self.stack: list[dict] = [{}]
        self.rows: list = []

    def _scope(self, node):
        self.stack.append({})
        for stmt in node.body:
            self.visit(stmt)
        self.stack.pop()

    visit_FunctionDef = _scope          # noqa: N815
    visit_AsyncFunctionDef = _scope     # noqa: N815

    def visit_Assign(self, node):  # noqa: N802
        text = literal_of(node.value)
        if text is not None:
            for t in node.targets:
                if isinstance(t, ast.Name):
                    self.stack[-1][t.id] = text
        for child in ast.iter_child_nodes(node):
            self.visit(child)

    def _record(self, holder, left, right, kind):
        text = how = None
        if isinstance(left, ast.Constant) and isinstance(left.value, str):
            text, how = left.value, "inline"
        elif isinstance(left, ast.Name) and left.id in self.stack[-1]:
            text, how = self.stack[-1][left.id], "via " + left.id
        if text is not None and isinstance(right, ast.Name) and right.id not in NON_SOURCE:
            self.rows.append((holder.lineno, kind, how, right.id, text))

    def visit_Assert(self, node):  # noqa: N802
        t = node.test
        if isinstance(t, ast.Compare) and len(t.ops) == 1 and isinstance(t.ops[0], ast.In):
            self._record(node, t.left, t.comparators[0], "assert")
        for child in ast.iter_child_nodes(node):
            self.visit(child)

    def visit_Call(self, node):  # noqa: N802
        if isinstance(node.func, ast.Name) and node.func.id == "check" and node.args:
            t = node.args[0]
            if isinstance(t, ast.Compare) and len(t.ops) == 1 and isinstance(t.ops[0], ast.In):
                self._record(node, t.left, t.comparators[0], "check")
        for child in ast.iter_child_nodes(node):
            self.visit(child)


def source_lines() -> dict:
    out = {}
    for p in sorted(REPO.rglob("*")):
        if not p.is_file() or p.suffix not in {".py", ".js"}:
            continue
        if any(part in SKIP_PARTS for part in p.parts):
            continue
        try:
            lines = p.read_text(encoding="utf-8").splitlines()
        except (OSError, UnicodeDecodeError):
            continue
        for ln in lines:
            out.setdefault(ln, []).append(str(p.relative_to(REPO)).replace("\\", "/"))
    return out


class Table(ast.NodeVisitor):
    """Second walker: the same anchors, but keeping the SECTION SPAN so the target file resolves."""

    def __init__(self) -> None:
        self.fn = ""
        self.span = (1, 1)
        self.rows: list = []

    def visit_FunctionDef(self, node):  # noqa: N802
        outer, self.fn = self.fn, (self.fn or node.name)
        if not outer:
            self.span = (node.lineno, node.end_lineno)
        for stmt in node.body:
            self.visit(stmt)
        self.fn = outer

    visit_AsyncFunctionDef = visit_FunctionDef  # noqa: N815

    def visit_Call(self, node):  # noqa: N802
        self.rows.append({"line": node.lineno, "section": self.fn, "span": self.span})
        for child in ast.iter_child_nodes(node):
            self.visit(child)

    visit_Assert = visit_Call  # noqa: N815


def target_of(span: tuple, var: str, lines: list[str]) -> str:
    """The file a section read into `var` - the same scan the total guard will use."""
    import re

    for ln in lines[span[0] - 1:span[1]]:
        m = re.match(rf'\s*{var}\s*=\s*\(?REPO\s*/\s*(.+?)\)?\.read_text\(', ln)
        if m:
            return "/".join(re.findall(r'"([^"]+)"', m.group(1)))
    return ""


def main() -> int:
    src_text = GS.read_text(encoding="utf-8")
    lines = src_text.splitlines()
    walk = Table()
    walk.visit(ast.parse(src_text))
    spans = {r["line"]: (r["section"], r["span"]) for r in walk.rows}
    f = Finder()
    f.visit(ast.parse(src_text))
    corpus = source_lines()
    per_file = {}
    for p in sorted(REPO.rglob("*")):
        if p.is_file() and p.suffix in {".py", ".js"} and not any(x in SKIP_PARTS for x in p.parts):
            try:
                per_file[str(p.relative_to(REPO)).replace("\\", "/")] = \
                    p.read_text(encoding="utf-8").splitlines()
            except (OSError, UnicodeDecodeError):
