  const entries = isDir(tmpDir) ? fs.readdirSync(tmpDir).sort(byName) : []
  if (entries.length) errs.push(`state/tmp 非空(${entries.length} 项: ${entries.slice(0, 5).join(', ')})`)
  let untracked
