const out = execFileSync('git', ['status', '--porcelain', '--untracked-files=all'], { cwd: root, encoding: 'ut
    untracked = out.split(/\r?\n/).filter((l) => l.startsWith('?? ')).map((l) => l.slice(3).trim().replace(/^"(.*)"$/, '$1'))
  } catch (e) {
    return { ok: false, errs: errs.concat([`git status 不可用,清场无法实测: ${errLine(e)}`]), untracked: -1 }
  }
