// ---------- 1. 编码 ----------
const bom = files.filter((f) => readBuf(f).subarray(0, 3).equals(Buffer.from([0xef, 0xbb, 0xbf])))
add('ENC-1 BOM', bom.length === 0, bom.length ? `带 BOM: ${bom.join(', ')}` : '无 BOM')

const badUtf8 = files.filter((f) => {
  const buf = readBuf(f)
  return !Buffer.from(buf.toString('utf8'), 'utf8').equals(buf)
})
add('ENC-2 UTF-8 往返', badUtf8.length === 0, badUtf8.length ? `非法 UTF-8: ${badUtf8.join(', ')}` : `${files.length} 文件全部为合法 UTF-8`)

const crlf = files.filter((f) => read(f).includes('\r\n'))
add('ENC-3 行尾 LF', crlf.length === 0, crlf.length ? `含 CRLF: ${crlf.join(', ')}` : '全部 LF')

const invisible = []
for (const f of files) {
  const t = read(f)
  for (let i = 0; i < t.length; i++) {
    const c = t.codePointAt(i)
    const isCtl = c < 0x20 && c !== 0x09 && c !== 0x0a
    const isSuspicious = c === 0x00a0 || c === 0x200b || c === 0xfeff || c === 0x2028 || c === 0x2029
    if (isCtl || isSuspicious) { invisible.push(`${f}@${i}:U+${c.toString(16).toUpperCase().padStart(4, '0')}`); break }
  }
}
add('ENC-4 无隐藏字符', invisible.length === 0, invisible.length ? invisible.join(', ') : '无控制字符/NBSP/零宽字符')

// ---- 引用解析（@limits.<path> 与 @{file.path}）----
const kernelJson = {}
const kernelJsonBad = []   // 预解析失败的 kernel JSON:记下原因继续,由用到它的判据行判红(MT-5)
for (const f of listFiles(K).filter((x) => x.endsWith('.json'))) {
  const name = path.basename(f, '.json')
  try { kernelJson[name] = JSON.parse(read(f)) } catch (e) { kernelJsonBad.push(`${name}: ${String(e.message).split('\n')[0]}`) }
}
