  gDecide.includes('strict_p1') ? 'strict_p1 已进判定序列,并声明 5→7→8 顺序' : '缺 strict_p1 分支')
const l3 = kernelJson.routing?.level_signals?.L3 ?? []
const routeSrc = read('tools/route.mjs')
add('REVIEW-P1a 级别信号单一来源', l3.length > 0 && routeSrc.includes('routing.level_signals'),
  `routing.level_signals.L3=${l3.length} 项; route.mjs 已改为读取内核`)
// 核心工具标准:p0..p5 全 0
const zeroKeys = ['p0', 'p1', 'p2', 'p3', 'p4', 'p5'].map((k) => `findings_max_${k}`)
const zeroOk = zeroKeys.every((k) => kernelJson.limits?.limits?.[k]?.v === 0)
add('REVIEW-ZERO p0–p5 门槛全为 0 且已进判定', zeroOk && JSON.stringify(kernelJson.policy?.gate?.strict_zero ?? {}).length > 10 && JSON.stringify(kernelJson['gate.schema'] ?? '').includes('findings_max_p'),
  zeroOk ? `limits 六项阈值均 0;policy.gate.strict_zero + gate 判定规则 11 已声明` : '阈值缺失或非 0')
