#!/usr/bin/env node
// 真实问题套件（r6）：把 177 条真实提问逐条过路由，按 p0-p5 机械分级，产出 findings。
// 目的（用户 2026-09-19 指令）：持续用真实问题测，缺陷不为 0 就继续修，直到 p0-p5 全为 0。
//   node tools/realq-suite.mjs           跑一遍，写 state/realq/findings.jsonl + 打印分级统计
//   node tools/realq-suite.mjs --json    只输出 JSON
// 只读（除 state/realq/**）。exit 0 = p0-p5 全 0；exit 12 = 有 findings。
//   node tools/realq-suite.mjs --selftest  只跑自证用例（链账绑定/链深阈值来源/编码同源）:0=全绿 / 12=有用例红
import fs from 'node:fs'
import path from 'node:path'
import { execFileSync } from 'node:child_process'

const ROOT = path.resolve(process.env.POLARIS_ROOT ?? path.join(path.dirname(new URL(import.meta.url).pathname.replace(/^\/([A-Za-z]:)/, '$1')), '..'))
const POOL = path.join(ROOT, 'tests', 'questions', 'real-2026-09-17.jsonl')
const OUT_DIR = path.join(ROOT, 'state', 'realq')
const JSON_ONLY = process.argv.includes('--json')

// 应触发形态（技能描述承诺的类型）——保守取强信号短语，避免把"怎么接入"误判成"怎么办"
const SHOULD_TRIGGER = ['为什么', '根因', '该不该', '值不值', '选哪个', '该选', '概率', '该信几成', '说明了什么', '能不能证明', '是否成立',
  '算不算', '违不违反', '两难', '借鉴', '从零', '重新设计', '取舍', '值得做吗', '有没有价值', '完备吗', '可行吗', '可以做到吗', '能做到吗', '靠谱吗']
// 信息/操作型形态（不该触发范式）
// 注意(2026-09-19 修)：初版把裸"是什么/的区别/在哪"也算信息型，结果把"是什么类型"（归纳）、
// "能力边界是什么"（规则边界）这类**分析型问法**误判成过度触发 —— 这是检查器口径错误，不是产品缺陷。
// 现按"无歧义的信息型短语"收窄；分析型形态（类型/关系/边界/取舍）单列，不作为信息型证据。
const SHOULD_NOT = ['怎么接入', '怎么配置', '如何设置', '介绍一下', '最新版', '教程', '怎么安装', '如何查看', '在哪里下载']
const ANALYSIS_FORM = ['是什么类型', '是什么关系', '能力边界', '边界是什么', '的区别', '之间的区别', '哪个更好', '哪个更适合']
// 风险信号（命中即必须 L3）——直接读内核，不另建表
const hot = JSON.parse(fs.readFileSync(path.join(ROOT, 'skills', 'aurapolaris', 'kernel', 'hot.json'), 'utf8'))
const L3_SIG = String(hot.L3 ?? '').split('|').filter(Boolean)
// 链账【唯一来源】= kernel/index.json 的 chains（数组：seq/depth/exception_reason 齐全）。
//   不消费 hot.chains:那是 kernel-pack.mjs:53 为省分发体积编的紧凑串(`id:seq.join('>')` 换行连接),
//   按 id 取值恒为 undefined —— 当映射用会让链深上限恒不生效、integrity_chain 对任何已登记链误判
//   "未登记链"(R7 syntax-1 p3)。解码紧凑串等于在消费者里再养第二份解析实现(F2 家族),且本文件本就
//   读同一份 index.json(范式/链),router(tools/route.mjs:12)也是 —— 故与权威源对齐,并把"紧凑串必须
//   与权威源一致"钉成一条可红判据(见文件末尾 selftest 的 selftest:chain-encoding)。
const kernelIndex = JSON.parse(fs.readFileSync(path.join(ROOT, 'skills', 'aurapolaris', 'kernel', 'index.json'), 'utf8'))
const CHAINS = Object.fromEntries((kernelIndex.chains ?? []).map((c) => [c.id, c]))
// 链深阈值【唯一来源】= kernel/limits.json 的 limits.max_chain_depth.v（与 tools/audit.mjs#REF-14 同一条判据的同一来源）。
//   读不到 / JSON 坏 / 形状不对 → **fail-closed 报错退出**，不退回任何内建默认值：`?? 2` 那种兜底等于在本文件里
//   再养一份口径 —— limits 那侧阈值一改（2→1），audit 报超深链而本文件照旧按 2 判，同一判据两个结论
//   （R7 logic-2 p2 的 F2 家族：同一条判据两份实现、两份口径）。
//   怎么复核：① node tools/realq-suite.mjs --selftest（selftest:chain-depth-threshold-source）；
//   ② 破坏注入（可红可绿）= 副本里把 limits.json 的 v 改小 + 把这里的读取改回写死 2 → 该用例必须红，
//   前后原始输出见 state/tasks/T-20260927113848-ddb1.result.json；③ node skills/aurapolaris/tools/diff-audit.mjs --stdin。
const LIMITS_REL = 'skills/aurapolaris/kernel/limits.json'
const LIMITS_PATH = path.join(ROOT, ...LIMITS_REL.split('/'))
// 纯函数：从 limits 文档取阈值；形状不对一律抛（不兜底）——"阈值来源坏了"与"判定照常放行"因此不可能同时发生。
function depthLimitFrom(doc, label = LIMITS_REL) {
  const v = doc?.limits?.max_chain_depth?.v
  if (typeof v !== 'number' || !Number.isFinite(v) || v < 1) {
    throw new Error(`${label} 的 limits.max_chain_depth.v=${JSON.stringify(v)} 不是 ≥1 的数`)
  }
  return v
}
// 生产读取点：文件缺失/JSON 坏/形状不对 → fail-closed 退出（exit 1 = kernel/io.json exit_codes 里的 "IO 错误"）
function loadDepthLimit() {
  let doc
  try { doc = JSON.parse(fs.readFileSync(LIMITS_PATH, 'utf8')) }
  catch (e) { console.error(`realq-suite: FAIL-CLOSED 读不到链深阈值来源 ${LIMITS_REL}: ${e.message}`); process.exit(1) }
  try { return depthLimitFrom(doc) }
  catch (e) { console.error(`realq-suite: FAIL-CLOSED ${e.message}；阈值无第二来源，拒绝用内建默认值继续`); process.exit(1) }
}
const DEPTH_LIMIT = loadDepthLimit()   // 链深上限只有一份来源：kernel/limits.json（不写死）
// 链解析:生产判定与自证共用这两行 —— 自证只把 idx/sequence 当参数传进来,不在自证里另写一份查表口径
//   也不在自证里改 CHAINS:守的就是这个绑定,改掉它自证必须变红。
const chainAt = (id) => CHAINS[id] ?? null
const chainKnown = (id) => Object.prototype.hasOwnProperty.call(CHAINS, id)
// hot.json 的紧凑串与权威源的一致性核验(返回不一致清单):同一事实两种编码形态,口径可以不同,事实只能一份
function hotChainMismatch() {
  const bad = []
  const raw = hot.chains
  if (raw === undefined) return ['hot.json 无 chains 字段']
  if (typeof raw !== 'string') return [`hot.chains 应为紧凑串,实际 ${typeof raw}`]
  const pairs = raw.split('\n').filter(Boolean).map((l) => [l.slice(0, l.indexOf(':')), l.slice(l.indexOf(':') + 1)])
  const seen = new Set(pairs.map(([id]) => id))
  for (const c of kernelIndex.chains ?? []) {
    const hit = pairs.find(([id]) => id === c.id)
    if (!hit) { bad.push(`hot.json 缺链 ${c.id}`); continue }
    if (hit[1] !== c.seq.join('>')) bad.push(`链 ${c.id} 序列不一致: hot=${hit[1]} index=${c.seq.join('>')}`)
  }
  for (const id of seen) if (!(kernelIndex.chains ?? []).some((c) => c.id === id)) bad.push(`hot.json 多出未登记链 ${id}`)
  return bad
}

const findings = []
const add = (sev, id, kind, detail, repro) => findings.push({ sev, id, kind, detail, repro })

const pool = fs.readFileSync(POOL, 'utf8').trim().split(/\r?\n/).map((l) => JSON.parse(l))
// 单题判定（纯函数形式:自证用同一份实现喂合成 route,不另写一份判据）
function judgeOne(q, r, view) {
  const idx = view?.index ?? kernelIndex
  const depthMax = view?.depthMax ?? DEPTH_LIMIT
  const at = view?.at ?? chainAt
  const known = view?.known ?? chainKnown
  const hitShould = SHOULD_TRIGGER.filter((s) => q.text.includes(s))
  const hitNot = SHOULD_NOT.filter((s) => q.text.includes(s))
  const analysisForm = ANALYSIS_FORM.filter((s) => q.text.includes(s))
  const l3 = L3_SIG.filter((s) => q.text.includes(s))

  // R6(2026-09-25):范式层按"可验证性"重裁后回来 → 判据恢复成 primary 口径;并**追加**一条级别口径
  //   (判断/分析形态不得掉回 L1):两套一起判,不是二选一。
  // p1-a 该触发却未触发（漏）
  if (hitShould.length && !r.primary) add('p1', q.id, 'route_miss', `含应触发短语 ${hitShould.slice(0, 2).join('/')} 却未路由(level=${r.level})`, `node tools/route.mjs ${JSON.stringify(q.text.slice(0, 40))}`)
  // p1-a2 判断形态掉回 L1（级别口径,2026-09-24 新增）
  if (hitShould.length && r.level === 'L1') add('p1', q.id, 'level_miss', `含应触发短语 ${hitShould.slice(0, 2).join('/')} 却判为 L1`, `node tools/route.mjs ${JSON.stringify(q.text.slice(0, 40))}`)
  // p1-b 信息型却触发（过）
  if (hitNot.length && !hitShould.length && !analysisForm.length && r.primary) add('p1', q.id, 'route_over', `信息型问法(含 ${hitNot.slice(0, 2).join('/')}) 却路由到 ${r.primary}`, `node tools/route.mjs ${JSON.stringify(q.text.slice(0, 40))}`)
  // p1-c 命中风险信号却不是 L3（task_guard 早返回会绕过 L3 判定）
  if (l3.length && r.level !== 'L3') add('p1', q.id, 'level_gap', `命中 L3 风险信号 ${l3.slice(0, 2).join('/')} 但 level=${r.level}（风险分级被绕过）`, `node tools/route.mjs ${JSON.stringify(q.text.slice(0, 40))}`)
  // p2 链深超上限且未登记例外（阈值现取 limits.json,不写死）
  if (r.chain) {
    const c = at(r.chain)
    const seq = c?.seq ?? []
    if (seq.length > depthMax && !c.exception_reason) add('p2', q.id, 'chain_depth', `链 ${r.chain} 深 ${seq.length} > ${depthMax} 且未登记 exception_reason`, `node tools/route.mjs ${JSON.stringify(q.text.slice(0, 40))}`)
  }
  // p1-d 完整性：路由结果必须在核心里可解析（范式要有 warm 行、level 要合法、链要已登记）
  if (r.primary) {
    const warmFile = path.join(ROOT, 'skills', 'aurapolaris', 'kernel', 'warm', `${r.primary}.json`)
    if (!fs.existsSync(warmFile)) add('p1', q.id, 'integrity_warm', `路由到 ${r.primary} 但缺 kernel/warm/${r.primary}.json`, `ls skills/aurapolaris/kernel/warm/${r.primary}.json`)
    if (!(idx.paradigm_ids ?? []).includes(r.primary)) add('p1', q.id, 'integrity_paradigm', `路由到未登记范式 ${r.primary}`, `node tools/route.mjs ${JSON.stringify(q.text.slice(0, 30))}`)
  }
  if (!['L1', 'L2', 'L3'].includes(r.level)) add('p1', q.id, 'integrity_level', `level=${r.level} 不是合法值`, `node tools/route.mjs ${JSON.stringify(q.text.slice(0, 30))}`)
  if (r.chain && !known(r.chain)) add('p1', q.id, 'integrity_chain', `返回未登记链 ${r.chain}`, `node tools/route.mjs ${JSON.stringify(q.text.slice(0, 30))}`)
}

for (const q of pool) {
  let r
  try {
    r = JSON.parse(execFileSync(process.execPath, [path.join(ROOT, 'tools', 'route.mjs'), q.text], { encoding: 'utf8', cwd: ROOT, env: { ...process.env, POLARIS_ROOT: ROOT } }))
  } catch (e) {
    add('p0', q.id, 'route_crash', `route.mjs 未能对真实问题返回可解析结果: ${String(e.message).slice(0, 120)}`, `node tools/route.mjs ${JSON.stringify(q.text.slice(0, 40))}`)
    continue
  }
  judgeOne(q, r)
}
// --selftest 在此之前返回:只出自证读数,不跑 177 题、也不写 state/realq/**
if (process.argv.includes('--selftest')) process.exit(selftest())

// 第二段：技能描述承诺的触发词必须真的能触发（描述→路由表一致性）
// 之前真实自测(q122/q171)就是栽在这里：描述承诺"可行/完备"类判断，但路由表没有对应信号。
const PROMISES = [
  ['该不该做这件事', 'practical'], ['这个方案值不值', 'counterfactual'], ['我该选哪个方案', 'practical'],
  ['这件事发生的概率有多大', 'bayesian'], ['这个结论该信几成', 'bayesian'], ['这些数据说明了什么规律', 'induction'],
  ['能不能证明这个命题', 'deduction'], ['这个操作是否违规', 'default-reasoning'], ['两种说法各有道理怎么调和', 'dialectical'],
  ['人家怎么做我们能不能套用', 'analogy'], ['抛开现状从零重新设计', 'first-principles'], ['帮我分析下这个取舍', 'practical'],
  ['这件事的根因是什么', 'abduction'], ['这个方案可行吗', 'practical'], ['这个内核完备吗', 'practical'],
  ['这个功能可以做到吗', 'practical'], ['这个工具靠谱吗', 'practical'], ['大概要多久能做完', 'estimation'],
  ['帮我复盘一下当初值不值', 'counterfactual'], ['对手会怎么反应', 'strategy'],
]
for (const [probe, expect] of PROMISES) {
  let r
  try { r = JSON.parse(execFileSync(process.execPath, [path.join(ROOT, 'tools', 'route.mjs'), probe], { encoding: 'utf8', cwd: ROOT, env: { ...process.env, POLARIS_ROOT: ROOT } })) }
  catch (e) { add('p0', `promise:${probe}`, 'route_crash', `描述承诺探针无法路由: ${String(e.message).slice(0, 100)}`, `node tools/route.mjs ${JSON.stringify(probe)}`); continue }
  if (r.primary !== expect) add('p1', `promise:${probe}`, 'promise_gap', `技能描述承诺的形态应路由到 ${expect},实际 ${r.primary ?? 'null'}(${r.level})`, `node tools/route.mjs ${JSON.stringify(probe)}`)
}

const bySev = {}
for (const f of findings) bySev[f.sev] = (bySev[f.sev] ?? 0) + 1
const summary = { at: new Date().toISOString(), total_questions: pool.length, findings: findings.length, by_severity: bySev }

fs.mkdirSync(OUT_DIR, { recursive: true })
fs.writeFileSync(path.join(OUT_DIR, 'findings.jsonl'), findings.map((f) => JSON.stringify(f)).join('\n') + (findings.length ? '\n' : ''))
fs.writeFileSync(path.join(OUT_DIR, 'summary.json'), JSON.stringify(summary, null, 1) + '\n')

if (JSON_ONLY) console.log(JSON.stringify(summary))
else {
  console.log(`真实问题套件: ${pool.length} 题, findings ${findings.length}`)
  for (const p of ['p0', 'p1', 'p2', 'p3', 'p4', 'p5']) console.log(`  ${p}: ${bySev[p] ?? 0}`)
  const kinds = {}
  for (const f of findings) kinds[f.kind] = (kinds[f.kind] ?? 0) + 1
  console.log('  类型分布:', Object.entries(kinds).map(([k, v]) => `${k}=${v}`).join(' ') || '(无)')
  for (const f of findings.slice(0, 12)) console.log(`  [${f.sev}] ${f.id} ${f.kind}: ${f.detail}`)
  if (findings.length > 12) console.log(`  …另有 ${findings.length - 12} 条（见 state/realq/findings.jsonl）`)
}
// ---------- 自证（--selftest）:把修好的行为钉在会失败的断言上 ----------
// 为什么必须自带:177 题里没有一题返回 r.chain（2026-09-27 实测 0 题）,链相关判据在这批语料上
//   **可达性为空** —— 只靠真实问题语料,链账绑错、链深阈值写死都会永远绿（R7 syntax-1 p3）。
// 三条链用例走生产同一份 judgeOne:只把"链账"换成一份【独立副本】,阈值一律用生产的 DEPTH_LIMIT。
function selftest() {
  const CASES = [
    { id: 'selftest:chain-registered',
      why: '已登记链 diagnose-cause-act（index.json 里 seq 齐全）必须认作已登记、seq 可解析,不得报未登记链/链深错',
      route: { primary: 'abduction', level: 'L2', chain: 'diagnose-cause-act' },
      want: { kinds: [], p0: 0, p1: 0, p2: 0 } },
    { id: 'selftest:chain-depth-over',
      why: `深度 3 的链未登记 exception_reason → 必须报 p2 chain_depth（阈值用生产的 DEPTH_LIMIT=${DEPTH_LIMIT}——即 limits.json 那个值,自证不做任何阈值注入）`,
      route: { primary: 'abduction', level: 'L2', chain: 'chain-deep-no-exception' },
      want: { kinds: ['chain_depth'], p0: 0, p1: 0, p2: 1 } },
    { id: 'selftest:chain-depth-exception',
      why: '同为深链但已登记 exception_reason → 必须 0 条（证明上一条不是"凡链必红"）',
      route: { primary: 'abduction', level: 'L2', chain: 'diagnose-cause-act' },
      want: { kinds: [], p0: 0, p1: 0, p2: 0 } },
  ]
  // 合成链只改造一份【独立的】链账副本（at/known 一起给,否则合成链会被生产 CHAINS 判成未登记链 ——

