#!/usr/bin/env node
// P0-① 内核预编译（三层，按"什么时候需要"切分，而不是按文件切分）：
//   hot.json        每轮必读：信号→范式、风险信号、链索引、守卫标记
//   warm/<id>.json  命中范式后读一个：用途/出口骨架/反证条件/常见错（**不含 steps**：R6 起"怎么想"不进内核）
//   cold.json       交付前自检才读：输出契约清单 + 配额
// 成本由读取路径结构承担（每轮只读 hot + 至多一个 warm）；本文件只报实测,不判阈值。
// 2026-09-25(R6)：范式层回来，但只回可验证的列（paradigms.tsv 10 列 → 8 列，删 avoid/steps）。
// 漂移防线：三者都是生成物，audit KPACK-1 用 --check 校验新鲜度（源变了没重生成即 FAIL）。
// 2026-09-27（DIGEST 条目 7ff0b32a51bf，p2）：hot.json 的两处内核事实改为**只从内核源取值**——
//   否定词表←routing.negation_guard.patterns、nomatch←visible.nomatch_line。此前二者是内联字面量：
//   改内核源再重生成 hot.json 不跟随，而 KPACK-1 仍报“新鲜”（判据永远绿、同一事实三份）。
//   取不到即 die（exit 12），不用默认值兜底；破坏锚点见 judge-registry 的
//   suite-kpack-negation-source / suite-kpack-nomatch-source。
//   node tools/kernel-pack.mjs           生成 hot/warm/cold
//   node tools/kernel-pack.mjs --check   只校验（exit 0=新鲜 / 12=过期或内核源缺件/坏件）
//   node tools/kernel-pack.mjs --stats   体积对比
//   node tools/kernel-pack.mjs --measure 打印每轮读取路径实测（永远 exit 0）
//   node tools/kernel-pack.mjs --budget  --measure 的等价别名（旧调用兼容）
import fs from 'node:fs'
import path from 'node:path'
import crypto from 'node:crypto'

const ROOT = path.resolve(process.env.POLARIS_ROOT ?? path.join(path.dirname(new URL(import.meta.url).pathname.replace(/^\/([A-Za-z]:)/, '$1')), '..'))
const K = path.join(ROOT, 'skills', 'aurapolaris', 'kernel')
const HOT = path.join(K, 'hot.json')
const COLD = path.join(K, 'cold.json')
const WARM_DIR = path.join(K, 'warm')

// 参数守卫(2026-09-29 arch-v2.C42):只做参数校验,不改任何既有档的行为与输出。
//   为什么必须有:此前无任何守卫,"--help" 不匹配任何档 → 静默落进【默认动作 = 重新生成 hot/warm/cold】,
//   于是"想看用法"这个只读意图会写盘(真树实测:mtime 变、内容不变),正好打穿别的在跑任务的 workspace_stamp。
//   出口语义统一:--help/-h → 打用法 + exit 0;未识别 --xxx → 点名该参数 + exit 1;两者都不执行默认动作。
const USAGE = '用法: node tools/kernel-pack.mjs [--check|--stats|--measure|--budget|--help]（无档=重新生成 kernel/hot.json、kernel/cold.json、kernel/warm/*.json）'
const KNOWN_FLAGS = ['--check', '--stats', '--measure', '--budget', '--help', '-h']
const argvFlags = process.argv.slice(2).filter((a) => a.startsWith('--') || a === '-h')
if (argvFlags.includes('--help') || argvFlags.includes('-h')) { console.log(USAGE); process.exit(0) }
const badFlags = argvFlags.filter((a) => !KNOWN_FLAGS.includes(a))
if (badFlags.length) { console.error(`未知参数: ${badFlags.join(' ')}`); console.error(USAGE); process.exit(1) }
const CHECK = process.argv.includes('--check')
const STATS = process.argv.includes('--stats')
const MEASURE = process.argv.includes('--measure') || process.argv.includes('--budget')
// P0-① 护栏:内核缺件/坏件 = 按行判红(FAIL + 原因 + 退出码 12),不把 Node 栈甩给用户 ——
//   调用方(audit KPACK-1)只认退出码,未捕获的 SyntaxError/ENOENT 会把"内核坏了"演成"工具挂了"。
const die = (msg) => { console.error(`KPACK FAIL: ${msg}`); process.exit(12) }
const bytes = (abs) => { try { return fs.readFileSync(abs) } catch (e) { die(`文件不可读 ${path.relative(ROOT, abs)}: ${e.message}`) } }
const srcText = (f) => bytes(path.join(K, f)).toString('utf8')
const read = (f) => { try { return JSON.parse(srcText(f)) } catch (e) { die(`内核 JSON 解析失败 ${f}: ${e.message}`) } }
const cut = (s, n) => { const t = String(s ?? ''); return t.length > n ? t.slice(0, n) + '…' : t }
// 粗估 token（与 --measure 的口径一致）：CJK≈1 token/字，其它≈0.25
const estTokens = (s) => { let cjk = 0, other = 0; for (const ch of String(s)) { const c = ch.codePointAt(0); if ((c >= 0x2e80 && c <= 0x9fff) || (c >= 0xf900 && c <= 0xfaff)) cjk++; else other++ } return Math.round(cjk * 1 + other * 0.25) }

// 取值闸：内核事实必须从内核源取到，取不到就 fail-closed —— 不许内联默认值/旧值兜底。
// 为什么（DIGEST 7ff0b32a51bf）：内联字面量会让“生成物跟随内核源”在生成器这一层断掉，且门禁照旧报新鲜。
const kernelFact = (v, where) => {
  if (typeof v !== 'string' || !v.trim()) die(`内核事实取不到 ${where} —— 拒绝用内联默认值生成（见 DIGEST 7ff0b32a51bf）`)
  return v
}

// 否定守卫的两组词表都只从 routing.negation_guard.patterns 抽（每条形如“词1/词2 + 语境”）：
//   否定指令组（一律抑制）与转述组（非发问才抑制）在 hot 里分两行渲染；哪一组是转述由
//   negation_guard.unless_note 点名的标记集合判定 —— 生成器这边不内联任何词。
// 诚实边界：若新加一组转述词而不同步 unless_note，它会落进“否定”行（不会静默丢词，但归行会错）；
//   取不到 / 组内半重叠 / note 与 patterns 不同源，一律 die，不猜、不兜底。
function negationGroups(routing) {
  const g = routing?.negation_guard
  const patterns = g?.patterns
  if (!Array.isArray(patterns) || !patterns.length) die('内核 routing.json 缺 negation_guard.patterns —— 否定词表无来源，拒绝生成')
  const groups = patterns.map((p) => {
    const parts = String(p).split('+')
    if (parts.length < 2) die(`negation_guard.patterns 的条目不是“词表 + 语境”形态：${JSON.stringify(String(p))}`)
    return parts[0].split('/').map((w) => w.trim()).filter(Boolean)
  })
  const empty = groups.findIndex((ws) => !ws.length)
  if (empty >= 0) die(`negation_guard.patterns[${empty}] 取不出词：${JSON.stringify(String(patterns[empty]))}`)
  const cited = String(g.unless_note ?? '').match(/[（(]([^（()）]*\/[^（()）]*)[)）]/)
  const quoted = new Set(cited ? cited[1].split('/').map((w) => w.trim()).filter(Boolean) : [])
  if (!quoted.size) die('negation_guard.unless_note 没点名转述类标记（形如“(词1/词2)”）—— 分不出否定指令组/转述组，拒绝猜')
  const hits = (ws) => ws.filter((w) => quoted.has(w)).length
  for (const ws of groups) if (hits(ws) && hits(ws) !== ws.length) die(`negation_guard.patterns 的 ${ws.join('/')} 混了转述类与否定指令类词，无法归类`)
  const missing = [...quoted].filter((w) => !groups.flat().includes(w))
  if (missing.length) die(`negation_guard.unless_note 点名的转述类标记 ${missing.join('/')} 在 patterns 里没有对应条目 —— 两处不同源，拒绝生成`)
  const quote = groups.filter((ws) => hits(ws) === ws.length).flat()
  const neg = groups.filter((ws) => hits(ws) === 0)
  if (!quote.length) die('negation_guard.patterns 里没有转述类条目 —— 与 unless_note 不同源，拒绝生成')
  if (!neg.length) die('negation_guard.patterns 里没有否定指令类条目 —— 与 unless_note 不同源，拒绝生成')
  return { neg: neg.flat().join('|'), quote: quote.join('|') }
}

// 源：除 compact.json 自身以外的内核文件（含 tsv）
const SOURCES = ['index.json', 'routing.json', 'paradigms.tsv', 'contract.tsv', 'visible.json', 'policy.json', 'limits.json', 'modes.json', 'meta.json', 'delegation.json']
const srcHash = crypto.createHash('sha256')
for (const f of SOURCES) srcHash.update(bytes(path.join(K, f)))
const source_sha256_16 = srcHash.digest('hex').slice(0, 16)

function buildHot() {
  const index = read('index.json')
  const routing = read('routing.json')
  const sig = Object.fromEntries((routing.main ?? []).map((m) => [m.id, (m.sig ?? []).join('|')]))
  const strong = Object.entries(routing.strong_sig ?? {}).filter(([k]) => k !== 'rule').map(([k, v]) => `${k}:${v.join('|')}`).join(';')
  const ng = negationGroups(routing)
  return {
    // 以下用紧凑字符串编码：省掉 JSON 的键名与括号开销（体积核算里这部分很贵）
    sig: Object.entries(sig).map(([k, v]) => `${k}:${v}`).join('\n'),
    strong,
    L3: (routing.level_signals?.L3 ?? []).join('|'),
    L2_long: (routing.level_signals?.L2_long ?? []).join('|'),
    chains: (index.chains ?? []).map((c) => `${c.id}:${c.seq.join('>')}`).join('\n'),
    guard: [
      `任务指令→L1(${(routing.task_guard?.patterns ?? []).join('|')};除非${(routing.task_guard?.unless ?? []).join('|')})`,
      `否定→抑制(${ng.neg})`,
      `转述→非发问才抑制(${ng.quote};问号或${(routing.negation_guard?.unless ?? []).join('|')}则不抑制)`,
    ].join('；'),
    nomatch: kernelFact(read('visible.json').nomatch_line, 'visible.json#nomatch_line'),
  }
}

// warm = 命中范式后真正进上下文的那一小块。列索引按 R6 的 8 列：id0 zh1 use2 out3 falsify4 reroute5 errs6 border7
//   故意不含 steps：那一列已删（没有判据，且实测里"内容体量"不影响结果——见 state/what-works-2026-09-22.md）。
function buildWarm() {
  const out = {}
  for (const line of srcText('paradigms.tsv').split(/\r?\n/)) {
    if (!line || line.startsWith('#')) continue
    const c = line.split('\t')
    if (c.length < 8) continue
    out[c[0]] = {
      zh: c[1],
      use: cut(c[2], 48),
      out: cut(c[3], 40),
      falsify: cut(c[4], 48),
      errs: cut(c[6], 28),
    }
  }
  return out
}

function buildCold() {
  const visible = read('visible.json')
  // 只留 id→sev：交付前自检够用；条目原文按需取 kernel/contract.tsv 的该行
  const contract = Object.fromEntries(srcText('contract.tsv')
    .split(/\r?\n/).filter((l) => l && !l.startsWith('#'))
    .map((l) => l.split('\t')).map((c) => [c[0], c[1]]))
  const limits = read('limits.json').limits
  const quota = Object.fromEntries(['user_model_inject_max', 'proactive_max_per_turn', 'strict_p1'].filter((k) => limits[k]).map((k) => [k, limits[k].v]))
  return {
    source_sha256_16,
    ck: 'CK1 路由冻结→CK2 证据封口→CK3 草稿自检→CK4 反省派发→CK5 门禁→CK6 生成前终检→CK7 归档；重跑按 finding 类型回跳(证据类→CK2,表达/推理类→CK3)',
    contract,
    anchors: Object.keys(visible.anchors ?? {}),
    confidence: visible.confidence,
    labels: visible.labels,
    quota,
  }
}

const hot = buildHot()
const warm = buildWarm()
const cold = buildCold()
const textOf = (o) => JSON.stringify(o, null, 1) + '\n'
const hotText = textOf(hot)
const coldText = textOf(cold)
const warmTexts = Object.fromEntries(Object.entries(warm).map(([k, v]) => [k, textOf(v)]))
const worstWarm = Object.entries(warmTexts).sort((a, b) => estTokens(b[1]) - estTokens(a[1]))[0]

if (MEASURE || STATS) {
  const skill = bytes(path.join(ROOT, 'skills', 'aurapolaris', 'SKILL.md')).toString('utf8')
  const tSkill = estTokens(skill), tHot = estTokens(hotText), tWarm = estTokens(worstWarm[1]), tCold = estTokens(coldText)
  const total = tSkill + tHot + tWarm + tCold
  console.log(`每轮读取路径实测（粗估 CJK≈1 / ASCII≈0.25;只报不判）:`)
  console.log(`  SKILL.md        ${String(skill.length).padStart(6)} 字符 ≈ ${String(tSkill).padStart(5)} tokens`)
  console.log(`  kernel/hot.json ${String(hotText.length).padStart(6)} 字符 ≈ ${String(tHot).padStart(5)} tokens`)
  console.log(`  warm/<最宽> ${worstWarm[0]}  ${String(worstWarm[1].length).padStart(6)} 字符 ≈ ${String(tWarm).padStart(5)} tokens`)
  console.log(`  kernel/cold.json${String(coldText.length).padStart(6)} 字符 ≈ ${String(tCold).padStart(5)} tokens`)
  console.log(`  ────────────────────────────────────────`)
  console.log(`  本轮合计 ≈ ${total} tokens（每轮只读 hot + 至多一个 warm）`)
  const srcAll = SOURCES.reduce((n, f) => n + srcText(f).length, 0)
  console.log(`  对照：整读内核 ${srcAll} 字符 ≈ ${estTokens(SOURCES.map((f) => srcText(f)).join(''))} tokens`)
  if (!CHECK) process.exit(0)
}

const prev = {
  hot: fs.existsSync(HOT) ? fs.readFileSync(HOT, 'utf8') : null,
  cold: fs.existsSync(COLD) ? fs.readFileSync(COLD, 'utf8') : null,
  warm: fs.existsSync(WARM_DIR) ? Object.fromEntries(fs.readdirSync(WARM_DIR).filter((f) => f.endsWith('.json')).map((f) => [f.replace(/\.json$/, ''), fs.readFileSync(path.join(WARM_DIR, f), 'utf8')])) : {},
}

if (CHECK) {
  const stale = []
  if (prev.hot !== hotText) stale.push('hot.json')
  if (prev.cold !== coldText) stale.push('cold.json')
  for (const [id, t] of Object.entries(warmTexts)) if (prev.warm[id] !== t) stale.push(`warm/${id}.json`)
  for (const id of Object.keys(prev.warm)) if (!warmTexts[id]) stale.push(`warm/${id}.json(多余)`)
  if (!stale.length) { console.log(`KPACK 新鲜：hot/warm(${Object.keys(warmTexts).length})/cold（源 ${source_sha256_16}）`); process.exit(0) }
  console.error(`KPACK 过期：${stale.slice(0, 6).join(', ')} —— 运行 node tools/kernel-pack.mjs 重新生成`)
  process.exit(12)
}

fs.writeFileSync(HOT, hotText)
fs.writeFileSync(COLD, coldText)
fs.mkdirSync(WARM_DIR, { recursive: true })
for (const [id, t] of Object.entries(warmTexts)) fs.writeFileSync(path.join(WARM_DIR, `${id}.json`), t)
if (fs.existsSync(path.join(K, 'compact.json'))) fs.rmSync(path.join(K, 'compact.json'))   // 旧的一体式产物退役
console.log(`已生成 kernel/{hot.json,cold.json,warm/*.json}（${Object.keys(warmTexts).length} 个 warm，源 ${source_sha256_16}）`)

