  }
  const { hits, suppressed } = sigHit(text)
  const suppressedIds = new Set(suppressed.map((s) => s.id))
  const explicit = explicitName(text)
  const level = L3_SIG.some((s) => text.includes(s)) ? 'L3' : (hits.length || explicit ? 'L2' : 'L1')
  let primary = null, second = null, chain = null
  let decision_reason = null
  const wantsBoth = MULTI.some((w) => text.includes(w))

  if (explicit) { primary = explicit; decision_reason = '①P1 显式点名' }
  else if (hits.length === 1) { primary = hits[0]; decision_reason = '候选唯一:main 命中数=1(无需仲裁)' }
  else if (hits.length > 1) {
    const strong = Object.entries(routing.strong_sig ?? {})
      .filter(([k]) => k !== 'rule')
      .filter(([k, sigs]) => hits.includes(k) && sigs.some((s) => text.includes(s)))
      .map(([k]) => k)
    if (strong.length === 1 && !wantsBoth) { primary = strong[0]; decision_reason = '②strong_sig 命中数=1' }
    if (!primary) {
      const hit = routing.pair.find(([a, b]) => hits.includes(a) && hits.includes(b))
      if (hit) {
        const [a, b, rule] = hit
        const chainId = (rule.match(/chain ([a-z-]+)/) ?? [])[1]
      // 两端信号都命中即建链(不再要求连接词:复核实测 F1 —— "复盘过去+下次该怎么办" 曾丢链)
      const sigHitOf = (id) => (routing.main.find((m) => m.id === id)?.sig ?? [])
        .some((s) => !suppressedIds.has(id) && text.toLowerCase().includes(String(s).toLowerCase()))
      // 被否定的范式不得入链(复核实测:"别提概率" 仍被当作 second)
      if (chainId && !suppressedIds.has(a) && !suppressedIds.has(b) && (wantsBoth || (sigHitOf(a) && sigHitOf(b)))) {
          const c = index.chains.find((x) => x.id === chainId)
          if (c) { chain = c.id; primary = c.seq[0]; second = c.seq[1] ?? null; decision_reason = `③pair 成对仲裁→链 ${c.id}` }
        }
        if (!primary) {
          const last = (id) => Math.max(...(routing.main.find((m) => m.id === id)?.sig ?? [''])
            .map((s) => text.toLowerCase().lastIndexOf(String(s).toLowerCase())))
          primary = last(b) > last(a) ? b : a
          decision_reason = `③pair 成对仲裁(取末次提到的信号:${primary})`
        }
      } else {
        primary = [...hits].sort((x, y) => index.tie_break.indexOf(x) - index.tie_break.indexOf(y))[0]
        decision_reason = '④tie_break 成本序(index.tie_break 最靠前者)'
      }
    }
    if (wantsBoth && !second) {
      // 多诉求同轮:主=最早提到的诉求,次=其次(不得用成本序覆盖"首个诉求优先")
      const pos = (id) => Math.min(...(routing.main.find((m) => m.id === id)?.sig ?? ['\u0000'])
        .map((s) => { const i = text.toLowerCase().indexOf(String(s).toLowerCase()); return i < 0 ? Number.MAX_SAFE_INTEGER : i }))
      const ordered = [...hits].sort((x, y) => pos(x) - pos(y))
      primary = ordered[0]
      second = ordered[1] ?? null
    }
    if (wantsBoth) decision_reason = `multi 首个诉求优先(${chain ? MULTI_CASES.dep.case : MULTI_CASES.parallel.case})`
  }
  if (primary && !second && !chain) {
    // 建链必须【两端都有信号、且都未被否定】(复核实测第4轮:自动建链分支漏了抑制检查)
    const auto = index.chains.find((c) => c.seq[0] === primary && suppressedIds.has(c.seq[1]) === false
      && (routing.main.find((m) => m.id === c.seq[1])?.sig ?? []).some((s) => text.toLowerCase().includes(String(s).toLowerCase())))
    if (auto) { chain = auto.id; second = auto.seq[1] ?? null; decision_reason = `index.chains 自动建链:${auto.id}` }
  }
  // task_kind 也由路由给出(唯一来源):checkanswer 不再从答案文本猜决策类
  const kindW = routing.task_kind?.decision ?? []
  const task_kind = kindW.some((k) => text.includes(k)) ? 'decision' : 'analysis'
  return {
    input: text, level, primary, second, chain, candidates: hits, suppressed, task_kind,
    // sig_contract 要求"四步都无结论时取 tie_break 最靠前者并记 decision_reason" —— 这里把裁决理由做成可观测字段
    decision_reason: decision_reason ?? (primary ? '未分类(不在①..④任一步)' : '无候选:未命中路由表(nomatch 路径)'),
    // routing.multi 的两条机械 case:有链=依赖链,无链=并列可分(另两条无判定者,见 consumer_contract)
    multi_case: wantsBoth ? (chain ? MULTI_CASES.dep.case : MULTI_CASES.parallel.case) : null,
    multi_do: wantsBoth ? (chain ? MULTI_CASES.dep.do : MULTI_CASES.parallel.do) : null,
  }
}
  }
  // R5 继承
  if (!base.primary && ctx?.primary && ANAPHORA.some((w) => lower.includes(w))) {
    return { ...out, mode: 'inherit', primary: ctx.primary, second: ctx.second ?? null, chain: ctx.chain ?? null, inherited: true, anchors: mkAnchors(ctx.primary, ctx.level ?? out.level) }
  }
  // R6 同范式 / R7 其余
  return { ...out, anchors: mkAnchors(base.primary ?? ctx?.primary, base.level) }
}

export function routeChain(inputs) {
  const states = []
  let ctx = null
  for (const t of inputs) {
    const r = routeTurn(t, ctx)
    states.push(r)
    ctx = { primary: r.primary, second: r.second, chain: r.chain, level: r.level, anchors: r.anchors }
  }
  return states
}

// 模式引导:决定是否建议 Plan/目标模式(规则见 kernel/modes.json)
export function modeAdvice({ level, text = '', hostMode = 'unknown' }) {
  const longTask = L2_LONG.some((w) => text.includes(w))
  if (hostMode === 'plan') {
    return {
      recommend: null, active: 'plan', may_execute: false,
      reason: '已在 Plan 模式:只产出计划(S0–S2),写操作与 S3/S4 延后',
      must_exit_plan_first: false,
    }
  }
  if (level === 'L3') {
    return {
      recommend: 'plan+goal', active: hostMode, may_execute: false,
      reason: 'L3:先规划再执行;建议目标模式时必须先退出 Plan 模式(Plan 下 /goal 不延续)',
      must_exit_plan_first: true,
    }
  }
  if (level === 'L2' && longTask) {
    return { recommend: 'plan', active: hostMode, may_execute: true, reason: 'L2 长任务:建议先规划', must_exit_plan_first: false }
  }
  return { recommend: null, active: hostMode, may_execute: true, reason: 'L1/短任务:不引导模式', must_exit_plan_first: false }
}

