// ---------- 内核规则块的消费者契约(routing.consumer_contract) ----------
// 病因(R7 logic-2 p3 c9a791a076fa):routing.json 里曾有块"写了但没人执行"(by_time/coarse/multi/priority 等),
//   而所有既有判据只查"文件里有没有这个块",没有一条查"有没有代码读它" —— 装饰性规则因此能长期活着。
// 本函数把"每个规则块都必须有消费者或有显式状态"钉成可跑判据:node tools/route.mjs --check-consumers
const META_KEY = 'consumer_contract'
const STATUSES = ['live', 'model-side', 'dead']
// 消费者集合:这些文件是内核路由事实的实际读取方(改这个名单等于改判据口径,必须同步 consumer_contract.consumers)
const CONSUMER_FILES = ['tools/route.mjs', 'tools/checkanswer.mjs', 'tools/kernel-pack.mjs', 'tools/audit.mjs', 'tools/kernel-consistency.mjs', 'cli/polaris.mjs']

// 去注释后再找读取点:注释里提到 routing.xxx 不算消费者(本文件的路由注释就提到过 context_rules)。
// 边界(已知,写进回执):按 routing.<键> 字面形态认读取点 —— 经别名变量(如 cli/polaris.mjs 的 JSON.parse(inj).coarse)
//   读同一份内核数据认不出来,所以 dead/model-side 的理由里必须写清"别名读取是否存在"。
function codeOnly(src) {
  let out = '', i = 0, q = null
  while (i < src.length) {
    const c = src[i], n = src[i + 1]
    if (q) { out += c; if (c === '\\') { out += n ?? ''; i += 2; continue } if (c === q) q = null; i++; continue }
    if (c === '"' || c === "'" || c === '`') { q = c; out += c; i++; continue }
    if (c === '/' && n === '*') { const j = src.indexOf('*/', i + 2); i = j < 0 ? src.length : j + 2; continue }
    if (c === '/' && n === '/') { const j = src.indexOf('\n', i); i = j < 0 ? src.length : j }
    out += c; i++
  }
  return out
}
const consumerCode = () => Object.fromEntries(CONSUMER_FILES.map((f) => {
  try { return [f, codeOnly(fs.readFileSync(path.join(ROOT, f), 'utf8'))] } catch { return [f, null] }
}))
const readsKey = (code, key) => code !== null && new RegExp(`routing\\??\\.${key}\\b`).test(code)

export function checkConsumers() {
  // 登记表写成数组(每行一个块):块名不作为 JSON 键 —— 避免"<键>": { 这个形状在文件里出现两次,
  //   把别人的破坏锚点(如 audit-route-3-4 的 find="level_signals": {)从 1 处变成 2 处而判失配。
  const cc = routing[META_KEY]
  const rowsIn = Array.isArray(cc?.blocks) ? cc.blocks : []
  const table = new Map(rowsIn.map((e) => [e?.block, e]))
  const blocks = Object.keys(routing).filter((k) => k !== META_KEY)
  const declared = rowsIn.map((e) => e?.block).filter(Boolean)
  const dupBlock = declared.filter((k, i) => declared.indexOf(k) !== i)
  const rows = []
  const push = (id, ok, detail) => rows.push({ id, ok, detail })
  const code = consumerCode()

  // ROUTE-5:内核顶层键 ↔ 登记表双向一致(少一条=有块没人管,多一条=登记表过期)
  const missing = blocks.filter((k) => !declared.includes(k))
  const ghost = declared.filter((k) => !blocks.includes(k))
  push('ROUTE-5 内核规则块与消费者登记表双向一致', !!cc && missing.length === 0 && ghost.length === 0 && dupBlock.length === 0,
    `内核块=${blocks.length} 登记=${declared.length}${missing.length ? ` 未登记=${missing.join('/')}` : ''}${ghost.length ? ` 幽灵条目=${ghost.join('/')}` : ''}${dupBlock.length ? ` 重复登记=${[...new Set(dupBlock)].join('/')}` : ''}`)

  // ROUTE-6:状态合法 + 非 live 必须给 why/evidence(防"一律标 dead"的空话通行证)
  const badStatus = [], thinWhy = []
  for (const k of declared) {
    const e = table.get(k) ?? {}
    if (!STATUSES.includes(e.status)) { badStatus.push(`${k}:${e.status ?? '无 status'}`); continue }
    if (e.status !== 'live' && !(String(e.why ?? '').trim().length >= 8 && String(e.evidence ?? '').trim())) thinWhy.push(k)
  }
  push('ROUTE-6 每块状态合法,非 live 必须给出 why+evidence', badStatus.length === 0 && thinWhy.length === 0,
    badStatus.length || thinWhy.length ? `坏状态=${badStatus.join('/') || '无'} 缺理由=${thinWhy.join('/') || '无'}` : `${declared.length} 块状态齐备`)

  // ROUTE-7:live 声明必须可证 —— 声明的读者文件里真的出现 routing.<键>(去注释后)
  const phantom = []
  for (const k of declared) {
    const e = table.get(k) ?? {}
    if (e.status !== 'live') continue
    const readers = Array.isArray(e.readers) ? e.readers : []
    if (!readers.length || !readers.every((f) => readsKey(code[f], k)))
      phantom.push(`${k}→${readers.join('+') || '未声明读者'}${readers.some((f) => code[f] === null) ? '(读者文件读不到)' : ''}`)
  }
  push('ROUTE-7 live 声明可证(声明的读者里真的有 routing.<键> 读取点)', phantom.length === 0,
    phantom.length ? `标了 live 但没人读=${phantom.join(' ')}` : `live 块=${declared.filter((k) => table.get(k)?.status === 'live').length} 条读取点全部命中`)

  // ROUTE-8:非 live 标记不得与代码读取矛盾(读了还标 dead/model-side = 标记过期)
  const stale = []
  for (const k of declared) {
    const e = table.get(k) ?? {}
    if (e.status === 'live') continue
    const who = CONSUMER_FILES.filter((f) => readsKey(code[f], k))
    if (who.length) stale.push(`${k}标${e.status}但被${who.join('+')}读`)
  }
  push('ROUTE-8 非 live 标记不得与代码读取矛盾', stale.length === 0, stale.length ? stale.join(' ') : '无矛盾')

  const ok = rows.every((r) => r.ok)
  for (const r of rows) console.log(`${r.ok ? 'PASS' : 'FAIL'}  ${r.id}  ${r.detail}`)
  console.log(ok
    ? `\n消费者契约 PASS:${blocks.length} 个规则块都有消费者或有显式状态(非 live 的块另判 ROUTE-6/ROUTE-8)`
    : `\n消费者契约 FAIL:${rows.filter((r) => !r.ok).length} 项`)
if (invokedDirectly) {
  if (process.argv[2] === '--check-consumers') {
    process.exitCode = checkConsumers() ? 0 : 12
  } else if (process.argv[2] === '--chain') {
    let inputs
    try {
      if (!process.argv[3]) throw new Error('缺少参数')
      inputs = JSON.parse(process.argv[3])
      if (!Array.isArray(inputs)) throw new Error('参数必须是 JSON 数组')
    } catch (e) {
      console.error(`--chain 用法: node tools/route.mjs --chain '["问题1","问题2"]'（${e.message}）`)
      process.exit(1)
    }
    console.log(JSON.stringify(routeChain(inputs), null, 1))
  } else {
    console.log(JSON.stringify(routeSingle(process.argv[2] ?? ''), null, 1))
  }
}

