#!/usr/bin/env node
// AuraPolaris CLI。零依赖。自解释约定:每个子命令先打印【这是什么 / 为什么 / 怎么复核】,再打印结果。
//   node cli/polaris.mjs doctor | lint | selftest | gate --in <report> | ledger add|ls | state get|set | help
// 退出码: 0 成功/approve, 1 用法或 IO 错误, 10 rerun, 11 halt, 12 检查失败, 13 unverified
import fs from 'node:fs'
import path from 'node:path'
import crypto from 'node:crypto'
// 子进程超时【唯一实现】(批次3 P3-21):这里的每个 spawn 都要有 timeout,且超时能杀整棵进程树(.cmd 包装器)。
import { runSync, DEFAULT_TIMEOUT_MS } from '../skills/aurapolaris/tools/run-sync.mjs'
// 路径推导只用 fileURLToPath:URL.pathname 保留百分号编码,安装目录含空格/中文时 ROOT 会变成 "...%20..."(P2-6 反证)
import { fileURLToPath } from 'node:url'
// 内容比对用的 sha256 只允许一份实现(tools/fingerprint.mjs 是工作区指纹的单一来源);这里只 import,不内联第二份
import { sha256 } from '../tools/fingerprint.mjs'
// 注入面接线判定【唯一实现】:适配器文件 + 机制声明 + 证据 + 本机实证,四者齐才算"已接线"(文件在≠接了线)。
// doctor 只消费它,不在这里写第二套判据;声明表=skills/aurapolaris/tools/adapters/injection.json。
import { judge as judgeInjection, isWired, isPartial } from '../tools/injection-matrix.mjs'
// 宿主根清单解析【唯一实现】=tools/host-matrix.mjs#parseHosts(F2-6:此前本文件另抄了一份 split('|') 解析,
//   与唯一实现两侧对"列数/注释/重复 host"的判定会各自漂移;单源门禁 tools/single-source.mjs --check 点名过 cli/polaris.mjs:83)。
import { parseHosts } from '../tools/host-matrix.mjs'

const argv = process.argv.slice(2)
const cmd = argv[0] ?? 'help'
// 选项解析:help 里写的是等号写法(--target=…),而 opt() 原先只认空格写法 —— 用户照 help 敲等号时,
//   值被吞掉、静默用默认路径去查/写宿主配置(2026-09-22 反证:hook status --target=E:\tmp\nope\hooks.json
