#!/usr/bin/env node
// Codex 适配器:stdin 收 hook 事件 JSON → 调 core(guard + 路由注入) → stdout 输出 hookSpecificOutput。
// 与 claude/gemini/hermes/openclaw 的差异只在 normalize/denormalize(见 normalize.mjs),core 逻辑完全共享。
import { spawnSync } from 'node:child_process'
import path from 'node:path'
import { normalize, denormalize } from './normalize.mjs'

const ROOT = path.resolve(process.env.POLARIS_ROOT ?? path.join(path.dirname(new URL(import.meta.url).pathname.replace(/^\/([A-Za-z]:)/, '$1')), '..', '..'))
const HOST = process.env.POLARIS_HOST ?? 'codex'
// 护栏子进程的等待上限(R7 f35192f76e71):宿主给 PreToolUse 的预算是 10s(tools/apply-hook.mjs 与
//   plugins/aurapolaris/hooks/hooks.json 都写 10),内部留一半余量,好在宿主杀我们之前把结论写出去。
//   为什么不用 run-sync.mjs 的 runSync(子进程超时【唯一实现】):那要 import 技能包内的模块,而本适配器的
//   ROOT 由 POLARIS_ROOT 决定 —— 技能包缺失/指错根时 import 先炸,恰好把"护栏不可用"这条要判的路变成
//   "适配器自己起不来"(宿主侧同样拿不到结论)。此处只需要"有界等待 + 到点判到",不需要杀进程树:
//   PreToolUse 路径上 guard.mjs 不派生任何子进程(hook.mjs 的 runSync 调用点都在 selftest 里),直接子进程=整棵树。
//   POLARIS_GUARD_TIMEOUT_MS 只用于自证(把等待缩到百毫秒级),见 tools/judge-registry.json#adapter-guard-fail-closed。
const GUARD_TIMEOUT_MS = Number(process.env.POLARIS_GUARD_TIMEOUT_MS) > 0 ? Number(process.env.POLARIS_GUARD_TIMEOUT_MS) : 5000
const GUARD_UNAVAILABLE = 'guard-unavailable'   // 机器可鉴别的标记:不再与"guard 判定放行"的空 stdout 同形

let input = ''
process.stdin.on('data', (d) => { input += d })
process.stdin.on('end', () => {
  let raw = {}
  try { raw = JSON.parse(input.replace(/^\uFEFF/, '') || '{}') } catch { process.stdout.write(JSON.stringify({ systemMessage: 'AuraPolaris adapter: hook 输入不是合法 JSON,已跳过' }) + '\n'); return }
  const ev = normalize(HOST, raw)

  // 1) 危险动作/越界写入:交给 guard(唯一权威)
  if (ev.event === 'pre_tool') {
    const g = spawnSync(process.execPath, [path.join(ROOT, 'skills/aurapolaris/tools/guard.mjs')],
      { input: JSON.stringify({ tool_name: raw.tool_name, tool_input: raw.tool_input, cwd: ev.cwd }), encoding: 'utf8', timeout: GUARD_TIMEOUT_MS, killSignal: 'SIGKILL', windowsHide: true })
    // 三态判定(R7 f35192f76e71「判据不判失败路径」):退出码 / error / 超时【全部参与判定】。
    //   修前只测 stdout 里有没有 "permissionDecision":"deny":guard 起不来/崩溃/超时的 stdout 为空,
    //   与"guard 判定放行"字节级同形 ⇒ 危险调用被静默放行(fail-open)。
    //   ① status=0 且输出 deny → 拦(用 guard 给的理由);
    //   ② status=0 且无 deny     → 放行(不输出)—— 唯一允许静默的分支;
    //   ③ 起不来/崩溃/被信号杀/超时 → 显式报"护栏不可用",按 fail-closed 拦。
    //   选 fail-closed 的理由与安全影响见 T-20260927122823-504f 回执:静默会把"护栏判放行"与"护栏没跑"
    //   混成同一个信号;本仓库对"组件缺失"的一致口径是不许静默继续(policy.fail_mode.rule;io.json 退出码 13
    //   要求显式 --force-unsafe + incident 才放行)。代价:护栏不可用期间该宿主的 Bash/Edit/Write 全被拒
    //   (可用性损失),但拒绝理由点名原因、带标记、可修 —— 是响的失败,不是静默的放行。
    const timedOut = g.error?.code === 'ETIMEDOUT'
    const broke = timedOut || !!g.error || g.status !== 0 || g.signal != null
    if (broke) {
      const why = timedOut ? `超时 ${GUARD_TIMEOUT_MS}ms 未出结论` : g.error ? `起不来(${g.error.code ?? g.error.message})` : g.signal != null ? `被信号 ${g.signal} 终止` : `退出码 ${g.status}`
      process.stdout.write(JSON.stringify(denormalize(HOST, { event: ev.event, deny: true, reason: `AuraPolaris ${GUARD_UNAVAILABLE}: 护栏子进程${why},无法判定本次调用,按 fail-closed 拒绝(修好安装再重试:node tools/hook-status.mjs)` })) + '\n')
      return
    }
    if (/"permissionDecision":"deny"/.test(g.stdout ?? '')) {
      const reason = (g.stdout.match(/"permissionDecisionReason":"([^"]+)"/) ?? [])[1] ?? 'blocked'
      process.stdout.write(JSON.stringify(denormalize(HOST, { event: ev.event, deny: true, reason })) + '\n')
      return
    }
    return   // 放行:不输出
  }

  // 2) 用户回合:判级别并注入一行。R5(2026-09-24)起不再注入"疑似范式"——范式层已取消,
  //    注入的只剩【级别 + 该级别要交什么】,这是边界,不是流程(kernel/routing.json.level_signals)。
  if (ev.event === 'user_prompt') {
    const r = spawnSync(process.execPath, [path.join(ROOT, 'tools/route.mjs'), ev.text], { encoding: 'utf8' })
    let line = '[polaris] 未命中级别信号;非分析/判断类请忽略'
    try {
      const j = JSON.parse(r.stdout)
      // L2/L3 才注入：L1 是单点/事实类问题，注入只会加噪音(a02 控制题就是这条)。
      if (j.level === 'L3') line = '[polaris] 本轮判为 L3：先规划再执行；不可逆动作先停下确认；结论先行、四类标注、关键结论给证伪条件、引用可定位'
      else if (j.level === 'L2') line = '[polaris] 本轮判为 L2：结论先行；事实/来源声称/推断/假设分开；关键结论给证伪条件；引用可定位'
    } catch { /* 判级失败即用保守提示 */ }
    process.stdout.write(JSON.stringify(denormalize(HOST, { event: ev.event, inject: line })) + '\n')
    return
  }
  // 3) 其他事件:交给 core 的断点/回注逻辑(M1 之后接 state),当前不输出
})

