  const encl = (idx) => fr.filter(f => f.open < idx && idx < f.close).sort((a, b) => (b.open - a.open)); // innermost first

  // ---- (a) catch blocks ----
  const catchRe = /\bcatch\b/g;
  let cm;
  while ((cm = catchRe.exec(masked)) !== null) {
    // ensure it's a real catch keyword (not part of identifier) - regex \b handles it
    let j = skipWs(masked, cm.index + 5);
    let param = null;
    if (masked[j] === '(') { const cp = matchParen(masked, j); param = src.slice(j, cp + 1); j = skipWs(masked, cp + 1); }
    if (masked[j] !== '{') continue;
    const close = matchBrace(masked, j);
    if (close < 0) continue;
    const rawBody = src.slice(j + 1, close);
    const body = stripComments(rawBody);
    const ln = lineOf(src, cm.index);
    const srcLine = src.split('\n')[ln - 1].trim();
    let klass = null;
    if (body === '') klass = rawBody.trim() === '' ? 'EMPTY' : 'COMMENT_ONLY';
    else if (/^return\s*;?$/.test(body)) klass = 'BARE_RETURN';
    else if (/^return\s+(\[\]|\{\}|null|undefined|false|true|0|''|""|``)\s*;?$/.test(body)) klass = 'RETURN_LITERAL';
    else if (/^return\b/.test(body)) klass = 'RETURN_EXPR';
    else klass = null;   // non-trivial body: NOT counted as a swallow
    if (klass) {
      results.empty_catch.push({
        file: rel, line: ln, klass, param: param ?? '(none)',
        body_raw: rawBody.replace(/\s+/g, ' ').trim().slice(0, 120),
        src: srcLine.slice(0, 300), scope: scopeLabel,
      });
    }
  }

  // ---- (b) process.exit inside try-with-finally ----
  const exitRe = /process\.exit\s*\(/g;
  let em;
  while ((em = exitRe.exec(masked)) !== null) {
    const chain = encl(em.index);
    const tryFrame = chain.find(f => f.kind === 'try');
    if (!tryFrame) continue;
    if (!tryFrame.hasFinally) continue;
    const ln = lineOf(src, em.index);
    results.exit_in_try_with_finally.push({
      file: rel, line: ln,
      try_open_line: lineOf(src, tryFrame.open), try_close_line: lineOf(src, tryFrame.close),
      try_has_catch: !!tryFrame.hasCatch, try_has_finally: !!tryFrame.hasFinally,
      src: src.split('\n')[ln - 1].trim().slice(0, 300), scope: scopeLabel,
    });
  }

  // ---- (c) sync child calls ----
  const callRe = /\b(spawnSync|execFileSync|execSync)\s*\(/g;
  let km;
  while ((km = callRe.exec(masked)) !== null) {
    const callee = km[1];
    const open = masked.indexOf('(', km.index);
    const close = matchParen(masked, open);
    if (close < 0) continue;
    // statement start: last boundary char before call
    let st = km.index;
    while (st > 0 && !/[;{}\n]/.test(masked[st - 1])) st--;
    // statement end: next ';' at paren depth 0 after close, or newline if no ';'
    let en = close + 1;
    let d = 0; let found = -1;
    for (let i = en; i < masked.length; i++) {
      const c = masked[i];
      if (c === '(' || c === '[' || c === '{') d++;
      else if (c === ')' || c === ']' || c === '}') { if (d === 0) { found = i; break; } d--; }
      else if (c === ';' && d === 0) { found = i + 1; break; }
      else if (c === '\n' && d === 0) { found = i; break; }
    }
    if (found < 0) found = Math.min(masked.length, close + 200);
    let stmt = src.slice(st, found);
    // extend across continuation lines when the statement clearly continues
    let ext = found;
    for (let guard = 0; guard < 12; guard++) {
      const tail = src.slice(st, ext);
      const openP = (tail.match(/[([{]/g) || []).length, closeP = (tail.match(/[)\]}]/g) || []).length;
      if (openP > closeP && ext < src.length) { const nx = masked.indexOf('\n', ext + 1); ext = nx < 0 ? src.length : nx; continue; }
      break;
    }
    stmt = src.slice(st, ext).trim();
    const before = src.slice(st, km.index);
    const callText = src.slice(km.index, close + 1);
    const assigned = /(const|let|var)\s+[A-Za-z_$][\w$]*\s*=\s*$/.test(before.trimEnd())
      || /[A-Za-z_$][\w$.\[\]]*\s*=\s*$/.test(before.trimEnd())
      || /(const|let|var)\s+[A-Za-z_$][\w$]*\s*=\s*[^;]*$/.test(before);
    const chain = encl(km.index);
    // widen the inspection window: up to 3 following lines, but never past the enclosing block's closing brace
    //   (otherwise a bare call on the last line of a function would "see" the next function's .status check)
    let winEnd = ext;
    for (let g = 0; g < 3; g++) { const nx = masked.indexOf('\n', winEnd + 1); if (nx < 0) break; winEnd = nx; }
    if (chain.length) winEnd = Math.min(winEnd, chain[0].close);
    const window = src.slice(st, winEnd);
    const statusRef = /.(status|error|signal|stdout|stderr)\b/.test(window)
      || /\bstatus\b/.test(window) || /\berror\b/.test(window) || /\bcatch\b/.test(window);
    const valueConsumed = /(=|=>|\breturn|\bawait|[\(\[,:]|\?\?|\|\||&&|\+)\s*$/.test(before)
      || /^\s*\./.test(src.slice(close + 1, close + 40));
    const inTry = chain.some(f => f.kind === 'try');
    const inTryWithCatch = chain.some(f => f.kind === 'try' && f.hasCatch);
    const inTry = chain.some(f => f.kind === 'try');
    const inTryWithCatch = chain.some(f => f.kind === 'try' && f.hasCatch);
    // an enclosing `catch (e) { ... e.status ... }` means the outcome IS inspected (via the thrown error)
    const catchInspects = chain.some(f => f.kind === 'try' && f.catchText
      && /\.(status|error|stdout|stderr|message|code|signal)\b/.test(f.catchText));
    const inCatchOrFinally = chain.some(f => f.kind === 'catch' || f.kind === 'finally');
    const ln = lineOf(src, km.index);
    const rec = {
      file: rel, line: ln, callee, scope: scopeLabel,
      assigned_to_var: assigned, value_consumed: valueConsumed, status_or_error_inspected: statusRef,
      enclosing_catch_inspects_error: catchInspects,
      lexically_inside_try: inTry, lexically_inside_try_with_catch: inTryWithCatch,
      lexically_inside_catch_or_finally: inCatchOrFinally,
      return_checked: valueConsumed || statusRef,
      outcome_checked: valueConsumed || statusRef || catchInspects,
      throw_checked: inTryWithCatch,
      src_call: callText.replace(/\s+/g, ' ').slice(0, 300),
      src_stmt: stmt.replace(/\s+/g, ' ').slice(0, 300),
    };
    results.child_calls_all.push(rec);
    if (!rec.outcome_checked || !rec.throw_checked) {
      const kinds = [];
      if (!rec.outcome_checked) kinds.push('RETURN_VALUE_NOT_CHECKED');
      if (!rec.throw_checked) kinds.push('THROWN_ERROR_NOT_IN_TRY');
      results.unchecked_child.push({ ...rec, unchecked: kinds });
    }
      src_stmt: stmt.replace(/\s+/g, ' ').slice(0, 300),
    };
    results.child_calls_all.push(rec);
    if (!rec.return_checked || !rec.throw_checked) {
      const kinds = [];
      if (!rec.return_checked) kinds.push('RETURN_VALUE_NOT_CHECKED');
      if (!rec.throw_checked) kinds.push('THROWN_ERROR_NOT_IN_TRY');
      results.unchecked_child.push({ ...rec, unchecked: kinds });
    }
  }
}

// ---- instrument self-test: known-answer fixture (validates the parser, not the repo) ----
for (const f of scanned) analyze(f.rel, fs.readFileSync(f.abs, 'utf8'), f.scope);
for (const f of extraScanned) analyze(f.rel, fs.readFileSync(f.abs, 'utf8'), f.scope + ' [EXTRA]');

const out = {
  repo_root: ROOT,
  scopes: SCOPES.map(s => s.glob),
  extra_scopes_not_requested: EXTRA.map(s => s.glob),
  files_scanned: scanned.map(f => f.rel),
  files_scanned_extra: extraScanned.map(f => f.rel),
  counts: {
    empty_catch: results.empty_catch.length,
    exit_in_try_with_finally: results.exit_in_try_with_finally.length,
    child_calls_total: results.child_calls_all.length,
    unchecked_child: results.unchecked_child.length,
  },
  ...results,
};
fs.writeFileSync(path.join(OUT, 'q5.json'), JSON.stringify(out, null, 2), 'utf8');

const L = [];
L.push('FILES SCANNED (' + scanned.length + '): ' + scanned.map(f => f.rel).join(', '));
L.push('');
L.push('(a) EMPTY / COMMENT-ONLY / RETURN-ONLY CATCH  [' + results.empty_catch.length + ']');
for (const c of results.empty_catch) L.push('  ' + c.file + ':' + c.line + '  [' + c.klass + '] param=' + c.param + ' body={`' + c.body_raw + '`}\n      src: ' + c.src);
L.push('');
L.push('(b) process.exit( INSIDE try{} WITH finally  [' + results.exit_in_try_with_finally.length + ']');
for (const c of results.exit_in_try_with_finally) L.push('  ' + c.file + ':' + c.line + '  try@L' + c.try_open_line + '-L' + c.try_close_line + ' catch=' + c.try_has_catch + ' finally=' + c.try_has_finally + '\n      src: ' + c.src);
L.push('');
L.push('(c) ALL sync child calls in scope  [' + results.child_calls_all.length + ']');
for (const c of results.child_calls_all) L.push('  ' + c.file + ':' + c.line + '  ' + c.callee + '  retChecked=' + c.return_checked + ' throwInTry=' + c.throw_checked + '\n      ' + c.src_call);
L.push('');
L.push('(c) UNCHECKED  [' + results.unchecked_child.length + ']');
for (const c of results.unchecked_child) L.push('  ' + c.file + ':' + c.line + '  ' + c.unchecked.join('+') + '\n      ' + c.src_call);
fs.writeFileSync(path.join(OUT, 'q5-detail.txt'), L.join('\n'), 'utf8');

console.log(JSON.stringify(out.counts));
console.log('files=' + scanned.length + ' extra=' + extraScanned.length);

