#!/usr/bin/env node
// AuraPolaris 内部审计：编码 / 结构 / 引用 / 魔法值 / 接口。零依赖，退出码 0=全绿。
import fs from 'node:fs'
import path from 'node:path'
import { execFileSync } from 'node:child_process'
import { pathToFileURL } from 'node:url'

// 根参数 = 第一个【非 --flag】的位置参数:POLARIS_ROOT 优先级不变;改前 argv[2] 一取到底,
//   于是 `node tools/audit.mjs --only=ROUND-1` 会把 '--only=ROUND-1' 当成根目录(全树读不到、判据整片红)。
const ROOT = path.resolve(process.env.POLARIS_ROOT ?? process.argv.slice(2).find((a) => !a.startsWith('--')) ?? '.')
const results = []
// ---- 诊断档 --only=<判据id>[,<id>…](2026-09-27 T-20260927161014-0dda) ------------------------------
// 口径与 tools/judge-registry.mjs --only=SUBSTR 同款:子串命中;命中 0 条 = 拒绝(空集不是通过,见文件末)。
// 只改【选择】:被点名的判据照常完整执行,读数与全量跑逐字相同(诊断档不改写任何判据的判定)。
// 为什么不是"只执行被点名的那条":判据体是 109 段顺序执行的顶层代码,逐段加闸 = 改 109 处现有判据;
//   而把过滤落在唯一出口 add() 上时,"被选中那条的输出与全量跑逐字相同"是【构造性】成立的。
const ONLY = process.argv.slice(2).filter((a) => a.startsWith('--only='))
  .flatMap((a) => String(a.slice('--only='.length)).split(',').map((s) => s.trim()).filter(Boolean))
const onlyHit = (id) => ONLY.length === 0 || ONLY.some((p) => String(id).includes(p))
let addTotal = 0   // 本次实际执行过的判据总数(--only 横幅 N/M 的 M:全量跑时 = 判定行数)
// 三态出口(唯一):ok=true → PASS / ok=false → FAIL / ok=null →【未执行】(第四参 na:{pending})。
//   定义与计数口径(含 N/M 的分子分母怎么算)见下方【判据第三态】小节;--selftest 断言的同一份。
const add = (id, ok, detail, na) => {
  addTotal++
  if (onlyHit(id)) results.push({ id, ok, detail, na: !!na, pending: !!(na && na.pending) })
}
// ---- 读文件【唯一口径】(2026-09-27 批 B5 收尾) ----------------------------------------
// 为什么口径落在 read/readBuf 本身,而不是逐个调用点补 readIf(T-20260927151058-aea6 的教训):
//   那份补丁只改了看得见的 3 处 read('cli/polaris.mjs') 与 read('desired_state.json');同一份文件里
//   其余同类调用 —— 包括 helper 内部的(tsvRows/tsvParsed)与字面清单里的(files/entryFiles)—— 仍会 ENOENT。
//   它自己在回执 deviation 4 里实测:越过 259 行后在 355 行因 install.sh 缺失再次整跑崩,判定行 0 条。
//   看得见的调用点能补完,但"下一个 helper"补不上 —— 所以口径必须落在唯一的读函数上,而不是调用点上。
// 容忍的是【读】,不是【缺】:read 只保证"读不到不崩",缺件本身照旧由 PKG-1 / REF-2 / DS-1 / IO-3 点名判红。
//   同时记一笔 miss(不是静默略过),由末尾的 IO-3 把这批"没读到的输入"逐条打出来。
const readMisses = []
const noteMiss = (abs) => {
  const rel = path.relative(ROOT, abs).split(path.sep).join('/')
  if (!readMisses.includes(rel)) readMisses.push(rel)
}
// 绝对路径版:校准提案、终态产物、zip 成员等不经过 path.join(ROOT, ·) 的读也吃同一份口径
const readRaw = (abs) => { try { return fs.readFileSync(abs, 'utf8') } catch { noteMiss(abs); return '' } }
const readBufRaw = (abs) => { try { return fs.readFileSync(abs) } catch { noteMiss(abs); return Buffer.alloc(0) } }
// 读 + 解析【同一口径】:读不到或解析不了都给 fallback —— 坏件/缺件由各自的判据行点名,
//   读它的判定器不替它崩(否则 JSON.parse('') 会在任何判据产出行之前把整跑打掉,与旧 ENOENT 同一个洞)。
const readJson = (p, fallback = null) => { try { return JSON.parse(read(p)) } catch { return fallback } }
// 绝对路径版(别拿 readJson 嗂绝对路径:read 会再 path.join(ROOT, ·) 一次 → 拼出不存在的路径,
//   结果是"文件在但读不到"的假缺失 —— 调试一次实测就是这个坑)
const readJsonAbs = (abs, fallback = null) => { try { return JSON.parse(readRaw(abs)) } catch { return fallback } }
const read = (p) => readRaw(path.join(ROOT, p))
const readBuf = (p) => readBufRaw(path.join(ROOT, p))
const exists = (p) => fs.existsSync(path.join(ROOT, p))
// 兼容旧调用点:语义与 read 完全相同(留名字是为了让"同一份口径"在 diff 里只落在一处)
const readIf = (p) => read(p)
const listFiles = (d) => {
  let entries = []
  try { entries = fs.readdirSync(path.join(ROOT, d), { withFileTypes: true }) } catch { noteMiss(path.join(ROOT, d)); return [] }
  return entries.flatMap((e) => (e.isDirectory() ? listFiles(path.join(d, e.name)) : [path.join(d, e.name)]))
}

// ---- 子进程读数【唯一实现】----
// 为什么收敛到一处(2026-09-27):旧写法在 catch 里丢掉子进程的 stdout/stderr,detail 又写死成期望串,
//   于是 DS-2/DELEG-4 的 FAIL 行自印 "node cli/polaris.mjs build --check → exit 0" —— 一条判红却在自证退出码 0,
//   看的人无法据此动手(R7 清单把 9d10480f4786 判成 fixed 并声称修好了这条,现场从未变过 = 假闭合)。
// 口径:退出码与输出尾部都取【实测】;子进程坏掉也要产出可行动的红行,不许"先崩、红行产不出"。
const runCmd = (args, opts = {}) => {
  const cmdline = `node ${args.join(' ')}`
  try {
    const out = execFileSync(process.execPath, args, {
      cwd: ROOT, encoding: 'utf8', timeout: 300_000, maxBuffer: 16 * 1024 * 1024, ...opts,
    })
    return { ok: true, exit: 0, out: String(out ?? ''), cmdline }
  } catch (e) {
    const out = `${e.stdout ?? ''}${e.stderr ?? ''}`
    const exit = typeof e.status === 'number' ? e.status : (e.signal ? `signal:${e.signal}` : 124)
    return { ok: false, exit, out, cmdline, err: String(e.message ?? e).split('\n')[0] }
  }
}
// 输出尾部:取最后两条非空行(原始输出,不加工);没有输出才退回异常消息
const outTail = (r, n = 200) => {
  const tail = String(r.out ?? '').split(/\r?\n/).map((s) => s.trim()).filter(Boolean).slice(-2).join(' ⏎ ')
  const t = tail || r.err || '(无输出)'
  return t.length > n ? '…' + t.slice(-n) : t
}
// 证据串 = 真实命令行 + 真实退出码 + 原始输出尾部(PASS/FAIL 同一份读数,不许写死期望值)
const evid = (r) => `${r.cmdline} → exit ${r.exit}; 输出尾部: ${outTail(r)}`

const K = 'skills/aurapolaris/kernel'
const files = [...listFiles(K), 'desired_state.json', 'skills/aurapolaris/SKILL.md']
const norm = (f) => String(f).split(path.sep).join('/')   // listFiles 在 Windows 用反斜杠,扫描前统一
const repoFiles = listFiles('.').map(norm)
const delegJson = readJson(`${K}/delegation.json`, {})
const jsonFiles = files.filter((f) => f.endsWith('.json'))

// ---------- 判据第三态【未执行】+ 布局事实(唯一谓词)【2026-09-29 T-wo-arch-v2-C66】 ----------
// 这一节回答两个问题,都只在这里回答一次:
//   ① 本树是【包内布局】还是【仓库形态】?—— packageLayoutFacts() 的三个事实(state/ 在不在、
//      state/rounds 是不是目录、根上有没有 MANIFEST.sha256)。roundLedgerLayout()(ROUND-1/MUT-1 用)
//      与 distJudgeLayout()(SC-2/SC-3 用)都只读这一份,不各写一套路径猜测(§0.4 isTaskFile 的教训)。
//   ② 判据跑不了时报什么?—— 第三态【未执行】:既不是 PASS(FALSE-GREEN),也不是 FAIL(FALSE-RED)。
// 为什么要有第三态(本单要修的实测缺陷):dist/ 不在时 SC-2/SC-3 走的是 add(..., true, ...) ——
//   判据【没跑】却报 PASS。旁证:dist/ 是 gitignored,裸 git clone 里就没有它,于是“不打包直接跑
//   closeout 也能到 0”,而那个 0 一条读数都没证明。同族:hook.mjs --selftest 的 exit 0 + 0 行输出。
// 计数口径(N/M 通过 的分母与分子):只有【跑过】的判据进分母;未执行的两条既不进分子也不进分母
//   —— “判据无法执行”没有读数可报:算进“通过”是假绿,算进“待修”在包内布局下是假红。
//   两档未执行:
//     · na.pending=true  → 未执行【且计入待修】:本树本该判得出(仓库形态缺 dist/),判据却无对象可测;
//     · na.pending=false → 未执行【且不计入待修】:本布局下判据无对象可测(包内布局按定义不带 dist/)。
const packageLayoutFacts = () => {
  const roundsAbs = path.join(ROOT, 'state', 'rounds')
  let st = null
  try { st = fs.statSync(roundsAbs) } catch { st = null }
  return {
    rounds: !!st && st.isDirectory(),                       // 判定对象在不在(事实检查,非路径猜测)
    stateDir: fs.existsSync(path.join(ROOT, 'state')),
    pkgManifest: fs.existsSync(path.join(ROOT, 'MANIFEST.sha256')),
  }
}
const tagOf = (r) => (r.na ? '未执行' : (r.ok ? 'PASS' : 'FAIL'))
// 判定行的排版【唯一实现】:PASS/FAIL 两态与改前逐字节相同(padEnd(4) 后仍是“PASS  ”两空格)
const renderRow = (r) => `${tagOf(r).padEnd(4)}  ${r.id.padEnd(34)} ${r.detail}`
// 汇总行的口径【唯一实现】:audit 末尾的输出与 --selftest 读的是同一个函数,不许两处各写一套
const summarize = (rs) => {
  const naRows = rs.filter((r) => r.na)
  const fail = rs.filter((r) => !r.na && r.ok === false)
  const pendingNa = naRows.filter((r) => r.pending)
  const judged = rs.length - naRows.length                  // 分母只算【跑过】的判据
  const pending = fail.length + pendingNa.length
  return {
    judged, fail, na: naRows, pending,
    pass: judged - fail.length,
    exit: pending ? 1 : 0,
    line: `${judged - fail.length}/${judged} 通过; ${pending} 项待修`
      + (naRows.length ? `; ${naRows.length} 项未执行(不计入 N/M 的分子与分母:判据无法执行 ≠ 通过`
        + (pendingNa.length ? `;其中 ${pendingNa.length} 项按仓库形态计入待修` : '') + ')' : ''),
  }
}

// ---------- SC-2/SC-3 的布局三态:dist/ 里有没有可判的 .zip ----------
// 三态(唯一决策点=distModeOf):
//   · 有 zip                → 照判(现行判据与阈值一字未改,读数与改前逐字相同);
//   · 没有 zip + 包内布局    → 【本布局不适用/未执行】,不计入待修。出货包按定义不带 dist/(它是构建产物,
//     本身就在 dist/ 里,AGENTS.md §1):包内自审在这里判红就是假红 —— 同一坑 DP-08 已记过一次
//     (tests/range.ps1 的 V3.2 曾因包内必然红而长期假红)。
//   · 没有 zip + 仓库形态    → 【未执行 + 为什么 + 可行动提示】,且计入待修:这棵树本该判得出,
//     静默放行正是本单要修的假绿(裸 clone 没打包 / dist/ 被删都落到这一档)。
// 空的 dist/(目录在但没有 .zip)与“dist/ 不在”同档:旧写法在那种树上打出“0 个 zip 与工作区逐文件一致”
//   的 PASS —— 空集不是通过(与 --only 命中 0 条=拒绝同款口径),一并归入未执行。
const distModeOf = ({ zipCount, layMode }) => (zipCount ? 'judge' : (layMode === 'na' ? 'na' : 'missing'))
const distLayoutOf = ({ zipCount, layMode, pkgManifest, stateDir }) => {
  const mode = distModeOf({ zipCount, layMode })
  return {
    mode, zipCount, layMode, pending: mode === 'missing',
    evid: `dist 里的 zip 数=${zipCount};布局判定=roundLedgerLayout() 的 mode=${layMode}(state/ 存在=${stateDir}、包内标记 MANIFEST.sha256 存在=${pkgManifest})`,
  }
}
const distJudgeLayout = () => {
  let zips = []
  try { zips = fs.readdirSync(path.join(ROOT, 'dist')).filter((f) => f.endsWith('.zip')) } catch { zips = [] }
  const f = packageLayoutFacts()
  const layMode = f.rounds ? 'judge' : (f.stateDir ? 'gone' : 'na')   // 与 roundLedgerLayout() 同一份决策
  return { ...distLayoutOf({ zipCount: zips.length, layMode, ...f }), zips }
}
// “没得判”时那两行的文案【唯一实现】:SC-2/SC-3 段实际 add 的与 --selftest 断言的是同一份
const distMissingRows = (L) => {
  const common = `【未执行】dist/ 里没有可判的 .zip(实测 ${L.zipCount} 个)`
  const why = L.mode === 'na'
    ? `${common};本布局=包内(出货包按定义不带 dist/ —— 它是构建产物,本身就在 dist/ 里,AGENTS.md §1):本判据【无对象可测】,按既有口径报【本布局不适用】并【不计入待修】(不判红、也不假装通过)。判据本体与阈值一字未改;仓库形态(state/ 在)下本行不出现。${L.evid}`
    : `${common};本树=仓库形态(有 state/),这两条判据本该判得出 —— 不许算通过:先跑 node tools/package.mjs . 生成产物,再复跑 node tools/audit.mjs .。${L.evid}`
  return [
    { id: 'SC-2 zip 必备条目齐备', why, pending: L.pending },
    { id: 'SC-3 dist 与工作区一致(需重打包?)', why, pending: L.pending },
  ]
}

// ---------- NAME-1 扫描面【唯一实现】(arch-v2.C163) ----------
// 扫描面谓词与"面外"声明只在这里写一次:NAME-1 的判据体与 --selftest 的两态断言都读这一份
//   (同一谓词只许一处实现;形态先例 = tools/warrant-check.mjs#SURFACE.skipDirs 的声明式跳过表)。
// 为什么要有这张表(本单要修的缺陷,当刻真树读数 node tools/audit.mjs . --only=NAME-1 ⇒ 0/1 待修):
//   `.polaris/**` 被漏在面内,于是命中全是【自指引用】—— `.polaris/tmp-q1/answer.md`(框架臂草稿在报告
//   NAME-1 问题)、`.polaris/workorders/*.result.json`(回执在说"新增文案里没有旧名残留"时引了那个字符串
//   本身)、本单自己的施工单 `.polaris/workorders/arch-v2.C163.json`(它复述红行原文)。
//   这与本文件既有的豁免同族(检查器自身含旧名模式字面量、DESIGN/AGENTS/NEXT-SESSION 历史豁免):
//   面内 = 仓库规范性内容;工作区本地态(施工单/回执/临时草稿)引用那个字符串,恰恰是因为它必须说出它。
// 可见性(硬要求):面外声明与【所排除文件数】由 NAME-1 的 detail 行原样打印(不静默跳过;
//   宁可在 detail 里多一句,也不许悄悄少扫)。
const NAME1_SCAN_EXT = /\.(mjs|js|json|tsv|ps1|sh|cmd|md)$/
const NAME1_FACE_OUT = [
  { rel: 'state/**', tag: '台账非规范件', test: (f) => /^state\//.test(f), why: '台账/日志不是仓库规范性内容(既有豁免)' },
  { rel: 'dist/**', tag: '构建产物', test: (f) => /^dist\//.test(f), why: '构建产物(既有豁免)' },
  { rel: 'tools/migrations/**', tag: '一次性历史脚本', test: (f) => f.startsWith('tools/migrations/'), why: '一次性历史迁移脚本(既有豁免)' },
  { rel: '.bak-*', tag: '备份件', test: (f) => /\.bak-/.test(f), why: '备份文件(既有豁免)' },
  { rel: 'DESIGN.md/AGENTS.md/NEXT-SESSION.md', tag: '历史豁免文档', test: (f) => ['DESIGN.md', 'AGENTS.md', 'NEXT-SESSION.md'].includes(f), why: '历史豁免:讲"旧名是什么"的文档' },
  { rel: 'tools/audit.mjs', tag: '检查器自身', test: (f) => f === 'tools/audit.mjs', why: '豁免:检查器自身含旧名模式字面量,扫自己必假阳(既有豁免)' },
  { rel: '.polaris/**', tag: '工作区本地态', test: (f) => f.startsWith('.polaris/'), why: '工作区本地态(施工单/回执/临时草稿):引用是自指或历史记录,不是仓库规范性内容(同 warrant-check SURFACE.skipDirs 先例)' },
]
// 谓词(纯函数,唯一实现):入参=仓库相对路径(反斜杠会归一成斜杠),出参={inFace:boolean, why:string}。
const name1ScanFace = (rel) => {
  const f = String(rel).split(path.sep).join('/')
  if (!NAME1_SCAN_EXT.test(f)) return { inFace: false, why: '后缀不在扫描面内(原有口径,不逐件点名)' }
  for (const d of NAME1_FACE_OUT) if (d.test(f)) return { inFace: false, why: `面外声明 ${d.rel}` }
  return { inFace: true, why: '' }
}
// 扫描面读数(唯一实现,可见打印用):面内件数 + 每条面外声明各排除多少件 + 后缀未进面多少件。
const name1FaceReport = (all) => {
  const hit = new Map(NAME1_FACE_OUT.map((d) => [d.rel, 0]))
  let inFace = 0
  let outExt = 0
  for (const raw of all) {
    const f = String(raw).split(path.sep).join('/')
    if (name1ScanFace(f).inFace) { inFace++; continue }
    const d = NAME1_FACE_OUT.find((x) => x.test(f))
    if (d) hit.set(d.rel, hit.get(d.rel) + 1)
    else outExt++
  }
  return {
    inFace,
    outExt,
