#!/usr/bin/env node
// =============================================================================
// tools/round.mjs —— 轮次收口门【唯一实现】
//
// 【这是什么】把"一轮"从主题名变成可机械判定的结果单元。四件事都在这里:
//   ① 轮次卡 schema 校验     —— state/rounds/<RID>/ROUND.json
//   ② 六路清单聚合 --digest  —— 报告 + fix_backlog + 上一轮承接 → state/rounds/<RID>/DIGEST.jsonl
//   ③ 收口判定     --check   —— 十条条件全过才 ROUND PASS,否则逐行 ROUND FAIL + exit 1
//   ④ 连续清零计数 --bump    —— 仅 phase=closed 且 open p0=p1=0;state/rounds/CONVERGENCE.json
//
// 【为什么】"这一轮做完了"如果只靠自述就无法证伪 —— 清零可以永远是口头承诺。本文件把收口条件
//   写成可跑判据:tmp_clean / sweep_done 这类自述字段一律【实测】(state/tmp 为空、git 无未跟踪
//   临时件、RECEIPT.md 真存在且非空),DIGEST 的内容用 SHA 钉回轮次卡(手改清单当场露馅)。
//
// 【口径:只消费既有契约,不重新定义】
//   · finding 行 = 与 tools/review-check.mjs 同一口径:行首 p0..p5 + 7 段(severity|file|anchor|
//     claim|evidence|fix|falsifier)+ 同一行内必须含 trigger_path: 与 repro_cmd:。
//     ⚠ trigger_path:/repro_cmd: 必须与 7 段【同行】(review-check 按行判定,续行不继承)。
//     ⚠ 【围栏代码块内的行一律不看】:报告里的"格式示例表"是给子代理看的模板,不是发现。
//       不跳围栏就会产出幽灵行 —— R7 的 03810f9d111b 混进 51 行清单(wontfix 3 条里 1 条是幽灵),
//       R8 同一个 id 又把 `observations 未分诊: 1 条` 这个收口缺口凭空造出来。见 fencedMask()。
//   · 缺证据门槛的条目降级为 observation:落盘为 sev="obs" 的行,不计入 findings,不静默丢弃。
//   · 独立成段的 observation 由"status 是否 open"定义分诊:status=open 即未分诊 → 不得 phase=closed。
//   · 写回轮次卡只许两个键:counts、mechanisms.digest_sha256(见 WRITEBACK_KEYS)。
//     写回是【外科式】的:只替换这两个键的文本区段,其它字节一个都不动;越权即抛错(不写盘)。
//   · 一组靶场 = {dir, spec, raw} 三键,spec/raw 必须是磁盘上真实存在的非空文件,dir 不得重复。
//
// 【怎么复核】
//   node tools/round.mjs --selftest                    # 自证:逐例 PASS/FAIL(沙箱在系统临时目录,不写工作区)
//   node tools/round.mjs --case=<id>                   # 单跑一条用例;id 取自 tests/round.jsonl(目录里的任意一条),未知 id 会列出真实可用集合
//   node tools/round.mjs --check   --round=R7          # 收口门 → exit 0/1
//   node tools/round.mjs --digest  --round=R7          # 聚合报告 → DIGEST.jsonl + 写回 counts/digest_sha256
//                                                      #   卡里有 carry_forward_from 时另把上一轮"仍需处置"的行带入(见【承接】)
//   node tools/round.mjs --bump    --round=R7          # 连续清零计数(仅 closed 且 p0=p1=0)
//   node tools/round.mjs --template --round=R8         # 打印轮次卡模板(不写盘)
//   根目录解析顺序:--root=DIR > POLARIS_ROOT > 本文件所在仓库根。
//
// 【不变式:同一 id 出现两次的清单必须幂等】
//   两份报告报同一条 (f,anchor,claim) → 同一 id 两行(第 2 行判 duplicate + dup_of)。状态继承的三级优先
//   (磁盘清单人工分诊 > 备份票自述 > open)**只认非 duplicate 行** —— duplicate 是位置结论,它一旦进
//   prevStatus,同一 id 的【首行】就会被兜底判回 open,人工分诊被每轮抹掉(收口门永远清不了零)。
//   用例:node tools/round.mjs --case=dup-id-idempotent
//
// 【duplicate 必须带可机械回溯的 dup_of】
//   判 duplicate 是有代价的动作:该行随即【退出 open 计数】,收口门不再看它 —— 所以"重复"这个结论必须能被
//   机器沿链回溯:dup_of 非空且能落到清单里真实存在的【另】一行。做不到就不许判 duplicate(退回 open)。
//   R7 的两条 duplicate(44f468d7fee6 / cfabfaddce36)dup_of 都是 null、同源项只写在 triage_why 散文里,
//   而该轮靶场 A3 的判据原文是「重复项判 duplicate 并记 dup_of」—— 记了判据、没记事实。
//   实现:dup_of 不能并进 prevStatus(会压掉首行分诊),另开一张 prevDupOf 表跨轮携带;--digest 写盘前用
//   duplicatePointerErrs 自审,不合法就 exit 12 且一个字节不落。校验器:dupPointerOk / duplicatePointerErrs。
//   用例:node tools/round.mjs --case=dup-of-recorded
//
// 【承接:carry_forward_from(轮次之间不许"没被看见")】
//   为什么要有它:`--digest` 只读【本轮】的报告目录与 fix_backlog,上一轮明确留下、还没来得及处置的条目
//   会随轮次翻页静默消失 —— 这正是本仓库反复防的"没被看见 = 不存在"。所以承接做成【显式声明 + 机械搬运】:
//   · 声明:轮次卡写 carry_forward_from: "<上一轮 RID>"(键不存在/为空 = 行为与本机制引入前完全一致);
//   · 搬运:读 state/rounds/<上一轮>/DIGEST.jsonl,只带 status ∈ {open,fixing} 的行(仍需处置);
//     fixed/wontfix/closed/duplicate/已分诊的 obs 一律不带 —— 它们已经了结,带了就是重复计数;
//   · 对账:承接行保留【原 id】并新增 carried_from / carried_from_status;与本轮聚合出的行【按 id 去重】,
//     同 id 两边都有 → 以本轮报告为准,只在该行注明 also_in_prior=true(说明本轮又报了同一条);
//   · fail-closed:来源卡/清单读不到、上一轮卡没把清单 sha 钉住(null)、或磁盘 sha 与上一轮卡
//     mechanisms.digest_sha256 不符 → 一行 ROUND FAIL,--digest 侧 exit 12(不许静默当"没有可承接的");
//     --check 侧同一条判据进缺口表(承接来源已被改动(sha 不符)),并要求承接行【真的在本轮清单里】(防承接空转)。
//   · 口径:counts 仍是"清单里 open 的 p0..p5"—— 承接行与本轮行同一把尺(收口门按同一批行重算,两处用不同
//     分母就成了同一数值的第二份复述),承接只【另报一行】:承接: 自 <RID> 带入 N 条(其中 p0..p5 = …)。
//   · 幂等:承接行的状态吃同一套继承(磁盘清单人工分诊 > 来源状态),第 2 次跑不许把人工分诊抹回原状态。
//   用例:carry-basic / carry-dedup / carry-dedup-reworded / carry-missing-source / carry-sha-mismatch / carry-no-field
//
// 【退出条件必须是判据(exit_conditions 不许是死声明)】
//   为什么(2026-09-27 p2):exit_conditions 曾经只被判"是不是数组",内容零消费者,而且它的文字与真正在跑的
//   gateCheck 不同源 —— 卡面 5 条里既没有「open p2–p5 = 0」也没有「observations 已分诊」,而实现两条都拦。
//   读卡的人会以为满足那 5 条就能收口 —— 这正是本仓反复防的"声明与实现两份"。
//   终态(选 (a):让声明可 falsify):卡里每条 exit_conditions 都必须能落到 GATE_CONDITIONS 里的一条【真实】
//   条件上(关键词映射),对不上就红;空数组也算"没有可证伪的声明"→ 红。GATE_CONDITIONS 每项还带一个
//   src_frag = 收口门实现里的字面片段,用例 exit-conditions-mapped 机械对账"登记表 ↔ 实现"
//   (裁判没实现的条登记不上去),两处因此不会各说各话。校验器:exitConditionErrs。
//   R7 的卡一个字都不改:它那 5 条本来就都能落表(dependency_order 那条由 gateCheck 的真条件兜住),
//   所以 --check --round=R7 仍 ROUND PASS —— 是"对得上",不是"被豁免"。
//
// 【跨轮同源键 origin_key(承接去重不许只靠逐字相同)】
//   为什么(2026-09-27 p3):承接去重与本轮新发现共用 id,而 id = findingId(f,anchor,claim) 含 claim ——
//   同一缺陷点【换个措辞重报】,id 就变了,于是清单两行、counts 双计。自带的 carry-dedup 之所以 PASS,
//   只是因为它两轮 claim 逐字相同。所以每行另记一个【来源无关】的键:origin_key = sha256(归一化 f + 归一化
//   anchor) 前 12 位(与 id 同形;行里 f/anchor 都在,任何人都能重算 → 可核)。承接行拿自己的 (f,anchor)
//   现算同一把键,只去撞【本轮行】:
//   · 换个措辞重报 → origin_key 相同 → 只留本轮一行(also_in_prior=true),不双计;
//   · 真不同缺陷(不同 f 或不同 anchor)→ 键不同 → 各自成行,不误并;
//   · 承接行之间【不】按 origin_key 互并(上一轮账里本来就是两条,并了就是静默丢工作项)。
//   id 与 dup_of 一律不动 —— dup_of 的可回溯性(dup-of-recorded)与"同 id 撞车判 duplicate"的语义照旧。
//   用例:node tools/round.mjs --case=carry-dedup-reworded
//     (把跨轮键退化成逐字比较 → 同一缺陷点两行、counts.p2=2 → 当场变红)
//
// 【git 锚点:第⑩条,按轮声明、不追溯;已收口轮按【轮内记录】判(2026-10-13 arch-v2.C193)】
//   为什么(2026-09-27 p3):十条里唯一用到 git 的是⑤清场,而它只量【未跟踪的临时件】;于是 R7 能在整棵树
//   未提交(48→50 个已跟踪文件被改、全库 0 个 tag)的状态下收口,而它自报的 rollback 会抹掉自己的成果
//   —— 成果没进版本库 = 不可检出 = 不可回滚。第⑩条因此要求"本轮的工作树是一个可检出的锚点":
//   没有未提交的已跟踪改动 + 仓库有 tag + HEAD 可解析(卡里另写 tag:"<名字>" 时可指定该轮的 tag)。
//   【按轮声明、不追溯】只有卡里显式写了 git_anchor:{required:true} 的轮次才受它约束。R7 卡没有这个字段
//   → 行为与本条件引入前完全一致,R7 必须仍 ROUND PASS(硬回归线)。不满足时点明"本轮的工作树尚未成为
//   可检出的锚点(未提交 N 个 / 无 tag)"并给出可执行动作 —— 但本工具【不代跑 git commit】(那是父线程的动作)。
//   【判据对象的范围:已收口轮 = 该轮自己的记录】(批准件 label:A-20261013-04,口径归位):对已收口轮
//   (phase=closed 或已进 CONVERGENCE.history),判据对象收拢为 state/rounds/<rid>/** 无未提交改动 ∧ 有 tag
//   (卡里声明 tag 就按该 tag)∧ HEAD 可解析;全树未提交数【降为可见读数】照样打印(『当刻全树未提交 N 个
//   （读数，不计入本判据）』)。为什么:旧口径把【当前工作树的全局未提交状态】混进了【该轮的锚点是否成立】
//   —— 套件自身的生命周期写入(state/closeout.json、state/realq/*、state/state.json)与别处日常脏树会让
//   已收口多轮的轮次在【每次全量面】里必红(e2e-round),而那条红不是该轮的红。未收口轮【一字不变】:
//  收口门仍要整棵树干净 + tag + HEAD,缺一即 exit 1(报错原文照旧 ⇒ 收口顺序对未收口轮照旧有效)。
//   实测:node tools/round.mjs --case=git-anchor-required(三段 + 已收口轮轮外脏/轮内脏两相 + 反相臂)
//
// 【--check 对未收口的轮次是读操作,不写账】
//   归零(consecutive_clean → 0)只许发生在【已完成的轮次】变脏时:该轮 phase=closed,或该轮已在
//   CONVERGENCE.history 里。对【未收口】的轮次跑 --check,CONVERGENCE.json 必须一个字节都不动。
//   为什么:用户口径的停止条件是「连续出现三轮 p0=p1=0」,判的是【已收口】的轮次;一轮本来就该开局脏、
//   收口净(六路独立审查的产出就是 finding)。拿"本轮还有待清的问题"去断连续清零链 = 上一轮被白计,
//   发版门槛永远差一轮。2026-09-27 实测:R8 仍 phase=blueprint 时跑 --check → 账被写坏 1 → 0。
//   用例:node tools/round.mjs --case=convergence-not-reset-midround
//
// 【退出码】0=通过 / 1=用法错或收口门不过
// =============================================================================
import fs from 'node:fs'
import os from 'node:os'
import path from 'node:path'
import crypto from 'node:crypto'
import { execFileSync } from 'node:child_process'
import { fileURLToPath } from 'node:url'
// 临时箱【唯一入口】(2026-09-27 T-20260927161651-0289):沙箱建在 POLARIS_TMP_ROOT ?? os.tmpdir(),
//   清理挂在退出路径上(exit 钩子 + SIGINT/SIGTERM)。取证型保留改走 keepOnRed:
//   判红仍保留沙箱,但现在会打印 `box kept: <路径>` + 登记 + 可被 `tmpbox.mjs --sweep` 清掉。
import { mkbox } from '../skills/aurapolaris/tools/tmpbox.mjs'

const HERE = path.dirname(fileURLToPath(import.meta.url))
const TOOL = fileURLToPath(import.meta.url)

// ---------- 常量(判据的机械定义都在这里,别处不许再写第二份) ----------
export const SCHEMA_VERSION = 1
export const PHASES = ['blueprint', 'review', 'fix', 'verify', 'closed']
export const SEVS = ['p0', 'p1', 'p2', 'p3', 'p4', 'p5']
export const STATUSES = ['open', 'fixing', 'fixed', 'closed', 'wontfix', 'duplicate']
export const FAMILIES = ['F1', 'F2', 'F3', 'F4']
export const OBS_SEV = 'obs'                 // 降级条目在 DIGEST 里的 sev 值
// 承接口径:只有这两态是"仍需处置"。fixed/closed/wontfix/duplicate/已分诊的 obs 都算已了结,带了就是重复计数。
export const CARRY_STATUSES = ['open', 'fixing']
// 承接行比本轮行多出的两个字段(名字稳定,方便下游按字段取)。
export const CARRY_FIELDS = ['carried_from', 'carried_from_status']
export const LENS_COUNT = 6                  // review 阶段要求恰好 6 路且互不重复
export const RANGES_REQUIRED = 3             // 靶场组数(轮次卡不得用 mechanisms.ranges_required 改小它)
export const REQUIRED_CONVERGENCE_ROUNDS = 3 // 连续清零轮数门槛(发版门槛,只报不自动发版)
// 写回轮次卡的白名单:只这两个键。加一个键 = 放宽"最小写面",必须改这里并同步单测。
export const WRITEBACK_KEYS = ['counts', 'mechanisms.digest_sha256']
// 轮次卡字段表:[键, 类型];类型见 typeOk。缺键/类型错 → 一行 ROUND FAIL。
export const CARD_SCHEMA = [
  ['schema_version', 'number'],
  ['round_id', 'string'],
  ['kind', 'string'],
  ['theme', 'string'],
  ['phase', 'string'],
  ['phase_flow', 'array'],
  ['goal', 'string'],
  ['deliverables', 'array'],
  ['acceptance', 'array'],
  ['non_goals', 'array'],
  ['rollback', 'string'],
  ['entry_conditions', 'array'],
  ['exit_conditions', 'array'],
  ['review', 'object'],
  ['fix_backlog', 'array'],
  ['ranges', 'array'],
  ['counts', 'object'],
  ['mechanisms', 'object'],
  ['consecutive_clean', 'number'],
  ['tmp_clean', 'boolean'],
  ['sweep_done', 'boolean'],
  ['opened_at', 'string'],
  ['closed_at', 'string|null'],
]
// 临时件形态:只有命中它的未跟踪文件才算"工作区没清干净"(轮次产物本身也是 ?? 新增件,不能一刀切)。
const TEMP_PATH_RE = /(^|\/)(state\/tmp|tmp|temp|\.tmp)(\/|$)|\.(tmp|temp|bak|orig|rej|swp|swo|partial|crdownload|log)$|~$|(^|\/)(\.DS_Store|Thumbs\.db|npm-debug\.log.*)$/i

// ---------- 小工具 ----------
const WS = ' \t\r\n'
const readText = (p) => fs.readFileSync(p, 'utf8')
const isFile = (p) => { try { return fs.statSync(p).isFile() } catch { return false } }
const isDir = (p) => { try { return fs.statSync(p).isDirectory() } catch { return false } }
const posix = (p) => String(p).split(path.sep).join('/')
const oneLine = (s) => String(s ?? '').replace(/\s+/g, ' ').trim()
const errLine = (e) => oneLine(String(e?.message ?? e)).slice(0, 200)
export const sha256 = (buf) => crypto.createHash('sha256').update(buf).digest('hex')
export const sha256_16 = (buf) => sha256(buf).slice(0, 16)
// 原子落盘:同目录临时文件 + rename。中途失败只会留下 *.tmp(收口门把它当临时件点名),不会留半写文件。
function writeAtomic (target, text) {
  const tmp = `${target}.tmp`
  fs.mkdirSync(path.dirname(target), { recursive: true })
  fs.writeFileSync(tmp, text)
  fs.renameSync(tmp, target)
}
// 子进程的唯一出口:根必须【显式】钉死 —— cwd=ROOT 且 POLARIS_ROOT=ROOT 双保险,
// 不许让子工具从进程环境隐式推断根(CONS-7 约定;"同一份输入在不同 cwd 下结论不同"的唯一来源就是漏钉根)。
// 入参:root 根目录, file 可执行文件, args 参数数组, opts 其余 execFileSync 选项(env 会在基线上叠加)。
// 出参:子进程 stdout(utf8 字符串)。失败:抛错,由调用方决定 fail-closed 还是记一行。
function spawnAt (root, file, args, opts = {}) {
  const ROOT = root
  return execFileSync(file, args, {
    encoding: 'utf8', ...opts, cwd: ROOT, env: { ...process.env, POLARIS_ROOT: ROOT, ...(opts.env ?? {}) },
  })
}
// 确定性排序:不依赖 locale(否则不同机器上清单顺序会漂)。
const byName = (a, b) => (a < b ? -1 : a > b ? 1 : 0)
// 目录树里所有 .md/.jsonl(相对路径排序),用于 report_dir 的六路报告。
function walkReports (dir) {
  const out = []
  for (const e of fs.readdirSync(dir, { withFileTypes: true }).sort((x, y) => byName(x.name, y.name))) {
    const p = path.join(dir, e.name)
    if (e.isDirectory()) out.push(...walkReports(p))
    else if (/\.(md|jsonl)$/i.test(e.name)) out.push(p)
  }
  return out
}

// ---------- 根目录 ----------
// 入参:显式 --root 字符串(可空)。出参:绝对路径。失败:不抛,回退到本文件所在仓库根。
export function resolveRoot (explicit) {
  if (explicit) return path.resolve(String(explicit))
  if (process.env.POLARIS_ROOT) return path.resolve(process.env.POLARIS_ROOT)
  return path.resolve(path.join(HERE, '..'))
}

// ---------- 最小 JSON 文本扫描(为了"外科式"改键:不重排、不重排缩进) ----------
// 为什么不用 JSON.stringify 重写整份:轮次卡是人写的,含内联数组/自定义断行,重写会改动几十处字节,
// 而"写回"只被授权改两个键。所以这里按文本定位值区段,只替换区段。
function skipWs (t, i) { while (i < t.length && WS.includes(t[i])) i++; return i }

