#!/usr/bin/env node
// 判据登记表运行器【唯一实现】:登记表在 tools/judge-registry.json,本文件做六件事:
//   ① 覆盖对账:contract.tsv 的每条 check + audit/consistency 里出现的每个检查 id,都必须在登记表里被点名;
//      未登记的机械判据 → 判红并点名(这是"新增了红不了的判据"的唯一机械拦截点)。
//   ② 破坏注入(--mutate):在 %TEMP% 副本里按登记表声明的"破坏方式"改坏判据的判定对象 → 跑该判据 → 必须红;
//      复原 → 必须绿。任一判据"破坏后仍绿"即 exit 12(判据失效,不是被判定对象失效)。
//   ③ 轻档抽验(门禁档 --check 默认【每个判据脚本各 1 条】):门禁链也要实测一部分登记项"破坏→红、复原→绿";
//      只抽【判据脚本已在登记表 spot_policy.scripts 里声明轻量 + 自带基线】的登记项,
//      单条超时 SPOT_TIMEOUT_MS 兜底,不许把门禁拖慢。条数与组内选法唯一权威 = 登记表 spot_policy。
//   ④ 逐条 PASS/FAIL 输出 + 反例点名 + 末行"口径=实测"结论;--evidence=DIR 把每次跑的原始输出留档(供回执)。
//   ⑤ 册面↔实测【集合】对账(arch-v2.C104):registry.audit_uncovered(册面/声明)必须与 coverage().missing
//      (即 --list 的 missing;现算/权威侧)【逐字集合相等】—— 只比条数会漏掉"条数同、成员不同"
//      (实测:册面 7 条含 USER-4、实测 7 条含 CONS-1,两个都是 7,旧口径照旧判绿)。
//      口径/谓词/消费者三处可对照:--explain 页 + --check 的"册面对账"行 + 登记表 audit_uncovered_about;
//      可证伪自证 = --selftest(自有夹具,四相:一致/塞一条/删一条/条数同成员不同)。
//   ⑥ 分批计划 / 预算形态 / entry-id 唯一性闸(arch-v2.C152,2026-10-11):
//      · --plan(只读):打印默认分批计划(按 source 分组 / 组内按预计成本升序 / 组间按组内总成本升序;
//        timeoutMs ≥ 300000 的条目单独成【重入口批】,默认预算批不含它们,除非 --include-heavy);
//      · --mutate [--budget-minutes=N]:按计划逐条跑,【到点即停】(当前条跑完再停,不半途杀),
//        每条跑完【立刻】打印一行 PASS/FAIL(不许整轮缓冲),结束打印【对账摘要】:跑了 X/总数、
//        花费 M 分钟、未跑 Y 条 —— 未跑是第三态(未跑 ≠ 通过:既没实证破坏→红,也没实证复原→绿);
//        无 --budget-minutes 时仍走分批顺序但跑全部(分批只是顺序与可见性,不是抽样);
//      · entry-id 唯一性闸:judges[].id 重复 ⇒ --check/--mutate 开跑前判红并逐条点名
//        (撞名会让 --only/抽验/对账【静默命中多条】,判定口径先决条件被破坏)。
//   ⑦ 扫面账本 + --resume(arch-v2.C166,2026-10-11):全量扫面一趟 9.5 小时(343 条),而它的读数只要
//      【没变的东西】重跑就是浪费 —— "下次从头再跑"正是上一轮扫面被推迟的唯一原因。口径:
//      `--mutate --resume` 只跳过【有 PASS 行 ∧ entry 哈希 ∧ 判据脚本哈希 ∧ 打包域哈希 三者全同】的条目;
//      无行永不跳过(未跑 ≠ 通过:账本不许把"从没跑过"读成"跑过且绿")、FAIL 行永不跳过、声明白
//      no_resume 的条目永不跳过(判不了"同输入 ⇒ 同结论"就宁可不跳过)、跳过逐条可见打印、
//      对账摘要单列"跳过 N 条(=上次实证且三哈希未变)/ 实跑 M 条 / 未跑 K 条"。
//      账本 = state/tests/mutate-ledger.jsonl(append-only、流式落盘:每条实证跑完【立刻】一行);
//      --mutate 不带 --resume 时【不读账本、一条不跳】—— 与今天逐字节一致。三哈希口径见 resumeDecision 段。
//   ⑧ 副本文件级排除 copy_exclude(arch-v2.C167 A):登记表声明【要复制的面里的例外】(逐文件 glob,
//      如 state/tasks/*.claim.json)。在跑认领件 = 机器态/租约态,不是被判据面 —— 排除后副本里
//      「无在跑单」是确定条件,lint 的写面 DRIFT 段自然空过(缺陷与口径全文见 includeMatcher 头注释);
//      .void.json【不】排除(作废记录是账)。头行如实打印排除清单 + 实际排除件数。
// 结论文案不许强于实测范围:PASS/FAIL 文案由 claimFacts() 的实测计数渲染,再过一遍 claimViolations()
//   ("判据都能红"这类越范围断言,或没写明"未实证 N 条" → 判红 exit 12),所以文案永远跟着实测数字走。
//   audit 的 MUT-1 只认本命令的退出码 → 这两条(抽验 + 文案口径)就是 MUT-1 能红的路径。
// 只读工作区:所有破坏都发生在【副本根】(POLARIS_TMP_ROOT ?? E:\AuraPolaris-tmp;win32 不用 %TEMP% ——
//   它在 C:\Users\cxk 家目录前缀下,会撞施工单 forbid_paths 让副本里 lint 恒红,见 SANDBOX_ROOT 头注释)
//   的副本里,复原后校验逐字节回到原状。副本箱走 tmpbox.mkbox(建箱即登记 + 退出钩子 + 信号处理器 + 可 sweep):
//   --keep 语义不变(保留并打印路径),但保留的箱也进登记表 ⇒ 硬杀留下的孤儿箱可被 `tmpbox --sweep` 清掉。
//   2026-09-27 T-20260927163802-1361:旧写法自建 mkdtempSync 且只在末尾 rmSync,判红(exit 12)/抛异常/被中断
//   三种离开方式都会跳过它(票 r8-tool-tempdir-no-finally;本工具是 --mutate 整仓复制的最大生产者之一)。
//   node tools/judge-registry.mjs [--check] [--mutate] [--only=SUBSTR] [--fast] [--observe] [--json] [--keep]
//   --check        覆盖对账 + 破坏锚点适用性 + 轻档抽验(audit 的 MUT-1 走这一档)
//   --mutate       真跑破坏注入(慢:每条判据一次判据运行);--budget-minutes=N 时到点即停(未跑逐条点名)
//   --resume       (只作用于 --mutate)读账本 state/tests/mutate-ledger.jsonl,只跳过【有 PASS 行 ∧
//                  三哈希全同】的条目;无行/FAIL 行/no_resume 声明永不跳过;不带它 = 不读账本、一条不跳
//   --plan         分批计划(只读):按 source 分组 / 组内按预计成本升序 / 组间按总成本升序 + 重入口批
//   --budget-minutes=N  --mutate 的墙钟预算(分钟,> 0);--include-heavy 把重入口批也纳入预算批
//   --spot=N       轻档抽验条数;不给 = 登记表 spot_policy 的默认口径(每判据脚本各 1 条,脚本级全覆盖)。
//                  0=不抽验,只做锚点。副本内(POLARIS_MUTATION_RUN)自动不抽验
//   --only=SUBSTR  只测点名匹配的登记项;此时"只点名未实证"的已知缺口也按同一匹配过滤(否则深档恒红)
//                  命中 0 条 = 拒绝(exit 12)并列出可选 id 集合 —— 空集不是"全部通过",见 main() 里的 selector 相
//   --max-gaps=N   未实证判据数 > N 即判红(--strict-gaps 等价 --max-gaps=0;默认不设预算)
//   --explain      口径页(名字/谓词/消费者 + 怎么复核 + 边界);只读,exit 0
//   --selftest     册面↔实测集合对账的自有夹具自证(四相);不一致相存在则 exit 12
// 退出码:0=全绿 / 12=有判据红不了、未登记、选择器没匹配到任何登记项、抽验不过 / 1=用法错(语义未变:0 与 12 的含义照旧)
import fs from 'node:fs'
import { mkbox, tmpRoot } from '../skills/aurapolaris/tools/tmpbox.mjs'
import path from 'node:path'
import crypto from 'node:crypto'
import { execFileSync } from 'node:child_process'
import { fileURLToPath } from 'node:url'

const HERE = path.dirname(fileURLToPath(import.meta.url))
export const ROOT = path.resolve(process.env.POLARIS_ROOT ?? path.join(HERE, '..'))
export const REGISTRY_REL = 'tools/judge-registry.json'

// ---------- 副本/箱落位【唯一口径】(arch-v2.C164 A,2026-10-11) ----------
// POLARIS_TMP_ROOT 可覆盖;win32 缺省 E:\AuraPolaris-tmp —— 【不许再用 %TEMP%】。
// 为什么(根因,当刻可复现):本机 %TEMP% = C:\Users\cxk\AppData\Local\Temp 落在诸施工单 forbid_paths 的
//   'C:/Users/cxk' 家目录前缀下;副本里按【副本根】解析的相对 allow_write_paths 因此落进 forbid 前缀 ⇒
//   副本内 `node tools/taskctl.mjs lint` 恒红(「T-wo-…json: allow_write_paths(…) 落在 forbid_paths(C:\Users\cxk) 内」),
//   连带凡 judge 走到 lint/指针面的条目(DS-1×11、DS-2、wo-scope、策略单源、EVO-*、IMM-*、CONC-*…)基线全被污染
//   (2026-10-11 全量扫面 343 条 / 9.5 小时判失 34 项即此)。这正是仓库 AGENTS.md §0.5 自己立过的规矩
//   「一律落 E:/AuraPolaris-tmp/<task id>/(不用 %TEMP%:本机它在 forbid 前缀下)」。
// A/B 正对照(同一棵树、同一份排除表,只差落位):副本落 E:/AuraPolaris-tmp ⇒ taskctl lint 绿、audit 111/111;
//   落 %TEMP% ⇒ lint 红(forbid 前缀命中)。修后读数抄进回执。
// 建箱/登记/sweep/三条退出路径仍是 tmpbox 的唯一实现(mkbox):本处只把 root 传进去
//   (与 tools/gate-plan.mjs:62、tools/package.mjs:65 同款),不自己拼 mkdtemp、不自己写清理。
export const SANDBOX_ROOT = path.resolve(process.env.POLARIS_TMP_ROOT || (process.platform === 'win32' ? 'E:\\AuraPolaris-tmp' : tmpRoot()))

const argv = process.argv.slice(2)
const flag = (n, d = null) => { const p = argv.find((a) => a.startsWith(`--${n}=`)); return p ? p.slice(n.length + 3) : (argv.includes(`--${n}`) ? true : d) }
const only = flag('only', null)
const wantJson = !!flag('json', false)
const wantMutate = !!flag('mutate', false)
const wantFast = !!flag('fast', false)
const wantObserve = !!flag('observe', false)
const wantKeep = !!flag('keep', false)
const evidenceDir = flag('evidence', null)
// 轻档抽验(门禁档也实测一部分登记项):--spot=N 显式给条数;不给 = 用登记表的默认口径(每判据脚本各 1 条
//   => 脚本级全覆盖);--spot=0 = 关。副本内(POLARIS_MUTATION_RUN)自动不抽。
// 2026-09-27 T-20260927154732-96f8 —— 为什么口径要改:原实现 = 「SPOT_ALLOW 白名单 + 按登记表顺序
//   slice(0,spotN)」,默认 spotN=2 落在 c19/c20,而白名单里没有 tools/round.mjs —— judge.cmd 跑
//   round.mjs 的那一族(实测 29 条 ROUNDGATE-*)结构上**永不入抽**:登记了却一条都不验,深档 --mutate
//   也 0 调用者。这不是"抽得少",是"某一族结构性不可达"。
// 现口径(登记在案、可复核)= 按【判据脚本】分组轮转:默认每个脚本各出 1 条,余量按登记表顺序补。
//   脚本内优先挑带 --case=<单个用例> 的单例档(实测 0.31–0.72s),整档 --selftest/--check 排后
//   (round.mjs --selftest 实测 13.4s,一次抽验要跑 3 遍 ≈ 40s,会明显拖慢门禁)——
//   "默认抽几条 / 脚本内怎么选"不散在本文件里当魔法数:唯一权威是 tools/judge-registry.json#spot_policy,
//   本文件只执行它(缺 scripts 即判红,不静默回退到"抽 0 条")。
const spotRaw = flag('spot', null)
const spotN = spotRaw === null ? null : Math.max(0, Math.trunc(Number(spotRaw === true ? 1 : spotRaw)) || 0)
const SPOT_TIMEOUT_MS = 60_000
// 抽验脚本白名单的【兼容默认】:只在被显式以两参形态调用的 spotEligible(e, box) 下生效。
//   主流程一律走登记表 spot_policy.scripts —— 见 spotPolicyOf() 与 main() 里的 cov.spotPolicy。
const DEFAULT_SPOT_ALLOW = Object.freeze([
  'skills/aurapolaris/tools/diff-audit.mjs',
  'skills/aurapolaris/tools/site-check.mjs',
  'skills/aurapolaris/tools/visibility.mjs',
  'tools/route.mjs',
  'tools/round.mjs',
])
// 缺口预算:--max-gaps=N(未实证判据数 > N 判红);--strict-gaps == --max-gaps=0。默认 null=不设预算。
const maxGapsRaw = flag('max-gaps', null)
const maxGaps = maxGapsRaw === null
  ? (argv.includes('--strict-gaps') ? 0 : null)
  : (maxGapsRaw === true ? 0 : Math.max(0, Math.trunc(Number(maxGapsRaw)) || 0))
// 分批计划 / 预算形态(arch-v2.C152):--plan 只读打印计划;--budget-minutes 只作用于 --mutate(深档)。
//   为什么非法值 fail-closed:预算给的是一张"跑到哪为止"的票,认不出就【没有】票 —— 若静默当成
//   "没给预算",一次意图 1 分钟的跑会退化成全量 763 分钟(那正是本单要修的形状)。
function parseBudgetMinutes(raw) {
  if (raw === null || raw === undefined || raw === false) return { minutes: null, err: '' }
  if (raw === true) return { minutes: null, err: '--budget-minutes 需要一个值(形如 --budget-minutes=15)' }
  const n = Number(String(raw).trim())
  if (!Number.isFinite(n) || n <= 0) return { minutes: null, err: `--budget-minutes=${String(raw)} 认不出:必须是 > 0 的分钟数(读到 ${JSON.stringify(String(raw))};非法值不许静默当"没给预算")` }
  return { minutes: Math.trunc(n), err: '' }
}
const budget = parseBudgetMinutes(flag('budget-minutes', null))
const wantPlan = !!flag('plan', false)
const wantIncludeHeavy = !!flag('include-heavy', false)
// --resume(arch-v2.C166):只作用于 --mutate;不带它 = 不读账本、不跳过(与今天逐字节一致)。
const wantResume = !!flag('resume', false)

const readJson = (p) => JSON.parse(fs.readFileSync(p, 'utf8'))
const sha = (buf) => crypto.createHash('sha256').update(buf).digest('hex')

// ---------- 登记表 ----------
export function loadRegistry(root = ROOT) {
  const file = path.join(root, REGISTRY_REL)
  if (!fs.existsSync(file)) throw new Error(`找不到判据登记表: ${file}(新增判据必须先登记)`)
  const reg = readJson(file)
  if (!Array.isArray(reg.judges) || !reg.judges.length) throw new Error(`${REGISTRY_REL}: 缺 judges`)
  return reg
}

export const entryIds = (e) => (Array.isArray(e.ids) && e.ids.length ? e.ids : [e.id]).filter(Boolean)
// 破坏目标文件清单(支持单条/数组两种写法);missingTargets 用来判断"本环境有没有这些产物"
export const opFiles = (m) => [].concat(m ?? []).map((o) => (o && o.kind !== 'none' ? String(o.file ?? '').split('#')[0] : '')).filter(Boolean)
// op.file 的最小 glob(arch-v2.C41):仅文件名段、不递归目录;命中 0 个 → 空清单,
//   由 applyOne 判"锚点不可落地"并点名(fail-closed:不许静默跳过,也不许当成"本条无破坏方式")。
export const globTargets = (box, file) => {
  const rel = String(file)
  if (!rel.includes('*')) return [path.join(box, rel)]
  const dir = path.join(box, path.dirname(rel))
  if (!fs.existsSync(dir)) return []
  const re = new RegExp(`^${path.basename(rel).replace(/[.+^${}()|[\]\\]/g, '\\$&').replace(/\*/g, '.*')}$`)
  return fs.readdirSync(dir, { withFileTypes: true }).filter((d) => d.isFile() && re.test(d.name)).map((d) => path.join(dir, d.name)).sort()
}
export const missingTargets = (e, box) => [...new Set([...opFiles(e.mutation), ...opFiles(e.greenMutation)].filter((f) => (String(f).includes('*') ? !globTargets(box, f).length : !fs.existsSync(path.join(box, f)))))]
// optional_target(本环境可能没有的构建产物)只认【字面路径】:glob 形态命中 0 个 = 锚点悬空,
//   必须落到 applyOne 判"不可落地",不许被 optional 分支静默跳过。
const optionalMissing = (e, box) => (e.optional_target === true ? missingTargets(e, box).filter((f) => !String(f).includes('*')) : [])

// ---------- 锚点适用性(arch-v2.C86,2026-09-30) ----------
// 一条破坏锚点可以声明【适用条件】:声明目录在本根不存在 ⇒ 该锚点是【不适用】,不是【不成立】。
// 为什么要与 optional_target 分开:optional_target 的语义是"这个产物可能没有 ⇒ 跳过",它对 glob 形态【不生效】
//   (见上一段的处置,arch-v2.C41 有意如此),而且它既不产出理由、也不区分"本根没有这一【类】产物"与"登记表过期"。
// 本函数只认一条【可核的事实谓词】:声明目录在【本根(ROOT,判定对象)】里存不存在 —— 【不能】拿破坏副本判:
//   锚点循环自己在副本里落地/复原破坏动作,而复原只删文件、不删父目录(applyOneAbs 的 restore),
//   于是"副本/state 存不存在"会随登记表顺序漂移。实测(arch-v2.C86):拿副本判时,前几条锚点落下 state/* 后,
//   后面 9 条台账锚点全被误判成"适用"从而误判红。理由逐条打进输出与 --json(不许静默)。
// 条件不成立(目录在)时一切照旧:破坏必须真落地,glob 命中 0 个照旧由 applyOne 判【锚点不可落地】并判红。
// 先例(同款取舍,不是新发明):tools/audit.mjs 的 M4-1 与 mut1InPackageNa 按布局报"不适用+理由"而非冒充失败;
//   tests/range.ps1 第 100-105 行注释即该口径的落地处。
export function applicabilityNa(e, box) {
  const a = e?.applicability
  if (!a || a.kind !== 'dir-exists') return ''
  const dir = String(a.dir ?? '').replace(/[\\/]+$/, '')
  if (!dir) return ''
  if (fs.existsSync(path.join(box, dir))) return ''      // 适用条件成立 ⇒ 照旧 fail-closed,一个字节不放宽
  const why = String(a.why_absent ?? '').trim()
  return `不适用(本根没有 ${dir}/ ⇒ 该锚点不适用)${why ? `:${why}` : ''}`
}
// 适用性声明的形状校验(登记表被改坏 = 判红,不许静默降级成"没有声明"):kind 只认 dir-exists;
//   且 dir 必须覆盖本条的每个 op.file —— 否则"不适用"会盖住声明面之外的破坏对象(targets 不在该目录下时它照样该判红)。
export function applicabilityErrs(e) {
  const a = e?.applicability
  if (!a) return []
  if (a.kind !== 'dir-exists' || !String(a.dir ?? '').trim()) return [`applicability 形态不认(只认 {kind:"dir-exists",dir,why_absent}): ${JSON.stringify(a)}`]
  const dir = String(a.dir).replace(/[\\/]+$/, '') + '/'
  const outside = opFiles(e.mutation).filter((f) => !f.startsWith(dir))

