# AuraPolaris 保底安装器（Windows）。无需 Node/Python，双击 install.cmd 即可。
[CmdletBinding()]
param(
  [Alias('root')]
  [string[]] $SkillsRoot = @(),
  [string]   $Source = '',
  [switch]   $Yes,
  [switch]   $DryRun,
  [switch]   $ListHosts,
  [switch]   $Uninstall,
  [switch]   $Rollback,
  [switch]   $SelfTest
)
Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'

$SkillName = 'aurapolaris'
$HomeDir   = if ($env:USERPROFILE) { $env:USERPROFILE } else { $HOME }
$Utc       = (Get-Date).ToUniversalTime().ToString('yyyyMMddTHHmmssZ')

# 标准输入句柄:进程启动时取一次(交互式终端下非 0;管道/重定向/< NUL 时可能为 0)。
# 纯自证入口(-SelfTest)排在 -Source 解析之前,所以这个函数必须先于下面那段解析定义。
function Get-ConsoleInputHandle {
  try { $h = [Console]::OpenStandardInput(); if ($h -and $h.CanRead) { return $h } } catch { }
  return $null
}

# 为什么必须是纯函数:交互与取消两条分支在自动化里走不到,抽成"输入 → 判定"后,一条无写盘命令(-SelfTest)
# 就能把四态各走一遍 —— 否则"取消"分支永远测不到 = 未实证。
function Get-ConfirmDecision {
  param([bool] $Yes, [bool] $DryRun, [bool] $Interactive, [string] $Answer = '')
  if ($Yes) { return 'skip' }                              # ① -Yes:跳过确认(备份与隔离照旧)
  if ($DryRun) { return 'no-confirm' }                     # ② -DryRun:不写盘,无人可确认
  if (-not $Interactive) { return 'proceed' }               # ④ 非交互:无人可确认,按既有语义继续(不阻塞)
  if (Test-ConfirmAnswer $Answer) { return 'proceed' }      # ③ 交互且答 y/Y/yes → 继续
  return 'cancel'                                           # ③ 交互且答非 y/Y/yes → 取消(调用方零写入)
}
# 回答口径与 install.sh:87 的 case "$ans" in y|Y|yes|YES|Yes) 逐条对齐
function Test-ConfirmAnswer([string] $Answer) {
  if ($null -eq $Answer) { return $false }
  $a = $Answer.Trim()
  return ($a -ceq 'y' -or $a -ceq 'Y' -or $a -ceq 'yes' -or $a -ceq 'YES' -or $a -ceq 'Yes')
}
# 交互性判定:以"标准输入是不是终端"为准,不用 [Environment]::UserInteractive —— 有桌面会话时它恒为 true,
# 会把管道里跑误判成交互(然后 Read-Host 永久阻塞)。
function Test-InteractiveConsole {
  return ($ConsoleIn -and -not [Console]::IsInputRedirected)
}
$ConsoleIn = Get-ConsoleInputHandle

# $PSScriptRoot 不能作为 param 默认值（-File 调用时会为空），必须在脚本体内解析
if (-not $Source -or $Source.Trim() -eq '') {
  $psr = Get-Variable -Name PSScriptRoot -ErrorAction SilentlyContinue -ValueOnly
  if ($psr) { $Source = $psr }
  elseif ($MyInvocation.MyCommand.Path) { $Source = Split-Path -Parent $MyInvocation.MyCommand.Path }
  else { throw '无法确定脚本所在目录;请用 -Source <目录> 显式指定' }
}
$Source = (Resolve-Path -LiteralPath $Source).Path
$SrcSkill  = Join-Path $Source "skills/$SkillName"
$ManifestName = '.install-manifest.json'
function Get-Version([string] $dir) {
  $f = Join-Path $dir 'kernel/index.json'
$ManifestName = '.install-manifest.json'

# 四态提示语的期望文本(自证与实现各写一份,不共用变量 —— 否则改错了实现会连带改绿期望)
$stDecisionLines = [ordered]@{
  skip    = '确认         : 已由 -Yes 跳过（备份与隔离照旧）'
  proceed = '确认         : 交互确认通过'
  cancel  = '已取消:未做任何写入（-Yes 可跳过确认）。'
}
# 纯函数自证的探针脚本(顶层定义:内嵌 here-string 若嵌在 if 块里,裁剪后的子串会缺终止符而无法解析)。
# 只读 + 不写盘:子进程只 ReadAllText 本文件、只 Write-Output,不 New-Item / Copy-Item / Move-Item。
# 裁剪点由调用方算好当参数传进来(见 Test-StDecision):探针源码必然嵌在目标文件内部,若它自己也搜锚点,
#   IndexOf 会先命中探针自己那几行(实测踩过两次:一次断在 here-string 中间,一次断在注释中间,两次都让子进程直接失败)。
$stProbe = @'
param([string] $Self, [int] $Cut, [string] $Yes, [string] $DryRun, [string] $Interactive, [string] $Answer)
$ErrorActionPreference = 'Stop'
# powershell -File 把实参一律当字符串传(不认字面量 $true),所以这边自己归一
function ConvertTo-StBool([string] $v) { return ($v -match '^(?i)\$?true$') }
$Yes = ConvertTo-StBool $Yes
$DryRun = ConvertTo-StBool $DryRun
$Interactive = ConvertTo-StBool $Interactive
$src = [IO.File]::ReadAllText($Self)
if ($Cut -le 0 -or $Cut -ge $src.Length) { throw "裁剪点越界: $Cut" }
# 只求值"函数定义 + 纯判定调用点",不做任何写盘:故裁剪点及其后(要目标/提问/分支副作用/写盘/汇总)整段裁掉
Invoke-Expression $src.Substring(0, $Cut)
$d = Get-ConfirmDecision -Yes $Yes -DryRun $DryRun -Interactive $Interactive -Answer $Answer
Write-Output ('DECISION=' + $d)
if ($d -eq 'skip') { Write-Output ("确认         : 已由 -Yes 跳过（备份与隔离照旧）") }
elseif ($d -eq 'no-confirm') { }
elseif ($d -eq 'proceed' -and $Interactive) { Write-Output '确认         : 交互确认通过' }
elseif ($d -eq 'cancel') { Write-Output '已取消:未做任何写入（-Yes 可跳过确认）。' }
elseif ($d -eq 'proceed') { Write-Output '确认         : 非交互运行（标准输入不是终端）→ 无人可确认,按既有语义继续（仍逐个备份;只想看会写什么用 -DryRun）' }
'@
function Test-StDecision {
  param([string] $Name, [bool] $Yes, [bool] $DryRun, [bool] $Interactive, [string] $Answer, [string] $Want)
  # 探针落在本脚本旁边(不落 %TEMP%:本仓 forbid 面把家目录下的 TEMP 前缀列进去了)。只活到本格结束,finally 必删。
  $stProbeFile = $stSelf + '.selftest-probe.ps1'
  try {
    [IO.File]::WriteAllText($stProbeFile, $stProbe, (New-Object Text.UTF8Encoding($true)))
    $stPsExe = Join-Path $PSHOME 'powershell.exe'
    $stExe = if (Test-Path -LiteralPath $stPsExe) { $stPsExe } else { 'powershell' }
    # 布尔实参写成字面量 '$true'/'$false' 传,子进程自己归一(见探针里的 ConvertTo-StBool)
    $stL = if ($Yes) { '$true' } else { '$false' }
    $stD = if ($DryRun) { '$true' } else { '$false' }
    $stI = if ($Interactive) { '$true' } else { '$false' }
    $stArgs = @('-NoProfile', '-ExecutionPolicy', 'Bypass', '-File', $stProbeFile, $stSelf, $stL, $stD, $stI, $Answer)
    $stOut = @(& $stExe @stArgs 2>&1 | ForEach-Object { "$_" })
    $stHit = @($stOut | Where-Object { $_ -like 'DECISION=*' })
    $stGot = if ($stHit.Count -gt 0) { $stHit[0].Substring(9) } else { '(无输出)' }
    $stOk = ($stGot -eq $Want)
    Write-StLine ("      原始输出: [" + (($stOut | Where-Object { $_ -notlike 'DECISION=*' }) -join ' / ') + "]")
    Test-St ("STATE $Name") $stOk ("期望 decision={0};实得 decision={1}" -f $Want, $stGot)
    if ($stOk -and $stDecisionLines.Contains($Name)) {
      $stWantLine = $stDecisionLines[$Name]
    # 裁剪点在这里算好再传给探针。锚点是四段拼出来的:任何一段都不含完整 nonce,
    #   所以本行(以及整个探针源码,它嵌在目标文件里)不会成为 IndexOf 的首个命中。
    #   实测踩过四次自匹配 —— 完整 nonce 一旦出现在源码里,IndexOf 就命中它,裁出来的是半个文件。
    $stAnchor = 'APC' + 'UT7F' + '3E91' + 'D2'
    $stCut = ([IO.File]::ReadAllText($stSelf)).IndexOf($stAnchor)
    if ($stCut -lt 0) { Write-StLine '      (裁剪锚点失配:install.ps1 里找不到自证裁剪锚点 nonce)' }
    $stArgs = @('-NoProfile', '-ExecutionPolicy', 'Bypass', '-File', $stProbeFile, $stSelf, $stCut, $stL, $stD, $stI, $Answer)
    if ($stCut -lt 0) { Write-StLine '      (裁剪锚点失配:install.ps1 里找不到自证裁剪锚点行)' }
    $stArgs = @('-NoProfile', '-ExecutionPolicy', 'Bypass', '-File', $stProbeFile, $stSelf, $stCut, $stL, $stD, $stI, $Answer)
      Test-St ("STATE $Name 提示语逐字") $stLineOk ("期望 [{0}];实得 [{1}]" -f $stWantLine, $stShow)
    } else {
      Write-StLine '      提示语逐字: 判定未达期望,本格不计入 PASS(不给假绿)'
    }
  } finally {
    if (Test-Path -LiteralPath $stProbeFile) { Remove-Item -LiteralPath $stProbeFile -Force }
  }
}

# -SelfTest:被测件自带自证(本仓惯例:tools/round.mjs --selftest、tools/host-matrix.mjs --selftest)。
# 位置在 -Source 解析之前、任何写盘动作之前 —— 与 -ListHosts 同为早退路径,零写盘。
if ($SelfTest) {
  $stFail = @()
  # 被测件路径取本脚本自身:-File 调用下 $PSScriptRoot 可用;拿不到才报一条 FAIL(不静默变绿)
  $stSelf = Get-Variable -Name PSScriptRoot -ErrorAction SilentlyContinue -ValueOnly
  if ($stSelf) { $stSelf = Join-Path $stSelf 'install.ps1' }
    Write-StLine ("[{0}] {1}: {2}" -f $mark, $Name, $Detail)
    if (-not $Ok) { $script:stFail += $Name }
  }

  # ---- 自证 1/3:自身编码(UTF-8 BOM + CRLF;tools/audit.mjs 的 PKG-5 机械判这一条) ----
  if (-not $stSelf) {
    Test-St 'ENC 自身编码=BOM+CRLF' $false '取不到本脚本路径($PSScriptRoot 为空),无法自证编码'
  } else {
    $stBytes = [IO.File]::ReadAllBytes($stSelf)
    $stBom = ($stBytes.Length -ge 3 -and $stBytes[0] -eq 0xEF -and $stBytes[1] -eq 0xBB -and $stBytes[2] -eq 0xBF)
    $stLF = ([regex]::Matches([IO.File]::ReadAllText($stSelf), "`n")).Count
    $stCrlf = ([regex]::Matches([IO.File]::ReadAllText($stSelf), "`r`n")).Count
    Test-St 'ENC 自身编码=UTF-8 BOM' $stBom ("期望 BOM=True(EF BB BF),实得 {0}" -f $stBom)
    Test-St 'ENC 自身换行=CRLF' (($stLF -gt 0) -and ($stLF -eq $stCrlf)) ("期望 LF={0} 与 CRLF={1} 相等且 >0,实得 LF={0} CRLF={1}" -f $stLF, $stCrlf)
  }

  # ---- 自证 2/3:$Yes 确有消费点 ----
  # 只数行会骗人(死开关也能被数到),所以这里的硬判据是行为面的四态断言(下面 Test-StDecision 逐条对照)。
  if (-not $stSelf) {
    Test-St '$Yes 有消费点' $false '取不到本脚本路径,无法自证'
    } finally {
      if (Test-Path -LiteralPath $stProbeFile) { Remove-Item -LiteralPath $stProbeFile -Force }
    }
  }
