#!/usr/bin/env node
// 宿主根名单一致性门禁:三个消费者(install.ps1 -ListHosts / install.sh --list-hosts / cli/polaris.mjs hosts)
// 的列根输出必须与唯一来源 hosts.tsv 逐行一致;源码里再抄一份名单也会判红(被抄的字面量从清单自身推导)。
//   node tools/host-matrix.mjs --check [--root=DIR]   # 只读;0=三处一致 / 12=不一致(点名哪一处、差哪一行) / 1=用法错
//   node tools/host-matrix.mjs --selftest             # 在沙箱副本上自证:改清单会传导、改消费者会判红、复原回绿
// 本机无 sh 时 install.sh 一处标 unverified(不假绿):静态面仍在查它 —— 这正是"跑不了也要能判红"的那一格。
import fs from 'node:fs'
import path from 'node:path'
import { spawnSync } from 'node:child_process'
import { fileURLToPath } from 'node:url'

export const ROOT = path.resolve(process.env.POLARIS_ROOT ?? path.join(path.dirname(fileURLToPath(import.meta.url)), '..'))
export const HOSTS_REL = 'hosts.tsv'
// 三个消费者【怎么列出根】和【怎么读清单】都只有一份实现(hosts.tsv);这里只登记调用形状。
export const CONSUMERS = {
  'install.ps1': 'powershell -File install.ps1 -ListHosts',
  'install.sh': 'sh install.sh --list-hosts',
  'cli/polaris.mjs': 'node cli/polaris.mjs hosts',
}

// 解析唯一格式:空行与 # 注释跳过;每行 host|root|always(root 相对家目录,always 只许 true/false)
export function parseHosts(text, where = HOSTS_REL) {
  const rows = []
  text.split(/\r?\n/).forEach((raw, i) => {
    const line = raw.trim()
    if (!line || line.startsWith('#')) return
    const c = line.split('|')
    if (c.length !== 3) throw new Error(`${where}:${i + 1} 行格式应为 host|root|always,实际: ${line}`)
    if (!/^(true|false)$/.test(c[2])) throw new Error(`${where}:${i + 1} always 只能是 true/false,实际: ${c[2]}`)
    rows.push({ host: c[0], root: c[1], always: c[2] === 'true' })
  })
  if (!rows.length) throw new Error(`${where}: 无有效行(清单为空)`)
  const dup = [...new Set(rows.map((r) => r.host).filter((h, i, a) => a.indexOf(h) !== i))]
  if (dup.length) throw new Error(`${where}: host 重复: ${dup.join(', ')}`)
  return rows
}
export const lineOf = (r) => `${r.host}|${r.root}|${r.always ? 'true' : 'false'}`
export function loadHosts(root = ROOT) {
  const file = path.join(root, HOSTS_REL)
  if (!fs.existsSync(file)) throw new Error(`找不到宿主根清单: ${file}`)
  return { file, rows: parseHosts(fs.readFileSync(file, 'utf8'), HOSTS_REL) }
}

// 静态面(不跑子进程,可在任何平台跑):清单可解析 + 三消费者都只从清单取根、且不内嵌清单里的根字面量。
// kernel-consistency 的 CONS-17 直接 import 这一份,不写第二份实现。
export function staticCheck(root = ROOT) {
  let rows
  try { rows = loadHosts(root).rows } catch (e) { return { ok: false, detail: `清单不可用: ${e.message}` } }
  const problems = []
  for (const f of Object.keys(CONSUMERS)) {
    const abs = path.join(root, f)
    if (!fs.existsSync(abs)) { problems.push(`${f} 不存在`); continue }
    const src = fs.readFileSync(abs, 'utf8')
    src.split(/\r?\n/).forEach((l, i) => {
      for (const r of rows) if (l.includes(r.root)) problems.push(`${f}:${i + 1} 内嵌根字面量 "${r.root}"(名单必须从 ${HOSTS_REL} 读)`)
    })
    if (!src.includes(HOSTS_REL)) problems.push(`${f} 未引用 ${HOSTS_REL}(没在读唯一来源)`)
  }
  return { ok: problems.length === 0, detail: problems.length ? problems.slice(0, 4).join('; ') : `${rows.length} 根 / 三消费者都只读 ${HOSTS_REL}`, rows }
}

const linesOf = (s) => String(s ?? '').split(/\r?\n/).map((l) => l.trim()).filter(Boolean)
// sh 解析器:默认取 PATH 上的 sh;本机把 sh 装在非 PATH 目录时可 --sh=<路径>(或 POLARIS_SH)显式指定,
//   免得"跑不成就一律标 unverified"变成永远的借口。
let SH_CMD = process.env.POLARIS_SH ?? 'sh'
// 子进程一律被指到"正在检查的那个根":cwd=ROOT 且 POLARIS_ROOT=ROOT(与 tools/ 内的统一约定一致)
function spawn(interp, args, ROOT) {
  // HOME 兜底:POSIX 安装器用 $HOME 解析家目录,Windows 上通常是 USERPROFILE
  const env = { ...process.env, POLARIS_ROOT: ROOT, HOME: process.env.HOME ?? process.env.USERPROFILE ?? '' }
  const r = spawnSync(interp, args, { cwd: ROOT, env, encoding: 'utf8', maxBuffer: 8 << 20 })
  if (r.error) return { missing: true, why: r.error.code ?? String(r.error.message) }
  return { code: r.status ?? 1, out: `${r.stdout ?? ''}${r.stderr ?? ''}` }
}
// 真实跑消费者(不是读它的源码猜):列根模式的输出就是要比对的东西
function runConsumer(file, root) {
  if (file === 'install.ps1') {
    for (const ps of ['powershell', 'pwsh']) {
      const r = spawn(ps, ['-NoProfile', '-ExecutionPolicy', 'Bypass', '-File', path.join(root, file), '-ListHosts', '-Source', root], root)
      if (!r.missing) return { ...r, via: ps }
    }
    return { unverified: true, why: '本机无 powershell/pwsh' }
  }
  if (file === 'install.sh') {
    const r = spawn(SH_CMD, [path.join(root, file), '--list-hosts'], root)
    return r.missing ? { unverified: true, why: `本机无 sh(${r.why};非 PATH 安装可用 --sh=<路径> 指定)` } : { ...r, via: SH_CMD }
  }
  const r = spawn(process.execPath, [path.join(root, file), 'hosts'], root)
  return r.missing ? { unverified: true, why: 'node 不可用' } : { ...r, via: 'node' }
}

export function checkHosts(root = ROOT) {
  const { rows } = loadHosts(root)
  const want = rows.map(lineOf)
  const problems = []
  const observed = {}
  const st = staticCheck(root)
  if (!st.ok) problems.push({ who: '静态面', kind: 'static', detail: st.detail })
  for (const f of Object.keys(CONSUMERS)) {
    const r = runConsumer(f, root)
    if (r.unverified) { observed[f] = { unverified: true, why: r.why }; continue }
    const got = linesOf(r.out)
    observed[f] = { exit: r.code, lines: got, via: r.via }
    if (r.code !== 0) {
      // 环境缺件不是"名单分叉"(P2,2026-09-24 R4):--sh 指向的 sh 存在、但 PATH 里没有 coreutils 时,
      //   脚本自己 exit 127(name/head/dirname 之类 command not found)—— 以前这格判 FAIL,把环境问题
      //   说成消费者不一致。现在按 unverified 处理并在 PASS 行点名(真跑了多少行仍然会点出来)。
      const missingTool = r.code === 127 || /command not found|not recognized as an internal or external command/i.test(String(r.out ?? ''))
      if (missingTool) {
        observed[f] = { unverified: true, why: `本机 sh 缺 coreutils(退出码 127/${got.slice(-1)[0] ?? ''});改用带 coreutils 的 sh,如 --sh="C:\\Program Files\\Git\\bin\\bash.exe"` }
        continue
      }
      problems.push({ who: f, kind: 'exit', detail: `${CONSUMERS[f]} 退出码 ${r.code}(期望 0);输出尾部: ${got.slice(-3).join(' / ') || '(空)'}` })
      continue
    }
    if (got.join('\n') !== want.join('\n')) {
      const diff = []
      for (let i = 0; i < Math.max(got.length, want.length); i++) {
        if (got[i] !== want[i]) { diff.push(`第 ${i + 1} 行 清单="${want[i] ?? '(无)'}" vs 消费者="${got[i] ?? '(无)'}"`); if (diff.length >= 3) break }
      }
      problems.push({ who: f, kind: 'mismatch', detail: `${CONSUMERS[f]} 与 ${HOSTS_REL} 不一致(${got.length} 行 vs ${want.length} 行): ${diff.join('; ')}` })
    }
  }
  return { rows, want, observed, problems }
}

function cmdCheck(rootArg) {
  const root = path.resolve(rootArg ?? ROOT)
  let res
  try { res = checkHosts(root) } catch (e) { console.error(`HOSTS-MATRIX FAIL: 清单不可用: ${e.message}`); process.exit(12) }
  console.log(`宿主根清单: ${HOSTS_REL} (${res.rows.length} 根);根目录 ${root}`)
  for (const [f, o] of Object.entries(res.observed)) {
    console.log(`  ${f.padEnd(16)} ${o.unverified ? `unverified(${o.why})` : `exit=${o.exit} 行数=${o.lines.length} via=${o.via}`}`)
  }
  if (res.problems.length) {
    console.error(`\nHOSTS-MATRIX FAIL: ${res.problems.length} 处 —— 名单只有一份(${HOSTS_REL}),三处必须逐行一致`)
    for (const p of res.problems) console.error(`  [${p.kind}] ${p.detail}`)
    process.exit(12)
  }
  // PASS 行必须带实跑计数:一条 PASS 里混着"没跑"的消费者,读的人会把 unverified 当已验证(P2-9 反证)。
  //   未跑项逐条点名到 PASS 行上 —— 不靠读者往上翻,也不把"本机没有 sh"升级成失败(那会让这条门禁在本机永远红)。
  const entries = Object.entries(res.observed)
  const ran = entries.filter(([, o]) => !o.unverified)
  const unver = entries.filter(([, o]) => o.unverified)
  console.log(`\nHOSTS-MATRIX PASS: 三消费者列根输出与 ${HOSTS_REL} 逐行一致,且无内嵌名单 (${ran.length}/${entries.length} 实跑,${unver.length} 未验证${unver.length ? `: ${unver.map(([f, o]) => `${f} unverified(${o.why})`).join(';')}` : ''})`)
  process.exit(0)
}

// ---- 自证:在沙箱副本上制造"清单改了/消费者少一行/偷偷硬编码",门禁必须判红并点名 ----
const SANDBOX = path.join(ROOT, 'state/reviews/probes/.hosts-matrix-selftest')
const COPY = [HOSTS_REL, 'install.ps1', 'install.sh', 'cli/polaris.mjs', 'tools/host-matrix.mjs', 'tools/fingerprint.mjs']
function sandboxReset() {
  if (!path.resolve(SANDBOX).startsWith(path.resolve(ROOT) + path.sep)) throw new Error(`拒绝清理工作区外的路径: ${SANDBOX}`)
  fs.rmSync(SANDBOX, { recursive: true, force: true })
  for (const rel of COPY) {
    const dst = path.join(SANDBOX, rel)
    fs.mkdirSync(path.dirname(dst), { recursive: true })
    fs.copyFileSync(path.join(ROOT, rel), dst)
  }
}
function patch(rel, from, to, expect = 1) {
  const abs = path.join(SANDBOX, rel)
  const src = fs.readFileSync(abs, 'utf8')
  const hits = src.split(from).length - 1
  if (hits !== expect) throw new Error(`沙箱补丁锚点失配(${rel}):找到 ${hits} 处,期望 ${expect} 处 —— 消费者实现变了就该同步改自证`)
  fs.writeFileSync(abs, src.split(from).join(to))
}
function cmdSelftest() {
  const cases = []
  const run = (name, fn) => { try { const d = fn(); cases.push({ name, ok: true, detail: d ?? '' }) } catch (e) { cases.push({ name, ok: false, detail: e.message }) } }
  try {
    sandboxReset()
    run('D4a 基线(沙箱未改)= 绿', () => {
      const r = checkHosts(SANDBOX)
      if (r.problems.length) throw new Error(`期望 exit 0,实得问题: ${r.problems.map((p) => p.detail).join(' | ')}`)
      return `exit 0;消费者行数 ${Object.entries(r.observed).map(([f, o]) => `${f}=${o.unverified ? 'unverified' : o.lines.length}`).join(' ')}`
    })
    run('D1 改清单一行 → 三消费者同步变', () => {
      const orig = fs.readFileSync(path.join(SANDBOX, HOSTS_REL), 'utf8')
      fs.writeFileSync(path.join(SANDBOX, HOSTS_REL), orig.replace('codex|.codex/skills|false', 'codex|.codex/skills-next|false'))
      const seen = []
      for (const f of Object.keys(CONSUMERS)) {
        const r = runConsumer(f, SANDBOX)
        if (r.unverified) { seen.push(`${f}=unverified`); continue }
        const hit = linesOf(r.out).find((l) => l.startsWith('codex|'))
        if (hit !== 'codex|.codex/skills-next|false') throw new Error(`${f} 没跟着变: ${hit ?? '(无该行)'}`)
        seen.push(`${f} → ${hit}`)
      }
      const chk = checkHosts(SANDBOX)
      if (chk.problems.length) throw new Error(`清单改动后本应仍一致,实得: ${chk.problems.map((p) => p.detail).join(' | ')}`)
      seen.push('--check = 0(仍一致)')
      sandboxReset()   // 每个用例各自从干净副本起:清单被改过会让后面的"硬编码"字面量不匹配任何当前根,白测一场
      return seen.join('; ')
    })
    run('D2 消费者少一行 → 判红并点名(两个消费者各试一次)', () => {
      patch('install.ps1', 'foreach ($r in Get-HostManifest) {', 'foreach ($r in (Get-HostManifest | Select-Object -Skip 1)) {')
      patch('cli/polaris.mjs', 'for (const r of hostManifest()) console.log(hostLine(r))',
        'for (const r of hostManifest().slice(0, -1)) console.log(hostLine(r))')
      const r = checkHosts(SANDBOX)
      const hits = r.problems.filter((p) => p.kind === 'mismatch')
      for (const f of ['install.ps1', 'cli/polaris.mjs']) if (!hits.some((p) => p.who === f)) throw new Error(`未点名 ${f},实得: ${JSON.stringify(r.problems)}`)
      return hits.map((p) => p.detail).join(' || ')
    })
    run('D3 消费者偷偷硬编码 → 判红并点名', () => {
      sandboxReset()
      patch('install.ps1', '$all = @(Get-HostManifest | ForEach-Object { @{ host = $_.host; root = (Join-Path $HomeDir $_.rootRel); always = $_.always } })',
        "$all = @(@{ host = 'agents'; root = (Join-Path $HomeDir '.agents/skills'); always = $true })")
      patch('install.sh', '  rows=$(manifest_rows) || return 1',
        '  echo "codex|$HOME_DIR/.codex/skills"\n  rows=$(manifest_rows) || return 1')
      const r = checkHosts(SANDBOX)
      const stat = r.problems.find((p) => p.kind === 'static')
      if (!stat) throw new Error(`静态面没判红(只靠清单自己是不够的,这一格必须能红): ${JSON.stringify(r.problems)}`)
      for (const f of ['install.ps1', 'install.sh']) if (!stat.detail.includes(f)) throw new Error(`未点名 ${f}: ${stat.detail}`)
      return stat.detail
    })
    run('D4b 复原 → 回绿', () => {
      sandboxReset()
      const r = checkHosts(SANDBOX)
      if (r.problems.length) throw new Error(`复原后仍红: ${r.problems.map((p) => p.detail).join(' | ')}`)
      return 'exit 0(与原基线逐行一致)'
    })
  } finally {
    if (fs.existsSync(SANDBOX)) fs.rmSync(SANDBOX, { recursive: true, force: true })
  }
  for (const c of cases) console.log(`${c.ok ? 'PASS' : 'FAIL'}  ${c.name}  ${c.detail}`)
  const bad = cases.filter((c) => !c.ok)
  console.log(`\n沙箱已清理: ${path.relative(ROOT, SANDBOX)}(无残留)`)
  console.log(bad.length ? `HOST-MATRIX SELFTEST FAIL: ${bad.length}/${cases.length}` : `HOST-MATRIX SELFTEST PASS: ${cases.length}/${cases.length}`)
  process.exit(bad.length ? 12 : 0)
}

// 被 import 时(Built-in CONS-17 只取静态面)不得执行任何东西:只在直接运行时进 CLI
const isMain = process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)
if (isMain) {
  const args = process.argv.slice(2)
  const rootArg = args.find((a) => a.startsWith('--root='))?.slice('--root='.length)
  const shArg = args.find((a) => a.startsWith('--sh='))?.slice('--sh='.length)
  if (shArg) SH_CMD = shArg
  if (args.includes('--selftest')) cmdSelftest()
  else if (args.includes('--check')) cmdCheck(rootArg)
  else { console.error('用法: node tools/host-matrix.mjs --check [--root=DIR] [--sh=<sh路径>] | --selftest'); process.exit(1) }
}


























































      const r = checkHosts(SANDBOX)
      assertNoStale('D3 硬编码判红', r)
      const stat = r.problems.find((p) => p.kind === 'static')
      if (!stat) throw new Error(`静态面没判红(只靠清单自己是不够的,这一格必须能红): ${JSON.stringify(r.problems)}`)
      for (const f of ['install.ps1', 'install.sh']) if (!stat.detail.includes(f)) throw new Error(`未点名 ${f}: ${stat.detail}`)
      return stat.detail
    })
    run('D4b 复原 → 回绿', () => {
      sandboxReset()
      return `${assertGreen('D4b 复原', checkHosts(SANDBOX))}(与原基线逐行一致)`
    })
    // 新增判据(FIXTURE-STALE)自己的破坏锚点:故意让闭包少一个必需文件,它必须【自报】而不是伪装成判据判红。
    //   被删的文件同样由模块图推导 = 消费者第一条相对 import 的目标(必然在闭包内、也必然被加载)——
    //   消费者改了 import,这个锚点自己跟着走,不用人手同步。
    run('D5 夹具过期 → 自报 FIXTURE-STALE 并点名(不许算成判据判红)', () => {
      const first = relImportsOf(path.join(ROOT, 'cli/polaris.mjs'))[0]
      if (!first) throw new Error('夹具破坏锚点失配:cli/polaris.mjs 已无相对 import,本用例要跟着模块图重挑缺件')
      const victim = path.posix.normalize(path.posix.join(path.posix.dirname('cli/polaris.mjs'), first))
      sandboxReset([victim])
      const r = checkHosts(SANDBOX)
      const st = staleProblems(r)
      if (st.length !== 1) throw new Error(`期望恰好 1 条 kind:fixture-stale,实得 ${st.length} 条: ${JSON.stringify(r.problems)}`)
      const d = st[0].detail
      const flat = d.replace(/\\/g, '/')
      for (const need of ['FIXTURE-STALE', 'cli/polaris.mjs', victim, '沙箱 COPY/闭包规则该更新']) if (!flat.includes(need)) throw new Error(`判定没点名 ${need}: ${d}`)
      if (r.problems.some((p) => p.kind === 'mismatch')) throw new Error(`夹具过期被算成了"名单不一致": ${JSON.stringify(r.problems)}`)
      sandboxReset()
      return `删 ${victim} → ${d} ;复原 → ${assertGreen('D5 复原', checkHosts(SANDBOX))}`
    })
  } finally {
    if (fs.existsSync(SANDBOX)) fs.rmSync(SANDBOX, { recursive: true, force: true })
  }

// 被 import 时(Built-in CONS-17 只取静态面)不得执行任何东西:只在直接运行时进 CLI
const isMain = process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)
if (isMain) {
  const args = process.argv.slice(2)
  const rootArg = args.find((a) => a.startsWith('--root='))?.slice('--root='.length)
  const shArg = args.find((a) => a.startsWith('--sh='))?.slice('--sh='.length)
  if (shArg) SH_CMD = shArg
  if (args.includes('--selftest')) cmdSelftest()
  else if (args.includes('--check')) cmdCheck(rootArg)
  else { console.error('用法: node tools/host-matrix.mjs --check [--root=DIR] [--sh=<sh路径>] | --selftest'); process.exit(1) }
}

