#!/usr/bin/env node
// 文档事实绑定门禁(F3 家庭"文档/台账与实况不符"的机制票 MT-3)。
//
// 【这是什么】把文档里"会随实况腐烂"的断言(计数/版本/判定词/接线状态)逐条绑到一条机械证据上;
//   没有绑定的事实句判红并点名。绑定有三种档,都写成 HTML 注释 `<!-- <档名>: … -->`:
//     fact            复跑 `cmd`,输出须含 `expect` —— 用于"今天仍然为真"的断言。
//     ref             `ref: path:line`,文件存在、行号不越界、该行非空。
//     fact-historical 历史引文:`as-of="YYYY-MM-DD"` + `ref="path:line"` 指向留档行。
//                     历史数字本来就与今天不同,所以【计数守卫不适用】,也不复跑命令。
//   JSON 数值(2026-09-27 补)对 JSON 台账还有第三种"绑定位置":JSON 不能内联标记,所以 `JSON_NUM_KEYS` 里
//     登记过的腐烂字段由 `JSON_NUM_BINDINGS`(工具内的绑定注册表)盯着,档位仍是上面那三种的前两种。
//
// 【为什么这样写】三次同因翻车(见 state/rounds/R7-doc-facts-scope/WORKORDER.md)的根因不是"文档写错",
//   而是【标记没被看见】:旧 MARKER_RE 写成 `(fact|ref):`,而 `<!-- fact-historical: … -->` 里 `fact`
//   后面是 `-historical:` 不是冒号 → 整条标记被静默忽略 → 该段事实句判"未绑定",而且没有任何提示。
//   所以本文件有两条铁律:
//     ① 档名白名单【单一来源】= BINDING_KINDS,标记正则与"纯标记行"判定都从它派生,不许两处各写一份;
//     ② 名字不在白名单的 `<!-- <word>: … -->` 必须【判红】(why=`未知绑定档 <word>`),不许静默通过。
//   历史档的 ref 判定直接复用 checkRef,不复制一份逻辑 —— 复制出来的第二份迟早各自腐烂。
//
// 【怎么复核】
//   node tools/doc-facts.mjs --selftest              # 读 tests/doc-facts.jsonl 逐条自证;0=全绿 / 12=有用例红
//   node tools/doc-facts.mjs --check [--root=DIR]    # 只读;0=全绑定且复跑一致 / 12=有红线(逐条点名) / 1=用法错
//   反向验证(证明"新用例真能红"):把 BINDING_KINDS 改回 ['fact','ref'](等价于旧式 `(fact|ref):`)
//   → --selftest 必须 FAIL;逐字节改回来再跑必须全绿。两次原始输出都要进回执。
//   JSON 数值判据的反向验证(同款要求):把 state/status.json 的 `observed_generation` 从 8 改成 88 → 不得影响红绿(历史档不适用计数守卫);
//   把 JSON_NUM_BINDINGS 里的一条删掉 → 必红(未绑定);把字段改名 → 必红(悬空)。三组原始输出见回执。
//   缺档 fail-closed 的反向验证(同款要求):造一棵只有 INSTALL.md 的树 → `--check --root=<它>` 必须 exit≠0
//   且逐条点名 HANDOVER.md / RELEASE.md / NEXT-SESSION.md 不存在(不得是堆栈);把这三份补齐 → 这三条红行消失。
//   JSON 数值判据的反向验证(同款要求):把 state/status.json 的 `observed_generation` 从 8 改成 88 → 不得影响红绿(历史档不适用计数守卫);
//   把 JSON_NUM_BINDINGS 里的一条删掉 → 必红(未绑定);把字段改名 → 必红(悬空)。三组原始输出见回执。
//   缺档 fail-closed 的反向验证(同款要求):造一棵只有 INSTALL.md 的树 → `--check --root=<它>` 必须 exit≠0
//   且逐条点名 HANDOVER.md / RELEASE.md / NEXT-SESSION.md 不存在(不得是堆栈);把这三份补齐 → 这三条红行消失。
//   两相原始输出见 T-20260927154600-e6f0 的回执(沙箱两相;该缺陷原本把 R7-B 冻结回归网打成"只剩崩溃")。
//   比对口径:expect 与命令输出都先把连续空白折叠成一个空格再判子串 —— 否则对齐全靠数空格,改一次排版就假红。
import fs from 'node:fs'
import os from 'node:os'
import path from 'node:path'
import { spawnSync } from 'node:child_process'
import { fileURLToPath } from 'node:url'

const HERE = path.dirname(fileURLToPath(import.meta.url))
export const ROOT = path.resolve(process.env.POLARIS_ROOT ?? path.join(HERE, '..'))

// 自证用例表(外置):每行一个 JSON 用例,读起来是一张表,而不是嵌在函数体里的字面量数组。
export const CASES_FILE = path.join(HERE, '..', 'tests', 'doc-facts.jsonl')

// 默认文档集(唯一约定:INSTALL.md 顶部一节):散文类事实源,不含任务文件与 review 目录下的历史实验记录。
// 【2026-09-27 扩面】接手人最先读到的三份根文档(HANDOVER.md / RELEASE.md / NEXT-SESSION.md)原先不在扫描面内,
//   实测代价:R8 六路⑥人镜发现它们写着过期读数(NEXT-SESSION.md:33 `期望 89/89 通过`、RELEASE.md:55 `101/106 通过; 5 项待修`、
  'RELEASE.md',
  'NEXT-SESSION.md',
  'INSTALL.md',
  'state/status.json',
  'state/*.md',
  'state/reviews/dsh-all-profiles-20260922.md',
  'state/host-injection-matrix.md',
  'state/what-works-2026-09-22.md',
]

// 模式表:只判"会随实况腐烂"的量词/版本/状态断言,不判一般散文(误伤边界见文件尾注释)。
export const PATTERNS = [
  { id: 'count-个', re: /(?<![\w.])\d+\s*个(?![\w])/u, what: '计数(个)' },
  { id: 'count-条', re: /(?<![\w.])\d+\s*条(?![\w])/u, what: '计数(条)' },
  // 审计/回归读数(N/M 通过)【2026-09-27 收紧】:原 PATTERNS 只抓 PASS/FAIL 与中文量词,`89/89 通过; 0 项待修`
  //   这种"期望值"句一个模式都不命中 —— 于是"照旧文档把今天的 10x/107 当成回归"这条最贵的坑没有判据。
  //   收紧(不是放宽):只多判"N/M 通过"这一种形态,不动既有模式,也不删任何断言。
  { id: 'audit-count', re: /(?<![\w.])\d+\s*\/\s*\d+\s*通过/u, what: '审计计数(N/M 通过)' },
  { id: 'verdict', re: /\bPASS\b|\bFAIL\b/u, what: '判定词' },
  { id: 'version', re: /(?<![\w.])\d+\.\d+\.\d+(?:[-+][\w.]+)?(?![\w])/u, what: '版本号' },
  { id: 'status', re: /已接线|未接线|已实测|未验证|已安装|未安装/u, what: '接线/验证状态' },
]
// 数字覆盖守卫:计数类断言最容易"改个数字糊过去"(绑定只要在段里就算过),所以行内的 N 必须在绑定里出现一次
// —— fact 看 expect 文本,ref 看被引用的那一行。改写数字 = 直接红,不用等复跑命令。
export const GUARD_RE = /(?<![\w.])(\d+)\s*(个|条)(?![\w])/gu

// JSON 数值判据【2026-09-27 补】:台账里的腐烂数字常常是【裸 number】(`"observed_generation": 8`、`"artifacts": 264`),
//   PATTERNS 只抓中文量词与版本串,一个都不命中;而 JSON 又【不能内联标记】(整文件一段 + 绑定必须同行,
//   往里写 `<!-- fact -->` 就不是合法 JSON 了)。实测代价:state/status.json 在扫描面内却 0 条红 —— 最误导人的台账判据覆盖不到。
// 做法=【专门的绑定键】:会腐烂的字段名登记在 JSON_NUM_KEYS,每个 `<文件>#<字段名>` 必须在 JSON_NUM_BINDINGS 里有绑定;
//   绑定档位与文本档同源(fact / fact-historical),判定直接复用 checkFact/checkHistorical —— 不复制第二份逻辑。
// 边界(诚实声明,回执里同文):① 只覆盖登记过的字段名,同一文件里别的数值(时间戳、评分、内部计数)仍不判;
//   ② 字段改名/搬走/变成非数值 → 登记悬空,判红(不允许静默失效);③ 绑定只保证"这个数被一句可跑命令或一条带日期的留档行盯着",
//   不保证它一定正确 —— 值与实况对不上时,fact 复跑失败或留档行被读者复核才会暴露。
export const JSON_NUM_KEYS = ['observed_generation', 'artifacts']
export const JSON_NUM_BINDINGS = {
  // 两个字段的留档行都在文件自己身上:snapshot.这是什么 = 快照声明(写明 as-of 与"不是当前状态"),
  // desired_state.artifacts_note = 该数字的复算来历(何时、用什么命令算出来的)。
// =============================================================================
// 命令复跑器:按 cmd 去重(memo) + 有界并发
// =============================================================================
// 【只改调度,不改判定】prefetch 只往缓存里放结果,判定仍然跑 checkFact/checkHistorical/checkRef 同一份逻辑;
//   万一预取漏了,run() 会退化成同步 spawnSync(慢,但判定一模一样)—— 所以正确性不依赖预取的完备性。
// 【结果形状刻意与 spawnSync 同形】error 存【消息串】而不是 Error 对象 ⇒ checkFact 的三条红文案逐字不变。
function spawnSyncResult(root, cmd) {
  const r = spawnSync(cmd, { cwd: root, shell: true, encoding: 'utf8', timeout: CMD_TIMEOUT_MS })
  return { error: r.error ? r.error.message : null, status: r.status, stdout: r.stdout ?? '', stderr: r.stderr ?? '' }
}

// 异步版:与 spawnSyncResult 同形的返回值,同一条 shell 调用方式(shell:true + cwd),同一条超时上限。
//   超时的文案写成 spawnSync 的 ETIMEDOUT 形态 —— 这条分支在真树上不可达(唯一命令里没有挂死命令),
//   写成同形是为了“所有分支的 stdout 都与改造前一致”这句话没有例外。
function spawnAsyncResult(root, cmd) {
  return new Promise((resolve) => {
    let stdout = '', stderr = '', settled = false, timer = null
    const finish = (res) => { if (settled) return; settled = true; if (timer) clearTimeout(timer); resolve(res) }
    let child
    try { child = spawn(cmd, { cwd: root, shell: true }) } catch (e) { finish({ error: e.message, status: null, stdout, stderr }); return }
    timer = setTimeout(() => { try { child.kill() } catch { /* 已退 */ } finish({ error: `spawnSync ${cmd} ETIMEDOUT`, status: null, stdout, stderr }) }, CMD_TIMEOUT_MS)
    child.stdout.on('data', (d) => { stdout += d })
    child.stderr.on('data', (d) => { stderr += d })
    child.on('error', (e) => finish({ error: e.message, status: null, stdout: String(stdout), stderr: String(stderr) }))
    child.on('close', (status) => finish({ error: null, status, stdout: String(stdout), stderr: String(stderr) }))
  })
}

function makeRunner(root, jobs = DEFAULT_JOBS) {
  const cache = new Map()   // cmd -> 结果(唯一命令只跑一次)
  const hits = new Map()    // cmd -> 被几条事实句用到(复用证据,不是“跳过”证据)
  let calls = 0
  let spawns = 0
  const put = (cmd, res) => { if (!cache.has(cmd)) { cache.set(cmd, res); spawns++ } }
  return {
    jobs,
    // 同步取用:命中缓存就复用结果,未命中就现在跑一次并落缓存。
    run(cmd) {
      calls++
      hits.set(cmd, (hits.get(cmd) ?? 0) + 1)
      if (!cache.has(cmd)) put(cmd, spawnSyncResult(root, cmd))
      return cache.get(cmd)
    },
    // 预取:只把结果放进缓存,不放判定。jobs 个 worker 从同一条有序队列里取活。
    async prefetch(cmds) {
      const queue = cmds.filter((c) => !cache.has(c))
      let next = 0
      const worker = async () => {
        while (next < queue.length) {
          const cmd = queue[next++]
          if (cache.has(cmd)) continue
          put(cmd, await spawnAsyncResult(root, cmd))
        }
      }
      await Promise.all(Array.from({ length: Math.max(1, Math.min(jobs, queue.length)) }, worker))
    },
    stats: () => ({ jobs, calls, uniq: cache.size, spawns, reuse: Math.max(0, calls - cache.size), hits }),
  }
}

// 默认文档集(唯一约定:INSTALL.md 顶部一节):散文类事实源,不含任务文件与 review 目录下的历史实验记录。
// 【2026-09-27 扩面】接手人最先读到的三份根文档(HANDOVER.md / RELEASE.md / NEXT-SESSION.md)原先不在扫描面内,
// 边界(有意保留,不改):值【整体】被转义的畸形输入(`ref=\"y\"`)返回 null —— 那是契约外输入,
// fail-closed 比"顺手把它修好"更安全(修好等于悄悄扩大契约)。此行为由 selftest 的 N8b 锁住。
export function attr(payload, name) {
  const m = payload.match(new RegExp(name + '\\s*=\\s*"((?:[^"\\\\]|\\\\.)*)"')) ?? payload.match(new RegExp(name + "\\s*=\\s*'([^']*)'"))
  return m ? m[1].replace(/\\(["\\])/g, '$1') : null
}

// 段 = 空行分隔的连续行;段内任何一条绑定覆盖该段所有事实句(表格整块一行一个绑定,不然每行都要贴标记)。
function segments(lines) {
  const segs = []
  let cur = null
  lines.forEach((line, i) => {
    if (!line.trim()) { cur = null; return }
    if (!cur) { cur = { from: i, to: i, lines: [] }; segs.push(cur) }
    cur.to = i
    cur.lines.push(i)
  })
  return segs
}

export function scanText(text, where, root = ROOT) {
  const lines = text.split(/\r?\n/)
  const binds = []            // { line, kind, payload, expect, hide }
  const unknownAt = new Map() // 行号 -> [why]:未知档先在扫描期记下,判红时按行序插入
  lines.forEach((raw, i) => {
    const markers = [...raw.matchAll(MARKER_RE)]
    for (const m of markers) binds.push({ line: i, kind: m[1], payload: m[2], expect: m[1] === 'fact' ? attr(m[2], 'expect') : null, hide: REF_ONLY_LINE_RE.test(raw.trim()) })
    for (const m of raw.matchAll(UNKNOWN_KIND_RE)) {
      if (!BINDING_KINDS.includes(m[1])) unknownAt.set(i, [...(unknownAt.get(i) ?? []), `未知绑定档 ${m[1]}(白名单只有 ${BINDING_KINDS.join(' / ')};名字不认识=这条标记不会被采纳)`.slice(0, 200)])
    }
    if (!markers.length) for (const m of raw.matchAll(REF_INLINE_RE)) binds.push({ line: i, kind: 'ref', payload: `${m[1]}:${m[2]}`, hide: false })
  })
  const scope = new Map()     // 段起点 -> 该段的绑定
  for (const seg of segments(lines)) scope.set(seg.from, binds.filter((b) => b.line >= seg.from && b.line <= seg.to))
  const segOf = new Map()
  for (const seg of segments(lines)) for (const i of seg.lines) segOf.set(i, seg.from)
  const ext = path.extname(where)

  const reds = []
  const counters = { bindings: binds.length, facts: 0, historical: binds.filter((b) => b.kind === 'fact-historical').length }
  lines.forEach((raw, i) => {
    // 未知档先判红,且必须早于下面任何 return —— 否则"标记写了但没被看见"还是静默通过。
    for (const why of unknownAt.get(i) ?? []) reds.push({ where, line: i + 1, why, text: norm(raw).slice(0, 120) })
    if (REF_ONLY_LINE_RE.test(raw.trim())) return   // 纯标记行不是事实句
    const hits = judgeable(raw, ext)
    if (!hits.length) return
    counters.facts++
    // JSON 无空行分段(整文件一段),段级继承等于一条注释绑定全文件 —— 那里的绑定必须同行。
    const own = (ext === '.json' ? binds.filter((b) => b.line === i) : scope.get(segOf.get(i)) ?? [])
    if (!own.length) { reds.push({ where, line: i + 1, why: `未绑定(${hits.map((h) => h.what).join('/')})`, text: norm(raw).slice(0, 120) }); return }
    // 历史档不适用计数守卫:那段数字本来就与今天不同(它就是"当时为真"),它的证据是留档行本身。
    if (own.some((b) => b.kind === 'fact-historical')) return
    for (const g of raw.matchAll(GUARD_RE)) {
      if (!own.some((b) => bindingCarries(b, g[1], root))) reds.push({ where, line: i + 1, why: `绑定未覆盖计数 ${g[1]} ${g[2]}(改数字即红:绑定里没这个数)`, text: norm(raw).slice(0, 120) })
    }
  })
  return { lines, binds, reds, counters }
}

// 计数守卫:fact 看 expect 文本;ref 看被引用的那一行 —— 引用行里没这个数字 = 绑定是空的。
// 只认 expect 值,不认整段 payload:cmd 里的 'utf8' 之类的杂数字会把守卫糊过去(实测踩过)。
function bindingCarries(b, digits, root = ROOT) {
  if (b.kind === 'fact') return (b.expect ?? '').includes(digits)
  const m = b.payload.trim().match(/^(.+):(\d+)\s*$/)
  if (!m) return false
  const abs = path.isAbsolute(m[1]) ? m[1] : path.join(root, m[1])
  try { return (fs.readFileSync(abs, 'utf8').split(/\r?\n/)[Number(m[2]) - 1] ?? '').includes(digits) } catch { return false }
}

function checkRef(root, payload) {
  const m = payload.trim().match(/^(.+):(\d+)\s*$/)
  if (!m) return `ref 用法错: "${payload.trim()}"(应为 ref: path:line)`
  const rel = m[1].trim()
  const abs = path.isAbsolute(rel) ? rel : path.join(root, rel)
  if (!fs.existsSync(abs)) return `ref 指向的文件不存在: ${rel}`
  const lines = fs.readFileSync(abs, 'utf8').split(/\r?\n/)
  const n = Number(m[2])
  if (!(n >= 1 && n <= lines.length)) return `ref 行号越界: ${rel}:${n}(文件共 ${lines.length} 行)`
  if (!lines[n - 1].trim()) return `ref 指向空行: ${rel}:${n}`
  return null
}

// 历史引文档:内容"当时为真、今天已不成立",所以既不能复跑命令,也不能要求数字对得上今天。
// 它能自证的只有两件事:① 写明 as-of 日期且是真实日期;② 指向一条留档行(存在/不越界/非空)。
// ② 直接复用 checkRef —— 复制第二份判定迟早与第一份各自腐烂(旧工单的坑)。
const AS_OF_RE = /^\d{4}-\d{2}-\d{2}$/
function checkHistorical(root, payload) {
  const asOf = attr(payload, 'as-of')
  if (asOf === null) return `历史档缺 as-of: 需要 as-of="YYYY-MM-DD"(实际: "${payload.trim().slice(0, 80)}")`
  const day = asOf.trim()
  if (!AS_OF_RE.test(day)) return `历史档 as-of 格式不符: "${day}"(应为 YYYY-MM-DD,例 2026-09-22)`
  if (Number.isNaN(Date.parse(`${day}T00:00:00Z`))) return `历史档 as-of 不是真实日期: "${day}"(YYYY-MM-DD 里月/日超范围)`
  const ref = attr(payload, 'ref')
  if (ref === null || !ref.trim()) return `历史档缺 ref: 需要 ref="path:line" 指向留档行(实际: "${payload.trim().slice(0, 80)}")`
  return checkRef(root, ref)
}

function checkFact(root, payload) {
  const cmd = attr(payload, 'cmd')
  const expect = attr(payload, 'expect')
  if (!cmd || !expect) return `fact 用法错: 需要 cmd="..." 与 expect="..."(实际: "${payload.trim().slice(0, 80)}")`
  const r = spawnSync(cmd, { cwd: root, shell: true, encoding: 'utf8', timeout: 300000 })
  if (r.error) return `fact 命令跑不起来: ${cmd}(${r.error.message})`
  if (r.status !== 0) return `fact 命令 exit=${r.status}: ${cmd}(尾部: ${norm(`${r.stdout}${r.stderr}`).slice(-120)})`
  const out = norm(`${r.stdout}${r.stderr}`)
  if (!out.includes(norm(expect))) return `fact 期望未命中: ${cmd} 输出不含 "${norm(expect)}"(尾部: ${out.slice(-120)})`
  return null
}

export function checkBindings(root, scans) {
  const reds = []
  for (const s of scans) for (const b of s.binds) {
    const why = b.kind === 'fact' ? checkFact(root, b.payload)
      : b.kind === 'fact-historical' ? checkHistorical(root, b.payload)
        : checkRef(root, b.payload)
    if (why) reds.push({ where: s.where, line: b.line + 1, why, text: `<!-- ${b.kind}: ${norm(b.payload)} -->`.slice(0, 120) })
  }
  return reds
}

// 把 JSON 数值绑定的结构化条目转成文本档 payload —— 让 checkFact/checkHistorical 一份逻辑两处用。
// 转义与 attr() 的取值规则对偶:`"`→`\"`、`\`→`\\`,取回时再反解(实测往返一致,见回执)。
function jsonBindingPayload(b) {
  const q = (v) => String(v).replace(/\\/g, '\\\\').replace(/"/g, '\\"')
  if (b.kind === 'fact') return ` cmd="${q(b.cmd)}" expect="${q(b.expect)}" `
  return ` as-of="${q(b.asOf)}" ref="${q(b.ref)}" `
}

// 在 JSON 文本里定位字段所在行:绑定只能登记在工具里,但判红时仍要点名到行,不然读者不知道该动哪一行。
function jsonKeyLine(lines, key) {
  const re = new RegExp(`"${key}"\\s*:`)
  for (let i = 0; i < lines.length; i++) if (re.test(lines[i])) return i + 1
  return 1
}

// 递归收集"键名在 JSON_NUM_KEYS 里、值是 number"的叶子(嵌套对象与数组里的对象都算)。
function jsonNumLeaves(value, out = [], path = []) {
  if (Array.isArray(value)) { value.forEach((v, i) => jsonNumLeaves(v, out, [...path, String(i)])); return out }
  if (value && typeof value === 'object') {
    for (const [k, v] of Object.entries(value)) {
      if (typeof v === 'number' && JSON_NUM_KEYS.includes(k)) out.push({ key: k, path: [...path, k].join('.'), value: v })
      else jsonNumLeaves(v, out, [...path, k])
    }
  }
  return out
}

// JSON 数值判据:① 登记过的字段无绑定 → 红(不再静默);② 绑定复跑/留档行验不过 → 红;
// ③ 登记了但文档里找不到那个数值字段 → 红(悬空绑定:改名/搬走/变成字符串都不许静默失效)。
export function checkJsonNumbers(root, scans) {
  const reds = []
  const seen = new Set()
  for (const s of scans) {
    if (path.extname(s.where) !== '.json') continue
    let doc
    try { doc = JSON.parse(s.lines.join('\n')) } catch (e) {
      reds.push({ where: s.where, line: 1, why: `JSON 数值判据跑不了:文件不是合法 JSON(${e.message})`, text: '' })
      continue
    }
    for (const leaf of jsonNumLeaves(doc)) {
      const id = `${s.where}#${leaf.key}`
      seen.add(id)
      const line = jsonKeyLine(s.lines, leaf.key)
      const b = JSON_NUM_BINDINGS[id]
      if (!b) {
        reds.push({ where: s.where, line, why: `未绑定(JSON 数值 ${leaf.path}=${leaf.value};JSON 不能内联标记,须在 tools/doc-facts.mjs 的 JSON_NUM_BINDINGS 里登记 fact 或 fact-historical)`, text: norm(s.lines[line - 1]).slice(0, 120) })
        continue
      }
      const why = b.kind === 'fact' ? checkFact(root, jsonBindingPayload(b))
        : b.kind === 'fact-historical' ? checkHistorical(root, jsonBindingPayload(b))
          : `档名不认识: ${b.kind}(白名单只有 ${BINDING_KINDS.filter((k) => k !== 'ref').join(' / ')})`
      if (why) reds.push({ where: s.where, line, why: `JSON 数值绑定失败: ${why}`, text: `<!-- ${b.kind}:${norm(jsonBindingPayload(b))} -->`.slice(0, 120) })
    }
  }
  // 悬空判定只对"本次真被扫描到"的文件生效 —— 否则 selftest 用单文件沙箱扫时,注册表里的别文件名会被误判成悬空。
  for (const [id, b] of Object.entries(JSON_NUM_BINDINGS)) {
    if (seen.has(id)) continue
    const [file, key] = id.split('#')
    const s = scans.find((x) => x.where === file)
    if (!s) continue
    reds.push({ where: file, line: jsonKeyLine(s.lines, key), why: `JSON 数值绑定悬空: ${id} 在文档里找不到数值字段(字段改名/搬走/变成非数值)`, text: `<!-- ${b.kind}:${norm(jsonBindingPayload(b))} -->`.slice(0, 120) })
  }
  return reds
}

export function scan(root = ROOT, docs = DEFAULT_DOCS) {
  const { files, missing } = resolveDocs(root, docs)
  const scans = files.map((rel) => ({ where: rel, ...scanText(fs.readFileSync(path.join(root, rel), 'utf8'), rel, root) }))
  const reds = [...scans.flatMap((s) => s.reds), ...checkBindings(root, scans), ...checkJsonNumbers(root, scans)]
  // 显式声明要扫却读不到的档:一条点名该路径的红(fail-closed),不是静默跳过、也不是堆栈。
  //   为什么必须红:静默跳过会让"文档被删/改名"变成无感事件 —— 那正是 R7-B/B4 一类判据要防的。
  //   行号取 1:文件级问题在本文件里已有同款约定(checkJsonNumbers 的"文件不是合法 JSON"也落在 line 1)。
  //   追加在 reds 末尾(不是插到最前):不改变既有红线的先后,取 reds[0] 的既有语义逐字不变。
  for (const rel of missing) reds.push({
    where: rel, line: 1, text: '',
    why: `不存在（${docs === DEFAULT_DOCS ? 'DEFAULT_DOCS' : '本次 docs 参数'} 显式声明要扫它；该文档的事实句全部无法判定）`,
  })
  // 默认扫描面专属的兜底:注册表盯的文件一旦从 DEFAULT_DOCS 里掉出去,绑定会静默失效 —— 这里补一条红。
  // 传了自定义 docs(selftest 的单文件沙箱、别的消费者) 时不做这条,不然会误判成悬空。
  if (docs === DEFAULT_DOCS) for (const id of Object.keys(JSON_NUM_BINDINGS)) {
    const file = id.split('#')[0]
    if (!files.includes(file)) reds.push({ where: file, line: 1, why: `JSON 数值绑定悬空: ${id} 的宿主文件不在默认扫描面里(从 DEFAULT_DOCS 掉出去了?)`, text: '' })
  }
  return { files, scans, reds }
}

function report(r) {
  const facts = r.scans.reduce((a, s) => a + s.counters.facts, 0)
  const binds = r.scans.reduce((a, s) => a + s.counters.bindings, 0)
  const historical = r.scans.reduce((a, s) => a + s.counters.historical, 0)
  // text 为空的红线(缺文档、JSON 悬空这类"没有可引用的原文行"的)不再打一行缩进的空白。
  for (const x of r.reds) console.log(x.text ? `  ${x.where}:${x.line} ${x.why}\n      ${x.text}` : `  ${x.where}:${x.line} ${x.why}`)
  const jsonNums = r.scans.filter((s) => path.extname(s.where) === '.json').length
  // 【2026-09-27 字段顺序:新字段一律追加到行尾】head 行不只是给人看的 —— 冻结靶场
  //   state/ranges/R7-B-doc-bindings/run.mjs:173 用位置正则抓 `事实句 N 条, 绑定 N 处, 历史绑定 N 处, 红线 N 条`
  //   这一整段连续子串(B7 的插行幂等判据要真读 facts/bindings/redCount)。3f74 把 `JSON 数值键 N`
  //   插在这段中间,位置正则就整体失配 → B7 拿到的是 null,那条判据变成空转(实测:dOf 打 `红线=null/0`)。
  //   这里把新字段挪到行尾:字段内容一字未变、判据一条未动,只是让被位置解析的那一段保持连续
  //   —— “追加而非插入”是给位置解析行守的兼容纪律,不是为了让哪条变绿(挪完 B7 真读数反而生效)。
  const head = `DOC-FACTS 扫描: ${r.files.length} 个文档(含 JSON ${jsonNums}), 事实句 ${facts} 条, 绑定 ${binds} 处, 历史绑定 ${historical} 处, 红线 ${r.reds.length} 条, JSON 数值键 ${Object.keys(JSON_NUM_BINDINGS).length}`
  if (r.reds.length) { console.log(head); console.log(`DOC-FACTS FAIL: 尚有 ${r.reds.length} 条未绑定/不符(见上;判据=INSTALL.md 顶部"文档事实绑定"一节)`); return 12 }
  console.log(head); console.log('DOC-FACTS PASS: 全部事实句已绑定,且 fact 复跑命中 / ref 可定位'); return 0
}

// 用例表外置在 tests/doc-facts.jsonl:每行一个用例,三种 unit ——
//   (默认 'doc') { name, rel?, doc, extra?, want:红线数, why?:为什么正则, wantLine?:命中红线须在这一行 }
//   'attr'      { name, unit:'attr', payload, attr, want }          —— 直接断言 attr() 的返回值(取值,不只红绿)
//   'marker'    { name, unit:'marker', line, wantKind, wantPayload } —— 断言标记被"看见"成哪一档(kind 正则的回归锁)
function loadCases() {
  const raw = fs.readFileSync(CASES_FILE, 'utf8')
  return raw.split(/\r?\n/).filter((l) => l.trim()).map((l, i) => {
    try { return JSON.parse(l) } catch (e) { throw new Error(`${CASES_FILE} 第 ${i + 1} 行不是合法 JSON: ${e.message}`) }
  })
}

// 沙箱自证:每条只断言"该红/该绿"或"函数返回值",不依赖真仓库文档的当前内容 ——
// 所以文档怎么漂移都不会让自证假红/假绿。
function selftest() {
  const cases = loadCases()
  const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'doc-facts-'))
  const write = (rel, text) => { fs.mkdirSync(path.dirname(path.join(tmp, rel)), { recursive: true }); fs.writeFileSync(path.join(tmp, rel), text) }
  let failed = 0
  for (const c of cases) {
    let ok, detail = ''
    if (c.unit === 'attr') {
      const got = attr(c.payload, c.attr)
      ok = got === c.want
      detail = `实际 ${JSON.stringify(got)} 期望 ${JSON.stringify(c.want)}`
    } else if (c.unit === 'marker') {
      const ms = [...c.line.matchAll(MARKER_RE)]
      const m = ms[0]
      ok = Boolean(m) && m[1] === c.wantKind && m[2] === c.wantPayload
      detail = m ? `kind=${JSON.stringify(m[1])} payload=${JSON.stringify(m[2])}` : '未命中:这条标记根本没被看见'
    } else {
      const rel = c.rel ?? 'doc.md'
      for (const d of fs.readdirSync(tmp)) fs.rmSync(path.join(tmp, d), { recursive: true, force: true })
      write(rel, c.doc)
      for (const [k, v] of Object.entries(c.extra ?? {})) write(k, v)
      const r = scan(tmp, [rel])
      const reds = r.reds.length
      ok = reds === c.want
      if (ok && c.want && c.why) ok = r.reds.some((x) => new RegExp(c.why).test(x.why))
      if (ok && c.wantLine) ok = r.reds.some((x) => x.line === c.wantLine)
      detail = `实际红线 ${reds}: ${r.reds.map((x) => x.why).join(' | ') || '-'}`
    }
    console.log(`${ok ? 'ok  ' : 'FAIL'} ${c.name}${ok ? '' : `(${detail})`}`)
// 在 JSON 文本里定位字段所在行:绑定只能登记在工具里,但判红时仍要点名到行,不然读者不知道该动哪一行。
function jsonKeyLine(lines, key) {
  const re = new RegExp(`"${key}"\\s*:`)
  for (let i = 0; i < lines.length; i++) if (re.test(lines[i])) return i + 1
  return 1
}

// 递归收集"键名在 JSON_NUM_KEYS 里、值是 number"的叶子(嵌套对象与数组里的对象都算)。
function jsonNumLeaves(value, out = [], path = []) {
  if (Array.isArray(value)) { value.forEach((v, i) => jsonNumLeaves(v, out, [...path, String(i)])); return out }
  if (value && typeof value === 'object') {
    for (const [k, v] of Object.entries(value)) {
      if (typeof v === 'number' && JSON_NUM_KEYS.includes(k)) out.push({ key: k, path: [...path, k].join('.'), value: v })
      else jsonNumLeaves(v, out, [...path, k])
    }
  }
  return out
}

// JSON 数值判据:① 登记过的字段无绑定 → 红(不再静默);② 绑定复跑/留档行验不过 → 红;
// ③ 登记了但文档里找不到那个数值字段 → 红(悬空绑定:改名/搬走/变成字符串都不许静默失效)。
export function checkJsonNumbers(root, scans) {
  const reds = []
  const seen = new Set()
  for (const s of scans) {
    if (path.extname(s.where) !== '.json') continue
    let doc
    try { doc = JSON.parse(s.lines.join('\n')) } catch (e) {
      reds.push({ where: s.where, line: 1, why: `JSON 数值判据跑不了:文件不是合法 JSON(${e.message})`, text: '' })
      continue
    }
    for (const leaf of jsonNumLeaves(doc)) {
      const id = `${s.where}#${leaf.key}`
      seen.add(id)
      const line = jsonKeyLine(s.lines, leaf.key)
      const b = JSON_NUM_BINDINGS[id]
      if (!b) {
        reds.push({ where: s.where, line, why: `未绑定(JSON 数值 ${leaf.path}=${leaf.value};JSON 不能内联标记,须在 tools/doc-facts.mjs 的 JSON_NUM_BINDINGS 里登记 fact 或 fact-historical)`, text: norm(s.lines[line - 1]).slice(0, 120) })
        continue
      }
      const why = b.kind === 'fact' ? checkFact(root, jsonBindingPayload(b))
        : b.kind === 'fact-historical' ? checkHistorical(root, jsonBindingPayload(b))
          : `档名不认识: ${b.kind}(白名单只有 ${BINDING_KINDS.filter((k) => k !== 'ref').join(' / ')})`
      if (why) reds.push({ where: s.where, line, why: `JSON 数值绑定失败: ${why}`, text: `<!-- ${b.kind}:${norm(jsonBindingPayload(b))} -->`.slice(0, 120) })
    }
  }
  // 悬空判定只对"本次真被扫描到"的文件生效 —— 否则 selftest 用单文件沙箱扫时,注册表里的别文件名会被误判成悬空。
  for (const [id, b] of Object.entries(JSON_NUM_BINDINGS)) {
    if (seen.has(id)) continue
    const [file, key] = id.split('#')
    const s = scans.find((x) => x.where === file)
    if (!s) continue
    reds.push({ where: file, line: jsonKeyLine(s.lines, key), why: `JSON 数值绑定悬空: ${id} 在文档里找不到数值字段(字段改名/搬走/变成非数值)`, text: `<!-- ${b.kind}:${norm(jsonBindingPayload(b))} -->`.slice(0, 120) })
  }
  return reds
}

export function scan(root = ROOT, docs = DEFAULT_DOCS) {
  const { files, missing } = resolveDocs(root, docs)
  const scans = files.map((rel) => ({ where: rel, ...scanText(fs.readFileSync(path.join(root, rel), 'utf8'), rel, root) }))
  const reds = [...scans.flatMap((s) => s.reds), ...checkBindings(root, scans), ...checkJsonNumbers(root, scans)]
  // 显式声明要扫却读不到的档:一条点名该路径的红(fail-closed),不是静默跳过、也不是堆栈。
  //   为什么必须红:静默跳过会让"文档被删/改名"变成无感事件 —— 那正是 R7-B/B4 一类判据要防的。
  //   行号取 1:文件级问题在本文件里已有同款约定(checkJsonNumbers 的"文件不是合法 JSON"也落在 line 1)。
  //   追加在 reds 末尾(不是插到最前):不改变既有红线的先后,取 reds[0] 的既有语义逐字不变。
  for (const rel of missing) reds.push({
    where: rel, line: 1, text: '',
    why: `不存在（${docs === DEFAULT_DOCS ? 'DEFAULT_DOCS' : '本次 docs 参数'} 显式声明要扫它；该文档的事实句全部无法判定）`,
  })
  // 默认扫描面专属的兜底:注册表盯的文件一旦从 DEFAULT_DOCS 里掉出去,绑定会静默失效 —— 这里补一条红。
  // 传了自定义 docs(selftest 的单文件沙箱、别的消费者) 时不做这条,不然会误判成悬空。
  if (docs === DEFAULT_DOCS) for (const id of Object.keys(JSON_NUM_BINDINGS)) {
    const file = id.split('#')[0]
    if (!files.includes(file)) reds.push({ where: file, line: 1, why: `JSON 数值绑定悬空: ${id} 的宿主文件不在默认扫描面里(从 DEFAULT_DOCS 掉出去了?)`, text: '' })
  }
  return { files, scans, reds }
}

function report(r) {
  const facts = r.scans.reduce((a, s) => a + s.counters.facts, 0)
  const binds = r.scans.reduce((a, s) => a + s.counters.bindings, 0)
  const historical = r.scans.reduce((a, s) => a + s.counters.historical, 0)
  // text 为空的红线(缺文档、JSON 悬空这类"没有可引用的原文行"的)不再打一行缩进的空白。
  for (const x of r.reds) console.log(x.text ? `  ${x.where}:${x.line} ${x.why}\n      ${x.text}` : `  ${x.where}:${x.line} ${x.why}`)











































//   'attr'      { name, unit:'attr', payload, attr, want }          —— 直接断言 attr() 的返回值(取值,不只红绿)
//   'marker'    { name, unit:'marker', line, wantKind, wantPayload } —— 断言标记被"看见"成哪一档(kind 正则的回归锁)
function loadCases() {
  const raw = fs.readFileSync(CASES_FILE, 'utf8')
  return raw.split(/\r?\n/).filter((l) => l.trim()).map((l, i) => {
    try { return JSON.parse(l) } catch (e) { throw new Error(`${CASES_FILE} 第 ${i + 1} 行不是合法 JSON: ${e.message}`) }
  })
}

// 沙箱自证:每条只断言"该红/该绿"或"函数返回值",不依赖真仓库文档的当前内容 ——
// 所以文档怎么漂移都不会让自证假红/假绿。
function selftest() {
  const cases = loadCases()
  const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'doc-facts-'))
  const write = (rel, text) => { fs.mkdirSync(path.dirname(path.join(tmp, rel)), { recursive: true }); fs.writeFileSync(path.join(tmp, rel), text) }
  let failed = 0
  for (const c of cases) {
    let ok, detail = ''
    if (c.unit === 'attr') {
      const got = attr(c.payload, c.attr)
      ok = got === c.want
      detail = `实际 ${JSON.stringify(got)} 期望 ${JSON.stringify(c.want)}`
    } else if (c.unit === 'marker') {
      const ms = [...c.line.matchAll(MARKER_RE)]
      const m = ms[0]
      ok = Boolean(m) && m[1] === c.wantKind && m[2] === c.wantPayload
      detail = m ? `kind=${JSON.stringify(m[1])} payload=${JSON.stringify(m[2])}` : '未命中:这条标记根本没被看见'
    } else {
      const rel = c.rel ?? 'doc.md'
      for (const d of fs.readdirSync(tmp)) fs.rmSync(path.join(tmp, d), { recursive: true, force: true })
      write(rel, c.doc)
      for (const [k, v] of Object.entries(c.extra ?? {})) write(k, v)
      const r = scan(tmp, [rel])
      const reds = r.reds.length
      ok = reds === c.want
      if (ok && c.want && c.why) ok = r.reds.some((x) => new RegExp(c.why).test(x.why))
      if (ok && c.wantLine) ok = r.reds.some((x) => x.line === c.wantLine)
      detail = `实际红线 ${reds}: ${r.reds.map((x) => x.why).join(' | ') || '-'}`
    }
    console.log(`${ok ? 'ok  ' : 'FAIL'} ${c.name}${ok ? '' : `(${detail})`}`)
    if (!ok) failed++
  }
  fs.rmSync(tmp, { recursive: true, force: true })
  console.log(failed ? `DOC-FACTS SELFTEST FAIL: ${failed}/${cases.length}` : `DOC-FACTS SELFTEST PASS: ${cases.length}/${cases.length}`)
  return failed ? 12 : 0
}

