  const modes = ['--check', '--explain', '--selftest'].filter(has)
  if (!modes.length) { console.log(USAGE); return 1 }
  if (modes.length > 1) { console.log(`用法错: --check/--explain/--selftest 只能选一个(给了 ${modes.join(', ')})`); console.log(USAGE); return 1 }
