  const sinceRaw = pref('--since')
  let sinceMs = null
  if (sinceRaw) { const t = Date.parse(sinceRaw); if (!Number.isFinite(t)) { console.log(`用法错: --since=${sinceRaw} 不是可解析的时间`); return 1 } sinceMs = t }
  let leasesText, leasesSource
  try { const l = runLeases(leasesFile); leasesText = l.text; leasesSource = l.source } catch (e) { console.log(`CONC FAIL: ${e.message}`); return 12 }
  const opts = { root, round: pref('--round'), leasesText, leasesSource, sinceMs, wrapping: has('--wrapping'), scratch: pref('--scratch'), temp: pref('--temp') }
  let r
  try { r = evaluate(opts) } catch (e) { console.log(`CONC FAIL(fail-closed): ${e.message}`); return 12 }
  if (has('--json')) printJson(r, opts); else printReport(r, opts)
  return r.exit
}

