// ============================ ① 在跑集合:消费 taskctl leases ============================
function runLeases(leasesFile) {
  if (leasesFile) {
    const t = readText(leasesFile)
    if (t === null) throw new Error(`--leases-file 读不到: ${leasesFile}`)
    return { text: t, source: `--leases-file=${leasesFile}` }
  }
  const cli = path.join(ROOT, 'tools', 'taskctl.mjs')
  let out
  try {
    out = execFileSync(process.execPath, [cli, 'leases'], { encoding: 'utf8', maxBuffer: 64 * 1024 * 1024 })
  } catch (e) {
    throw new Error(`跑 node tools/taskctl.mjs leases 失败(在跑集合的唯一来源不可用 → fail-closed): ${e.message}`)
  }
  return { text: out, source: 'node tools/taskctl.mjs leases (文本行;该命令无 --json,见文件头 ①)' }
}



































