// 认的形态(数值 + 可选单位后缀 _mb/_gb/_bytes/_b;或对象里的 mb/gb/bytes/max_mb/budget_mb):
//   max_parallel | maxParallel | max_concurrency | concurrency | parallel | degree
//   scratch 侧:/scratch/i    temp 侧:/temp/i
function scanDecl(obj, pred, out = [], p = '') {
  if (obj === null || typeof obj !== 'object') return out
  for (const [k, v] of Object.entries(obj)) {
    const kp = p ? `${p}.${k}` : k
    if (pred.test(k)) out.push({ key: kp, value: v })
    if (v && typeof v === 'object') scanDecl(v, pred, out, kp)
  }
  return out
}
const toBytesOrMb = (key, v) => {
  if (typeof v === 'number' && Number.isFinite(v)) {
    if (/_bytes$|_b$/i.test(key)) return { mb: v / MB, raw: `${v} bytes`, key }
    if (/_gb$/i.test(key)) return { mb: v * 1024, raw: `${v} GB`, key }
    return { mb: v, raw: `${v} MB`, key }
  }
  if (v && typeof v === 'object') {
    for (const k of ['mb', 'max_mb', 'budget_mb']) if (typeof v[k] === 'number') return { mb: v[k], raw: `${v[k]} MB (${key}.${k})`, key: `${key}.${k}` }
    for (const k of ['gb', 'max_gb']) if (typeof v[k] === 'number') return { mb: v[k] * 1024, raw: `${v[k]} GB (${key}.${k})`, key: `${key}.${k}` }
    for (const k of ['bytes', 'max_bytes']) if (typeof v[k] === 'number') return { mb: v[k] / MB, raw: `${v[k]} bytes (${key}.${k})`, key: `${key}.${k}` }
  }
  return null
}
function loadDecl(root = ROOT) {
  const p = path.join(root, KERNEL_DECL_REL)
  const j = readJson(p)
  const res = { path: p, rel: KERNEL_DECL_REL, exists: j !== null, maxParallel: null, scratch: null, temp: null }
  if (j === null) return res
  for (const c of scanDecl(j, /^(max_parallel|maxParallel|max_concurrency|concurrency|parallel|degree)$/)) {
    if (typeof c.value === 'number' && Number.isFinite(c.value)) { res.maxParallel = { value: c.value, key: c.key }; break }
  }
  for (const [slot, re] of [['scratch', /scratch/i], ['temp', /temp/i]]) {
    for (const c of scanDecl(j, re)) { const conv = toBytesOrMb(c.key, c.value); if (conv) { res[slot] = conv; break } }
  }
  return res
}

