function openPool(root = ROOT) {
  const p = path.join(root, 'state', 'tasks', 'OPEN.json')
  const j = readJson(p)
  if (j === null) return { path: p, tasks: [], error: 'OPEN.json 读不到或不是合法 JSON' }
  const arr = Array.isArray(j.open) ? j.open : Array.isArray(j.tasks) ? j.tasks : null
  if (!arr) return { path: p, tasks: [], error: 'OPEN.json 里既无 open[] 也无 tasks[]' }
  const tasks = arr.map((t) => (typeof t === 'string' ? { id: t, paths: [] } : { id: String(t.id ?? t.task_id ?? '?'), paths: t.allow_write_paths ?? t.write_paths ?? [] }))
  return { path: p, tasks, error: null }
}

