        // 既不是 id 形态、又不在字典里 —— 两条判据各自成立，各判一条（同一行都点名，不是重复计数）。
        counts.shell += 1
        push('WRT-1', w.line, `空壳: law/analogy 目标 ${JSON.stringify(tgt)} 不是原理 id 形态（可核写法见 --explain 形态表）`)
      }

export function checkText(text, ctx) {
  const parsed = parseText(text, ctx.labels)
  return { ...checkParsed(parsed, ctx), parsed }
}

// ------------------------------ ④ 扫描面（运行时算，不写死文件列表） ------------------------------
// 为什么不用 tools/single-source.json 的 scan：它按 F2 语义整目录跳过 state/**（「账本与证据允许出现坏例子」），
//   而本判据的样本集按施工单就落在 state/rounds/R9/ —— 照抄它会把判据自己的样本判成不在面上（分母塌缩）。
// 所以这里用一份【声明式跳过表 + 运行时遍历】，并把跳过项与分母全部打印出来（可见，不静默）。
export const SURFACE = {
  extensions: ['.md', '.mjs', '.js', '.cjs', '.json', '.tsv', '.ps1', '.sh', '.cmd'],
  skipDirs: [
    { rel: '.git', why: '版本库元数据' },
    { rel: 'node_modules', why: '依赖' },
    { rel: 'dist', why: '构建产物' },
    { rel: 'plugins', why: '分发副本（CONS-16 逐字节防分叉，源在 skills/）' },
    { rel: '.polaris', why: '工作区本地态' },
    { rel: 'tests/ab3', why: '实验臂里整目录复制的技能副本' },
    { rel: 'state/tasks', why: '派单台账（tools/fingerprint.mjs#DISPATCH_ARTIFACTS 同款口径）：施工单原文里写的是【语法占位】而不是真引用，且台账不进判据面' },
    { rel: 'state/tmp', why: '临时区' },
  ],
  skipFilePatterns: [/\.bak-/, /\.void\.json$/, /\.claim\.json$/, /\.verify\.json$/, /\.receipt\.json$/, /\.result\.json$/],
  // 分母守卫的哨兵：扫描面里必须出现它们，否则按「分母塌缩」判红（本轮已因分母塌缩出过 17 条假 PASS）。
  sentinels: [DICT_REL, SKILL_REL, 'state/rounds/R9/warrant-samples.md'],
  // 负例夹具自声明标记：夹具按设计必须含悬空引用（否则「反例必红」这条验收不成立），
  //   故允许文件在自己头部声明 `warrant-scan: skip-references` —— 工具运行时发现它、逐条打印路径与理由后跳过。
  //   这不是静默豁免：跳过清单会连路径带理由打进 --tree 输出；同一文件在 --check 上照样逐条判红。
  selfSkipRe: /warrant-scan\s*:\s*skip-references/,
}
export function surface(root = ROOT, opts = {}) {
  const skip = opts.skipDirs ?? SURFACE.skipDirs
