    for (const e of entries) {
      const abs = path.join(d, e.name)
      const rel = path.relative(root, abs).split(path.sep).join('/')
      if (skip.some((s) => rel === (s.rel ?? s) || rel.startsWith(`${s.rel ?? s}/`))) continue
      if (e.isDirectory()) { walk(abs); continue }
      if (!exts.has(path.extname(e.name)) || skipFile.some((r) => r.test(rel))) continue
      files.push(rel)
    }
  }
    if (K.family === 'law' && !isPlaceholder && ID_RE.test(tgt)) {
      item = D.byId.get(tgt) ?? null
      if (!item) push('WRT-2', w.line, `悬空 id: ${tgt} 不在 ${D.rel}#items（现有 ${D.items.length} 条: ${[...D.byId.keys()].slice(0, 4).join(', ')}…）`)
    }
    if (K.family === 'cite' && !isPlaceholder) {
      const r = citeResolve(tgt)
      if (!r.ok) push('WRT-2', w.line, `引用对不上: ${r.why}`)
    }
    if (K.family === 'law' && !fv('applies_when')) push('WRT-2', w.line, '引用但没给「为什么适用」→ 补 applies_when:（本条为什么落在该原理的适用边界内）')

    // WRT-3：law/analogy 的推断必须给可跑证伪观测。
    if (K.family === 'law') {






































































































    try { text = fs.readFileSync(path.join(root, rel), 'utf8') } catch { continue }
    const head = toLines(text).slice(0, 30).join('\n')
    if (SURFACE.selfSkipRe.test(head)) { counts.skippedFixtures.push(rel); counts.selfSkipped += 1; continue }
    let hit = 0
    for (const [i, raw] of toLines(text).entries()) {
      const m = raw.match(refRe)
      if (!m) continue
      const kind = m[1]
      const tgt = m[2].replace(/[，。；、）】」`'"]+$/, '')
      if (!m) continue
      const kind = m[1]
      const tgt = m[2].replace(/[，。；、）】」`'"]+$/, '')
      const K = KIND_TO_STRENGTH[kind]
      if (!K) continue                       // 语法讲解里的别的词（如 `warrant: 三选一`）不算引用
      hit += 1
      counts.refs += 1
      if (!ID_RE.test(tgt)) { counts.dangling += 1; reds.push({ id: 'WRT-2', where: rel, line: i + 1, why: `空壳/非 id: law|analogy 目标 ${JSON.stringify(tgt)} 不是原理 id 形态` }); continue }
      if (!D.byId.has(tgt)) { counts.dangling += 1; reds.push({ id: 'WRT-2', where: rel, line: i + 1, why: `悬空 id: ${tgt} 不在 ${D.rel}#items` }) }
    }
    if (hit) counts.withRefs += 1
  }
  // SKILL.md 必填位（③）：找到那个槽位，并要求窗口里三选一具名 + 指向字典。
  const skill = checkSkillSlot(root)
  reds.push(...skill.reds)
  const uniq = [...new Map(reds.map((r) => [`${r.id}|${r.where}|${r.line}|${r.why}`, r])).values()]
  return { dict: D, dictAudit, files, counts, skill, notes, reds: uniq, ok: uniq.length === 0 }
}

// 输出模板里的 warrant 必填位：形态 = 某一行同时含 `warrant:` 与「必填」，且该行 ±3 行窗口里
//   ①三选一具名（obs:/law:/cite:）②指向 kernel/warrants.json。全机械，逐项点名行号。
export function checkSkillSlot(root = ROOT) {
  const rel = SKILL_REL
  const abs = path.join(root, rel)
  const reds = []





















































































































  const D = loadDict(root, dictRel)
