  const labels = loadLabels(root)
  let reds = [...D.problems.map((why) => ({ id: 'WRT-2', where: D.rel, line: null, why }))]
  reds.push(...dictAudit.reds)
  const allCounts = []
  for (const rel of files) {
    let text
    try { text = fs.readFileSync(path.join(root, rel), 'utf8') } catch (e) { console.log(`WARRANT 跳过（读不了）: ${rel} — ${e.message}`); continue }
    const r = checkText(text, { D, dictAudit: null, citeResolve: (t) => resolveCite(t, root), labels, where: rel })
    allCounts.push({ rel, ...r })
    reds.push(...r.reds)
  }
  if (stdin != null) {
    const r = checkText(stdin, { D, dictAudit: null, citeResolve: (t) => resolveCite(t, root), labels, where: '<stdin>' })
    allCounts.push({ rel: '<stdin>', ...r })
    reds.push(...r.reds)
  }
  // 口径：字典自洽（WRT-2 前半）在对字典本身的对账里判，不重复计进每个文件。
  for (const c of allCounts) {
    const k = Object.entries(c.counts.byKind).map(([a, b]) => `${a} ${b}`).join(' / ') || '无'
    console.log(`WARRANT ${c.rel}  断言 ${c.counts.asserts} 条 / 挂 warrant ${c.counts.withWarrant} / 空壳 ${c.counts.shell} / 缺挂 ${c.counts.missing} / 孤立 ${c.counts.stray} / 语法示例 ${c.counts.placeholders} / 按种类 ${k}`)
    for (const n of c.notes) console.log(`  note: ${n}`)
  }
  const uniq = [...new Map(reds.map((r) => [`${r.id}|${r.where}|${r.line}|${r.why}`, r])).values()]
  for (const r of uniq) console.log(fmtRed(r))
  const totals = allCounts.reduce((a, c) => ({ asserts: a.asserts + c.counts.asserts, w: a.w + c.counts.withWarrant, shell: a.shell + c.counts.shell, miss: a.miss + c.counts.missing }), { asserts: 0, w: 0, shell: 0, miss: 0 })
  console.log(`\nWRT 汇总: 判 ${totals.asserts} 条断言 / 挂 warrant ${totals.w} / 空壳 ${totals.shell} / 缺挂 ${totals.miss} / 红 ${uniq.length}`)
  console.log(uniq.length ? `WARRANT FAIL: ${uniq.length} 条红（逐条点名见上；字典=${D.rel} 条目 ${dictAudit.counts.items}）` : `WARRANT PASS: 断言均挂合规根据（字典=${D.rel} 条目 ${dictAudit.counts.items}，kinds=${JSON.stringify(D.kinds)} strength=${JSON.stringify(D.strength)}）`)
  process.exit(uniq.length ? 12 : 0)
}
function loadLabels(root) {
  const abs = path.join(root, VISIBLE_REL)
  if (!fs.existsSync(abs)) { console.error(`warrant-check: 缺 ${VISIBLE_REL} → 断言形态（四类标注）无权威源，fail-closed`); process.exit(12) }
  let j































































  // ---- 反例④：analogy 当 obs 写（错级）----
  const r4 = judge('- 推断: 把类比外推当观测直推。\n  warrant: obs: 类比外推。\n    cmd: node a.mjs\n    reading: exit=0\n', 'r4.md')
