  add('⑤[反]空壳 `law: 某原理` ⇒ WRT-1 红', redIds(r5).join(',') === 'WRT-1', `reds=${redIds(r5).join(',')}`)

  // ---- 反例⑥：引用但没给「为什么适用」----
  const r6 = judge('- 推断: 没给为什么适用。\n  warrant: law: amdahl-limit\n    plain: x\n    strength: analogy\n    weak: 类比\n    must_give: node a.mjs → exit 0\n', 'r6.md')
  add('⑥[反]law 缺 applies_when ⇒ WRT-2 红', redIds(r6).join(',') === 'WRT-2', `reds=${redIds(r6).join(',')}`)

  // ---- 反例⑦：obs 读数与推测分不开（推测面的数字读数里找不到）----
  const r7 = judge('- 事实: 并发度 16 时耗时没有变好。\n  warrant: obs: 实测读数。\n    cmd: node tools/conc-check.mjs --check\n    reading: 两档均在声明预算内\n', 'r7.md')
  add('⑦[反]obs 推测面数字 16 不在 reading 里 ⇒ WRT-1 红（读数与推测分离）', redIds(r7).join(',') === 'WRT-1', `reds=${redIds(r7).join(',')}`)

