  const r9why = r9.reds.map((x) => x.why).join(' ')
  add('⑨[反]strength=analogy 无弱/外推标注 ⇒ WRT-4 红', redIds(r9).join(',') === 'WRT-4' && /弱/.test(r9why), `reds=${redIds(r9).join(',')}`)


  const fakeRoot = path.join(sb, 'broken-root')
