  const ct = run(['--tree'])
  add('⑳[正]CLI --tree 真树 ⇒ exit 0', ct.code === 0, `exit=${ct.code} ${ct.err}`)

  const bad = results.filter((c) => !c[1]).length
  for (const [name, ok, detail] of results) console.log(`${ok ? 'PASS' : 'FAIL'}  ${name} — ${detail}`)
  console.log(`warrant-check selftest: ${results.length - bad}/${results.length}（反向验证 ${results.filter(([, , d]) => /\[反\]/.test(d)).length || results.filter(([n]) => /\[反\]/.test(n)).length} 条）`)
