const argv = process.argv.slice(2)
const flag = (k, d) => { const a = argv.find((x) => x.startsWith(`--${k}=`)); return a ? a.slice(k.length + 3) : d }
const root = path.resolve(flag('root', ROOT))
const dictRel = flag('dict', DICT_REL)
if (argv.includes('--selftest')) selftest()
else if (argv.includes('--explain')) { console.log(EXPLAIN); process.exit(0) }
else if (argv.includes('--tree')) runTree({ root, dictRel })
else if (argv.includes('--check')) {
  const useStdin = argv.includes('--stdin')
  const files = argv.filter((a) => !a.startsWith('--'))
  let stdin = null
  if (useStdin) { try { stdin = fs.readFileSync(0, 'utf8') } catch (e) { console.error(`warrant-check: --stdin 读不了(${e.message})`); process.exit(1) } }
  if (!files.length && stdin == null) { console.error('用法: node tools/warrant-check.mjs --check <文件...> [--stdin]'); process.exit(1) }
  runCheck({ root, dictRel, files, stdin })
} else {
  console.error('用法: node tools/warrant-check.mjs --check <文件...> [--stdin] | --tree | --explain | --selftest [--root=DIR] [--dict=REL]')
  process.exit(1)
}

