function ledgerInjection ({ id, tag, mutator, expectRedId, expectSubs, title }) {
  ensureCopy()
  const fails = []
  const before = runCheckIn(COPY)
  const brokenPath = mutateLedger(tag, mutator)
  const brokenSha = sha256File(brokenPath)
  const broken = runCheckIn(COPY, brokenPath)
  const reds = redsOf(broken.out)
  const hits = reds.filter((r) => r.id === expectRedId && expectSubs.every((s) => r.msg.includes(s) || r.raw.includes(s)))
  const brokenOk = broken.code !== 0 && hits.length > 0
  if (!brokenOk) fails.push(`注入「${title}」后期望 ${expectRedId} 判红并含 ${JSON.stringify(expectSubs)}；实测 exit=${broken.code} / ${expectRedId} 命中 ${hits.length} 条 / 全部红项: ${reds.map((r) => r.id).join(',') || '(无)'}`)
  fs.rmSync(brokenPath, { force: true })
  const injectedGone = !fs.existsSync(brokenPath)
  const restored = runCheckIn(COPY)
  const copyLedgerSha = sha256File(path.join(COPY, LEDGER_REL))
  const realLedgerSha = sha256File(path.join(REPO, LEDGER_REL))
  const restoredOk = restored.code === 0 && copyLedgerSha === realLedgerSha
  if (!restoredOk) fails.push(`复原后未回绿或副本台账与真树不逐字节相同（exit=${restored.code}, copy=${copyLedgerSha.slice(0, 16)}, real=${realLedgerSha.slice(0, 16)}）`)
  if (!injectedGone) fails.push(`注入件 ${brokenPath} 未删除`)
  if (before.code !== 0) fails.push(`破坏前副本基线不是绿的（exit=${before.code}）`)
  raw(`${id}-${tag}.txt`, block(`${id} · ${title} —— 破坏前 / 破坏后 / 复原后（全部在沙箱副本 ${COPY} 内）`, [
    { cmd: `[破坏前] node ${posix(path.relative(COPY, toolOf(COPY)))} --check --round=R9   (cwd=${posix(COPY)})`, code: before.code, ms: before.ms, out: before.out },
    { cmd: `[注入] 写沙箱台账副本 ${posix(brokenPath)}  sha256_16=${brokenSha.slice(0, 16)}（基线台账 sha256_16=${sha256File(path.join(COPY, LEDGER_REL)).slice(0, 16)}）`, code: 0, ms: 0, out: `injector=${title}\nledger_sha16(broken)=${brokenSha.slice(0, 16)}\nledger_sha16(baseline)=${sha256File(path.join(COPY, LEDGER_REL)).slice(0, 16)}\n真树台账 sha256_16=${realLedgerSha.slice(0, 16)}（本用例未碰真树）` },
    { cmd: `[破坏后] node tools/evolve.mjs --check --round=R9 --ledger=${posix(brokenPath)}`, code: broken.code, ms: broken.ms, out: broken.out },
    { cmd: `[复原] rm ${posix(brokenPath)} 后跑副本自带台账`, code: restored.code, ms: restored.ms, out: restored.out },
  ]))
  return {
    fails,
    phases: { before: before.code === 0, broken: brokenOk, restored: restoredOk },
    redHits: hits.map((h) => h.raw),
    allReds: reds.map((r) => r.id),
    detail: `破坏前 exit=${before.code} → 注入后 exit=${broken.code} 且 ${expectRedId} 命中 ${hits.length} 条（${hits[0] ? oneLine(hits[0].raw).slice(0, 160) : '—'}）→ 复原后 exit=${restored.code} 且副本台账 sha16=${copyLedgerSha.slice(0, 16)}==真树`,
  }
}

  raw(`${id}-${tag}-restored.txt`, block(`${id} · ${title} —— 【复原后】删注入件 + 副本自带台账（副本台账 sha256_16=${copyLedgerSha.slice(0, 16)} == 真树 sha256_16=${realLedgerSha.slice(0, 16)} → ${copyLedgerSha === realLedgerSha}）`, [
    { cmd: 'node tools/evolve.mjs --check --round=R9   (cwd=副本)', code: restored.code, ms: restored.ms, out: restored.out },
  ]))
  return {
    fails,
    phases: { before: before.code === 0, broken: brokenOk, restored: restoredOk },
    redHits: hits.map((h) => h.raw),
    allReds: reds.map((r) => r.id),
    detail: `破坏前 exit=${before.code} → 注入后 exit=${broken.code} 且 ${expectRedId} 命中 ${hits.length} 条（${hits[0] ? oneLine(hits[0].raw).slice(0, 160) : '—'}）→ 复原后 exit=${restored.code} 且副本台账 sha16=${copyLedgerSha.slice(0, 16)}==真树`,
  }
}

// ---------- 通用探针注入（改沙箱副本里的 tools/evolve.mjs → 逐字节复原） ----------
// patch = [{ label, find: [行...], repl: [行...] }]，按行拼接、容忍 CRLF；每处 find 必须**唯一命中**。
function applyPatch (src, patch) {
  const esc = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')
  const rx = new RegExp(patch.find.map(esc).join('\\r?\\n'), 'g')
  const hits = src.match(rx)
  need(hits && hits.length === 1, `注入锚点「${patch.label}」命中 ${hits ? hits.length : 0} 次（期望恰好 1）`)
  return src.replace(rx, () => patch.repl.join('\n'))
}
function probeInjection ({ id, tag, patches, title, expect }) {
  ensureCopy()
  const fails = []
  const toolRel = path.join('tools', 'evolve.mjs')
  const toolAbs = path.join(COPY, toolRel)
  const original = fs.readFileSync(toolAbs)
  const originalSha = sha256(original)
  const before = runProbeIn(COPY)
  let patchedTxt = original.toString('utf8')
  for (const p of patches) patchedTxt = applyPatch(patchedTxt, p)
  fs.writeFileSync(toolAbs, patchedTxt)
  const patchedSha = sha256File(toolAbs)
  const syntax = runNode(['--check', toolAbs], COPY)
  need(syntax.code === 0, `注入后的副本工具语法不过（node --check exit=${syntax.code}）: ${oneLine(syntax.out).slice(0, 300)}`)
  const broken = runProbeIn(COPY)
  const reds = redsOf(broken.out)
  const verdictLine = lineOf(broken.out, /^EVO-7 双向证明:/) ?? lineOf(broken.out, /^EVO-8 逐字节相同:/) ?? ''
  const hits = (expect.redSubs ?? []).filter((s) => broken.out.includes(s))
  const absent = (expect.mustNotContain ?? []).filter((s) => broken.out.includes(s))
  const brokenOk = broken.code !== 0 && hits.length === (expect.redSubs ?? []).length && absent.length === 0
  if (!brokenOk) fails.push(`注入「${title}」后期望 ${expect.redIds.join('/')} 判红并含 ${JSON.stringify(expect.redSubs)}、且不含 ${JSON.stringify(expect.mustNotContain)}；实测 exit=${broken.code} / 命中 ${hits.length}/${(expect.redSubs ?? []).length} / 误命中 ${JSON.stringify(absent)} / 红项 ${reds.map((r) => r.id).join(',') || '(无)'}`)
  fs.writeFileSync(toolAbs, original)
  const restoredSha = sha256File(toolAbs)
  const restoredOk = restoredSha === originalSha
  if (!restoredOk) fails.push(`副本工具未逐字节复原（${restoredSha.slice(0, 16)} != ${originalSha.slice(0, 16)}）`)
  const restored = runProbeIn(COPY)
  if (restored.code !== 0) fails.push(`复原后探针未回绿（exit=${restored.code}）`)
  if (before.code !== 0) fails.push(`破坏前副本探针不是绿的（exit=${before.code}）`)
  raw(`${id}-${tag}.txt`, block(`${id} · ${title} —— 破坏前 / 破坏后 / 复原后（全部在沙箱副本 ${COPY} 内）`, [
    { cmd: `[破坏前] node tools/evolve.mjs --probe   (cwd=${posix(COPY)}, POLARIS_TMP_ROOT=${posix(TOOL_TMP)})`, code: before.code, ms: before.ms, out: before.out },
    { cmd: `[注入] 改副本里的 tools/evolve.mjs（${patches.map((p) => p.label).join(' + ')}）  sha256_16 ${originalSha.slice(0, 16)} → ${patchedSha.slice(0, 16)}`, code: 0, ms: 0, out: patches.map((p) => `## ${p.label}\n- ${p.find.join('\n- ')}\n+ ${p.repl.join('\n+ ')}`).join('\n\n') },
    { cmd: '[破坏后] node tools/evolve.mjs --probe', code: broken.code, ms: broken.ms, out: broken.out },
    { cmd: `[复原] 写回原件字节（sha256_16=${restoredSha.slice(0, 16)}）后跑 --probe`, code: restored.code, ms: restored.ms, out: restored.out },
  ]))
  return {
    fails,
    phases: { before: before.code === 0, broken: brokenOk, restored: restoredOk && restored.code === 0 },
    brokenOut: broken.out,
    verdictLine,
    detail: `破坏前 exit=${before.code} → 注入后 exit=${broken.code}（${oneLine(verdictLine).slice(0, 150)}）→ 复原后 sha16=${restoredSha.slice(0, 16)}==原字节 且 exit=${restored.code}`,
  }
}

