  const rx = new RegExp(patch.find.map(esc).join('\\r?\\n'), 'g')
  const hits = src.match(rx)
  need(hits && hits.length === 1, `注入锚点「${patch.label}」命中 ${hits ? hits.length : 0} 次（期望恰好 1）`)
  return src.replace(rx, () => patch.repl.join('\n'))
}
