  }
  fs.writeFileSync(abs, Buffer.from(patched.text, 'utf8'))
  need((fs.readFileSync(abs, 'utf8').split(selftestTok).length - 1) === 0, '改名后源码里仍残留原旗标字面量(形态检测仍会命中, 本条注入无效)')
  const broken = fcRun(dir)
  const Pk = fcParse(broken.out)
  const line = Pk.rows.find((x) => x.id === 'FRACTAL-2' && x.detail.includes(target.rel))
  const toolLine = Pk.toolLines.find((x) => x.rel === target.rel)
  if (!line) fails.push(`把 ${target.rel} 的 ${selftestTok} 改名为 ${renamed} 后, FRACTAL-2 没有点名 ${target.rel}`)
  else {
    if (line.ok) fails.push(`改名后 FRACTAL-2 对 ${target.rel} 仍判 PASS(B4 的形态检测是恒真的)`)
    if (!line.detail.includes(`缺=${selftestTok}`)) fails.push(`红行没有点名缺的那一项 缺=${selftestTok}: ${oneLine(line.detail).slice(0, 240)}`)
  }
  if (!toolLine || toolLine.selftest !== '缺') fails.push(`逐工具读数里 ${target.rel} 的 selftest 不是"缺"(实测=${toolLine?.selftest ?? '(无行)'})`)
  const restored = restore(abs, orig, 'B5')
  const back = fcRun(dir)
  const Pr = fcParse(back.out)
  const lineBack = Pr.rows.find((x) => x.id === 'FRACTAL-2' && x.detail.includes(target.rel))
  if (lineBack) fails.push(`逐字节复原后 FRACTAL-2 仍在点名 ${target.rel}(改名的效果没有被撤干净)`)
  const toolBack = Pr.toolLines.find((x) => x.rel === target.rel)
  if (toolBack?.selftest !== 'ok') fails.push(`复原后 ${target.rel} 的 selftest 读数没有回到 ok(实测=${toolBack?.selftest ?? '(无行)'})`)
  const baseLine = Pb.rows.find((x) => x.id === 'FRACTAL-2' && x.detail.includes(target.rel))
  const detail = `副本里把 ${target.rel} 的 ${selftestTok} 改名为 ${renamed}: 该工具读数 selftest=${target.selftest} → ${toolLine?.selftest} → ${toolBack?.selftest}; FRACTAL-2 点名该工具 ${baseLine ? '破坏前就有(异常)' : '破坏前无'} → 破坏后 ${line ? '有' : '无'} → 复原后 ${lineBack ? '仍有' : '无'}; 复原 sha=${restored.sha256.slice(0, 16)}`
  raw('B5-selftest-renamed.txt', threePhase('B5 反向验证 B4: 把某工具的 --selftest 改名 —— B4 必须红并点名该工具', [FC_REL, DECL_REL], {
    before: { cmd: `POLARIS_ROOT=<副本> node <副本>/${FC_REL} --check --round=${ROUND}`, code: base.code, out: base.out, basis: `副本逐字节复制自真树, 清单 sha256=${copy.manifestSha}` },
