        ledgerDeclared: Number((f2main.detail.match(/台账共声明\s+(\d+)\s+个/) ?? [])[1] ?? NaN),
        strictMissingN: Number((f2main.detail.match(/未落盘\s+(\d+)\s+个/) ?? [])[1] ?? NaN),
        legacyN: Number((f2main.detail.match(/存量面\s+(\d+)\s+个/) ?? [])[1] ?? NaN),
        collapse: /严格面 0 个已落盘/.test(f2main.detail),
      }
    : null
  // 逐工具读数两种形态(严格面带 bytes=/syntax=, 存量面只有四项形态)。
  //   【踩过的坑】图条目里不含目录名的那些, 被测工具是按【裸文件名】打印的(它的 universe 原样
  //   来自 audit 的图), 而 audit SYN-1 的自述清单里它们同样是不带目录的名字 —— 所以下面的
  //   "图 ⊆ 逐工具读数"比对必须按 rel ∪ basename 两个口径认; 只认 rel 会得到 18 个假不符。
  //   【不许静默】看着像逐工具读数但没解析出来的行一律收集, 由用例判红(格式一变就要当场发现)。
  const toolLines = []
  const unparsedToolLines = []
  const TOOL_LINE_RE = /^\s*(严格面|存量面)\s+\S+\s+/
  for (const l of lines) {
    if (!TOOL_LINE_RE.test(l)) continue
    const m = l.match(
    const m = l.match(/^\s*(严格面|存量面)\s+(\S+)\s+bytes=(\d+)\s+check=(\S+)\s+selftest=(\S+)\s+explain=(\S+)\s+exit=(\S+?)\[([^\]]*)\]\s+syntax=(\S+)\s+→\s+(全形|不合形)\s*$/)
    if (m) {
      toolLines.push({
        face: m[1], rel: m[2], bytes: Number(m[3]),
        check: m[4], selftest: m[5], explain: m[6], exit: m[7], codes: m[8], syntax: m[9], full: m[10] === '全形', kind: 'strict',
      })
      continue
    }
    const m2 = l.match(/^\s*(严格面|存量面)\s+(\S+)\s+check=(\S+)\s+selftest=(\S+)\s+explain=(\S+)\s+exit=(\S+)\s+→\s+(全形|不合形)\s*$/)
    if (m2) {
      toolLines.push({ face: m2[1], rel: m2[2], check: m2[3], selftest: m2[4], explain: m2[5], exit: m2[6], full: m2[7] === '全形', kind: 'legacy' })
      continue
    }
    unparsedToolLines.push(l.trim())
  }
  const reds = rows.filter((r) => !r.ok).map((r) => r.raw)
  const rowKey = (r) => `${r.id}|${r.ok ? 'P' : 'F'}|${r.detail}`
  return {
    rows, layerRow, parseLayer, transposeRow, dualRow, f2rows, f2, toolLines, unparsedToolLines, reds,
    rowKeys: rows.map(rowKey).sort(),
    line: (re) => lines.find((l) => re.test(l)) ?? null,
  }
}

