#!/usr/bin/env node
// tools/fractal-check.mjs —— R9·B 分形层【只读】判定器:FRACTAL-1 / FRACTAL-2 的机械化。
// 单:id T-20260927182715-3677(施工单 = state/tasks/T-20260927182715-3677.json,brief_sha256 e65036f9a6babe2f…)
//
// ======================= 这是什么 / 为什么 / 怎么复跑 / 怎么关掉 =======================
// 【这是什么】判两条"分形层"条件(判据原文与注入方式见 state/rounds/R9/fractal-criteria.md):
//   FRACTAL-1 四槽位(declaration|criteria|witness|verdict)× 三层(task|round|release)齐备,
//             且 slots/levels/synonyms 这份单源映射表无悬空无遗漏(逐格互为转置);
//             null 格 = "本层无此键"(已登记),不是漏填 —— 但它【不是永久豁免】:实况漂移照红。
//   FRACTAL-2 工具 CLI 契约同形(--check 判 / --selftest 自证 / --explain 人读 / fail-closed 退出码 0-12-1)。
//   FRACTAL-3 三层自解释齐备(2026-09-28 新增；依据 A-20260928-06-r9b-b6-self-explanation):
//             任务层／轮次层／发布层各自声明的自解释键，在【各自声明的件】里在不在 —— 缺任一层的任一键
//             → 红并点名 `层.件.键`。件名/切点/selector 全部读声明源 #self_explanation；任务层带切点口径
//             (judged/inflight/legacy 三桶；分母=0 判红)。这判不了什么、以及为什么，见 --explain 那一节。
//             【2026-09-28 收紧：键名不再与声明同源(立案 r9-fractal3-key-table-self-shrinking)】
//             三层各两个【期望键对】冻结在本文件的 SELF_EXPLAIN_EXPECTED(= 判据期望;改它=改判据,须报批),
//             声明源的 layers.<层>.keys(判面取值)与 expected_keys(声明源自报的期望,供对账)都要与它
//             【集合相等】;多/少任一键、多/少任一层 → 红并逐项点名。改前只遍历"声明出来的键" ⇒
//             从 keys 数组删掉一个键 = 判据的判面跟着声明一起变小、照样全绿(F1 假绿家族)。
//             冻结期望自身缺失/为空/形态坏 → fail-closed 判红(不许"没有期望就不对账")。
//             名单【由图跑出】:复用 tools/audit.mjs 的 SYN-1 图机制(该判据在 tools/audit.mjs 第 164 行,
//             图函数 coreToolGraph 在第 113 行,种子 SYNTAX_SEEDS 在第 110 行)。本文件【不写第二份工具名单】:
//             只 spawn `node tools/audit.mjs --only=SYN-1` 并解析它判定行里逐字打印的那份名单;
//             读不出/被截断/自述计数与解析数不符 → fail-closed 判红(分母不可信就不许出结论)。
// 【口径单源】槽位/层/键名/CLI 契约一律从 skills/aurapolaris/kernel/fractal.json 读(只读消费,一个字节都不写它)。
//   文件缺失或缺字段 → fail-closed 并点名缺什么。
// 【判定面两段】(AGENTS.md §0.4【不追溯判红】)
//   严格面 = 本轮台账现算的工具 = ① 轮次卡 deliverables 里的 tools/*.mjs
//            ∪ ② 属于本轮的任务(allow_write_paths 起点是 state/rounds/<RID>/ 或在轮次卡里被逐字点名)所写的 tools/*.mjs。
//            默认轮次 = state/rounds 下字典序最后一轮,--round=RID 可指定。名单里没有任何写死的工具文件名。
//   存量面 = 图跑出来但不属本轮的工具:只打印命中/未命中与总数,【不计入退出码】。
// 【怎么复跑】node tools/fractal-check.mjs --check --round=R9   (0=全过 / 12=有红,逐条点名 / 1=用法错)
//            (FRACTAL-3 的红色逐条点名到 `层.件.键`，例: round.state/rounds/R7/ROUND.json.rollback)
//            node tools/fractal-check.mjs --explain             (四要素 + 3×4 矩阵表 + 第②2款定夺 + 存量分布实测)
//            node tools/fractal-check.mjs --selftest            (自证:≥10 条用例、含 ≥4 条反向验证)
// 【怎么关掉】删掉 skills/aurapolaris/kernel/fractal.json → 本工具 fail-closed 判红
//            (声明源是唯一权威;没有它就没有口径,不许自己造一份)。
// 【只读】除自证沙箱外零写入:--check 不改写任何文件,也不执行任何被测工具(只做静态读源 + node --check)。
//   自证夹具一律落 E:/AuraPolaris-tmp/T-20260927182715-3677/(可用 POLARIS_TMP_ROOT 覆盖),
//   并在 process.on('exit') + finally 双保险上清理,覆盖【正常返回 / 判红 exit 12 / 异常抛出】三种离开方式;
//   只删自己那一个子目录,永不删顶层目录。
// 【已知缺口(照实写,不假装覆盖)】FRACTAL-2 是【形态】预检,与 SYN-1 同款:静态读源 + `node --check`,不执行被测件。
//   它证明"契约在源里被声明",不证明"契约被正确执行"(一个工具可以声明了表却不用它)。
//   执行每个工具的 --check/--selftest 会写各自的沙箱与落盘件,与本单"只读"硬约束冲突,故明写为缺口。

import fs from 'node:fs'
import path from 'node:path'
import crypto from 'node:crypto'
import { execFileSync } from 'node:child_process'
import { fileURLToPath, pathToFileURL } from 'node:url'

// ---------- 常量:口径与身份 ----------
const TASK_ID = 'T-20260927182715-3677'
const TOOLDIR = path.dirname(fileURLToPath(import.meta.url))
const DECL_REL = 'skills/aurapolaris/kernel/fractal.json'      // 唯一权威(只读)
const GRAPH_REL = 'tools/audit.mjs'                            // SYN-1 图机制的宿主
const TMP_ROOT = process.env.POLARIS_TMP_ROOT ?? 'E:/AuraPolaris-tmp'
const BOX_ROOT = path.join(TMP_ROOT, TASK_ID)                  // 本单沙箱(只删这一个子目录)
// fail-closed 退出码:本工具自己按同一份契约走
const EXIT = { ok: 0, red: 12, usage: 1 }

// 判定槽【漂移探测器】:null 格不是永久豁免 —— 层记录里冒出这些顶层键 = 映射表过期。
// 为什么要有它:映射表把 task/release 的 verdict 格写成 null("本层无此键"),但"今天没有"不等于"永远没有"。
// 它只探顶层键名;判定值长什么样不进判定(值语义不可机械判),故探到就报"该格已过期,需重新登记"。
const VERDICT_PROBE = /^(verdict|verdicts|judg(e)?ment|decision|ruling|outcome|result|status|conclusion|结论|判定|裁定)$/i
// 判据槽【名字族】:轮次卡里"判据槽"可能用的键名(权威键由声明源给,这里只用来发现【多余的】判据键)。
// 为什么 entry_conditions 不在族里:它是轮次卡的【进入条件】槽,与判据槽是两件事。
//   实测代价:若用 /condition/ 这种宽正则,三张真卡会因为 entry_conditions 全部假红。
const CRITERIA_FAMILY = /^(acceptance|acceptance_criteria|criteria|criterion|exit_conditions|success_criteria|done_when|definition_of_done|completion_criteria)$/i

// ---------- 沙箱:自建自清,三种离开方式都覆盖 ----------
const BOXES = new Set()
let boxCleaned = false
function cleanupBoxes () {
  if (boxCleaned) return
  boxCleaned = true
  for (const b of BOXES) {
    // 顶层目录任何情况下不许删:只删本单那一个子目录(AGENTS.md §0.5)
    if (path.resolve(b) === path.resolve(TMP_ROOT)) continue
    if (!path.resolve(b).startsWith(path.resolve(BOX_ROOT) + path.sep)) continue
    try { fs.rmSync(b, { recursive: true, force: true }) } catch { /* 清理失败不改判定 */ }
  }
  BOXES.clear()
}
process.on('exit', cleanupBoxes)   // 正常返回 / process.exit(12) / 未捕异常三条路都会经过这里

// ---------- 读:同一份口径 ----------
const abs = (root, ...p) => path.join(root, ...p)
const readRaw = (p) => { try { return fs.readFileSync(p, 'utf8') } catch { return null } }
const readJsonAbs = (p) => { try { return JSON.parse(fs.readFileSync(p, 'utf8')) } catch { return null } }
const isFile = (p) => { try { return fs.statSync(p).isFile() } catch { return false } }
const isDir = (p) => { try { return fs.statSync(p).isDirectory() } catch { return false } }
const oneLine = (s) => String(s ?? '').replace(/\s+/g, ' ').trim()
const sha256_16 = (buf) => crypto.createHash('sha256').update(buf).digest('hex').slice(0, 16)
const posix = (p) => String(p).split(path.sep).join('/')

// ---------- 任务文件谓词单源(AGENTS.md §0.4:不许在第二处再写文件名正则) ----------
let PRED = { ok: false, why: 'taskctl.mjs 未加载' }
async function loadTaskPredicates () {
  const p = path.join(TOOLDIR, 'taskctl.mjs')
  if (!isFile(p)) return { ok: false, why: `tools/taskctl.mjs 不在磁盘上(${p})→ isTaskFile/isDerivedArtifact 谓词单源不可用` }
  try {
    const m = await import(pathToFileURL(p).href)
    if (typeof m.isTaskFile !== 'function' || typeof m.isDerivedArtifact !== 'function') {
      return { ok: false, why: 'tools/taskctl.mjs 未导出 isTaskFile/isDerivedArtifact → 谓词单源不可用' }
    }
    // FRACTAL-3 的"在飞"那一桶：收工(receiptDoneIn)与作废(isVoidedIn)必须消费 taskctl 的【同一份】谓词，
    //   不在本工具里再写一个"这单交没交/死没死"的判定（AGENTS.md §0.4 单源）。
    //   要根作用域版(In)：本工具的自证夹具在【夹具根】里判在飞，而 taskctl 模块级 TASKS 绑的是本进程的
    //   POLARIS_ROOT —— 直接复用会把夹具读数指回真树。
    if (typeof m.receiptDoneIn !== 'function' || typeof m.isVoidedIn !== 'function') {
      return { ok: false, why: 'tools/taskctl.mjs 未导出 receiptDoneIn/isVoidedIn → FRACTAL-3 的在飞判定没有单源谓词可用' }
    }
    return { ok: true, isTaskFile: m.isTaskFile, isDerivedArtifact: m.isDerivedArtifact, receiptDone: m.receiptDoneIn, isVoided: m.isVoidedIn, why: '' }
  } catch (e) {
    return { ok: false, why: `tools/taskctl.mjs 不可加载: ${oneLine(e?.message ?? e)}` }
  }
}
PRED = await loadTaskPredicates()

// ---------- 声明源:fail-closed ----------
function loadDeclaration (root) {
  const file = abs(root, DECL_REL)
  const text = readRaw(file)
  const miss = []
  if (text === null) return { ok: false, miss: [`${DECL_REL}(文件不存在或读不到)`], decl: null, text: null, sha: null }
  let j = null
  try { j = JSON.parse(text) } catch (e) { return { ok: false, miss: [`${DECL_REL}(不是合法 JSON: ${oneLine(e.message)})`], decl: null, text, sha: sha256_16(text) } }
  for (const k of ['slots', 'levels', 'synonyms', 'tool_cli_contract']) if (!(k in j)) miss.push(`${DECL_REL}#${k}`)
  if (!Array.isArray(j.slots) || j.slots.length === 0) miss.push(`${DECL_REL}#slots(不是非空数组)`)
  if (!j.levels || typeof j.levels !== 'object' || Array.isArray(j.levels)) miss.push(`${DECL_REL}#levels(不是对象)`)
  if (!Array.isArray(j.synonyms)) miss.push(`${DECL_REL}#synonyms(不是数组)`)
  const c = j.tool_cli_contract
  if (!c || typeof c !== 'object') miss.push(`${DECL_REL}#tool_cli_contract`)
  else {
    for (const k of ['check', 'selftest', 'explain']) if (typeof c[k] !== 'string' || !c[k]) miss.push(`${DECL_REL}#tool_cli_contract.${k}`)
    if (!c.exit || typeof c.exit !== 'object') miss.push(`${DECL_REL}#tool_cli_contract.exit`)
    else for (const k of ['ok', 'red', 'usage']) if (typeof c.exit[k] !== 'number') miss.push(`${DECL_REL}#tool_cli_contract.exit.${k}`)
  }
  if (miss.length) return { ok: false, miss, decl: j, text, sha: sha256_16(text) }
  // 逐层逐槽必须有键位(哪怕是 null)—— 映射表不能有洞
  for (const [L, m] of Object.entries(j.levels)) {
    if (!m || typeof m !== 'object' || Array.isArray(m)) { miss.push(`${DECL_REL}#levels.${L}(不是对象)`); continue }
    for (const s of j.slots) if (!(s in m)) miss.push(`${DECL_REL}#levels.${L}.${s}(槽位缺键位)`)
    for (const k of Object.keys(m)) if (!j.slots.includes(k)) miss.push(`${DECL_REL}#levels.${L}.${k}(不是声明的槽位名 → 悬空)`)
  }
  for (const row of j.synonyms) {
    if (!row || typeof row !== 'object') { miss.push(`${DECL_REL}#synonyms(有非对象行)`); continue }
    if (!j.slots.includes(row.concept)) miss.push(`${DECL_REL}#synonyms.concept=${JSON.stringify(row.concept)}(不是声明的槽位名 → 悬空)`)
    for (const L of Object.keys(j.levels)) if (!(L in row)) miss.push(`${DECL_REL}#synonyms[concept=${row.concept}].${L}(缺该层格)`)
    for (const k of Object.keys(row)) if (k !== 'concept' && !(k in j.levels)) miss.push(`${DECL_REL}#synonyms.${k}(不是声明的层名 → 悬空)`)
  }
  const concepts = j.synonyms.map((r) => r.concept)
  for (const s of j.slots) if (!concepts.includes(s)) miss.push(`${DECL_REL}#synonyms(漏了槽位 ${s} 的转置行)`)
  return { ok: miss.length === 0, miss, decl: miss.length ? j : j, text, sha: sha256_16(text) }
}

// ---------- 层记录收集(分母全部现算) ----------
function readLayers (root, rid) {
  const out = []
  // ---- 任务层 ----
  {
    const dir = abs(root, 'state', 'tasks')
    let entries = null
    try { entries = fs.readdirSync(dir) } catch { entries = null }
    const dirOk = entries !== null
    const names = (entries ?? []).filter((n) => PRED.ok && PRED.isTaskFile(n))
    const derived = (entries ?? []).filter((n) => PRED.ok && PRED.isDerivedArtifact(n))
    const records = names.map((n) => ({ file: `state/tasks/${n}`, json: readJsonAbs(path.join(dir, n)) }))
    out.push({
      layer: 'task', dirOk, records, denominator: records.length,
      source: 'state/tasks/*.json(非派生物;谓词 = tools/taskctl.mjs 导出的 isTaskFile)',
      note: `同目录派生件 ${derived.length} 份经 isDerivedArtifact 排除;目录条目共 ${(entries ?? []).length}`
    })
  }
  // ---- 轮次层 ----
  {
    const dir = abs(root, 'state', 'rounds')
    let subs = null
    try { subs = fs.readdirSync(dir, { withFileTypes: true }).filter((d) => d.isDirectory()).map((d) => d.name) } catch { subs = null }
    const dirOk = subs !== null
    const cards = (subs ?? []).filter((s) => isFile(path.join(dir, s, 'ROUND.json')))
    const records = cards.map((s) => ({ file: `state/rounds/${s}/ROUND.json`, round: s, json: readJsonAbs(path.join(dir, s, 'ROUND.json')) }))
    const withReceipt = cards.filter((s) => isFile(path.join(dir, s, 'RECEIPT.md')))
    out.push({
      layer: 'round', dirOk, records, denominator: records.length,
      source: 'state/rounds/*/ROUND.json(逐轮次目录)',
      note: `同层见证件 RECEIPT.md 存在 ${withReceipt.length}/${cards.length}(${cards.map((s) => `${s}${withReceipt.includes(s) ? ':有' : ':无'}`).join(' ')})`
    })
  }
  // ---- 发布层 ----
  {
    const records = [{ file: 'desired_state.json', json: readJsonAbs(abs(root, 'desired_state.json')) }]
    const st = readJsonAbs(abs(root, 'state', 'status.json'))
    const accN = st && st.acceptance && typeof st.acceptance === 'object' && !Array.isArray(st.acceptance) ? Object.keys(st.acceptance).length : null
    const devN = st && Array.isArray(st.deviations) ? st.deviations.length : null
    out.push({
      layer: 'release', dirOk: true, records, denominator: records.length,
      source: 'desired_state.json(发布层声明件)',
      note: `发布级判定落点(非本层键,照实登记) state/status.json#acceptance(${accN === null ? '不可读' : `${accN} 键:${Object.keys(st.acceptance).join(',')}`}) / #deviations(${devN === null ? '不可读' : `${devN} 条`})`
    })
  }

