#!/usr/bin/env node
// =============================================================================
// state/ranges/R9-B-fractal-sameness/run.mjs —— R9 靶场 B 组「分形同形性(结构面)」
//
// 【这是什么】本轮(用户 2026-09-28 第 27 行规则)三组新靶场之一。覆盖面 =
//   skills/aurapolaris/kernel/fractal.json + tools/fractal-check.mjs(R9·B 层)。
//   判据 B1–B6 逐条照 state/rounds/R9/RANGES-SPEC.md 的 B 组小节实现 —— 判据/命令/期望
//   一条不增、不减、不改(键名与期望文字逐字引自该表)。
//   【例外,B6】2026-09-28 经用户批准(A-20260928-06-r9b-b6-self-explanation)修订了 B6 的两处口径
//   (任务层加【存量口径 + 切点】、发布层改指真实承载件), 并把"缺任一层的任一键 → 红并点名 层.件.键"
//   落成 tools/fractal-check.mjs 的 FRACTAL-3; B1–B5 的判据/命令/期望 一字未动。
//
// 【为什么】三层(任务/轮次/发布)应当是同一形状(声明—判据—见证—判定), 层与层之间只是同名
//   概念的换词。"分形"好看, 但不可证伪就成了口号。本组要证的正是【可证伪】: 真删掉某一层的
//   一个槽位、真给映射表加一个未登记的判定键、真把某工具的 --selftest 改名 —— 对账工具必须
//   当场变红, 并点名到 层.槽 / 文件名 / 工具名。只有 green 没有 red = 假绿, 故 B3/B5 是
//   反向验证(破坏 → 点名 → 逐字节复原 → 回绿), 且破坏一律发生在**沙箱副本**里。
//
// 【怎么复跑】
//   node state/ranges/R9-B-fractal-sameness/run.mjs .                    # 全量
//   node state/ranges/R9-B-fractal-sameness/run.mjs --root=<仓库>
//   node state/ranges/R9-B-fractal-sameness/run.mjs . --keep              # 失败时留沙箱,调试用
//   node state/ranges/R9-B-fractal-sameness/run.mjs . --sandbox=<目录>     # 换沙箱父目录
//   node state/ranges/R9-B-fractal-sameness/run.mjs . --red-only=B3       # 现场重演反向验证的红态
//   退出码: 全绿 0 / 有用例红 1 / 用法错 2 / --red-only 现场确认红 12(红是它的正确结果)。
//   末尾打印 PASS=n FAIL=m TOTAL=n+m(只计冻结判据 B1–B6; Z1 清场单独一行计, 其失败同样使 exit≠0)。
//
// 【怎么关掉】删掉本目录 ⇒ 该组靶场不复存在(本轮覆盖面留档缺失)。判据本身不可被本文件关掉:
//   没有 --skip / --allow-* 一类开关; 要改判据只能报批(state/approvals/)。
//
// 【被测工具根怎么指 —— 踩过的坑】tools/fractal-check.mjs **没有 --root 旗标**: 其 841 行是
//   ROOT = process.env.POLARIS_ROOT ?? 第一个非 -- 位置参数 ?? '.'。实测 `--root=<副本>` 会被
//   它的 parseArgsCli 判成未知参数 → 打印 USAGE, exit 1(不是 12)。故副本读数一律用
//   【POLARIS_ROOT=<副本> + cwd=<副本> + 跑副本自己的 tools/fractal-check.mjs】。
//
// 【黑盒】不 import 被测实现的内部函数做白盒断言。读数一律取自:
//   ① 子进程的退出码与原始输出(node tools/fractal-check.mjs --check --round=R9/
//      node tools/audit.mjs <root> --only=SYN-1);
//   ② 被测源的字节(B2/B3/B4/B5/B6 的注入与复原, 复原以 sha256 相等为据);
//   ③ 声明源 skills/aurapolaris/kernel/fractal.json 的公开值(slots/levels/synonyms/tool_cli_contract，
//      以及 B6 修订后新增的 self_explanation:层→selector→件→键 + 任务层切点)。
//   唯一被 import 的是 tools/taskctl.mjs 导出的 isTaskFile/isDerivedArtifact/receiptDoneIn/isVoidedIn
//   —— 那是 AGENTS.md §0.4 点名的【任务文件枚举单源】与【收工判定单源】, 本文件刻意不在第二处
//   再写一份文件名正则或"这单交没交"的谓词。
//
// 【读数与 revision】被测件在跑动期间可能被同仓其它在跑单改写(本单实测发生过)。每条读数一律按
//   开工时读到的 sha256_16 钉住(raw/B-INFO-pins.txt), 末尾另印收工对照。读数只对那个 sha 成立;
//   本文件是【可复跑的活 harness】, 复跑即刷新读数(冻结的是判据与期望, 不是读数)。
//
// 【数字一律运行期派生】分母(任务指针数 / 轮次卡数 / 图跑出的工具数 / 严格面条数)全部现算,
//   本文件里没有任何写死的分母; 工具名只在"从运行期读数里选目标"时出现, 不做白名单。
// =============================================================================
import fs from 'node:fs'
import path from 'node:path'
import crypto from 'node:crypto'
import { spawnSync } from 'node:child_process'
import { pathToFileURL } from 'node:url'

// ---------- 小工具 ----------
const sha256 = (b) => crypto.createHash('sha256').update(b).digest('hex')
const sha16 = (p) => sha256(fs.readFileSync(p)).slice(0, 16)
const posix = (p) => String(p).split(path.sep).join('/')
const oneLine = (s) => String(s ?? '').replace(/\s+/g, ' ').trim()
const nowIso = () => new Date().toISOString()
const isFile = (p) => { try { return fs.statSync(p).isFile() } catch { return false } }
const isDir = (p) => { try { return fs.statSync(p).isDirectory() } catch { return false } }
const readRaw = (p) => { try { return fs.readFileSync(p, 'utf8') } catch { return null } }
const readJsonAbs = (p) => { try { return JSON.parse(fs.readFileSync(p, 'utf8')) } catch { return null } }
function need (cond, msg) { if (!cond) throw new Error(msg) }
const esc = (k) => k.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')

// ---------- 参数 ----------
const argv = process.argv.slice(2)
const flagVal = (name) => argv.find((a) => a.startsWith(`--${name}=`))?.slice(name.length + 3) ?? null
const positional = argv.filter((a) => !a.startsWith('--'))
const KEEP = argv.includes('--keep')
const RED_ONLY = flagVal('red-only')
const ROUND = flagVal('round') ?? 'R9'

function resolveRepoRoot () {
  const raw = flagVal('root') ?? positional[0] ?? '.'
  const abs = path.resolve(raw)
  if (!isFile(path.join(abs, 'tools', 'fractal-check.mjs'))) return null
  if (!isFile(path.join(abs, 'tools', 'audit.mjs'))) return null
  if (!isFile(path.join(abs, 'skills', 'aurapolaris', 'kernel', 'fractal.json'))) return null
  if (!isDir(path.join(abs, 'state', 'rounds'))) return null
  if (!isDir(path.join(abs, 'state', 'tasks'))) return null
  return abs
}
const REPO = resolveRepoRoot()
if (!REPO) {
  console.log('USAGE FAIL: 找不到仓库根(缺 tools/fractal-check.mjs 或 tools/audit.mjs 或')
  console.log('            skills/aurapolaris/kernel/fractal.json 或 state/rounds 或 state/tasks)。')
  console.log('用法: node state/ranges/R9-B-fractal-sameness/run.mjs .')
  process.exit(2)
}
const RANGE_DIR = path.join(REPO, 'state', 'ranges', 'R9-B-fractal-sameness')
const RAW_DIR = path.join(RANGE_DIR, 'raw')
const FC_REL = 'tools/fractal-check.mjs'
const DECL_REL = 'skills/aurapolaris/kernel/fractal.json'

// 施工单点名的沙箱父目录。找不到时退回 <仓库祖父>/<仓库名>-tmp —— 【不回退到系统临时目录】
// (仓库 forbid_paths 第一条就是家目录, %TEMP% 在家目录下)。
const MANDATED_SANDBOX_PARENT = 'E:\\AuraPolaris-tmp'
const SANDBOX_PARENT = path.resolve(flagVal('sandbox') ?? (
  process.platform === 'win32' && fs.existsSync(MANDATED_SANDBOX_PARENT)
    ? MANDATED_SANDBOX_PARENT
    : path.join(path.dirname(path.dirname(REPO)), `${path.basename(REPO)}-tmp`)
))
const BOX_PREFIX = 'R9-B-fractal-sameness-'
const BOX = path.join(SANDBOX_PARENT, `${BOX_PREFIX}${process.pid}-${Date.now()}`)
const BOX_TMP = path.join(BOX, '_tmp')
if (posix(BOX).toLowerCase().startsWith(posix(REPO).toLowerCase() + '/')) {
  console.log(`USAGE FAIL: 沙箱 ${BOX} 落在仓库内(${REPO}), 拒绝施工`)
  process.exit(2)
}

// =============================================================================
// 沙箱清理挂在退出路径上(依据 A-20260928-07 本条修订)
// =============================================================================
// 【为什么】原先只有 Z1(正常收尾)与 --red-only 的三个分支各自 rmSync 一次: 判红走
//   process.exit(12)、未抛获异常、被中断三种离开方式都会跳过它 ⇒ 整仓副本留在盘上
//   (AGENTS.md §0.5 的 r8-tool-tempdir-no-finally 口径; 六工具本体全部合规, 只有靶场不合规)。
// 【口径】BOX 一算出来就挂 process.on('exit', …) —— Node 在正常退出、process.exit()、
//   未抛获异常(exit code 1)三种情况下都会触发 'exit' 事件; SIGINT/SIGTERM 另挂钩子覆盖"被中断"。
//   清理幂等; 只删本单建的那一个子目录, 顶层目录任何情况下不删; --keep 时不动。
//   只在"退出时沙箱还在"(= Z1 没跑到)时印一行 ⇒ 正常跑动的输出逐字不变。
function removeBox () {
  if (KEEP) return !fs.existsSync(BOX)
  // 硬保险: 绝不删顶层目录本身(只删本单建的那一个子目录)
  const abs = path.resolve(BOX)
  const parent = path.resolve(SANDBOX_PARENT)
  if (abs === parent || !abs.startsWith(parent + path.sep)) return false
  try { fs.rmSync(abs, { recursive: true, force: true }) } catch { /* 下面回读复核 */ }
  if (fs.existsSync(abs)) {
    // 兜底: Windows 上路径里有以点结尾的目录时 fs.rmSync 会静默留下, 用扩展长度前缀 + cmd rd 再试
    try { spawnSync('cmd', ['/c', 'rd', '/s', '/q', `\\\\?\\${abs}`], { encoding: 'utf8' }) } catch { /* 回读复核见下 */ }
  }
  return !fs.existsSync(abs)
}
let exitPathDisposed = false
function disposeBoxOnExit (how) {
  if (exitPathDisposed) return
  exitPathDisposed = true
  if (KEEP || !fs.existsSync(BOX)) return
  const gone = removeBox()
  console.log(`[exit-path ${how}] 沙箱 ${BOX} 在退出路径上清理: 存在=${fs.existsSync(BOX)}(${gone ? '已删' : '未删掉'})`)
}
process.on('exit', () => { try { disposeBoxOnExit('exit') } catch { /* 退出路径上不许再抛 */ } })
for (const sig of ['SIGINT', 'SIGTERM']) {
  process.on(sig, () => {
    try { disposeBoxOnExit(sig) } catch { /* 同上 */ }
    process.exit(sig === 'SIGINT' ? 130 : 143)
  })
}

// ---------- 被测读数面(revision pin) ----------
const SUT_FILES = [
  'tools/fractal-check.mjs',
  'skills/aurapolaris/kernel/fractal.json',
  'tools/audit.mjs',
  'tools/round.mjs',
  'tools/taskctl.mjs',
  'state/rounds/R9/ROUND.json',
  'desired_state.json',
  'state/status.json',
]
function snapshotPins () {
  const out = []
  for (const rel of SUT_FILES) {
    const abs = path.join(REPO, rel)
    try {
      const st = fs.statSync(abs)
      out.push({ rel, sha256: sha16(abs), bytes: st.size, mtime: new Date(st.mtimeMs).toISOString(), absent: false })
    } catch { out.push({ rel, absent: true }) }
  }
  return out
}
const pinsStart = snapshotPins()
const pinOf = (rel) => pinsStart.find((p) => p.rel === rel)?.sha256 ?? '(缺)'
// ---------- pin 缺件: 机械、非静默(三组同一口径) ----------
// 【为什么】pin 表是「运行期依赖闭包」的留档。缺件原先只在表里印一个 (缺) 就过去 ⇒ 闭包退化成
//   人手清单(callchain-3 finding): 读者从读数里分辨不出「这份依赖根本不在」与「读的时候正好被别的单改没了」。
// 【口径】与 R9-A / R9-C 逐字同一套: 逐条点名 `pin 缺件 <rel>` + 一行计数;
//   有缺件 ⇒ fail-closed(计进 _summary.txt 与退出码) —— 缺件时那些读数谈不上「对齐了某个 revision」。
function pinGap (pins) {
  const miss = pins.filter((p) => p.absent).map((p) => p.rel)
  return {
    miss,
    line: miss.length
      ? `pin 缺件 ${miss.length}/${pins.length} 份: ${miss.map((rel) => `pin 缺件 ${rel}`).join('; ')}`
      : `pin 缺件 0/${pins.length} 份(声明面每份都在册且已取到 sha256_16)`,
  }
}
const pinGapStart = pinGap(pinsStart)

// ---------- 运行外部命令 ----------
// TEMP/TMP 一律指沙箱; POLARIS_ROOT 显式钉到被测根(继承来的环境变量会把被测工具指回真树)。
function subEnv (root, tmpRoot) {
  return { ...process.env, TEMP: tmpRoot, TMP: tmpRoot, POLARIS_ROOT: root }
}
// 崩溃嗅探: "正常判红"与"沙箱缺件崩掉"必须分得开 —— 后者触发用例级重试, 前者是真读数。
const CRASH_RE = /\n\s+at\s/
const CRASH_CODE_RE = /(Cannot find module|ERR_MODULE_NOT_FOUND|ENOENT:|EACCES:|EPERM:|ENOTDIR)/
function run (cmd, args, cwd, env) {
  const t0 = Date.now()
  const r = spawnSync(cmd, args, { cwd, encoding: 'utf8', timeout: 300_000, maxBuffer: 64 * 1024 * 1024, env })
  const code = typeof r.status === 'number' ? r.status : 124
  const out = `${r.stdout ?? ''}${r.stderr ?? ''}`
  const crashed = CRASH_RE.test(out) && CRASH_CODE_RE.test(out)
  return { code, out, crashed, ms: Date.now() - t0 }
}
function runNode (args, cwd, root = cwd, tmpRoot = BOX_TMP) {
  need(fs.existsSync(cwd), `沙箱工作目录不存在(疑似被外部扫掉): ${cwd}`)
  for (const rel of args.filter((a) => typeof a === 'string' && /[\\/]/.test(a) && !a.startsWith('--'))) {
    const abs = path.isAbsolute(rel) ? rel : path.join(cwd, rel)
    if (!fs.existsSync(abs)) throw new Error(`被测可执行体在沙箱里不见了(疑似被外部扫掉): ${abs}`)
  }
  const r = run(process.execPath, args, cwd, subEnv(root, tmpRoot))
  if (r.crashed) throw new Error(`子进程崩溃(exit=${r.code}, 疑似沙箱缺件): ${oneLine(r.out).slice(-260)}`)
  return r
}
// 跑被测工具: 用【该根自己的】tools/fractal-check.mjs, POLARIS_ROOT 与 cwd 都钉到该根。
// 为什么不用 --root=(见文件头): fractal-check.mjs 没有这个旗标, 传了会被判未知参数 exit 1。
function fcRun (root, extra = []) {
  const script = path.join(root, 'tools', 'fractal-check.mjs')
  return { ...runNode([script, '--check', `--round=${ROUND}`, ...extra], root, root), cmdline: `node ${posix(path.relative(REPO, script)) || script} --check --round=${ROUND}` }
}

// =============================================================================
// 仓库副本(整块复制 + 逐文件回验 sha)
// =============================================================================
// 副本面 = fractal-check 真正会读的四处 + 发布层声明件; 其余整块不拷。
// 为什么剔掉整棵 state/(170 MB / 14700 文件): fractal-check 只读 state/tasks(任务层分母)、
//   state/rounds(轮次层分母)、state/status.json / INSTALL.json(发布层两键的真实承载件),
//   其余是账本与历史留档; 剔掉后副本 ~20 MB / 900 文件, 建副本 < 1 s, 且**不改变任何被测
