}
const REPO = resolved.abs

// 沙箱落点:施工单点名 `E:/AuraPolaris-tmp/`。它不存在时退回「仓库父目录下 <仓库名>-tmp」,
//   【不回退到系统临时目录】(AGENTS.md §0.5:不用 %TEMP%)。
const MANDATED_SANDBOX_PARENT = 'E:\\AuraPolaris-tmp'
const SANDBOX_PARENT = path.resolve(flagVal('sandbox') ?? (
  process.platform === 'win32' && fs.existsSync(MANDATED_SANDBOX_PARENT)
    ? MANDATED_SANDBOX_PARENT
    : path.join(path.dirname(REPO), `${path.basename(REPO)}-tmp`)
))
const BOX = path.join(SANDBOX_PARENT, `R9-C-immunity-and-extinction-${process.pid}-${Date.now()}`)
// 守卫:沙箱必须在仓库外(仓库内建沙箱 = 污染被跟踪面,且 tools/immunity.mjs 复制 ROOT 时会递归复制自己)。
if (posix(BOX).toLowerCase().startsWith(posix(REPO).toLowerCase() + '/')) {
  console.log(`USAGE FAIL: 沙箱 ${BOX} 落在仓库内(${REPO}),拒绝施工`)
  process.exit(2)
}
const IMM_TMP = path.join(BOX, 'immunity-tmp')   // 被测工具的临时根也收进本靶场的沙箱里,便于整片清场

// ---------- 读数面 pin(运行期依赖闭包) ----------
// 判据读数必须能说清"属于哪个版本"。这里列的是【运行期真的被读到的东西】,
// 不是"我觉得相关的东西" —— R8 的 B8 就是栽在 pin 表 ≠ 依赖闭包上。
const PIN_FILES = [
  'tools/immunity.mjs',
  'tools/warrant-check.mjs',
  'skills/aurapolaris/kernel/immunity.json',
  'skills/aurapolaris/kernel/warrants.json',
  'skills/aurapolaris/SKILL.md',            // WRT-1 的必填位
  'state/rounds/R9/immunity.jsonl',
  'state/rounds/R9/DIGEST.jsonl',
  'state/rounds/R9/warrant-samples.md',
  'state/rounds/R9/warrant-samples-bad.md',
  'tools/judge-registry.json',              // immunity 的抽样口径来源 spot_policy
  // 被抗体注入的目标件(真树只读门要盯住它们)
  'tools/pipeline-watch.mjs',
  'tools/round.mjs',
  'tools/audit.mjs',
  'tools/conc-check.mjs',
  'tools/taskctl.mjs',
  'skills/aurapolaris/tools/tmpbox.mjs',
]
const pinsOf = (repo) => PIN_FILES.map((rel) => ({ rel, sha16: isFile(path.join(repo, rel)) ? sha16(path.join(repo, rel)) : '(缺)' }))
const pinTable = (pins) => pins.map((p) => `${p.sha16}  ${p.rel}`).join('\n')
// 【逐字节复原的基准】在动任何沙箱之前,先把真树两件"被破坏源"的 sha16 钉死。
//   复原判据比的是"副本 == 我复制它的那个原件",不是"副本 == 此刻的真树" ——
//   否则别的在跑单中途追加一行台账,就会把"复原干不干净"这条判据弄成假红(G1 另行报版本漂移)。
const SRC_LEDGER_R9_SHA16 = sha16(ledgerAbsOf2(REPO, 'R9'))
const SRC_WARRANT_SAMPLES_SHA16 = sha16(path.join(REPO, 'state', 'rounds', 'R9', 'warrant-samples.md'))
function ledgerAbsOf2 (root, rid) { return path.join(root, 'state', 'rounds', rid, 'immunity.jsonl') }

// ---------- 跑 CLI(黑盒) ----------
function runNode (script, args, { cwd, env = {}, timeout = TIMEOUT_MS } = {}) {
  const r = spawnSync(process.execPath, [script, ...args], { cwd, encoding: 'utf8', timeout, env: { ...process.env, ...env } })
  const out = `${r.stdout ?? ''}${r.stderr ?? ''}`
  return { code: typeof r.status === 'number' ? r.status : 124, out }
}
// 被测工具 A:immunity.mjs。它没有 --root 旗标(ROOT = POLARIS_ROOT ?? <工具所在目录的父目录>),
//   所以"对着副本跑"靠 POLARIS_ROOT 环境变量 + cwd 一起指到副本;真树在另一条腿上单独跑。
const runImm = (root, args) => {
  const r = runNode(path.join(REPO, 'tools', 'immunity.mjs'), args, {
    cwd: root, env: { POLARIS_ROOT: root, POLARIS_IMMUNITY_TMP: IMM_TMP }, timeout: TIMEOUT_MS,
  })
  return { ...r, cmd: `POLARIS_ROOT=<${path.basename(root)}> node tools/immunity.mjs ${args.join(' ')}` }
}
// 被测工具 B:warrant-check.mjs —— 有 --root 旗标。
const runWarrant = (root, args) => {
  const r = runNode(path.join(REPO, 'tools', 'warrant-check.mjs'), [...args, `--root=${root}`], { cwd: root, timeout: 120000 })
  return { ...r, cmd: `node tools/warrant-check.mjs ${args.join(' ')} --root=<${path.basename(root)}>` }
}

// ---------- 仓库副本(注入/破坏只在这里做) ----------
// 跳过表与被测工具自己的 copyLayout 同款(.git/state/ab3/.polaris/dist)—— 只为体积,不为省判据:
//   被判据读的输入一个都不跳。
const COPY_SKIP = ['.git', '.polaris', 'state/ab3', 'dist']
function copyRepo (dst) {
  const t0 = Date.now()
  fs.mkdirSync(dst, { recursive: true })
  fs.cpSync(REPO, dst, {
    recursive: true,
    filter: (src) => {
      const rel = posix(path.relative(REPO, src))
      if (!rel) return true
      const parts = rel.split('/')
      if (parts.includes('.git') || parts.includes('.polaris')) return false
      return !COPY_SKIP.some((s) => rel === s || rel.startsWith(s + '/'))
    },
  })
  let files = 0; let bytes = 0
  const walk = (d) => { for (const e of fs.readdirSync(d, { withFileTypes: true })) { const p = path.join(d, e.name); if (e.isDirectory()) walk(p); else if (e.isFile()) { files++; bytes += fs.statSync(p).size } } }
  walk(dst)
  return { files, bytes, ms: Date.now() - t0 }
}
