#!/usr/bin/env node
// 插件包构建器【唯一来源】:plugins/aurapolaris/ 与 .agents/plugins/marketplace.json 的每个字节都由这里算出。
//   node tools/build-plugin.mjs           # 就地生成/刷新(幂等:内容相同即跳过,陈旧文件隔离不静默删)
//   node tools/build-plugin.mjs --check   # 只读比对:磁盘 == 生成(exit 0 一致 / 12 漂移,不写任何文件)
// 为什么要一个构建器:插件包里 skills/aurapolaris 是【源】的副本,两份必须逐文件一致 —— 手改副本就是分叉。
//   所以"插件该长什么样"只在这里实现一次,kernel-consistency 的 CONS-16 直接 import buildPlan() 比对,不写第二份。
// 写进 hooks.json 的命令指向【插件内】统一入口(改功能只改脚本,不动宿主配置);不写机器绝对路径(见 DESIGN.md 铁律 3)。
import fs from 'node:fs'
import path from 'node:path'
import crypto from 'node:crypto'
import { fileURLToPath } from 'node:url'

const HERE = path.dirname(fileURLToPath(import.meta.url))
// 根约定与其余工具一致:POLARIS_ROOT 可指到包根(靶场/临时副本上跑同一份代码)
export const ROOT = path.resolve(process.env.POLARIS_ROOT ?? path.join(HERE, '..'))
export const SRC_SKILL_REL = 'skills/aurapolaris'
export const PLUGIN_REL = 'plugins/aurapolaris'
export const MARKETPLACE_REL = '.agents/plugins/marketplace.json'
export const PLUGIN_NAME = 'aurapolaris'
export const MARKETPLACE_NAME = 'aurapolaris-repo'
export const PLUGIN_SKILLS_REL = `${PLUGIN_REL}/skills/aurapolaris`
// 插件内统一入口(相对插件根)。${PLUGIN_ROOT} 是宿主展开的插件根变量 —— 这里必须是普通字符串,不能是模板串。
export const HOOK_ENTRY_REL = 'skills/aurapolaris/tools/hook.mjs'
export const PLUGIN_ROOT_VAR = '${PLUGIN_ROOT}'
// 落点策略在【接线时声明】,不靠运行期环境变量:宿主钩子跑在沙箱里(TEMP 被改写成一次性目录),
//   环境变量在那一刻未必还在;写成 argv 才跨 shell/跨 OS 同形(只用双引号 + 正斜杠)。
//   默认 workspace = 状态落工作区;取值语义与 --log-dir 见 skills/aurapolaris/tools/hook.mjs。
export const HOOK_STATE = 'workspace'
export const hookCommand = (event) => `node "${PLUGIN_ROOT_VAR}/${HOOK_ENTRY_REL}" --event=${event} --state=${HOOK_STATE}`

// 隔离目录不入账:.removed-* 是"新版删掉的旧文件"的存档,不是插件内容(与 dist/ 同一约定)。
const ignored = (rel) => rel.split('/').some((s) => s.startsWith('.removed-'))
const json = (obj) => JSON.stringify(obj, null, 2) + '\n'

export function walkFiles(absDir, base = absDir) {
  const out = []
  const stack = [absDir]
  while (stack.length) {
    const dir = stack.pop()
    let entries = []
    try { entries = fs.readdirSync(dir, { withFileTypes: true }) } catch { continue }
    for (const e of entries) {
      const p = path.join(dir, e.name)
      const rel = path.relative(base, p).split(path.sep).join('/')
      if (ignored(rel)) continue
      if (e.isDirectory()) stack.push(p)
      else if (e.isFile()) out.push(rel)
    }
  }
  return out.sort()
}

// 每条宿主事件的接线参数(超时/匹配器/状态文案)。事件本身来自 kernel/delegation.json 的 event_map(单源),
// 这里只放"宿主调用形状"的细节:没有这一条的事件也照样接线,用默认 timeout。
const HOOK_SPEC = {
  SessionStart: { timeout: 5, matcher: 'startup|resume|clear|compact', label: '会话开始记录' },
  UserPromptSubmit: { timeout: 5, label: '提示提交记录' },
  PreToolUse: { timeout: 10, matcher: 'Bash|apply_patch|Edit|Write', label: '越界写入与破坏性命令检查' },
  PostToolUse: { timeout: 8, label: '工具调用记录' },
  PreCompact: { timeout: 30, matcher: 'auto', label: '压缩前记录' },
  SubagentStart: { timeout: 5, label: '子代理开始记录' },
  Stop: { timeout: 5, label: '收尾记录' },
}

function pluginManifest(version) {
  return {
    name: PLUGIN_NAME,
    version,
    description: 'AuraPolaris: 分析、判断、取舍、验证按固定范式走,并给出证伪条件与置信等级。',
    author: { name: 'AuraPolaris' },
    skills: './skills/',
    keywords: ['reasoning', 'analysis', 'judgement', 'review', 'guardrails'],
    interface: {
      displayName: 'AuraPolaris',
      shortDescription: '分析/判断/取舍走固定范式,给出证伪条件与置信等级',
      longDescription: 'AuraPolaris 把"先分析判断、再动手"变成可机械校验的纪律:内核范式(溯因/因果/反事实/贝叶斯等 13 条 + 链式触发)、委托与视角收口、判据门禁与只读审查,以及可接线到宿主的统一 hook 入口(默认影子模式,只记录不拦)。',
      developerName: 'AuraPolaris',
      category: 'Productivity',
      capabilities: [],
      defaultPrompt: ['分析这件事的根因,并给出证伪条件', '这两个方案该选哪个,代价和风险是什么', '复盘这次判断错在哪一步'],
    },
  }
}

// 描述里【不写版本】:hooks.json 是宿主侧配置(按条目哈希绑信任),每次改包内容都连带改它,就等于逼宿主重新信任。
// 本文件只随"事件表/接线参数"变,不随包内容变 —— 这才对得上"宿主只写一条统一入口,信任一次摊到全部功能"。
function hooksConfig(events) {
  const hooks = {}
  for (const [event, internal] of Object.entries(events)) {
    const spec = HOOK_SPEC[event] ?? {}
    hooks[event] = [{
      ...(spec.matcher ? { matcher: spec.matcher } : {}),
      hooks: [{
        type: 'command',
        command: hookCommand(event),
        timeout: spec.timeout ?? 5,
        statusMessage: `AuraPolaris: ${spec.label ?? internal}(统一入口)`,
      }],
    }]
  }
  return {
    description: 'AuraPolaris: 一条统一入口按事件路由(PreToolUse 走护栏,子代理开工注入纪律;默认影子模式,确认无误后再切 enforce)。',
    hooks,
  }
}

function pluginReadme(version, events) {
  // 接线清单要和 hooks.json 里的真实命令【同形】:漏掉 --state=… 就是在文档里写一条不存在的命令。
  const lines = Object.keys(events).map((e) => `- \`${e}\` → node \`${HOOK_ENTRY_REL}\` --event=${e} --state=${HOOK_STATE}`)
  return [
    `# AuraPolaris 插件包 ${version}`,
    '',
    '本目录**由 `tools/build-plugin.mjs` 生成**:`skills/aurapolaris/` 与仓库源逐文件一致,手改会在',
    '`node tools/build-plugin.mjs --check` 与 `node tools/kernel-consistency.mjs`(CONS-16)两侧同时变红。',
    '',
    '## 结构',
    '',
    '- `.codex-plugin/plugin.json`:插件清单(不写 `hooks` 字段 —— 校验器不收;hook 走插件内 `hooks/hooks.json` 默认发现,与本机已验证插件同形状)',
    '- `skills/aurapolaris/`:技能本体(源 `skills/aurapolaris/` 的副本,由构建器逐字节生成)',
    '- `hooks/hooks.json`:宿主事件 → 插件内统一入口(默认影子模式,只记录不拦)',
    '',
    '## 接线',
    '',
    ...lines,
    '',
    '重新生成:`node tools/build-plugin.mjs`;只读比对:`node tools/build-plugin.mjs --check`(exit 12 = 漂移)。',
    '',
  ].join('\n')
}

function marketplaceFile() {
  return {
    name: MARKETPLACE_NAME,
    interface: { displayName: 'AuraPolaris(仓库内)' },
    plugins: [{
      name: PLUGIN_NAME,
      source: { source: 'local', path: `./${PLUGIN_REL}` },
      policy: { installation: 'AVAILABLE', authentication: 'ON_INSTALL' },
      category: 'Productivity',
    }],
  }
}

// 插件版本 = 内核版本 + 【内容寻址】的 cachebuster。
// 为什么需要:宿主按 version 决定"装的是不是同一份";版本号不动,改了包它也不重装(实测:缓存里仍是旧 hook.mjs)。
// 为什么不用时间戳:时间戳要么人手改(与生成物冲突,CONS-16 判分叉),要么每次 build 都变(desired_state 无从核对)。
// 内容寻址 = 包内容变→版本变,内容不变→版本不变:可复现、无人工步骤、不依赖谁记得改号。
// 只摘要 skills/aurapolaris 源树(不含 manifest/README/hooks)——否则版本进 manifest、manifest 又进摘要,成环。
export function pluginCacheBuster(root = ROOT) {
  const h = crypto.createHash('sha256')
  for (const rel of walkFiles(path.join(root, SRC_SKILL_REL))) {
    h.update(rel).update('\0').update(fs.readFileSync(path.join(root, SRC_SKILL_REL, rel)))
  }
  // hooks.json 的内容由事件表与接线参数决定，不进摘要就会出现"改了钩子但版本没变=新钩子装不进宿主"
  h.update('\0').update(JSON.stringify({ events: codexEvents(root), spec: HOOK_SPEC, state: HOOK_STATE }))
  return h.digest('hex').slice(0, 16)
}

export function codexEvents(root = ROOT) {
  return JSON.parse(fs.readFileSync(path.join(root, SRC_SKILL_REL, 'kernel', 'delegation.json'), 'utf8'))
    ?.host_capabilities?.hook_injection?.event_map?.codex ?? {}
}

export function pluginVersion(root = ROOT) {
  const base = JSON.parse(fs.readFileSync(path.join(root, SRC_SKILL_REL, 'kernel', 'index.json'), 'utf8')).version
  return `${base}+codex.${pluginCacheBuster(root)}`
}

// 纯函数:给定仓库根,算出"插件包 + 市场文件"应该是什么。--check 与 CONS-16 共用这一份。
export function buildPlan(root = ROOT) {
  const version = pluginVersion(root)
  const events = codexEvents(root)
  const files = walkFiles(path.join(root, SRC_SKILL_REL)).map((rel) => ({
    path: `${PLUGIN_SKILLS_REL}/${rel}`,
    content: fs.readFileSync(path.join(root, SRC_SKILL_REL, rel)),
  }))
  files.push({ path: `${PLUGIN_REL}/.codex-plugin/plugin.json`, content: json(pluginManifest(version)) })
  files.push({ path: `${PLUGIN_REL}/hooks/hooks.json`, content: json(hooksConfig(events)) })
  files.push({ path: `${PLUGIN_REL}/README.md`, content: pluginReadme(version, events) })
  files.push({ path: MARKETPLACE_REL, content: json(marketplaceFile()) })
  files.sort((a, b) => (a.path < b.path ? -1 : 1))
  return { version, events, files }
}

// 只读比对:三类漂移 —— 缺(计划里有磁盘没有)/ 异(内容不同)/ 多(磁盘有但计划里没有)。
export function checkPlan(root = ROOT) {
  const { files } = buildPlan(root)
  const wanted = new Map(files.map((f) => [f.path, f.content]))
  const drift = []
  for (const f of files) {
    const abs = path.join(root, f.path)
    let disk = null
    try { disk = fs.readFileSync(abs) } catch { drift.push({ kind: 'missing', path: f.path }); continue }
    if (!disk.equals(Buffer.from(f.content))) drift.push({ kind: 'differs', path: f.path })
  }
  const pluginAbs = path.join(root, PLUGIN_REL)
  if (fs.existsSync(pluginAbs)) {
    for (const rel of walkFiles(pluginAbs)) {
      const repoRel = `${PLUGIN_REL}/${rel}`
      if (!wanted.has(repoRel)) drift.push({ kind: 'extra', path: repoRel })
    }
  }
  return { files, drift }
}

function main() {
  // 参数守卫(2026-09-29 arch-v2.C42):只做参数校验,不改任何既有档的行为与输出。
  //   为什么必须有:此前无任何守卫,"--help" 与任何未识别参数都不匹配 --check → 静默落进【默认动作 = 就地写盘】,
  //   "想看用法"这个只读意图会直接改 plugins/** 与 .agents/plugins/marketplace.json。
  //   出口语义与其余生成器统一:--help/-h → 打用法 + exit 0;未识别 --xxx → 点名 + exit 1;两者都不执行默认动作。
  const flags = process.argv.slice(2).filter((a) => a.startsWith('--') || a === '-h')
  const USAGE = '用法: node tools/build-plugin.mjs [--check] [--help]   (无档=就地生成/刷新 plugins/aurapolaris/ 与 .agents/plugins/marketplace.json;--check=只读比对,exit 0=一致/12=漂移)'
  const KNOWN_FLAGS = ['--check', '--help', '-h']
  if (flags.includes('--help') || flags.includes('-h')) { console.log(USAGE); process.exit(0) }
  const badFlags = flags.filter((a) => !KNOWN_FLAGS.includes(a))
  if (badFlags.length) { console.error(`未知参数: ${badFlags.join(' ')}`); console.error(USAGE); process.exit(1) }
  const check = process.argv.includes('--check')
  const plan = buildPlan(ROOT)
  if (check) {
    const { drift } = checkPlan(ROOT)
    console.log(`插件包比对:计划 ${plan.files.length} 文件(版本 ${plan.version},宿主事件 ${Object.keys(plan.events).length} 条)`)
    for (const d of drift.slice(0, 20)) console.log(`  ${d.kind.padEnd(7)} ${d.path}`)
    if (drift.length) {
      console.log(`\n插件包 DRIFT: ${drift.length} 处(缺/异/多)—— 跑 node tools/build-plugin.mjs 重新生成`)
      process.exit(12)
    }
    console.log('插件包 PASS:磁盘与生成逐字节一致')
    process.exit(0)
  }
  const stamp = new Date().toISOString().replace(/[-:T]/g, '').replace(/\./g, '').slice(0, 14)
  const stale = []
  let written = 0
  let same = 0
  for (const f of plan.files) {
    const abs = path.join(ROOT, f.path)
    const buf = Buffer.from(f.content)
    if (fs.existsSync(abs) && fs.readFileSync(abs).equals(buf)) { same++; continue }
    fs.mkdirSync(path.dirname(abs), { recursive: true })
    fs.writeFileSync(abs, buf)
    written++
  }
  const wanted = new Set(plan.files.map((f) => f.path))
  const pluginAbs = path.join(ROOT, PLUGIN_REL)
  if (fs.existsSync(pluginAbs)) {
    for (const rel of walkFiles(pluginAbs)) {
      const repoRel = `${PLUGIN_REL}/${rel}`
      if (wanted.has(repoRel)) continue
      const dest = path.join(pluginAbs, `.removed-${stamp}`, rel)
      fs.mkdirSync(path.dirname(dest), { recursive: true })
      fs.renameSync(path.join(pluginAbs, rel), dest)
      stale.push(repoRel)
    }
  }
  console.log(`插件包生成:版本 ${plan.version},written=${written} skipped(same)=${same} quarantined=${stale.length}`)
  for (const p of stale) console.log(`  quarantined: ${p} → ${PLUGIN_REL}/.removed-${stamp}/`)
  console.log(`判据:node tools/build-plugin.mjs --check 应报 PASS(逐字节一致)`)
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) main()

