#!/usr/bin/env node
// 宿主注入面接线判定【唯一实现】:声明只在 skills/aurapolaris/tools/adapters/injection.json,判定+对账都在本文件。
// 判据(只收紧不放松,不许退化成"有文件就算接线"):
//   适配器文件在 ∧ 声明里写了机制 ∧ 证据文件都在 ∧ 本机实证通过  → 已接线
//   声明行没写机制(mechanism 缺失或过短,如 ""/"n/a")              → 红:机制未声明(四要素里的"机制"也要实判)
//   同上但注入事件未登记(声明里给了 partial)                      → 部分接线(点名缺什么)
//   声明说已接线/部分接线而本机无实证                              → 红:声称已接线但无证据
//   宿主家目录不在本机                                              → 未验证(未安装),不猜"支持"
//   声明面齐(如 dsh 的 profile 挂载块)但运行期一条非探针记录都没有  → 未验证(本机无运行期实证),不再判"已接线"
//   运行期实证的记录【必须带非空 session_id】(2026-10-11 收紧,自证 S8):护栏记录路径(pre_tool)不落该字段,
//     手喂载荷不带它就能顶绿 —— 那是 ZCode 探针照出来的假绿形状(state/reviews/zcode-rewire-20261011/readings.md §5/§6)。
//   历史记录落在别的候选落点(旧 %TEMP% / POLARIS_LOG_DIR)           → 合并读取:换落点不许让历史消失
//   热日志被截断/清掉(1MiB 档)而实证已归档到 state/evidence/       → 存档是第 4 个落点(标签 archive:),
//     仍算实证(D4 修的正是"拿会截断的热日志当唯一账本");同一条实证在两处并存 → 同形去重读成一条(见 evidenceKey)
//   调用方显式隔离了日志落点(env POLARIS_LOG_DIR 生效)             → 存档跟随同一隔离根解析(<隔离根>/live-evidence.jsonl,
//     隔离根=日志落点目录的父级),不许回落真树(C155:否则一次性探针箱会把真树存档当本机实证读进来 ⇒ 隔离失效、
//     探针基线红;口径写清并自证 = --selftest S11)
//   登记的事件没全落在桥读的那份配置里(如登记 Stop 而落地只有 3 键)  → 红:事件缺口(能力缺口必须与事实一致)
//     口径=内核 event_map[宿主] 的键 ∧ 挂载块 configPath 指向的那份配置的 hooks 键。
//     为什么算缺口而不是观读数:登记了却没落地 = 那个接线点在桥上白空着(2026-09-29 实测:登记 4/落地 3,
//       交付前自检闸门在 dsh 上从未发生);反向也一样 —— 落地了没登记 = kind=unknown 只记录不处理。
//     只加读数与缺口,【不改状态词】:状态词要与 state/host-injection-matrix.md 逐行对账,不许被单侧细节带偏。
// 对账:state/host-injection-matrix.md 的接线状态列逐宿主 == 本判定(cli/polaris.mjs doctor 的 注入= 列同源)。
// 矩阵表行格式:| 宿主 | ... | 接线状态 | ... |(宿主列不写反引号,否则对账解析不到;其它表格首列别写成纯宿主名)。
//   node tools/injection-matrix.mjs --check [--root=DIR]   # 0=一致 / 12=缺口或对账不一致 / 1=用法错
//   node tools/injection-matrix.mjs --selftest             # 沙箱红/绿:假适配器、无实证、矩阵对账三类都必须能红
// 只读:除 --selftest 在 state/reviews/probes/ 的沙箱副本内造扰动(结束即清理)外不写任何文件。
import fs from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'
import { parseHosts, HOSTS_REL } from './host-matrix.mjs'
import { stateInfo, LOG_NAME } from '../skills/aurapolaris/tools/hook.mjs'
import { candidateRoots } from '../skills/aurapolaris/tools/state-root.mjs'

export const ROOT = path.resolve(process.env.POLARIS_ROOT ?? path.join(path.dirname(fileURLToPath(import.meta.url)), '..'))
export const REGISTRY_REL = 'tools/adapters/injection.json'
export const MATRIX_REL = 'state/host-injection-matrix.md'
// 证据存档(C145):热日志是【会截断的运行件】,实证的账本在这里 —— 落点相对工作区根,唯一追加者是 tools/evidence-archive.mjs。
export const ARCHIVE_REL = 'state/evidence/live-evidence.jsonl'
// 隔离根下的存档名(C155):与真树那份【同名】,只有"根"不同 —— 调用方显式隔离了日志落点(env POLARIS_LOG_DIR 生效,
//   判定见 logSources#archive)时,存档跟随同一隔离根解析成 <隔离根>/live-evidence.jsonl,不许回落真树 state/evidence/。
//   为什么同名同形状:存档是"第 4 个落点"这件事在真树与隔离箱里是同一件事实,只有根随调用方的隔离承诺走。
export const ISO_ARCHIVE_NAME = path.basename(ARCHIVE_REL)
// 适配器只许住在这两个目录:仓库侧 tools/adapters/(本任务新增)与分发侧 skills/aurapolaris/tools/adapters/。
const ADAPTER_DIRS = ['tools/adapters', 'skills/aurapolaris/tools/adapters']
// 状态词提取:括号里的理由不参与比对。**全角/半角括号都算** —— 中文文档里天然写全角,
//   只认半角会把"未接线（开发期已卸载）"整串当成状态词,从而误报"矩阵与判定不一致"(2026-09-24 实测踩到)。
export const statusToken = (s) => String(s ?? '').split(/[(（]/)[0].trim()
export const isWired = (s) => statusToken(s) === '已接线'
export const isPartial = (s) => statusToken(s) === '部分接线'

export function loadRegistry(root = ROOT) {
  const file = path.join(root, REGISTRY_REL)
  if (!fs.existsSync(file)) throw new Error(`找不到注入面登记表: ${file}`)
  const reg = JSON.parse(fs.readFileSync(file, 'utf8'))
  if (!reg.hosts || typeof reg.hosts !== 'object' || !Object.keys(reg.hosts).length) throw new Error(`${REGISTRY_REL}: 缺 hosts`)
  return reg
}

// 适配器候选=adapters/ 里以"某宿主名-"开头的文件(如 codex-hook.mjs / dsh-hooks.json)。
// 候选在而登记表没这一行 = 有人声称接了线却没有机制与证据 —— 这正是"假绿"要抓的形状。
export function adapterCandidates(root, hosts) {
  const out = []
  for (const rel of ADAPTER_DIRS) {
    const dir = path.join(root, rel)
    if (!fs.existsSync(dir)) continue
    for (const f of fs.readdirSync(dir)) {
      if (!/\.(mjs|js|json)$/.test(f)) continue
      const host = hosts.find((h) => f.startsWith(`${h.host}-`))?.host ?? null
      if (host) out.push({ file: `${rel}/${f}`, host })
    }
  }
  return out
}

// ---- 读侧取数【唯一实现】:落点候选表来自 state-root.mjs 的解析器(与钩子写侧同一张表),本文件不再自己拼路径 ----
// 为什么必须合并候选(2026-09-28 实测代价):写侧改成"按策略解析"之后,落点随宿主/启动目录/环境变化,而历史记录
//   留在【当时】的落点里 —— 真实 %TEMP% 那份有 2399 条(codex 的 session_start/subagent_start/pre_tool 全在),
//   新的工作区落点只有 45 条(dsh)。读侧只认当前落点,仪表就报"无触发记录":历史凭空消失、真接线被判成没接线。
//   于是:逐落点读 + 合并 + 每条标出来源(source 沿用解析器的标签口径)。hook-status.mjs 复用同一份(读侧只有一份实现)。
// 探针记录【唯一谓词】(施工单 C 口径):session_id 以 probe 开头,或记录里带 probe:true。
//   探针=人手工喂的一条载荷,只证明"脚本能跑",不证明"宿主真把事件送过来了" → 不算运行期实证。
export const isProbeRecord = (j) => j?.probe === true || /^probe/i.test(String(j?.session_id ?? '').trim())

// 日志候选【唯一实现】:deps 注入优先(自证沙箱钉死份数 —— 沙箱若也去合并真实候选落点,会把真实历史读进沙箱,
//   红/绿两相同时失真),否则按解析器给的候选表逐落点取同名日志。
export function logSources(deps = {}) {
  const out = []
  const push = (file, source) => {
    if (!file) return
    let abs
    try { abs = path.resolve(String(file)) } catch { return }        // 解析不了的路径:跳过,不猜
    if (out.some((s) => s.file.toLowerCase() === abs.toLowerCase())) return
    out.push({ file: abs, source: String(source ?? ''), root: path.dirname(abs) })
  }
  // 第 4 个落点=证据存档(C145):热日志按大小截断/换落点/被清掉之后,带 session_id 的实证只剩存档这一份 ——
  //   读侧不带它,"已接线"的历史就随截断一起消失(D4)。文件不在盘上照常跳过(readMergedLog 记 exists=false),
  //   口径一字不改:仍要求记录带非空 session_id 且非探针。
  //   两个例外,都是为了"沙箱不与真实树串味":① deps 钉死来源(沙箱)且没给 deps.root 时【不带】——
  //     带了会把真实存档读进沙箱,红/绿两相同时失真(与 deps.logFile 注入同一个理由);
  //     ② --collect 读热日志那一路用 deps.skipArchive 显式关掉(它自己就是写存档的那个,不该把存档当来源回读)。
  //   C155 隔离语义【修在载体上】:调用方显式隔离了日志落点(候选表里 env:POLARIS_LOG_DIR 生效)⇒ 存档【必须】跟随
  //     同一隔离根,不许回落真树 —— 否则一次性探针箱(只钉 POLARIS_LOG_DIR/cwd/TEMP)会把真树存档(实测 158 条
  //     真实会话)当本机实证读进来,"只有探针记录 ⇒ latest_trigger=null"这条判据当场失效(探针基线红,C155 实测)。
  //     隔离根口径【唯一,自证 = --selftest S11】= 日志落点目录的父级:真树里日志落点是 <工作区根>/.polaris,
  //     其父级就是工作区根(同一个"根"的语义,只是换成被隔离的那份);存档 = <隔离根>/live-evidence.jsonl。
  //     隔离箱里没放这份文件 ⇒ 读成 exists=false(不会凭空造实证);放了 ⇒ 仍能按存档判实证(隔离 ≠ 存档一律不看)。
  //   判定只消费解析器候选表的来源标签,不自己再读一遍 env(第二处落点解析会被 single-source F2-8 判红)。
  const archive = (cands) => {
    if (deps.skipArchive) return
    const pinned = !!(deps.logFile || Array.isArray(deps.logFiles) || Array.isArray(deps.stateDirs))
    if (pinned) {
      if (deps.root === undefined) return
      push(path.join(path.resolve(deps.root), ARCHIVE_REL), `archive:${ARCHIVE_REL}`)
      return
    }
    const isoLogDir = (cands ?? []).find((c) => c.source === 'env:POLARIS_LOG_DIR')?.root ?? null
    if (isoLogDir) {
      push(path.join(path.dirname(path.resolve(isoLogDir)), ISO_ARCHIVE_NAME), `archive:${ISO_ARCHIVE_NAME}@iso`)
      return
    }
    push(path.join(path.resolve(deps.root ?? ROOT), ARCHIVE_REL), `archive:${ARCHIVE_REL}`)
  }
  if (deps.logFile) { push(deps.logFile, 'deps:logFile'); archive(null); return out }
  if (Array.isArray(deps.logFiles)) { for (const f of deps.logFiles) push(f?.file ?? f, f?.source ?? 'deps:logFiles'); archive(null); return out }
  if (Array.isArray(deps.stateDirs)) { for (const d of deps.stateDirs) push(path.join(d, LOG_NAME), 'deps:stateDirs'); archive(null); return out }
  let cands = []
  try { cands = candidateRoots({ env: process.env, cwd: process.cwd() }) } catch { cands = [] }
  for (const c of cands) push(path.join(c.root, LOG_NAME), c.source)
  // 解析器当前选中的那个落点必须在内:候选表全不可写时它会 degraded 到更低档,那一档也在表里,但显式补一条最稳。
  try { const st = stateInfo(); push(path.join(st.root, LOG_NAME), `resolve:${st.source}`) } catch { /* 解析器炸了:候选表已给出能读的那些 */ }
  archive(cands)
  return out
}

// 同形去重【唯一谓词】(C145):同一条实证在"热日志 + 存档"两个落点各出现一次时不许读成两条 ——
//   键=ts+host+kind+event+session_id+tool,保留【先出现者】(来源表里靠前的落点=热日志优先,标签也留在热日志那份)。
//   不做这层:归档一次就把 hook-status 的计数与矩阵的命中读成两条(实测真实两落点间现有 4 条同形重叠)。
export const evidenceKey = (j) => JSON.stringify([j?.ts, j?.host, j?.kind, j?.event, j?.session_id, j?.tool]
  .map((v) => (v === undefined || v === null ? '' : String(v))))

// 逐落点读 + 合并:每条记录带回 {j, file, source, probe},按 ts 升序(缺 ts 的排最前 —— 不猜时间,只保证顺序确定)。
//   合并前按 evidenceKey 同形去重(重复条数记在返回值的 duplicates 里,读数可见)。
export function readMergedLog(sources) {
  const files = []
  const records = []
  for (const s of sources) {
    const rec = { ...s, exists: false, bytes: 0, entries: 0, probe: 0, error: null }
    try {
      if (fs.existsSync(s.file)) {
        rec.exists = true
        rec.bytes = fs.statSync(s.file).size
        for (const line of fs.readFileSync(s.file, 'utf8').split(/\r?\n/)) {
          if (!line.trim()) continue
          let j = null
          try { j = JSON.parse(line) } catch { continue }
          rec.entries++
          const probe = isProbeRecord(j)
          if (probe) rec.probe++
          records.push({ j, file: s.file, source: s.source, root: s.root ?? path.dirname(s.file), probe })
        }
      }
    } catch (e) { rec.error = String(e?.message ?? e) }
    files.push(rec)
  }
  const seen = new Set()
  const kept = []
  let duplicates = 0
  for (const r of records) {
    const k = evidenceKey(r.j)
    if (seen.has(k)) { duplicates++; continue }
    seen.add(k)
    kept.push(r)
  }
  kept.sort((a, b) => String(a.j.ts ?? '').localeCompare(String(b.j.ts ?? '')))
  return { files, records: kept, duplicates }
}

// 本机实证之一:hook 日志里有没有该宿主真的触发过注入类事件(取数走候选合并;探针记录不算)
function liveHookLog(live, deps) {
  const want = new Set(live.kinds ?? [])
  const read = deps.log.files.filter((f) => f.exists)
  if (!read.length) return { ok: false, why: `无触发记录(候选落点 ${deps.log.files.length} 个,一个日志文件都没有: ${deps.log.files.map((f) => f.file).join(' | ')})` }
  const mine = deps.log.records.filter((r) => !r.probe && r.j.host === live.host)
  // 实证记录必须带非空 session_id(2026-10-11 收紧):护栏记录路径(pre_tool)不落该字段,人喂载荷不带它会被判成宿主事件
  const hit = mine.filter((r) => want.has(r.j.kind) && String(r.j.session_id ?? '').trim() !== '').at(-1)
  if (hit) return { ok: true, why: `日志实证:${hit.j.ts} ${hit.j.event} kind=${hit.j.kind}(host=${hit.j.host} session_id=${String(hit.j.session_id).slice(0, 48)}) ← ${hit.source} [${hit.root}]` }
  const noSid = mine.filter((r) => want.has(r.j.kind)).length
  const probes = deps.log.records.filter((r) => r.probe && r.j.host === live.host).length
  const extra = noSid ? `;有 ${noSid} 条 ${[...want].join('/')} 记录但都不带 session_id(不算实证:手喂载荷与护栏记录都不落该字段)` : ''
  return { ok: false, why: `无触发记录(合并 ${read.length}/${deps.log.files.length} 个落点,没有 host=${live.host} 的带 session_id 的非探针 ${[...want].join('/')}${extra}${probes ? `;该宿主只有 ${probes} 条探针记录,不算实证` : ''})` }
}

// 本机实证之二(声明面):dsh 的 profile 补丁层里有没有本仓库的挂载,且挂载指向的配置文件真的在
function profileMountDeclared(live, deps) {
  const dir = path.join(deps.dshHome, 'profiles')
  if (!fs.existsSync(dir)) return { ok: false, why: `未找到 dsh profiles 目录(${dir})` }
  const wired = []
  const broken = []
  for (const p of fs.readdirSync(dir)) {
    const f = path.join(dir, p, 'cordis.patch.yml')
    if (!fs.existsSync(f)) continue
    const text = fs.readFileSync(f, 'utf8')
    if (!text.includes(live.marker)) continue
    const cfgs = [...text.matchAll(/configPath:\s*(\S+)/g)].map((m) => m[1])
    // 挂载点自己不带协议键(那在配置文件里):这里要同时验"配置文件真在"且"它真是本仓库的桥配置"
    const missing = cfgs.filter((c) => !fs.existsSync(c) || !fs.readFileSync(c, 'utf8').includes(live.config_marker))
    if (missing.length) broken.push(`${p}(挂载指向的配置缺或不是本仓库的: ${missing.join(',')})`)
    else wired.push(p)
  }
  if (wired.length) return { ok: true, why: `profile 挂载实证:${wired.join(',')}` }
  return { ok: false, why: broken.length ? `挂载指向的配置文件不存在: ${broken.join(';')}` : '无 profile 挂载本仓库的桥(未接线)' }
}

// 运行期面【唯一谓词】:合并日志里有该宿主的非探针记录(哪种事件都算 —— 它证明的是"桥真把事件送进了统一入口")
function runtimeEvidence(live, deps) {
