function scanSessions(opts) {
  const { root, projectDir = null, all = false, cwd = process.cwd(), cache = null, probeFactory = null } = opts;
  const warnings = [];
  const files = listSessionFiles(root, projectDir);
  const targetKey = normPathKey(cwd);
