  const declared = String(wo.report_to || (wo.file ? String(wo.file).replace(/\.json$/, '.result.json') : ''));
  if (!declared) return false;
  return ledgerRelPath(root, path.resolve(root, declared)) === `state/tasks/${id}.result.json`;
}

/**
 * 每个会话一个探针：把「谁在跑哪张单」的证据从记录里抽出来。
 * 分桶：beatCall(tool/call 参数) / beatTool(tool/result) / claim / path / text。
 */
/**
 * tool/call 的调用参数（data.arguments）：记录里是转义字符串，里面往往还裹一层 JSON —— 解两层再按行看。
 * 解不动就退到第一层文本，绝不抛错（会话格式是宿主的，宽容失败）。
 */
function ledgerToolArgs(raw) {
  const m = LEDGER_ARGS_RE.exec(raw);
  if (!m) return raw;
  let text;
  try {
    text = JSON.parse(`"${m[1]}"`);
  } catch {
    text = m[1].replace(/\\n/g, '\n').replace(/\\"/g, '"').replace(/\\\\/g, '\\');
  }
  try {
    const inner = JSON.parse(text);
    if (inner && typeof inner === 'object' && !Array.isArray(inner)) {
      const parts = [];
      for (const v of Object.values(inner)) if (typeof v === 'string') parts.push(v);
      if (parts.length) return parts.join('\n');
    }
  } catch {
    /* 不是 JSON 入参（比如整段就是一个命令） */
  }
  return text;
}

