/**
 * 把某一级的候选折成 {id, score, hits}。
 * 级内先按「同一会话出现多个时取出现次数最多的那个」筛出一批 —— 这条定自 beat 级，
 * 对 claim/path 同款适用：同级证据只差在条数，条数就是强度。
 * 条数并列的候选**全都留下**（不在这里去重）：它们同分，交给全局同分判定「不归属」，不许猜。
 */
/**
 * 把某一级的候选折成 {id, score, hits}。
 * 级内先按「同一会话出现多个时取出现次数最多的那个」筛出一批 —— 这条定自 beat 级，
 * 对 claim/path 同款适用：同级证据只差在条数，条数就是强度。
 * 条数并列的候选**全都留下**（不在这里去重）：它们同分，交给全局同分判定「不归属」，不许猜。
 */
function ledgerCandidates(level, map, rawText) {
  const out = [];
  if (!map || !map.size) return out;
  if (level === 'text') {
    // text 的分本身就跟条数挂钩（score = min(条数, 20)），所以逐个出分、不先筛；
    // 但命中 < 2 次的弱证据一律不当候选（只命中一次的偶发提及不足以定归属）
    for (const [id, n] of map) {
      if (n < LEDGER_TEXT_MIN_HITS) continue;
      out.push({ id, score: Math.min(n, LEDGER_TEXT_CAP), hits: (rawText && rawText.get(id)) || n });
    }
    return out;
  }
  let max = 0;
  for (const n of map.values()) if (n > max) max = n;
  for (const [id, n] of map) if (n === max) out.push({ id, score: LEDGER_SCORE[level], hits: n });
  return out;
}

/** 时间窗：origin=subagent ∧ createdAt ∈ [created_at, claim|receipt 时间 + 1h] */
function ledgerWindowMap(idx, node) {
  const m = new Map();
  if (!node || node.origin !== 'subagent' || !node.createdAt) return m;
  for (const t of idx.tasks.values()) {
    if (!t.createdAt || !t.windowEnd) continue;
    if (node.createdAt >= t.createdAt && node.createdAt <= t.windowEnd) m.set(t.id, 1);
  }
  return m;
}

/**
 * 归因（五级，取最高分）。返回 {ok:true, via, score, hits, taskId} 或 {ok:false, why, tie?}。
 * 零命中与同分一律不归属 —— 宁可不挂账，也不许猜。
 */
function attributeLedgerNode(idx, probe, node) {
  if (!probe) return { ok: false, why: 'no-probe' };
  const beat = new Map(probe.beatCall);
  // 证据面：beat 只认执行过的调用；其余四级参与打分，但**只有子代理会话**才允许归因
  //（主会话是派单方，不是被派的单 —— 它读过谁家的指针不代表它在跑那张单）
  const levels =
    node.origin === 'subagent'
      ? [
          ['beat', beat],
          ['claim', probe.claim],
          ['path', probe.path],
          ['text', probe.text],
          ['window', ledgerWindowMap(idx, node)],
        ]
      : [['beat', beat]];
  // 取最高分：各级候选放一张表里比分数，同一个 id 只留它最高的那一级
  const best = new Map();
  for (const [level, map] of levels) {
    for (const c of ledgerCandidates(level, map, probe.text)) {
      const prev = best.get(c.id);
      if (!prev || c.score > prev.score || (c.score === prev.score && c.hits > prev.hits)) best.set(c.id, { level, id: c.id, score: c.score, hits: c.hits });
    }
  }
  if (!best.size) return { ok: false, why: 'none', candidates: [] };
  const all = [...best.values()];
  let max = 0;
  for (const c of all) if (c.score > max) max = c.score;
  const top = all.filter((c) => c.score === max).sort((a, b) => cmpStr(a.id, b.id));
  if (top.length > 1) return { ok: false, why: 'tie', level: top[0].level, score: max, tie: top.map((c) => c.id), candidates: all };
  return { ok: true, via: top[0].level, score: top[0].score, hits: top[0].hits, taskId: top[0].id, candidates: all };
}

/**
 * 「本该可能归属、但按口径被拒」的候选，逐条留痕（不许猜，也不许藏）。
 * 三类：① beacon 出现过但没执行过 beat；② 非子代理会话的非 beat 证据；③ 裸文本命中 < 2 次。
 */
function ledgerRejections(idx, node, probe, attribution) {
  if (!probe) return [];
  const seen = new Set();
  const out = [];
  const push = (taskId, via, score, why) => {
    if (!idx.tasks.has(taskId)) return;
    const k = `${taskId}|${via}`;
    if (seen.has(k)) return;
    seen.add(k);
    out.push({ taskId, via, score, why });
  };
  for (const [id, n] of probe.beacon) {
    if (probe.beatCall.has(id)) continue;
    push(id, 'beat', LEDGER_SCORE.beat, `出现过 ${n} 处 --task=${id} 的 beacon 形态，但没有一条是【执行过】的 beat 调用（只认 tool/call 参数里行首的 agent-view.mjs beat；读进来的指针 brief、转述的模板都不算）`);
  }
  if (node.origin !== 'subagent') {
    for (const [level, map] of [
      ['claim', probe.claim],
      ['path', probe.path],
      ['text', probe.text],
      ['window', ledgerWindowMap(idx, node)],
    ]) {
      for (const [id, n] of map) {
        push(id, level, level === 'text' ? Math.min(n, LEDGER_TEXT_CAP) : LEDGER_SCORE[level], `会话 origin=${node.origin}（派单方，不是被派的单）：除【执行过的 beat】外一律不归因，该候选被拒`);
      }
    }
  } else {
    for (const [id, n] of probe.text) {
      if (n >= LEDGER_TEXT_MIN_HITS) continue;
      push(id, 'text', n, `裸文本只命中 ${n} 次（< ${LEDGER_TEXT_MIN_HITS} 次门槛），不足以定归属`);
    }
  }
  if (attribution && attribution.why === 'tie') {
    for (const id of attribution.tie) {
      push(id, attribution.level, attribution.score, `同分：${attribution.tie.length} 条候选并列 ${attribution.score} 分（${attribution.tie.join('、')}），按契约同分不归属`);
    }
  }
  return out.sort((a, b) => b.score - a.score || cmpStr(a.taskId, b.taskId) || cmpStr(a.via, b.via));
}

/** 归属成功时挂到节点上的 ledger 块（未归属的节点不写这个键） */
function ledgerBlockFor(idx, taskId, match) {
  const t = idx.tasks.get(taskId);
  if (!t) return null;
  return {
    taskId: t.id,
    title: t.title,
    role: t.role,
    kind: t.kind,
    state: t.state,
    createdAt: t.createdAt,
    claimedBy: t.claimedBy,
    claimedAt: t.claimedAt,
    workorder: t.workorder ? { id: t.workorder.id, file: t.workorder.file, specRevision: t.workorder.specRevision } : null,
    acceptance: t.acceptance.slice(),
    allowWrite: t.allowWrite.slice(),
    rollback: t.rollback,
    receipt: t.receipt
      ? {
          status: typeof t.receipt.status === 'string' ? t.receipt.status : '',
          file: t.receiptFile,
          artifacts: (Array.isArray(t.receipt.artifacts) ? t.receipt.artifacts : []).map((a) => ({
            path: a && typeof a.path === 'string' ? a.path : '',
            sha256_16: a && typeof a.sha256_16 === 'string' ? a.sha256_16 : '',
            bytes: a && Number.isFinite(Number(a.bytes)) ? Number(a.bytes) : 0,
          })),
          touched: Array.isArray(t.receipt.touched) ? t.receipt.touched.map(String) : [],
          deviationsCount: Array.isArray(t.receipt.deviations) ? t.receipt.deviations.length : 0,
        }
      : null,
    beats: t.beats.map((b) => ({ ts: b.ts, event: b.event, note: b.note })),
    match: { via: match.via, score: match.score, hits: match.hits },
  };
}

/** 顶层总账（只在读得到台账时出现） */
function ledgerSummary(idx, nodes, rejected) {
  const counts = { total: idx.tasks.size, open: 0, claimed: 0, done: 0, void: 0 };
  for (const t of idx.tasks.values()) {
    if (Object.prototype.hasOwnProperty.call(counts, t.state)) counts[t.state] += 1;
  }
  const assignedIds = new Set();
  let assignedNodes = 0;
  let unassignedSubagents = 0;
  for (const n of nodes) {
    if (n.ledger) {
      assignedNodes += 1;
      assignedIds.add(n.ledger.taskId);
    } else if (n.origin === 'subagent' || n.depth > 0) {
      unassignedSubagents += 1;
    }
  }
  const orphanTasks = [...idx.tasks.keys()]
    .filter((id) => !assignedIds.has(id))
    .sort(cmpStr)
    .map((id) => `${id}（${LEDGER_ORPHAN_NOTE}）`);
  return { root: idx.root, counts, assignedNodes, unassignedSubagents, beatsTotal: idx.beatsTotal, orphanTasks, rejected: rejected || [] };
}

/** 台账侧的结构自检（真矛盾才判红；历史存量只计数，不追溯判红） */
function checkLedger(g) {
  const problems = [];
  const hasLedger = !!g.ledger;
  const withBlock = g.nodes.filter((n) => n.ledger);
  if (!hasLedger && withBlock.length) problems.push(`图里没有顶层 ledger，却有 ${withBlock.length} 个节点挂了 ledger`);
  for (const n of withBlock) {
    const L = n.ledger;
    if (!L.taskId) problems.push(`节点 ${n.id} 的 ledger.taskId 为空`);
    if (!LEDGER_VIA.has(L.match && L.match.via)) problems.push(`节点 ${n.id} 的 ledger.match.via=${L.match && L.match.via} 非法`);
    if (!LEDGER_STATES.has(L.state)) problems.push(`节点 ${n.id} 的 ledger.state=${L.state} 非法`);
    if (LEDGER_SCORE[L.match && L.match.via] !== undefined && L.match.score !== LEDGER_SCORE[L.match.via]) {
      problems.push(`节点 ${n.id} 的 ledger.match.score=${L.match.score} 与 via=${L.match.via} 的定分不符`);
    }
  return best;
}

function buildGraph(opts) {
  const {
    sessionsRoot,
    projectDir = null,
    all = false,
    cwd = process.cwd(),
    now = Date.now(),
    currentSessionId = process.env.DSH_SESSION_ID || null,
    cache = null,
  } = opts;

  const warnings = [];
  const scan = scanSessions({ root: sessionsRoot, projectDir, all, cwd, cache });
  for (const w of scan.warnings) warnings.push(w);

  const unknownEvents = new Map();
  const summaries = scan.summaries;

  // 节点
  const nodeById = new Map();
  for (const s of summaries) {
    if (!s.ok || !s.header) continue;
    const id = normId(s.header.id) || normId(s.dir);
    if (!id) {
      warnings.push(`会话目录 ${s.project}/${s.dir}：头里没有 id，已跳过`);
      continue;
    }
    if (nodeById.has(id)) {
      warnings.push(`会话 id 重复：${id}（保留 ${nodeById.get(id).source}，忽略 ${s.project}/${s.dir}）`);
      continue;
    }
    const parentId = normId(s.header.parentSession);
    let origin = typeof s.header.origin === 'string' ? s.header.origin.toLowerCase() : '';
    if (origin !== 'main' && origin !== 'subagent') {
      if (parentId) origin = 'subagent';
      else if (Number(s.header.delegationDepth) > 0) origin = 'unknown';
      else origin = 'main';


























































































































































  // 输出对象（字段顺序 = 冻结契约顺序）
  const out = {
    schema: SCHEMA,
    generatedAt: now,
    sessionsRoot,
    project: projects.length === 1 ? projects[0] : projects.length === 0 ? '' : '*',
    currentSessionId: curId || null,
    nodes: nodes.map((n) => ({
      id: n.id,
      short: n.short,
      label: n.label,
      depth: n.depth,
      parentId: n.parentId,
      origin: n.origin,
      agentPreset: n.agentPreset,
      cwd: n.cwd,
      createdAt: n.createdAt,
      firstEventAt: n.firstEventAt,
      lastEventAt: n.lastEventAt,
      status: n.status,
      isCurrent: n.isCurrent,
      bytes: n.bytes,
      frames: n.frames,
      recordCount: n.recordCount,
      counts: n.counts,
      toolNames: n.toolNames,
      lastEventType: n.lastEventType,
      ...(n.ledger ? { ledger: n.ledger } : {}),
    })),
    edges,
    timeline: { t0, t1, events },
    stats: {
      nodeCount: nodes.length,
      edgeCount: edges.length,
      maxDepth,
      projects,
    },
    warnings: [...new Set(warnings)].sort(cmpStr),
  };
  return out;
}












































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































