      out.push({ id, score: Math.min(n, LEDGER_TEXT_CAP), hits: (rawText && rawText.get(id)) || n });
    }
    return out;
  }
  let max = 0;
  for (const n of map.values()) if (n > max) max = n;
  for (const [id, n] of map) if (n === max) out.push({ id, score: LEDGER_SCORE[level], hits: n });
  return out;
}

