function ev(cmd, exit, src, matches, maxLineLen = 0) {
  const raw = readTxt(src);
  const lines = raw.split(/\r?\n/);
  const picked = [];
  for (const line of lines) {
    if (!matches.some((m) => m.test(line))) continue;
    if (!raw.includes(line)) throw new Error(`抽出的行不在原文里: ${line.slice(0, 40)}`);
    picked.push(maxLineLen ? line.slice(0, maxLineLen) : line);
  }
  if (!picked.length) throw new Error(`没抽到任何行: ${src} / ${matches}`);
  const tail = picked.join('\n');
  if (tail.length > 400) throw new Error(`tail 超 400 字(${tail.length}): ${src}`);
  rows.push({ cmd, exit, tail });
}

