#!/usr/bin/env node
// 子代理可见性仪表（随技能分发，任何工作区可用）。
//   node tools/agent-view.mjs              看账：state/tasks/**(任务/claim/结果/产物)
//   node tools/agent-view.mjs --live       看心跳：state/agents.jsonl 最近 N 条（实时"他在干什么"）
//   node tools/agent-view.mjs beat --agent=<名> --task=<id> --event=start|step|done --note="一句话"
//   node tools/agent-view.mjs init [--goal="..."]   在工作区里起一个最小账本(state/tasks + state/blueprints)
//   node tools/agent-view.mjs --graph [其余参数]  转发给同目录 agent-graph.mjs(会话图/台账图,不重实现)
// 根＝当前工作区（POLARIS_ROOT 优先），所以换到任何目录（如 AuraVesta）都能用。
import fs from 'node:fs'
import path from 'node:path'
import { spawnSync } from 'node:child_process'
// 同目录兄弟件用 fileURLToPath 定位:URL.pathname 保留百分号编码,安装目录含空格/中文时会变成 "...%20..."
//   (同 cli/polaris.mjs 第 10 行的既有反证 P2-6)。

const ROOT = path.resolve(process.env.POLARIS_ROOT ?? process.cwd())
const T = path.join(ROOT, 'state', 'tasks')
const HEART = path.join(ROOT, 'state', 'agents.jsonl')
const argv = process.argv.slice(2)
const flag = (n, d = null) => { const i = argv.indexOf(`--${n}`); if (i >= 0) return argv[i + 1] ?? d; const p = argv.find((a) => a.startsWith(`--${n}=`)); return p ? p.slice(n.length + 3) : d }
const cmd = argv[0]

// --graph = 同目录 agent-graph.mjs 的入口透传(2026-09-29 arch-v2.C29):本文件【不重实现画图】,
//   参数原样转发、退出码原样透传(拿不到 code 时按 1 = 同一份「用法错/起不来」口径)。
//   根沿用本文件的 ROOT 传给子进程(POLARIS_ROOT),所以 agent-view 指对了根、图谱也就指对了根。
  const graph = path.join(path.dirname(new URL(import.meta.url).pathname.replace(/^\/([A-Za-z]:)/, '$1')), 'agent-graph.mjs')
  if (!fs.existsSync(graph)) { console.error(`图谱工具缺失(技能包不完整): ${graph}`); process.exit(1) }
  const child = spawnSync(process.execPath, [graph, ...argv.filter((a) => a !== '--graph')], { cwd: ROOT, stdio: 'inherit', env: { ...process.env, POLARIS_ROOT: ROOT } })
  process.exit(child.status ?? 1)
}

if (cmd === 'beat') {
  fs.mkdirSync(path.dirname(HEART), { recursive: true })
  const rec = { ts: new Date().toISOString(), agent: flag('agent', 'unknown'), task: flag('task', null), event: flag('event', 'step'), note: flag('note', null) }
  fs.appendFileSync(HEART, JSON.stringify(rec) + '\n')

