// skills/aurapolaris/tools/task-files.mjs — 任务文件枚举谓词族【唯一实现】(随技能包分发)。
//
// 为什么在这个落点(2026-09-29,施工单 arch-v2.C28;AGENTS.md §0.4):
//   谓词原先住在仓库侧 tools/taskctl.mjs。而本仓库的【可分发单元是 skills/aurapolaris/】——
//   技能包(aurapolaris-skill-0.8.0.zip,根 = polaris/)解压进任意 skills 根就算装完,那里【没有 tools/】。
//   实测代价:装到别的宿主后,ledger 源的任务层与执行者层为空(只剩蓝图 + 组件),
//   在包内跑 --selftest 直接 TypeError。所以谓词的落点必须跟着包走:包内这一份是唯一实现,
//   仓库侧 tools/taskctl.mjs 改为 import 本文件并【再导出】,既有消费者(pipeline-watch / fractal-check /
//   agent-graph)一行都不用改。
//
// 本文件是叶子模块:零依赖(只用 node 内置模块)、不读 POLARIS_ROOT、不在 import 期做任何 IO 或副作用。
//   "根作用域版(In)" 一律把 tasksDir 作为第一个参数收进来 —— 对账工具要在【自证夹具根】里判状态,
//   不能把它钉死在某个进程级根上。

import fs from 'node:fs'
import path from 'node:path'

// ---- 读 JSON:三态 ok / missing / bad ----
// 口径与 tools/audit.mjs 的 read/readBuf/readJson 同款:【读】容忍(不崩),【缺/坏】必须点名;
//   为什么带 why:坏输入要能"一行点名 + exit 12",调用侧拿不到 why 就只能甩栈或静默。
//   与 tools/taskctl.mjs 里那一份【逐字同源】:该模块的读任务文件链(readTaskFile/lint/verify)整条消费本实现,
//   所以"这文件读得出来吗"全仓只有这一处判。
const READ_OK = 'ok', READ_MISSING = 'missing', READ_BAD = 'bad'
const isPlainObject = (j) => !!j && typeof j === 'object' && !Array.isArray(j)
function readJsonState(p) {
  let raw
  try { raw = fs.readFileSync(p, 'utf8') } catch (e) { return { kind: READ_MISSING, why: e?.code === 'ENOENT' ? '文件不存在' : `读不到(${e?.code ?? e?.message})` } }
  if (!raw.trim()) return { kind: READ_BAD, why: 'JSON 解析失败(空文件)' }
  try { return { kind: READ_OK, value: JSON.parse(raw), raw } } catch (e) { return { kind: READ_BAD, why: `JSON 解析失败(${e.message})` } }
}
// 派生物(不是第二条读路径):只把三态压成"值 / null",供"读不到就按缺省走"的调用侧用。
const readJsonOrNull = (p) => { const r = readJsonState(p); return r.kind === READ_OK ? r.value : null }
export { READ_OK, READ_MISSING, READ_BAD, isPlainObject, readJsonState, readJsonOrNull }

// ---- 任务文件谓词【唯一一份】 ----
// 真任务文件 = T-*.json 且不是五种派生产物。派生产物各自都是"某次命令的落盘",不是可领任务:
//   .claim.json   某次【认领】的落盘(子代理开工前写)
//   .result.json  某次【回执】的落盘(协议 §7 交付物)
//   .void.json    某次【作废】的落盘(记账用,不伪造验收)
//   .verify.json  某次【复核】的落盘(taskctl verify 的派生数据,允许覆盖)
//   .receipt.json verify 的【自保副本】落点(preserveReceipt:轮次判不出时写 state/tasks/<id>.receipt.json)
//   漏掉任何一个,按文件名枚举 state/tasks 的消费者就会把它当成一张任务:实测漏 .verify.json 时
//   tools/pipeline-watch.mjs 多输出一行幻影任务 QUEUE: T-20260927111319-59fe.verify;
//   实测 .receipt.json 被 lint 当成一张任务并判红"缺 brief(不是任务文件?)" ——
//   verify 自己写的产物把门禁弄红。所以这一份【只许有一处】,消费者一律 import 它
//   (历史上 pipeline-watch 自带一份,少了两个后缀 → 两口径任务数 176 vs 170)。
export const DERIVED_SUFFIXES = ['.claim.json', '.result.json', '.void.json', '.verify.json', '.receipt.json']
export const isDerivedArtifact = (name) => DERIVED_SUFFIXES.some((s) => String(name).endsWith(s))
export const isTaskFile = (name) => /^T-.*\.json$/.test(String(name)) && !isDerivedArtifact(name)

// ---- 作废记录谓词【唯一一份】= 终态之一 ----
//   口径来源与 tools/pipeline-watch.mjs 的 status 谓词【逐字对齐】:
//     `hasResult ? 'done' : voided ? 'void' : claim ? 'inflight' : 'open'`,
//   以及它文件头"在跑的集合 = claim ∧ ¬result ∧ ¬void:作废(.void.json)与回执都是终态产物,不进 STALE 面"。
//   本谓词之前租约闸只读了"有回执"这一半终态,已作废单的 claim 继续占着写权 —— 实测 T-20260927161014-849a
//   代理已死、已写 void,它的租约仍把接手单的 lint 摁在 exit 12(lint 自述的红就是"写权相交(在跑)")。
//   边界如实声明:① "有回执"那一半【不换】—— receiptDone 比 pipeline-watch 的 hasResult 更宽
//   (多认"自声明非规范名 ∧ §7 形态",那是修过的真缺口 8f06),换成窄的反而会放宽在跑集合,属放宽;
//   ② 读得到 ∧ 顶层是对象才算作废记录:半写的 .void.json 不释放写权(fail-closed,宁可误报一次),
//   与"预算/时间解析不出就当在跑"同款取舍。
export const isVoidedIn = (tasksDir, id) => isPlainObject(readJsonOrNull(path.join(tasksDir, `${id}.void.json`)))
// 根作用域版本从第一天起就是这个形状(为 tools/fractal-check.mjs 的 FRACTAL-3):对账工具要在【自证夹具根】
//   里判"在飞",而模块级 TASKS 绑的是本进程的 POLARIS_ROOT —— 直接复用会把夹具读数指回真树。
//   仓库侧 tools/taskctl.mjs 的 isVoided 只是把它钉在自己的 TASKS 上(同一函数体,不是第二份)。
export const isVoided = (tasksDir, id) => isVoidedIn(tasksDir, id)

// ---- §7 回执形态 / 收工谓词【唯一一份】 ----
// §7 回执形态(status + evidence):用来判"这单到底交没交付"。名字不是证据时,内容要是。
export const isReceiptShaped = (p) => {
  const j = readJsonOrNull(p)
  return !!(j && typeof j === 'object' && !Array.isArray(j) && 'status' in j && 'evidence' in j)
}
// 该单声明的回执落点:①规范名 state/tasks/<id>.result.json;②它在自己 allow_write_paths 里显式声明的
//   state/tasks/*.result.json;③施工单档:指针上的 receipt_path(或 workorder.report_to)声明的【包外回执名】。
//   为什么需要③(2026-09-29 实测,DP-01/C36):施工单的 compose.report_to 一直落在 .polaris/workorders/,
//   而本函数原先只认 state/tasks/ 下的名字 —— 于是 C15..C32 十八张单的 §7 回执【全在盘上】
//   (17 done + 1 partial)却一律判 null ⇒ tools/pipeline-watch.mjs 打出 18 条假 STALL(STALL 是它 exit 12
//   的构成部分),而它是 AGENTS.md §0.3 指定的排空仲裁者 ⇒ 父线程结构上无法用它收口。
//   ③ 的名靠指针上的机器可读键认;名字的【形态闸】与 ② 同款(相对路径 ∧ 不以 / 或 X:/ 开头 ∧ 无 .. 段
//   ∧ .result.json 收尾 ∧ 读出来是 §7 形态),只是不再要求落在 state/tasks/ —— 施工单落点由图自己声明。
//   为什么需要②(2026-09-27 实测的真缺口):派单协议自己就会给非规范名回执 —— T-20260927114555-8f06 的真回执
//   是 brief 指定的 T-20260927115200-lease.result.json,而收工判定只看 <id>.result.json,
//   于是该单已 status=done、闸门却一直当它"在跑",6 分钟内挡住了别人的单(父线程实测)。
//   口径:规范名按【存在】认(历史口径不变,不动存量语义);非规范名按【§7 形态】认 ——
//   自己声明的名字不算证据,里面的 §7 内容才算。
//   消费侧:tasks/fractal-check.mjs 的 FRACTAL-3 要判"切点及以后 ∧ 在飞"这一桶,
//   而"在飞"的定义就是 claim ∧ ¬收工 ∧ ¬作废 —— 收工那一半必须消费本函数,不许在对账工具里再写第二份。
//   行为一字未动(原本就是 tools/taskctl.mjs 内部在用),只是搬到了随包分发的落点。
// 声明名的形态闸。刻意不写第二份"什么算合法回执名"的正则表:与 ② 同一套形态要求。
const declaredReceiptRel = (raw) => {
  const rel = String(raw ?? '').trim().replace(/\\/g, '/')
  if (!rel || rel.startsWith('/') || /^[A-Za-z]:/.test(rel)) return null
  if (rel.split('/').some((s) => s === '..')) return null
  return rel.endsWith('.result.json') ? rel : null
}
// 声明名的基准是【仓库根】= tasksDir 的上级的上级(state/tasks → 根;与 pipeline-watch 的 ROOT/TASKS 同构)。
//   ① 指针上的 receipt_path(2026-09-29 起 from-workorder 铸的机器可读键);② 旧指针只有 workorder.report_to。
//   两者都读 = 存量 18 张不靠回补也能被认(AGENTS.md §0.4【不回补】)。
//   【也不许按 cwd 解析】:回执落点只能是施工单的固定落点 .polaris/workorders/<名>.result.json —— 再宽一格
//   就会把"任意一个含 status+evidence 的文件"当成某单的收工证据(fail-open)。解析不出根 → 整支跳过
//   (fail-closed:认不出就不认收工,宁可误报一次 STALL,也不许把"读不出"当"已收工")。
const workorderReceiptDeclared = (tasksDir, id, t) => {
  const rel = declaredReceiptRel(t?.receipt_path) ?? declaredReceiptRel(t?.workorder?.report_to)
  if (!rel || rel === `state/tasks/${id}.result.json`) return null
  if (!rel.startsWith('.polaris/workorders/')) return null
  const root = path.dirname(path.dirname(tasksDir))
  // 盘上的绝对落点 = 解析出的根 + 声明名。tasksDir 是相对路径时 root 会退成 '.',此时才回退到 cwd ——
  //   两条路都在同一对 (root, rel) 上做同一个 existsSync + §7 形态判,不存在第二份判定。
  const abs = path.isAbsolute(root) ? path.join(root, rel) : path.resolve(rel)   // 后者 = 按 cwd 解析(相对根那一路的既有语义)
  return isReceiptShaped(abs) ? `workorder:${rel}` : null
}
export function receiptDoneIn (tasksDir, id, t) {
  if (fs.existsSync(path.join(tasksDir, `${id}.result.json`))) return 'canonical'
  for (const p of t?.allow_write_paths ?? []) {
    const rel = String(p).replace(/\\/g, '/')
    if (!/^state\/tasks\/[^/]+\.result\.json$/.test(rel)) continue
    const base = rel.slice('state/tasks/'.length)
    if (base === `${id}.result.json`) continue
    if (isReceiptShaped(path.join(tasksDir, base))) return `declared:${base}`
  }
  return workorderReceiptDeclared(tasksDir, id, t)
}

