source.text:
// 回执契约检查器(只读):按 kernel/delegation.json 的 workspace_ledger.composability.report_contract
// 校验 state/tasks/<id>.result.json 是不是一份"算数的回执",而不是 taskctl verify 的产物。
//
// 为什么要它:指针里的 acceptance 曾写成 `node -e "…"`(含引号与括号),被 taskctl 的形态闸 REFUSED
// → 本轮 7 张单的"父线程独立复核"一步也跑不起来。判据必须落在仓库内脚本上,不能靠内联代码。
//
// 用法: node tools/receipt-check.mjs <task-id|结果文件路径> [--allow-verify-artifact]
// 退出码: 0 = 合规回执; 12 = 不合规(逐条点名); 1 = 用法错
//
// 判据(逐条):
//  1) 文件存在且是 JSON。
//  2) 顶层键含 status / evidence / artifacts / touched / deviations / rollback(缺项点名)。
//  3) status ∈ done|partial|blocked。
//  4) evidence 是数组且非空;每条含 cmd/exit/phase/tail 四键;phase 只认 red|green。
//  5) evidence 里**同时**出现 phase=red 与 phase=green(只有 green=假绿),除非 status=blocked。
//  6) touched 与 artifacts 都是数组。
//  7) analyzer_boundary_check:【条件必需】touched 含产品件(=> 本单产出了代码 diff)时必填且非空字符串;
//     touched 全是账本/台账件(state/** 等)时不要求 —— 那种单没 diff 可审,强要一个字段只会被写成空话。
//     口径【与 state/rounds/R8/reviews/PROTOCOL.md §8 同一份】:协议里那段"条件必需"写的就是本文件这段
//     PRODUCT_TOUCHED(同一谓词、同一条件),两处可对照引用。为什么以前不同源:协议 §8 的 schema 列了 7 键、
//     本文件的 REQUIRE 只有 6 键 —— 唯一列了 analyzer_boundary_check 的那一边没有任何机械消费者,
//     于是"协议要求"与"检查器实测"两层各说各话(2026-09-27 六路审查 ⑤ 报的契约漏项)。
//     产品件谓词【不在这里手抄第二份名单】:复用 tools/fingerprint.mjs 的 isProductPath(唯一实现)。
// 例外: 若文件是 taskctl verify 的产物(顶层键 id/ok/results/verified_at),默认判不合规并提示
//   —— 那正说明回执被 verify 覆盖过;`--allow-verify-artifact` 只用于显式查看该情形。
import fs from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'
// 产品件谓词唯一实现(与 PROTOCOL.md §8 / 工作区指纹同一份);import 而非内联,免得又造出第二份名单。
import { isProductPath } from './fingerprint.mjs'

const ROOT = path.resolve(process.env.POLARIS_ROOT ?? path.join(path.dirname(fileURLToPath(import.meta.url)), '..'))
const argv = process.argv.slice(2)
const allowVerifyArtifact = argv.includes('--allow-verify-artifact')
const arg = argv.find((a) => !a.startsWith('--'))

if (!arg) {
  console.log('用法: node tools/receipt-check.mjs <task-id|结果文件路径> [--allow-verify-artifact]')
  process.exit(1)
}
const file = arg.endsWith('.json') ? path.resolve(ROOT, arg) : path.join(ROOT, 'state', 'tasks', `${arg}.result.json`)
if (!fs.existsSync(file)) {
  console.log(`RECEIPT FAIL: 回执不存在: ${path.relative(ROOT, file)}`)
  process.exit(12)
}
let j = null
try { j = JSON.parse(fs.readFileSync(file, 'utf8')) } catch (e) {
  console.log(`RECEIPT FAIL: 不是合法 JSON: ${e.message}`)
  process.exit(12)
}
const keys = Object.keys(j)
const isVerifyArtifact = keys.includes('verified_at') && keys.includes('ok') && !keys.includes('status')
if (isVerifyArtifact && !allowVerifyArtifact) {
  console.log(`RECEIPT FAIL: ${path.relative(ROOT, file)} 是 taskctl verify 的产物(顶层键 ${keys.join(',')}),不是 §7 回执`)
  console.log('  说明:回执已被 verify 覆盖,或该单从未写回执。要查看该产物请加 --allow-verify-artifact。')
  process.exit(12)
}

const problems = []
const REQUIRE = ['status', 'evidence', 'artifacts', 'touched', 'deviations', 'rollback']
for (const k of REQUIRE) if (!(k in j)) problems.push(`缺顶层键 ${k}`)
// status 口径（2026-09-27 扩充，有实测依据）：
//   done / partial / blocked —— 契约原文三态；
//   done_<后缀> —— 施工者已交付、但主动声明了一处偏离（例：done_with_declared_deviation）。
// 为什么要收它：实测（T-20260927-docfacts）施工者把“按 brief 做完了但有一处偏离”写成 done_with_declared_deviation，
// 内容合规却被旧口径判非法 —— 那是**判据太窄**，会逼人把真话改成 done 反而丢失信息。
// 边界：partial / blocked 仍然不算完成；done_* 必须配 deviations 非空（否则就是拿后缀当免费通行证）。
if ('status' in j) {
  const st = String(j.status)
  const legal = ['done', 'partial', 'blocked'].includes(st) || /^done_\w+/.test(st)
  if (!legal) problems.push(`status 非法: ${st}(只认 done|done_<后缀>|partial|blocked)`)
  if (/^done_\w+/.test(st) && !(Array.isArray(j.deviations) && j.deviations.length)) {
    problems.push(`status=${st} 但没有 deviations —— done_<后缀> 必须配一处已声明的偏离`)
  }
}
if ('evidence' in j) {
  if (!Array.isArray(j.evidence) || !j.evidence.length) problems.push('evidence 必须是非空数组')
  else {
    const phases = new Set()
    j.evidence.forEach((e, i) => {
      for (const k of ['cmd', 'exit', 'phase', 'tail']) if (!(k in (e ?? {}))) problems.push(`evidence[${i}] 缺 ${k}`)
      if (e?.phase && !['red', 'green'].includes(e.phase)) problems.push(`evidence[${i}].phase 非法: ${e.phase}(只认 red|green)`)
      if (e?.phase) phases.add(e.phase)
    })
    if (j.status !== 'blocked') {
      if (!phases.has('green')) problems.push('evidence 里没有 phase=green')
      if (!phases.has('red')) problems.push('evidence 里没有 phase=red(只有 green = 假绿)')
    }
  }
}
for (const k of ['artifacts', 'touched']) if (k in j && !Array.isArray(j[k])) problems.push(`${k} 必须是数组`)
// 7) analyzer_boundary_check:条件必需 —— 判据条件只落在 touched 上(见上列判据 7),与 PROTOCOL.md §8 同源。
//   为什么条件看 touched 而不是 artifacts:artifacts 是产出物(state/** 报告类),touched 才是"本单改过的路径";
//   且两者都是回执自报的,能用同一份谓词机检。status=blocked 也不豁免:真改过产品件就得写出边界在哪。
const PRODUCT_TOUCHED = (Array.isArray(j.touched) ? j.touched : []).map(String).filter(isProductPath)
if (!('analyzer_boundary_check' in j)) {
  if (PRODUCT_TOUCHED.length) {
    const head = PRODUCT_TOUCHED.slice(0, 3).join(', ')
    problems.push(`缺顶层键 analyzer_boundary_check: touched 含产品件 ${head}${PRODUCT_TOUCHED.length > 3 ? ` 等 ${PRODUCT_TOUCHED.length} 处` : ''} => 本单涉代码 diff,PROTOCOL.md §8 要求它条件必需(值=diff-audit 原始输出或其边界自报)`)
  }
} else if (typeof j.analyzer_boundary_check !== 'string' || !j.analyzer_boundary_check.trim()) {
  problems.push('analyzer_boundary_check 必须是非空字符串(空值/非字符串等于没写) —— 它自报的是 diff-audit 的粒度与豁免边界')
}
const rel = path.relative(ROOT, file).split(path.sep).join('/')
if (problems.length) {
  console.log(`RECEIPT FAIL: ${rel}`)
  for (const p of problems) console.log('  - ' + p)
  process.exit(12)
}
console.log(`RECEIPT PASS: ${rel}`)
console.log(`  status=${j.status} evidence=${j.evidence.length}(phases=${[...new Set(j.evidence.map((e) => e.phase))].sort().join(',')}) artifacts=${(j.artifacts ?? []).length} touched=${(j.touched ?? []).length} deviations=${(j.deviations ?? []).length}`)
process.exit(0)

