#!/usr/bin/env node
// 子代理可见性仪表（随技能分发，任何工作区可用）。
//   node tools/agent-view.mjs              看账：state/tasks/**(任务/claim/结果/产物)
//   node tools/agent-view.mjs --live       看心跳：state/agents.jsonl 最近 N 条（实时"他在干什么"）
//   node tools/agent-view.mjs beat --agent=<名> --task=<id> --event=start|step|done --note="一句话"
//   node tools/agent-view.mjs init [--goal="..."]   在工作区里起一个最小账本(state/tasks + state/blueprints)
//   node tools/agent-view.mjs --graph [其余参数]  转发给同目录 agent-graph.mjs(会话图/台账图,不重实现)
// 根＝当前工作区（POLARIS_ROOT 优先），所以换到任何目录（如 AuraVesta）都能用。
import fs from 'node:fs'
import path from 'node:path'
import { spawnSync } from 'node:child_process'
import { fileURLToPath } from 'node:url'
// 任务文件枚举谓词【唯一实现】随技能包同目录分发(skills/aurapolaris/tools/task-files.mjs)。
//   本文件是出货件,谓词【一行都不许在这里重写】(AGENTS.md §0.4 / arch-v2.C39):
//   这里原先内联的是 x.endsWith('.json') && !x.endsWith('.claim.json') && !x.endsWith('.result.json') && x !== 'OPEN.json'
//   —— 少了 .void/.verify/.receipt 三个后缀,把派生件当成了待领任务(实测 state/tasks 下 826 个文件里
//   108 个是派生件,它们被逐行打成 `- T-xxx.void [task] OPEN｜…` 的幻影指针),与 §0.4 记的
//   pipeline-watch 少排 .verify/.receipt 是同一种病。
//   导入同目录相对路径(不是 '../tools/taskctl.mjs'):可分发单元是 skills/aurapolaris/,技能包里没有
//   tools/,写死仓库侧路径会让"单装技能包"这种装法在 import 期就 ERR_MODULE_NOT_FOUND。
import { isTaskFile } from './task-files.mjs'
// 同目录兄弟件用 fileURLToPath 定位:URL.pathname 保留百分号编码,安装目录含空格/中文时路径会变 "...%20..."
//   (同 cli/polaris.mjs 第 10 行的既有反证 P2-6)。


const ROOT = path.resolve(process.env.POLARIS_ROOT ?? process.cwd())
const T = path.join(ROOT, 'state', 'tasks')
const HEART = path.join(ROOT, 'state', 'agents.jsonl')
const argv = process.argv.slice(2)
const flag = (n, d = null) => { const i = argv.indexOf(`--${n}`); if (i >= 0) return argv[i + 1] ?? d; const p = argv.find((a) => a.startsWith(`--${n}=`)); return p ? p.slice(n.length + 3) : d }
const cmd = argv[0]


// --graph = 同目录 agent-graph.mjs 的入口透传(2026-09-29 arch-v2.C29):本文件【不重实现画图】,
//   参数原样转发、退出码原样透传(拿不到 code 时按 1 = 同一份「用法错/起不来」口径)。
//   根沿用本文件的 ROOT 传给子进程(POLARIS_ROOT),所以 agent-view 指对了根、图谱也就指对了根。
// --graph = 同目录 agent-graph.mjs 的入口透传(2026-09-29 arch-v2.C29):本文件【不重实现画图】,
//   参数原样转发、退出码原样透传(拿不到 code 时按 1 = 同一份「用法错/起不来」口径)。
//   根沿用本文件的 ROOT 传给子进程(POLARIS_ROOT),所以 agent-view 指对了根、图谱也就指对了根。
//   根同源:本文件的 ROOT = path.resolve(POLARIS_ROOT ?? cwd),原样交给子进程。

if (cmd === 'init') {
  fs.mkdirSync(T, { recursive: true })
  fs.mkdirSync(path.join(ROOT, 'state', 'blueprints'), { recursive: true })
  const goal = flag('goal', '(未写目标)')
  console.log(`已在 ${ROOT} 起账本:\n  state/tasks/          任务指针与结果\n  state/blueprints/     蓝图\n  state/agents.jsonl    子代理心跳(用 beat 追加)\n目标: ${goal}`)
  process.exit(0)
}

if (cmd === '--live' || argv.includes('--live')) {
  if (!fs.existsSync(HEART)) { console.log(`暂无心跳文件 ${path.relative(ROOT, HEART) || HEART}（子代理用 agent-view.mjs beat 追加）`); process.exit(0) }
  const n = Number(flag('tail', 20))
  const lines = fs.readFileSync(HEART, 'utf8').split(/\r?\n/).filter((l) => l.trim()).slice(-n)
  console.log(`心跳（最近 ${lines.length} 条，${path.relative(ROOT, HEART)}）:`)
  for (const l of lines) { try { const o = JSON.parse(l); console.log(`  ${o.ts} ${o.agent} ${o.event}${o.task ? ' @' + o.task : ''}${o.note ? ' — ' + o.note : ''}`) } catch { /* 跳过坏行 */ } }
  process.exit(0)
}

// 默认：看账
if (!fs.existsSync(T)) {
  console.log(`本工作区还没账本: ${ROOT}\n起一个:  node ${path.relative(ROOT, new URL(import.meta.url).pathname.replace(/^\/([A-Za-z]:)/, '$1')) || '<skill>/tools/agent-view.mjs'} init\n`)
  console.log('（派子代理时用指针式派单:把任务写到 state/tasks/<id>.json，子代理先写 <id>.claim.json，产出写 REPORT；它跑的时候用 beat 写心跳）')
  process.exit(0)
}
const files = fs.readdirSync(T)
const rows = []
for (const f of files.filter((x) => x.endsWith('.json') && !x.endsWith('.claim.json') && !x.endsWith('.result.json') && x !== 'OPEN.json')) {
  const id = f.replace(/\.json$/, '')
  let t; try { t = JSON.parse(fs.readFileSync(path.join(T, f), 'utf8')) } catch { continue }
  if (!t?.id) continue
  const claim = fs.existsSync(path.join(T, `${id}.claim.json`)) ? JSON.parse(fs.readFileSync(path.join(T, `${id}.claim.json`), 'utf8')) : null
  const result = fs.existsSync(path.join(T, `${id}.result.json`)) ? JSON.parse(fs.readFileSync(path.join(T, `${id}.result.json`), 'utf8')) : null
  const reports = []
  const t0 = claim?.at ? Date.parse(claim.at) : Infinity
  const t1 = result?.at ? Date.parse(result.at) + 3600e3 : (claim?.at ? Date.parse(claim.at) + 24 * 3600e3 : 0)
  const scan = (d, depth = 0) => {
    if (depth > 3) return
    const abs = path.join(ROOT, d)
    if (!fs.existsSync(abs)) return
    for (const e of fs.readdirSync(abs, { withFileTypes: true })) {
      if (e.isDirectory()) { if (!/^(node_modules|dist|\.git)$/.test(e.name)) scan(path.join(d, e.name), depth + 1); continue }
      if (!/^REPORT.*\.md$/i.test(e.name)) continue
      const st = fs.statSync(path.join(abs, e.name))
      if (st.mtimeMs >= t0 && st.mtimeMs <= t1) reports.push(path.join(d, e.name).replace(/\\/g, '/'))
    }
  }
  scan('state')
  rows.push({ id, title: t.title, lens: t.lens ?? t.kind ?? 'task', claimed_by: claim?.claimed_by ?? null, claimed_at: claim?.at ?? null, result_ok: result?.ok ?? null, reports })
}
rows.sort((a, b) => String(a.claimed_at ?? '').localeCompare(String(b.claimed_at ?? '')))
// 自领入口:载荷丢失的子代理不看消息也能自助领取(任务 id / brief_sha256 / 规则)
const open = (() => { try { return JSON.parse(fs.readFileSync(path.join(T, 'OPEN.json'), 'utf8')) } catch { return null } })()
const openList = Array.isArray(open?.open) ? open.open : []
const relOpen = path.join(path.relative(ROOT, T) || 'state/tasks', 'OPEN.json')
console.log(`自领入口（${relOpen}）：待领 ${openList.length} 个`)
for (const o of openList) {
  console.log(`- ${o?.id ?? '?'} [${o?.role ?? o?.kind ?? 'task'}]${o?.for_agent ? ` for ${o.for_agent}` : ''}｜${o?.title ?? ''}`)
  console.log(`    brief_sha256: ${o?.brief_sha256 ?? '(缺)'}（开工前先与本文件校验一致）`)
  console.log(`    领取: 写 ${path.join(path.relative(ROOT, T) || 'state/tasks', `${o?.id ?? '?'}.claim.json`)} 再执行`)
}
if (open?.rule) console.log(`    规则: ${open.rule}`)
if (!openList.length) console.log('- 无待领任务 → 回 WAITING FOR TASK，不得自领')
if (openList.length > 1) console.log('- 多个待领任务 → 不得自领，回 WAITING FOR TASK 并列出所见')
console.log(`子代理账（${path.relative(ROOT, T) || 'state/tasks'}）：共 ${rows.length} 条`)
for (const r of rows) {
  const st = r.result_ok === true ? 'DONE(ok)' : r.result_ok === false ? 'DONE(fail)' : r.claimed_by ? 'CLAIMED' : 'OPEN'
  console.log(`- ${r.id} [${r.lens}] ${st}${r.claimed_by ? ` by ${r.claimed_by}` : ''}｜${r.title}`)
  if (r.reports.length) console.log(`    产物: ${r.reports.join(', ')}`)
}
if (fs.existsSync(HEART)) console.log(`\n（另有心跳可看: --live）`)

