  if (!t) { console.error('用法: polaris realq route | polaris realq answer [--dir=state/realq/answers]'); process.exit(1) }
  // realq-* 属【仓库开发工具】(依赖私有语料与 tests/),不随技能分发 → 从仓库 tools/ 跑,缺时明说
  const abs = path.join(ROOT, 'tools', t)
  if (!fs.existsSync(abs)) { console.error(`realq 仅在完整仓库可用（分发包不含私有语料与开发工具）: 缺 ${path.relative(ROOT, abs)}`); process.exit(1) }
  const r2 = runSync(process.execPath, [abs, ...argv.slice(2)], { cwd: ROOT, stdio: CHILD_STDIO, env: { ...process.env, POLARIS_ROOT: ROOT }, timeoutMs: DEFAULT_TIMEOUT_MS })
  process.exit(r2.status ?? 1)
}

// ---- M3/C13 接线：护栏显式启用（默认 dry-run；--apply 才写；写前备份，可回滚）----
// 本子命令只做【路由】:真正的写入= tools/apply-hook.mjs(唯一实现,默认指向安装态副本 hook.mjs),
// 真正的状态报告= tools/hook-status.mjs(三问:指向本技能/trust 匹配/最近触发),避免 CLI 与工具各写一份判定。
function cmdHook() {
  const sub = argv[1] ?? 'status'
  const home = homeDir()
  const target = opt('target', path.join(home, '.codex', 'hooks.json'))   // 注意：本 CLI 的 flag() 是布尔取值助手，取值要用 opt()
  const entryPath = path.join(ROOT, 'skills', 'aurapolaris', 'tools', 'hook.mjs')
  const applyTool = path.join(ROOT, 'tools', 'apply-hook.mjs')
  const statusTool = path.join(ROOT, 'tools', 'hook-status.mjs')
  say('护栏接线', '宿主 hooks.json 只写【一条统一入口】(node hook.mjs --event=PreToolUse):默认指向安装态副本,写前备份,可回滚',
    'node cli/polaris.mjs hook status  ← 三问:指向本技能? trust 匹配? 最近触发时间与计数?')
  if (sub === 'status') {
    const r = runSync(process.execPath, [statusTool, '--target', target, ...(flag('json') ? ['--json'] : [])],
      { stdio: CHILD_STDIO, env: { ...process.env, POLARIS_ROOT: ROOT }, timeoutMs: DEFAULT_TIMEOUT_MS })
    process.exit(r.status ?? 1)
  }
  if (sub === 'mode') {
    // 只认 [shadow|enforce]:以前 help 里写了 --target=<hooks.json>,白名单也接受这个 key,但这里根本不用它 ——
    //   用户以为"指定了目标文件",实际改的是 POLARIS_ROOT 下的模式文件(静默吞参,2026-09-22 反证 item12-red-*)。
    //   选择:不给 mode 加一个假的 target,而是把多余参数判成用法错误(真话优先于"看起来支持")。
    const extra = argv.slice(2).filter((a) => a !== 'shadow' && a !== 'enforce')
    if (extra.length) {
      console.error(`用法错误: hook mode 只接受 shadow|enforce,收到 ${extra.map((a) => JSON.stringify(a)).join(' ')};本子命令的落点固定为 POLARIS_ROOT 下的模式文件(不认 --target)`)
      process.exit(1)
    }
    const want = argv[2]
    const r = runSync(process.execPath, [entryPath, 'mode', ...(want ? [want] : [])],
      { stdio: CHILD_STDIO, env: { ...process.env, POLARIS_ROOT: ROOT }, timeoutMs: DEFAULT_TIMEOUT_MS })
    process.exit(r.status ?? 1)
  }
  if (sub === 'enable' || sub === 'disable') {
    if (!fs.existsSync(entryPath)) { console.error(`统一入口不存在(技能包不完整): ${entryPath}`); process.exit(1) }
    const args = [applyTool, '--target', target, ...(sub === 'disable' ? ['--remove'] : [])]
    // 默认只预览:只有显式 --apply 且未 --dry-run 才真写宿主配置
    if (!flag('apply') || flag('dry-run')) args.push('--dry-run')
    const r = runSync(process.execPath, args, { stdio: CHILD_STDIO, env: { ...process.env, POLARIS_ROOT: ROOT }, timeoutMs: DEFAULT_TIMEOUT_MS })
    process.exit(r.status ?? 1)
  }
  console.error('用法: polaris hook status [--json] [--target=<hooks.json>] | enable [--dry-run|--apply] [--target=<hooks.json>] | disable [--apply] [--target=<hooks.json>] | mode [shadow|enforce](不认 --target,模式文件在 POLARIS_ROOT 下)'); process.exit(1)
}
table.hook = cmdHook

// ---- M5 收口：跨会话判断检索（在 state/ 的 ledger/incidents/reviews 里按关键词找历史判断）----
function cmdRecall() {
  const q = argv.slice(1).join(' ').trim()
  if (!q) { console.error('用法: polaris recall "<关键词>"'); process.exit(1) }
  say('跨会话检索', '在 state/ 的历史证据里找"上次是怎么判的"', 'node cli/polaris.mjs recall "关键词"')
  const hits = []
  const walk = (d, depth = 0) => {
    if (depth > 4) return
    const abs = path.join(ROOT, d)
    if (!fs.existsSync(abs)) return
    for (const e of fs.readdirSync(abs, { withFileTypes: true })) {
      if (e.isDirectory()) { walk(path.join(d, e.name), depth + 1); continue }
      if (!/\.(jsonl|md|json)$/.test(e.name)) continue
      const p = path.join(abs, e.name)
      const lines = fs.readFileSync(p, 'utf8').split(/\r?\n/)
      lines.forEach((l, i) => { if (l.includes(q)) hits.push({ p: path.relative(ROOT, p).replace(/\\/g, '/'), i: i + 1, l: l.trim().slice(0, 160) }) })
    }
  }
  walk('state')
  console.log(`命中 ${hits.length} 条（state/ 下）：`)
  for (const h of hits.slice(0, 20)) console.log(`  ${h.p}:${h.i}  ${h.l}`)
  if (hits.length > 20) console.log(`  …另有 ${hits.length - 20} 条`)
  process.exit(hits.length ? 0 : 12)
}
table.recall = cmdRecall
table.hosts = cmdHosts
