#!/usr/bin/env node
// AuraPolaris CLI。零依赖。自解释约定:每个子命令先打印【这是什么 / 为什么 / 怎么复核】,再打印结果。
//   node cli/polaris.mjs doctor | lint | selftest | gate --in <report> | ledger add|ls | state get|set | help
// 退出码: 0 成功/approve, 1 用法或 IO 错误, 10 rerun, 11 halt, 12 检查失败, 13 unverified
import fs from 'node:fs'
import path from 'node:path'
import crypto from 'node:crypto'
// 子进程超时【唯一实现】(批次3 P3-21):这里的每个 spawn 都要有 timeout,且超时能杀整棵进程树(.cmd 包装器)。
import { runSync, DEFAULT_TIMEOUT_MS } from '../skills/aurapolaris/tools/run-sync.mjs'
// 路径推导只用 fileURLToPath:URL.pathname 保留百分号编码,安装目录含空格/中文时 ROOT 会变成 "...%20..."(P2-6 反证)
import { fileURLToPath } from 'node:url'
// 内容比对用的 sha256 只允许一份实现(tools/fingerprint.mjs 是工作区指纹的单一来源);这里只 import,不内联第二份
import { sha256 } from '../tools/fingerprint.mjs'
// 注入面接线判定【唯一实现】:适配器文件 + 机制声明 + 证据 + 本机实证,四者齐才算"已接线"(文件在≠接了线)。
// doctor 只消费它,不在这里写第二套判据;声明表=skills/aurapolaris/tools/adapters/injection.json。
import { judge as judgeInjection, isWired, isPartial } from '../tools/injection-matrix.mjs'
// 宿主根清单解析【唯一实现】=tools/host-matrix.mjs#parseHosts(F2-6:此前本文件另抄了一份 split('|') 解析,
//   与唯一实现两侧对"列数/注释/重复 host"的判定会各自漂移;单源门禁 tools/single-source.mjs --check 点名过 cli/polaris.mjs:83)。
import { parseHosts } from '../tools/host-matrix.mjs'
// 打包域【单一定义】=tools/pack-domain.mjs(§0.4 单源):终态产物清单与 tools/package.mjs 的脏检查/collect
//   读同一份域 —— 以前这里另写了一份 SHIP_DIRS/SHIP_FILES,隔离目录(.removed-*)在包里被排除、清单里还在,
//   两边口径各自漂移。安装态布局是 polaris/cli/polaris.mjs → polaris/tools/pack-domain.mjs,相对路径一致。
import { PACK_ROOTS, STATE_FILES, toPosix, inPackDomain, packDomainMayContain } from '../tools/pack-domain.mjs'

const argv = process.argv.slice(2)
const cmd = argv[0] ?? 'help'
// 选项解析:help 里写的是等号写法(--target=…),而 opt() 原先只认空格写法 —— 用户照 help 敲等号时,
//   值被吞掉、静默用默认路径去查/写宿主配置(2026-09-22 反证:hook status --target=E:\tmp\nope\hooks.json
//   报的仍是默认 ~/.codex/hooks.json)。现在两种写法等价,且 CLI 自己解析的子命令只认下面这张表:
//   未知 key、等号缺值、开关带 = 值一律 usage 错(exit 1),不许静默回落。
// 这张表必须覆盖 kernel/io.json.cli.global_flags 声明的全局旗标 --json/--quiet/--root:P2 a6d7712024c8 实测
//   --root/--quiet 不在表里 → assertArgs 当场判 usage 错(exit 1),照契约集成的调用方一个都进不来。
const BOOL_OPTS = ['apply', 'approve', 'check', 'dry-run', 'facts-only', 'force-unsafe', 'help', 'json', 'quiet', 'rollback', 'strict-p1']
const VALUE_OPTS = ['excerpt', 'in', 'iteration', 'kind', 'locator', 'max-iters', 'proposal', 'root', 'stage', 'target']
const KNOWN_OPTS = [...BOOL_OPTS, ...VALUE_OPTS]
// 子系统命令(blueprint/user/agents/ctx/realq/graph)把参数原样转交给各自的工具:旗标由那些工具解析,本 CLI 不越权判它们的 key。
//   graph 必须在这张表里:它有 --export/--source/--serve/--selftest/--explain/--port/--ledger-root/--sessions-root,
//   一个都不在该 CLI 的 KNOWN_OPTS 里 —— 漏进表里就会在转发【之前】被 assertArgs 判成「未知选项 --export」exit 1
//   (2026-09-29 本单实测:polaris graph --export … 正是这么红的)。
const PASSTHROUGH_CMDS = ['blueprint', 'user', 'agents', 'ctx', 'realq', 'graph']
function assertArgs(args, cmdName) {
  if (PASSTHROUGH_CMDS.includes(cmdName)) return
  for (let i = 1; i < args.length; i++) {
    const a = args[i]
    if (!a.startsWith('--')) continue
    const eq = a.indexOf('=')
    const key = a.slice(2, eq >= 0 ? eq : a.length)
    if (!KNOWN_OPTS.includes(key)) {
      console.error(`用法错误: 未知选项 --${key}(可用: ${KNOWN_OPTS.map((k) => '--' + k).join(' ')});node cli/polaris.mjs help`)
      process.exit(1)
    }
    if (eq >= 0) {
      if (a.slice(eq + 1) === '') { console.error(`用法错误: --${key}= 缺值(等号写法必须给值)`); process.exit(1) }
      if (BOOL_OPTS.includes(key)) { console.error(`用法错误: --${key} 是开关,不接受 =值(写成 --${key})`); process.exit(1) }
      continue
    }
    if (VALUE_OPTS.includes(key)) {
      const v = args[i + 1]
      if (v === undefined || v.startsWith('--')) { console.error(`用法错误: --${key} 缺值`); process.exit(1) }
      i++
    }
      if (v === undefined || v.startsWith('--')) { console.error(`用法错误: --${key} 缺值`); process.exit(1) }
      i++
    }
  }
}
const opt = (n, d = null) => {
  const i = argv.indexOf(`--${n}`)
  if (i >= 0) return argv[i + 1] ?? d
  const p = argv.find((a) => a.startsWith(`--${n}=`))
  return p ? p.slice(n.length + 3) : d
}
const flag = (n) => argv.includes(`--${n}`) || argv.some((a) => a.startsWith(`--${n}=`))
// ---- 用法档守卫(2026-09-29 arch-v2.C42):只做参数校验,不改任何既有档的行为与输出 ----
//   为什么必须有:`help` 本来就在 BOOL_OPTS 白名单里,所以 `build --help` 不被判用法错,
//   直接进 cmdBuild() → renderDesiredState() + writeFileSync(desired_state.json) ——
//   于是"想看用法"这个只读意图会重算终态清单(实测:mtime 与内容双双变)。
//   出口语义与其余生成器统一:--help/-h → 打用法 + exit 0;未识别 --xxx 仍由 assertArgs 校验 + exit 1;
//   两者都在【任何写盘动作之前】离开,不执行默认动作、不写盘。
//   只覆盖有默认动作的子命令;hook/ledger/state/limits 有自己的子档用法,不在表里,行为一字未动。
//   位置约束:本段必须在 assertArgs 【之前】—— assertArgs 只认 KNOWN_OPTS 白名单,而 --help 已不在里面,
//   放到它后面会被先判成未知选项 exit 1(2026-09-29 克隆实测:build --help 正是这么红的),够不着用法档。
const USAGE_LINE = {
  build: '用法: node cli/polaris.mjs build [--check] [--help]   (无档=重新生成 desired_state.json;--check=只核对不写盘,exit 0=一致/12=漂移)',
  doctor: '用法: node cli/polaris.mjs doctor [--check] [--help]   (--check=内容漂移判红)',
  lint: '用法: node cli/polaris.mjs lint [--help]',
  selftest: '用法: node cli/polaris.mjs selftest [--help]',
  gate: '用法: node cli/polaris.mjs gate --in <report.json> [--help]',
  upgrade: '用法: node cli/polaris.mjs upgrade [--check|--dry-run|--rollback] [--help]',
  uninstall: '用法: node cli/polaris.mjs uninstall [--dry-run] [--help]',
  hosts: '用法: node cli/polaris.mjs hosts [--check] [--help]',
  calibrate: '用法: node cli/polaris.mjs calibrate [--help]',
  recall: '用法: node cli/polaris.mjs recall "<关键词>" [--help]',
}
if ((argv.includes('--help') || argv.includes('-h')) && cmd !== 'help') {
  const line = USAGE_LINE[cmd]
  if (line) { console.log(line); process.exit(0) }
  // 未列名的命令(含子系统转发):退回总用法 —— 仍是"打用法 + exit 0",不执行默认动作。
  cmdHelp()
  process.exit(0)
}
// 其余参数才交给既有白名单校验(未识别 --xxx → 点名 + exit 1;这条口径一字未动)
