function shippedFiles() {
  const list = []
  for (const r of PACK_ROOTS) {
    if (!r.state) continue
    const abs = path.join(ROOT, r.dir)
    if (!fs.existsSync(abs)) continue
    const w = (d) => {
      for (const e of fs.readdirSync(d, { withFileTypes: true })) {
        const p = path.join(d, e.name)
        const rel = toPosix(path.relative(ROOT, p))
        if (e.isDirectory()) { if (packDomainMayContain(rel)) w(p); continue }
        if (inPackDomain(rel)) list.push(rel)
      }
    }
    w(abs)
  }
  for (const f of STATE_FILES) if (fs.existsSync(path.join(ROOT, f))) list.push(f)
  return [...new Set(list)].sort()
}
