function stripVolatile(o) { const c = JSON.parse(JSON.stringify(o)); delete c.generated_at; return c }
function cmdBuild() {
  const check = flag('check')
  const rendered = renderDesiredState()
  const dsPath = path.join(ROOT, 'desired_state.json')
  say('生成/核对终态文件 desired_state.json',
    '机器部分(版本/产物清单+哈希/入口)每次重算;散文部分(不变式/验收)保留人写内容',
    'node cli/polaris.mjs build --check')
  if (check) {
    const cur = fs.existsSync(dsPath) ? readJson(dsPath) : null
    const same = cur && JSON.stringify(stripVolatile(cur)) === JSON.stringify(stripVolatile(rendered))
    if (!same) {
      const curPaths = new Set((cur?.artifacts ?? []).map((a) => `${a.path}:${a.sha256_16}`))
      const want = rendered.artifacts.map((a) => `${a.path}:${a.sha256_16}`)
      const missing = want.filter((x) => !curPaths.has(x)).slice(0, 10)
      const extra = [...curPaths].filter((x) => !want.includes(x)).slice(0, 10)
      console.log(`\n漂移: 终态文件 ${cur?.spec_version ?? '(缺失)'} vs 内核 ${rendered.spec_version}`)
      if (missing.length) console.log('  需写入: ' + missing.join(', '))
      if (extra.length) console.log('  已过期: ' + extra.join(', '))
      console.log('  修复: node cli/polaris.mjs build')
    } else console.log(`\n一致: ${rendered.artifacts.length} 个产物,spec ${rendered.spec_version}(generation ${rendered.generation})`)
    process.exit(same ? 0 : 12)
  }
  fs.writeFileSync(dsPath, JSON.stringify(rendered, null, 1))
  console.log(`\n已生成: desired_state.json  spec=${rendered.spec_version} generation=${rendered.generation} artifacts=${rendered.artifacts.length}`)
}

