function cmdRecall() {
  const q = argv.slice(1).join(' ').trim()
  if (!q) { console.error('用法: polaris recall "<关键词>"'); process.exit(1) }
  say('跨会话检索', '在 state/ 的历史证据里找"上次是怎么判的"', 'node cli/polaris.mjs recall "关键词"')
  const hits = []
  const walk = (d, depth = 0) => {
    if (depth > 4) return
    const abs = path.join(ROOT, d)
    if (!fs.existsSync(abs)) return
    for (const e of fs.readdirSync(abs, { withFileTypes: true })) {
      if (e.isDirectory()) { walk(path.join(d, e.name), depth + 1); continue }
      if (!/\.(jsonl|md|json)$/.test(e.name)) continue
      const p = path.join(abs, e.name)
      const lines = fs.readFileSync(p, 'utf8').split(/\r?\n/)
      lines.forEach((l, i) => { if (l.includes(q)) hits.push({ p: path.relative(ROOT, p).replace(/\\/g, '/'), i: i + 1, l: l.trim().slice(0, 160) }) })
    }
  }
