// ---------------------------------------------------------------- A 径向焦点
function svgA() {
  const cx = 860, cy = 520, R = 372, N = ch.length
  let s = head(W, H, '草图 A · 径向焦点', '主代理居中，子代理成环（按工作量排序），孙代理挂在外圈 —— 一眼看出"派了多少、谁最重"')
  s += overview()
  // 环轴
  s += `<circle cx="${cx}" cy="${cy}" r="${R}" fill="none" stroke="${LINE}" stroke-dasharray="2 6"/>`
  for (const { n: gn, parent } of grand) {
    const i = ch.findIndex((c) => c.id === parent.id)
    const a = (-90 + i * (360 / N)) * Math.PI / 180
    const gx = cx + Math.cos(a) * (R + 84), gy = cy + Math.sin(a) * (R + 84)
    s += `<path d="M ${n1(cx + Math.cos(a) * (R + 18))} ${n1(cy + Math.sin(a) * (R + 18))} Q ${n1(cx + Math.cos(a) * (R + 52))} ${n1(cy + Math.sin(a) * (R + 52))} ${n1(gx)} ${n1(gy)}" fill="none" stroke="${LINE}" stroke-dasharray="3 4"/>
<rect x="${n1(gx - 26)}" y="${n1(gy - 9)}" width="52" height="18" rx="9" fill="#1a2130" stroke="${LINE}"/><text x="${n1(gx)}" y="${n1(gy + 4)}" fill="${TX3}" font-size="9.5" text-anchor="middle" font-family="${MONO}">孙 ${esc(gn.short)}</text>`
  }
  ch.forEach((n, i) => {
    const a = (-90 + i * (360 / N)) * Math.PI / 180
    const x = cx + Math.cos(a) * R, y = cy + Math.sin(a) * R
    const pw = 58, ph = 24, bw = Math.max(6, n1((n.counts.toolCalls / maxTools) * (pw - 8)))
    s += `<path d="M ${cx} ${cy} Q ${n1(cx + Math.cos(a) * R * 0.55)} ${n1(cy + Math.sin(a) * R * 0.55)} ${n1(x)} ${n1(y)}" fill="none" stroke="#2c3b57" stroke-width="1.1"/>
<g><rect x="${n1(x - pw / 2)}" y="${n1(y - ph / 2)}" width="${pw}" height="${ph}" rx="7" fill="#1b2432" stroke="${ST[n.status] ?? LINE}" stroke-opacity="0.75"/>
<text x="${n1(x)}" y="${n1(y - 1)}" fill="${TX}" font-size="9.5" text-anchor="middle" font-family="${MONO}">${esc(n.short)}</text>
<text x="${n1(x)}" y="${n1(y + 9)}" fill="${TX3}" font-size="8.5" text-anchor="middle" font-family="${MONO}">${n.counts.toolCalls}</text>
<rect x="${n1(x - pw / 2 + 4)}" y="${n1(y + ph / 2 - 3)}" width="${bw}" height="2" rx="1" fill="${ST[n.status] ?? ACC}"/></g>`
  })
  s += `<rect x="${cx - 118}" y="${cy - 40}" width="236" height="80" rx="16" fill="#1d2637" stroke="${ACC}" stroke-width="1.6"/>
<text x="${cx}" y="${cy - 12}" fill="${TX}" font-size="15" font-weight="600" text-anchor="middle">主代理 ${esc(cur.short)}</text>
<text x="${cx}" y="${cy + 9}" fill="${ACC}" font-size="11.5" text-anchor="middle" font-family="${MONO}">${cur.counts.toolCalls} 工具 · 派 ${ch.length}</text>
<text x="${cx}" y="${cy + 27}" fill="${TX3}" font-size="10.5" text-anchor="middle">${esc(cur.status)} · 本会话</text>
<circle cx="${cx}" cy="${cy - 40}" r="4" fill="${ST.active}"/>`
  s += legend(40, H - 96)
  s += `<text x="${W - 40}" y="${H - 60}" fill="${TX3}" font-size="11" text-anchor="end">历史会话 ${g.nodes.filter((n) => n.depth === 0).length - 1} 个已折叠（草图未画）· 浅蓝=空转 灰=已结束 绿=活跃</text>`
  return s + '</svg>'
}

// ---------------------------------------------------------------- B 分簇看板
function svgB() {
  let s = head(W, H, '草图 B · 分簇看板 + 台账泳道', '子代理按工作量分档成组（卡片=一个子代理），底部把台账 274 单的流向画出来')











































<text x="${lx + 18}" y="750" fill="${TX}" font-size="17" font-weight="600" font-family="${MONO}">${esc(v)}</text>`
    if (i < lane.length - 1) s += `<path d="M ${lx + 280} 728 L ${lx + 322} 728" stroke="${LINE}" stroke-width="1.4" marker-end="url(#ar)"/>`
    lx += 330
  })
  s += `<defs><marker id="ar" markerWidth="8" markerHeight="8" refX="6" refY="3" orient="auto"><path d="M0,0 L6,3 L0,6" fill="none" stroke="${LINE}" stroke-width="1.2"/></marker></defs>`
  const flows = [['done', L.counts.done, '#34d399'], ['claimed', L.counts.claimed, '#5b8cff'], ['open', L.counts.open, '#fbbf24'], ['void', L.counts.void, '#f87171']]
  let fx = 40
  s += `<text x="40" y="812" fill="${TX}" font-size="13.5" font-weight="600">任务终态分布</text>
<text x="40" y="832" fill="${TX3}" font-size="10.5">274 单里“做完的”占多大比例，以及卡在哪四类</text>`
  flows.forEach(([k, v, c]) => {
    const bw = n1((v / L.counts.total) * 300)
    s += `<rect x="${fx}" y="848" width="${bw}" height="26" fill="${c}" fill-opacity="0.9"/><text x="${fx + bw / 2}" y="866" fill="#0b0e14" font-size="11.5" font-weight="600" text-anchor="middle" font-family="${MONO}">${v}</text>`
    fx += bw
  })
  s += `<text x="${fx + 14}" y="866" fill="${TX3}" font-size="10.5">done / claimed / open / void</text>`
  s += `<text x="40" y="${H - 26}" fill="${TX3}" font-size="11">卡片底色亮 = 状态；底部细条 = 工具调用数 · 这一版把"谁在干什么"按档次排开，便于扫读</text>`
  return s + '</svg>'
}

// ---------------------------------------------------------------- C 时间泳道
function svgC() {
  let s = head(W, H, '草图 C · 时间泳道（甘特）', '每条 = 一个子代理的生命周期（横向），主代理贯穿全程 —— 这张最能表现"动态"：谁在什么时候被派、活了多久、何时并行')
  s += overview()
  const X0 = 190, X1 = W - 130, Y0 = 196, ROW = 20.5
  const t0 = Math.min(...ch.map((n) => n.createdAt)), t1 = Math.max(...ch.map((n) => n.lastEventAt))
  const span = t1 - t0
  const px = (t) => X0 + ((t - t0) / span) * (X1 - X0)
  s += `<rect x="${X0}" y="${Y0 - 26}" width="${X1 - X0}" height="4" rx="2" fill="${LINE}"/>`
  for (let h = 0; h <= 14; h += 2) {
    const x = X0 + (h / 14) * (X1 - X0)
    const d = new Date(t0 + (h / 14) * span)
    s += `<line x1="${n1(x)}" y1="${Y0 - 22}" x2="${n1(x)}" y2="${H - 90}" stroke="${LINE}" stroke-opacity="0.55"/>
<text x="${n1(x)}" y="${Y0 - 32}" fill="${TX3}" font-size="10" text-anchor="middle" font-family="${MONO}">${String(d.getHours()).padStart(2, '0')}:00</text>`
  }
  // 主代理：贯穿
  const mStart = cur.createdAt, mEnd = t1
  s += `<rect x="${n1(px(mStart))}" y="${Y0}" width="${n1(px(mEnd) - px(mStart))}" height="15" rx="7" fill="${ACC}" fill-opacity="0.9"/>
<text x="${X0 - 14}" y="${Y0 + 12}" fill="${TX}" font-size="11" text-anchor="end" font-family="${MONO}">${esc(cur.short)}</text>
<text x="${n1(px(mEnd)) - 8}" y="${Y0 + 12}" fill="${ACC}" font-size="10.5" text-anchor="end" font-family="${MONO}">主代理 · ${cur.counts.toolCalls} 工具 · 派 ${ch.length}</text>
<line x1="${n1(px(mEnd))}" y1="${Y0 - 18}" x2="${n1(px(mEnd))}" y2="${H - 96}" stroke="${ST.active}" stroke-width="1.4" stroke-dasharray="4 3"/>`
  const sorted = ch.slice().sort((a, b) => a.createdAt - b.createdAt)
  sorted.forEach((n, i) => {
    const y = Y0 + 24 + i * ROW
    if (i % 2) s += `<rect x="${X0}" y="${n1(y + 1)}" width="${X1 - X0}" height="${n1(ROW - 2)}" fill="#ffffff" fill-opacity="0.022"/>`
    const x = px(n.createdAt), w = Math.max(9, Math.min(px(n.lastEventAt), X1) - x)
    const c = ST[n.status] ?? ACC
    s += `<text x="${X0 - 14}" y="${y + 11}" fill="${TX3}" font-size="9.5" text-anchor="end" font-family="${MONO}">${esc(n.short)}</text>
<rect x="${n1(x)}" y="${n1(y + 3)}" width="${n1(w)}" height="11" rx="5.5" fill="${c}" fill-opacity="${n.status === 'idle' ? 0.55 : 0.42}" stroke="${c}" stroke-opacity="0.85"/>
<path d="M ${n1(x)} ${n1(y + 2)} l 0 -5 l 5 2.5 z" fill="${c}"/>
<text x="${X1 + 18}" y="${y + 12}" fill="${TX3}" font-size="9.5" font-family="${MONO}">${n.counts.toolCalls}</text>`
  })
  const gn = grand[0]
  if (gn) {
    const y = Y0 + 24 + sorted.length * ROW + 6
    s += `<text x="${X0 - 14}" y="${y + 11}" fill="${TX3}" font-size="9.5" text-anchor="end" font-family="${MONO}">孙 ${esc(gn.n.short)}</text>
<rect x="${n1(px(gn.n.createdAt))}" y="${n1(y + 3)}" width="${n1(Math.max(9, Math.min(px(gn.n.lastEventAt), X1) - px(gn.n.createdAt)))}" height="11" rx="5.5" fill="#a78bfa" fill-opacity="0.45" stroke="#a78bfa" stroke-opacity="0.85"/>`
  }
  s += `<text x="40" y="${H - 60}" fill="${TX3}" font-size="11">三角形 = spawn 时刻 · 条长 = 生命周期（createdAt→lastEventAt）· 实时版里新条会从左端生长出来，"现在"线向右走</text>`
  s += `<text x="${X1 + 18}" y="${Y0 - 22}" fill="${TX3}" font-size="10.5">工具数</text>`
  return s + '</svg>'
}

fs.writeFileSync(`${OUT}/A-radial.svg`, svgA())
fs.writeFileSync(`${OUT}/B-cluster.svg`, svgB())
fs.writeFileSync(`${OUT}/C-gantt.svg`, svgC())

