// =============================================================================
// --selftest:在【本仓库内】沙箱上跑真实子进程(不是调内部函数)。
//   为什么必须走子进程:本工具的输出形状(SKEW/STALE/计数行/退出码)就是接口,只有子进程能见证它;
//   在进程内调内部函数只能证明"变量值对",证明不了"打出来的东西对"。
//   做法对照 tools/host-matrix.mjs:149 的 SANDBOX:自建夹具 → 逐条断言 → finally 自清(判红路径也要清)。
//   下面全部用【函数声明】:它们在顶部 `if (argv.includes('--selftest')) cmdSelftest()` 处被调用,
//   而函数声明的提升正好跨过那里 —— 写成 const 箭头函数会踩 TDZ。
// =============================================================================
function sandboxReset() {
  // 拒绝在/清理工作区外的路径(照 host-matrix 的护栏:沙箱常量被改坏时不许 rm 到别处)。
  if (!path.resolve(SANDBOX).startsWith(path.resolve(REPO_ROOT) + path.sep)) {
    throw new Error(`拒绝清理工作区外的路径: ${SANDBOX}`)
  }
  fs.rmSync(SANDBOX, { recursive: true, force: true })
  fs.mkdirSync(SANDBOX_TASKS, { recursive: true })
}
// 一张夹具单 = 任务文件 + claim 文件;两者的 mtime 都按 writeMinutesAgo 设到过去(utimesSync 改的就是"最后写盘")。
//   claimSkewMinutes > 0 = claimed_at 落在未来(时钟偏移);否则 claimAgeMinutes > 0 = 落在过去。
function writeFixture(id, { claimSkewMinutes = 0, claimAgeMinutes = 0, writeMinutesAgo = 0, voidBody = null }) {
  const now = Date.now()
  const claimedAt = new Date(claimSkewMinutes > 0 ? now + claimSkewMinutes * 60000 : now - claimAgeMinutes * 60000)
  const taskAbs = path.join(SANDBOX_TASKS, `${id}.json`)
  const claimAbs = path.join(SANDBOX_TASKS, `${id}.claim.json`)
  fs.writeFileSync(taskAbs, JSON.stringify({ id, title: 'pipeline-watch 自证夹具', role: 'writer', kind: 'task', created_at: new Date(now - 60 * 60000).toISOString(), brief_sha256: '0'.repeat(64) }, null, 1))
  fs.writeFileSync(claimAbs, JSON.stringify({ id, claimed_by: 'selftest', claimed_at: claimedAt.toISOString() }, null, 1))
  // voidBody !== null = 顺带落一张 <id>.void.json(内容原样写,好造"顶层非对象"形态);默认不建 = 既有夹具逐字同形。
  if (voidBody !== null) fs.writeFileSync(path.join(SANDBOX_TASKS, `${id}.void.json`), voidBody)
  const t = new Date(now - writeMinutesAgo * 60000)
  fs.utimesSync(taskAbs, t, t)
  fs.utimesSync(claimAbs, t, t)
// 【收工事件】走真命令(skills/aurapolaris/tools/agent-view.mjs beat --event=done --receipt=…):
//   本判据消费的是那份记录形状,写侧与判侧必须端到端对得上(内部手写 JSONL 只能证明"我以为的形状"):
//   实测依据=同一单里两处写同一个字段的教训(AGENTS.md §0.4 "写成两份的代价")。
function beatDone(task, receiptRel, extra = []) {
  const av = path.join(REPO_ROOT, 'skills', 'aurapolaris', 'tools', 'agent-view.mjs')
  const args = [av, 'beat', '--agent=selftest', `--task=${task}`, '--event=done', ...(receiptRel ? [`--receipt=${receiptRel}`] : []), ...extra]
  const r = spawnSync(process.execPath, args, { cwd: SANDBOX, env: { ...process.env, POLARIS_ROOT: SANDBOX }, encoding: 'utf8', maxBuffer: 8 << 20 })
  if (r.error) throw new Error(`agent-view beat 起不来: ${r.error.code ?? r.error.message}`)
  return { code: r.status ?? 1, out: `${r.stdout ?? ''}${r.stderr ?? ''}` }
}
// 直接往账本追加一行(造存量/坏行形态用;正常路径一律走 beatDone = 真命令)。
function appendLedger(rec) {
