}
function minutesFromNow(m) { return new Date(Date.now() - m * 60000).toISOString() }
// 子进程的唯一出口:根必须【显式】钉死(cwd=SANDBOX 且 POLARIS_ROOT=SANDBOX 双保险,CONS-7 约定)。
function runWatch(args) {
  const r = spawnSync(process.execPath, [TOOL, ...args], {
    cwd: SANDBOX, env: { ...process.env, POLARIS_ROOT: SANDBOX }, encoding: 'utf8', maxBuffer: 8 << 20,
  })
  if (r.error) throw new Error(`子进程起不来(node ${args.join(' ')}): ${r.error.code ?? r.error.message}`)
  return { code: r.status ?? 1, out: `${r.stdout ?? ''}${r.stderr ?? ''}`, args: args.join(' ') }
}
function outLines(out) { return String(out ?? '').split(/\r?\n/).map((l) => l.trimEnd()).filter((l) => l.trim()) }
function lineWith(out, prefix) { return outLines(out).find((l) => l.startsWith(prefix)) ?? null }
function tailOf(out, n = 3) { return outLines(out).slice(-n).join(' ⏎ ') || '(空)' }
// 负数【年龄】的形状才是缺陷本体("在跑 -30 分钟")。偏移量本身带负号(偏移 -30 分钟)是正常输出,不在此列。
function negativeAges(out) { return outLines(out).filter((l) => /(在跑|待领|无回执|无人认领|无任何写盘)\s*-\d+\s*分钟/.test(l)) }
function must(cond, msg) { if (!cond) throw new Error(msg) }

























