    // 子(绿相回归·反向):全绿盘(在跑/待领/已收工/已作废四种 status 齐全,零坏件)→ exit 0 且无 BAD-POINTER。
    run('子 全绿盘(在跑+待领+已收工+已作废)→ exit 0 且无 BAD-POINTER', () => {
      sandboxReset()
      writeFixture('T-20260101000000-5555', { claimAgeMinutes: 2, writeMinutesAgo: 2 })
      fs.writeFileSync(path.join(SANDBOX_TASKS, 'T-20260101000000-6666.json'), JSON.stringify({ id: 'T-20260101000000-6666', title: '待领夹具', created_at: new Date(Date.now() - 3 * 60000).toISOString() }))
      writeFixture('T-20260101000000-7777', { claimAgeMinutes: 5, writeMinutesAgo: 5 })
      fs.writeFileSync(path.join(SANDBOX_TASKS, 'T-20260101000000-7777.result.json'), JSON.stringify({ status: 'ok', evidence: [] }))
      // 【本单新增】有回执就得有收工事件(缺一即红):夹具不补这一条,该盘就不再是"全绿盘"——
      //   这是把夹具对齐到新生效契约(收紧侧),不是给判据开豁免。
      must(beatDone('T-20260101000000-7777', 'state/tasks/T-20260101000000-7777.result.json').code === 0, 'agent-view beat 未成功')
      writeFixture('T-20260101000000-8888', { claimAgeMinutes: 5, writeMinutesAgo: 5, voidBody: JSON.stringify({ id: 'T-20260101000000-8888', status: 'void', reason: '绿相夹具' }) })
      const r = runWatch(['--max-minutes=30', '--quiet-minutes=15'])
      const j = runWatch(['--max-minutes=30', '--quiet-minutes=15', '--json'])
      must(r.code === 0, `期望 exit 0,实得 ${r.code};尾部: ${tailOf(r.out)}`)
      must(!/BAD-POINTER/.test(r.out), `全绿盘却打了 BAD-POINTER: ${outLines(r.out).filter((l) => l.startsWith('BAD-POINTER')).join(' | ')}`)
      must(!!lineWith(r.out, 'WAIT : T-20260101000000-5555'), `在跑单没列出来: ${tailOf(r.out)}`)
      must(!!lineWith(r.out, 'QUEUE: T-20260101000000-6666'), `无 claim 的待领单没列出来(既有面被坏指针改动挤掉了): ${tailOf(r.out)}`)
      must(!!lineWith(r.out, 'VOID : T-20260101000000-8888'), `完好作废单没列出来: ${tailOf(r.out)}`)
      const counts = lineWith(r.out, '计数')
      must(/回执 1/.test(counts) && /作废 1/.test(counts) && /在跑 1/.test(counts) && /待领 1/.test(counts), `计数行四种 status 不全(既有计数口径被改): ${counts}`)
      const jj = JSON.parse(j.out)
      must(j.code === 0 && jj.verdict === 'OK' && jj.counts.bad_pointers === 0, `--json exit=${j.code} verdict=${jj.verdict} bad_pointers=${jj.counts.bad_pointers}(期望 0/OK/0)`)
      must((jj.bad_pointers ?? []).length === 0, `--json 顶层 bad_pointers 非空: ${JSON.stringify(jj.bad_pointers)}`)
      return `${counts.trim().slice(0, 44)}… ｜ json verdict=${jj.verdict} bad_pointers=0 ｜ exit=${r.code}`
    })
    // 丑(反向):半写【认领记录】→ 非 0 + 点名 .claim.json,不许降级成"待领"(认领是"在跑"的唯一产物凭证)。
    run('丑 半写认领记录(claim 截断)→ 非 0 + 点名 .claim.json,不许降级成待领', () => {
      sandboxReset()
      const ID = 'T-20260101000000-9999'
      writeFixture(ID, { claimAgeMinutes: 2, writeMinutesAgo: 2 })
      fs.writeFileSync(path.join(SANDBOX_TASKS, `${ID}.claim.json`), `{"id":"${ID}","claimed_by":"selftest"`)
      const r = runWatch(['--max-minutes=30', '--quiet-minutes=15'])
      const j = runWatch(['--max-minutes=30', '--quiet-minutes=15', '--json'])
      must(r.code === 12, `期望 exit 12,实得 ${r.code};尾部: ${tailOf(r.out)}`)
      const bp = lineWith(r.out, `BAD-POINTER: state/tasks/${ID}.claim.json`)
      must(!!bp, `没有点名该 .claim.json 的 BAD-POINTER 行;尾部: ${tailOf(r.out)}`)
      must(/认领记录/.test(bp), `没点出坏的是认领记录(不是任务指针): ${bp}`)
      const faces = outLines(r.out).filter((l) => l.includes(ID))
      must(faces.length === 1 && faces[0].startsWith('BAD-POINTER: '), `半写 claim 的单被并进别的面: ${faces.join(' | ') || '(无)'}`)
      const jj = JSON.parse(j.out)
      must(jj.counts.bad_pointers === 1, `--json counts.bad_pointers=${jj.counts.bad_pointers}(期望 1)`)
      must((jj.bad_pointers ?? []).some((x) => x.file === `state/tasks/${ID}.claim.json` && x.kind === 'claim'), `--json bad_pointers 没点名 claim 件: ${JSON.stringify(jj.bad_pointers)}`)
      const row = (jj.rows ?? []).find((x) => x.id === ID)
      must(row?.status === 'unreadable' && row?.zone === 'broken', `--json status=${row?.status}/zone=${row?.zone}(期望 unreadable/broken)`)
      return `${bp.trim().slice(0, 72)}… ｜ json 行 status=${row.status}/zone=${row.zone} ｜ exit=${r.code}`
    })
  } finally {
    // 自清:判红路径(process.exit(12)/抛错)也走这里。残留本身要判红,不许"留下了但说清理了"。
    if (path.resolve(SANDBOX).startsWith(path.resolve(REPO_ROOT) + path.sep)) {
      fs.rmSync(SANDBOX, { recursive: true, force: true })
      residue = fs.existsSync(SANDBOX)
    } else residue = true
  }
  cases.push({ name: '己 沙箱自清(无残留)', ok: !residue, detail: residue ? `仍在盘上: ${relSandbox()}` : `已删: ${relSandbox()}(无残留)` })
  for (const c of cases) console.log(`${c.ok ? 'PASS' : 'FAIL'}  ${c.name}  ${c.detail}`)
  const badN = cases.filter((c) => !c.ok).length
  console.log(badN ? `PIPELINE-WATCH SELFTEST FAIL: ${cases.length - badN}/${cases.length}` : `PIPELINE-WATCH SELFTEST PASS: ${cases.length}/${cases.length}`)
  process.exit(badN ? 12 : 0)
}

