//   .polaris              workorder 与运行态账本
//   state/rounds          轮次清单/回执副本/六路审查聚合(DIGEST.jsonl、CONVERGENCE.json) —— 第一批
//   state/reviews         审查报告落盘 —— 第一批
//   state/realq           真实问题库跑批输出(findings.jsonl、summary.json) —— 第一批
//   state/ranges          冻结靶场的 SPEC/run.mjs/raw 原始输出 —— 第二批(本单)。凭什么:①4 张任务指针
//                         (T-20260927113648-47e0、T-20260927114822-d654、T-20260927134005-c356、
//                         T-20260927143906-c966)的 allow_write_paths 直接点名 state/ranges/**;
//                         ②实测 11 次写入落在 3 张任务的派单窗口内(例 R7-A/SPEC.md 写于
//                         T-20260927113946-9f70 窗口内);③实害已发生(T-20260927144203-4022 因它被判真 DRIFT 停工)。
//   state/evidence        子代理取证留档家族的基底目录(现为空)
//   state/evidence-T-*    【前缀型条目,原为逐目录列举的 9 条】凭什么该跳:①目录名内嵌被派任务 id,9/9 能对上现存任务指针;
//                         ②任务指针 T-20260924141556-fa5a 的 allow_write_paths 直接点名其中一个 -> 写者就是被派任务;
//                         ③实测 8 个目录共 ~159 次写入落在 10 张任务的派单窗口内,且含**跳单**实例
//                         (evidence-T-20260922155608-6f0f/gates-after.txt 写在 T-20260922161511-bf12 的窗口内;
//                         evidence-T-20260922232055-f15f/REPORT.md 同在 bf12 窗口内)-> 与 state/ranges 同类,会造真 DRIFT。
// 【代价(第二批的诚实边界)】state/ranges 与 evidence 家族因此**不再计入 DRIFT 检测**:靶场 raw/**
//   与历史取证包被改写,stamp 不会再报。那一层改由靶场 runner 自报(副本未被改坏)与回执自报 sha256 负责。
//   换来的是"靶场单/取证单不再被跳弟单误挡"。
// 【残余已收口 · 2026-09-27 T-20260927153246-488e 第三批】上一批把 state/evidence-T-* 写成**逐个目录列举**
//   (9 条),残余是:新铸一张单 -> 再建一个 state/evidence-<新id>/ -> 忘了在这里追加一行 -> 又一张单被假
//   DRIFT 挡住(这个残余在本轮已真实付过一次代价)。本批**新增一条前缀型条目** state/evidence-T-*,
//   以后同类目录(含新铸单建的)一次性纳入,不必再人工跟单 —— 实测:把表换回"只有 9 条字面项"的旧表,
//   触写 state/evidence-T-20990101-brandnew/f.txt 会让 treeStamp 的 sha 变(假 DRIFT 复现);前缀条目在表内
//   时同一个触写 sha 不变。前缀语法见上方【前缀型跳过条目】;安全线已同步覆盖前缀型。
//   【已于 2026-09-28 收敛 · T-20260927160811-5734】那 9 条逐目录字面项**已删除**,表里只剩前缀条目
//   state/evidence-T-*。它们对 fingerprint 早已冗余(前缀全覆盖);当时不删的唯一理由是"tools/taskctl.mjs
//   的 under() 不认 '*',删了会静默丢掉 taskctl 那侧的越界豁免"—— 该阻塞已由 T-20260927154732-96f8
//   解除:它让 taskctl 的 under() 复用本模块导出的 matchesSkip,全仓只剩这一份"哪些 rel 被跳过"的语义。
//   前置条件、复核命令与实测读数见数组里那段注释。
//   边界如实声明:前缀是字面量截断(不做通配展开);它只影响"哪些 rel 进跳过表",treeStamp 的算法
//   (relpath|size|mtime 排序取 sha)与 stampDiff 的输出形状一字未改;单源组合(SKIP_REL = .git +
//   DISPATCH_ARTIFACTS + APPEND_ONLY_LEDGERS)也一字未改。
// 【未纳入(逐条给依据,详单见回执)】state/backup-*(0/172 张任务指针授权写它;写者是宿主安装工具
//   apply-hook.mjs / apply-hook-dsh.mjs,会写家目录;内容是被改产品件的改前快照 = 近似"源",
//   不入跳过表反而白赚一份快照完整性)、state/approvals(放宽授权的权威记录)、state/status.json
//   (安装验收结论的权威落点)、state/hook-snippets、state/metrics、state/blueprints、state/budget、
//   state/calibration、state/probe-sdk-indep-1、state/usage-samples、state/user。
export const DISPATCH_ARTIFACTS = [
  'state/tasks',
  'state/ab3',
  '.polaris',
  'state/rounds',
  'state/reviews',
  'state/realq',
  'state/ranges',
  'state/evidence',
  // 【前缀型】= 所有 state/evidence-T-<taskId>/(含以后新铸单新建的)。凭什么该跳见上方注释。
  //   【已于 2026-09-28 收敛 · T-20260927160811-5734】这里原先还并列着 9 条逐目录字面项,本批删除,
  //   只留这一条前缀项。删得起是因为【前置条件】已成立:tools/taskctl.mjs 的越界判定(cmdRecycle 里
  //   `under = (a, b) => matchesSkip(a, b)`,由 T-20260927154732-96f8 改)已复用本模块导出的 matchesSkip
  //   —— 96f8 之前 taskctl 自带 `under = (a,b) => a===b || a.startsWith(b+'/')` **不认** '*',那时这 9 条
  //   是载荷(实测:旧 under('…/state/evidence-T-2026…-ff1e/REPORT.md',  '…/state/evidence-T-*') = false);
  //   96f8 之后同一判定 = true,前缀条目单独就扛得起这 9 个目录的豁免。96f8 另实测:删掉 9 条后
  //   taskctl selftest 仍 12/12 PASS,把前缀条目也一起删掉才变红。
  //   【复核命令】① node tools/taskctl.mjs selftest —— 施工单消费侧 12/12,其中 wo-gate-prefix-skip-exempt
  //   (前缀型跳过条目豁免生效)与 wo-gate-product-still-flagged(产品件仍算越界)必须同时 PASS;
  //   ② node state/rounds/R8/checks/fingerprint-skip-safety.mjs . —— 条目数变少但两条安全线不变
  //   (MUST_SKIP 仍在表内 + 跳过表不命中产品路径)。本批两条的实测读数与原始输出见
  //   state/tasks/T-20260927160811-5734.result.json。
  'state/evidence-T-*',
]

// 统一跳过表:.git(版本库元数据,每次 commit/checkout 都变) + 派单机械件 + 只追加账本。
// 调用方可传更窄的表(如 taskctl 自证沙箱要盯住 state/tasks 里被写坏的任务文件)。
export const SKIP_REL = ['.git', ...DISPATCH_ARTIFACTS, ...APPEND_ONLY_LEDGERS]

// 安全线①模块加载即断言(fail-closed):表一旦被改坏,所有 import 方立刻红,
// 不留给"把产品目录加进跳过表"一个静默生效的窗口。合法表下本块零副作用。
{
  const unsafe = auditSkipTable(SKIP_REL)
  if (unsafe.length) throw new Error(`跳过表命中产品路径(会让 DRIFT 检测对产品件失效,静默放宽): ${unsafe.join(', ')}`)
}

export const sha256 = (s) => crypto.createHash('sha256').update(s).digest('hex')

// 一条 rel 是否被某条跳过项命中。两种形态、互不交错:
//   字面条目(无 `*`):rel === 该项 或 rel 以【该项 + 斜杠】开头 —— 原语义一字未动。
//   前缀型条目(含 `*`):rel 以 `*` 之前的字面文本开头(见上方 prefixHead)。
// 只换"哪些 rel 被跳过",不碰 treeStamp 的算法。
export const matchesSkip = (rel, s) => {
  const h = prefixHead(s)
  if (h === null) return rel === s || rel.startsWith(s + '/')
  return rel.startsWith(h)
}
export const isSkippedRel = (rel, skipRel = SKIP_REL) => skipRel.some((s) => matchesSkip(rel, s))

// 记 relpath|size|mtime(排序后取 sha);返回 { sha, files } —— files 留作"变动文件"取证。
// 算法(relpath|size|mtime 排序取 sha)与 stampDiff 的输出形状是判据语义,不许改。
export function treeStamp(rootDir, skipRel = SKIP_REL) {
  // 安全线②:调用方传进来的窄表同样受管 —— 传一份含产品路径的表 = 局部关掉产品件追踪,
  // 与改坏全局表是同一类静默放宽。taskctl 自证沙箱传的 ['state/tasks'] 合法,不受影响。
  // 前缀型条目同样在这条线上(auditSkipTable 走 productOverlap)。
  const unsafe = auditSkipTable(skipRel)
  if (unsafe.length) throw new Error(`treeStamp 的跳过表命中产品路径(会让 DRIFT 检测对产品件失效,静默放宽): ${unsafe.join(', ')}`)
  const rows = []
  const walk = (d) => {
    let entries = []
    try { entries = fs.readdirSync(d, { withFileTypes: true }) } catch { return }
    for (const e of entries) {
      const p = path.join(d, e.name)
      const rel = path.relative(rootDir, p).split(path.sep).join('/')
      if (isSkippedRel(rel, skipRel)) continue
      if (e.isDirectory()) { walk(p); continue }
      try { const st = fs.statSync(p); rows.push(`${rel}|${st.size}|${Math.round(st.mtimeMs)}`) } catch { /* 读不到就跳过 */ }
    }
  }
  walk(rootDir)
  rows.sort()
  return { sha: sha256(rows.join('\n')), files: rows }
}

export function stampDiff(before, after) {
  const b = new Map(before.files.map((r) => [r.split('|')[0], r]))
  const a = new Map(after.files.map((r) => [r.split('|')[0], r]))
  const changed = []
  for (const [k, v] of a) if (b.get(k) !== v) changed.push(k)
  for (const [k] of b) if (!a.has(k)) changed.push(k + '(已删除)')
  return changed
}

