#!/usr/bin/env node
/**
 * assert-doc.mjs —— 独立复核 2026国庆自驾-终版逐时路书.md 的关键数字
 * 不依赖 skill 里的任何工具：自己读文件、自己算、自己判定。
 *
 * 用法: node assert-doc.mjs <路书.md> [路线图.html]
 *
 * 踩过的坑（写死在注释里，别再犯）：
 *  · 表 1 的里程格是裸数字 `**329.9**`，单位只在表头 → 不能要求「数字后面跟 km」
 *  · Markdown 行以 | 开头，split('|') 的 [0] 是空串 → 列号要 +1，里程在 [3]
 *  · 不要用 `^#{1,6}\s*(M/D)（周X）` 这种复合正则，实测在当地文件上一条都不匹配
 */
import fs from 'node:fs';

const [, , mdPath, htmlPath] = process.argv;
if (!mdPath) { console.error('用法: node assert-doc.mjs <路书.md> [路线图.html]'); process.exit(2); }

const md = fs.readFileSync(mdPath, 'utf8');
const lines = md.split('\n');
const html = htmlPath && fs.existsSync(htmlPath) ? fs.readFileSync(htmlPath, 'utf8') : null;

let pass = 0, fail = 0;
const ok = (name, detail) => { pass++; console.log(`  [OK] ${name}${detail ? ` -- ${detail}` : ''}`); };
const bad = (name, detail) => { fail++; console.log(`  [XX] ${name}${detail ? ` -- ${detail}` : ''}`); };
const near = (a, b, tol) => Math.abs(a - b) <= tol;
const cellNum = (s) => {
  const t = String(s ?? '').replace(/[*_`,\s]/g, '').replace(/[^\d.]/g, '');
  return t === '' ? undefined : Number(t);
};

/** 期望值（人工核对过的真相） */
const wantDaily = { '9/30': 329.9, '10/1': 339.0, '10/2': 224.2, '10/3': 435.6, '10/4': 487.4, '10/5': 300.3, '10/6': 449.2 };

/* ================= 1. 逐日里程 =================
 * 源 A: 表 1「一、总行程表」里程列，按列号定位 —— 7 天齐全，为准
 * 源 B: 逐日标题行 `## M/D（周X）· ...  NNN.N km` —— 9/30 标题不带 km，只有 6/7，作交叉验证
 */
console.log('\n【1】逐日里程（源 A = 表 1 里程列 / 源 B = 逐日标题行 km）');

const daily = {};
const h1 = lines.findIndex((l) => /^\|\s*日期\s*\|\s*行程\s*\|\s*里程\s*\|/.test(l));
if (h1 < 0) bad('未找到表 1（日期 | 行程 | 里程）');
else {
  console.log(`     表 1 表头在第 ${h1 + 1} 行`);
  for (let i = h1 + 2; i < lines.length && lines[i].includes('|'); i++) {
    const cells = lines[i].split('|');
    const d = (cells[1] || '').match(/(\d{1,2}\/\d{1,2})/);
    const km = cellNum(cells[3]);
    if (d && km !== undefined && Number.isFinite(km)) daily[d[1]] = km;
  }
}
for (const [d, v] of Object.entries(wantDaily)) {
  if (daily[d] === undefined) bad(`${d} 表 1 未抽到`);
  else if (near(daily[d], v, 0.05)) ok(`${d} = ${daily[d]}`);
  else bad(`${d} = ${daily[d]}，应为 ${v}`);
}

let headingDays = 0;
let headingChecked = 0;   // 真正比过的条数，用于断言“不是一条都没比”
for (const line of lines) {
  if (!line.startsWith('## ')) continue;
  const d = (line.match(/(\d{1,2}\/\d{1,2})/) || [])[1];
  if (!d) continue;
  // 只认真正的逐日大标题：`## M/D（周X）` 开头。三、逐日逐时表下的同名小标题也以 ## 开头，
  // 不能一起计数（否则会数出 15 条，看起来像“多出 8 天”）。
  if (!/^##\s+\d{1,2}\/\d{1,2}（周[一二三四五六日天]）/.test(line)) continue;
  headingDays++;
  if (!line.includes(' km')) continue;          // 9/30 标题不带 km，正常跳过
  const v = Number((line.match(/([\d,]+(?:\.\d+)?)\s*km/) || [])[1].replace(/,/g, ''));
  // 先断言两边都抽到了东西，再比值。
  // 教训：写成 `if (daily[d] !== undefined && !near(...))` 时，只要 daily 是空的，
  // 整个条件恒假 → 一条校验都不跑，而输出看起来像“没报错 = 通过”。那是假阴性。
  if (daily[d] === undefined) { bad(`标题行 ${d} 有值 ${v}，但表 1 没有该日`); continue; }
  if (!near(v, daily[d], 0.05)) bad(`标题行 ${d} ${v} vs 表 1 ${daily[d]}`);
  else { headingChecked++; ok(`标题行 ${d} ${v} 与表 1 一致`); }
}
const dailySum = Object.values(daily).reduce((a, b) => a + b, 0);
// 硬断言：抽不到就该响，不能让「0 条」静默通过
// 实测：每天的大标题出现 2 次（二、逐段实测明细 + 三、逐日逐时表），共 14 条；
// 其中带 km 的是 7 条（连 9/30 的逐时表标题也带 km，只有它的路线标题不带）。
if (headingDays === 14) ok('逐日大标题 14 条 = 7 天 × 2 处（路线 + 逐时）');
else bad(`逐日大标题抽到 ${headingDays} 条（实测应为 14 = 7 天 × 2 处）—— 提取器可能部分失效`);
if (headingChecked === 7) ok('标题行 km 已与表 1 逐条比对 7 条，全部一致');
else bad(`标题行 km 只比对了 ${headingChecked} 条（实测应为 7 条）—— 校验未真正执行，属假阴性`);
console.log(`     表 1 逐日之和 = ${dailySum.toFixed(1)}；含日期的二级标题 ${headingDays} 条`);

/* ================= 2. 声明总里程 ================= */
console.log('\n【2】声明的总里程');
const totM = md.match(/总里程\s*([\d,]+)\s*km/);
const declaredTotal = totM ? Number(totM[1].replace(/,/g, '')) : null;
if (declaredTotal === null) bad('未找到「总里程 N km」');
else if (near(dailySum, declaredTotal, 1.5)) ok(`逐日之和 ${dailySum.toFixed(1)} vs 声明 ${declaredTotal}`, `差 ${(dailySum - declaredTotal).toFixed(1)} <= 1.5`);
else bad(`逐日之和 ${dailySum.toFixed(1)} vs 声明 ${declaredTotal}`, `差 ${(dailySum - declaredTotal).toFixed(1)} > 1.5`);

/* ================= 3. 充电次数 ================= */
console.log('\n【3】充电次数');
const charges = [];
if (h1 >= 0) {
  for (let i = h1 + 2; i < lines.length && lines[i].includes('|'); i++) {
    const m = lines[i].match(/\|\s*(\d+)\s*次\s*\|/);
    if (m) charges.push(Number(m[1]));
  }
}
const chargeSum = charges.reduce((a, b) => a + b, 0);
const dcM = md.match(/共\s*(\d+)\s*次充电/);
const dc = dcM ? Number(dcM[1]) : null;
if (charges.length !== 7) bad(`表 1 只抽到 ${charges.length} 天的充电次数（应为 7）`);
else if (dc !== null && chargeSum === dc) ok(`表 1 逐日充电 [${charges.join('+')}] = ${chargeSum} vs 声明 ${dc}`);
else bad(`逐日充电和 ${chargeSum} vs 声明 ${dc}`);

/* ================= 4. 天数 / 晚数 ================= */
console.log('\n【4】天数与晚数');
const nightsM = md.match(/([\d,]+)\s*km[／\/]\s*(\d+)\s*晚/);
const declaredNights = nightsM ? Number(nightsM[2]) : null;
const roomsM = md.match(/六、住宿（(\d+)\s*晚）/);
if (declaredNights !== null && roomsM && Number(roomsM[1]) === declaredNights) ok(`声明 ${declaredNights} 晚，与「住宿（${roomsM[1]} 晚）」一致`);
else bad(`晚数不一致: ${declaredNights} vs ${roomsM ? roomsM[1] : '未找到'}`);
// 标题行计数只作参考：三、逐日逐时表下的同名小标题也以 `## M/D（周X）` 开头，
// 所以 14 条（7 天×2 处）是正常的。真正的校验在上面：每个标题行的 km 都已与表 1 逐个对上。
console.log(`     （参考）以 \`## M/D（周X）\` 开头的标题共 ${headingDays} 条，= 每天 2 处 × 7 天`);

/* ================= 5. 预算表 ================= */
console.log('\n【5】预算表');
const budget = {};
const bStart = lines.findIndex((l) => /^\|\s*项目\s*\|\s*计算\s*\|\s*金额\s*\|/.test(l));
if (bStart < 0) bad('未找到预算表');
else {
  for (let i = bStart + 2; i < lines.length && lines[i].includes('|'); i++) {
    const cells = lines[i].split('|').map((c) => c.trim()).filter((c) => c !== '');
    if (cells.length < 3) break;
    const label = cells[0].replace(/[*_`]/g, '');
    const n = Number(cells[cells.length - 1].replace(/[*_`≈,\s]/g, '').replace(/[^\d.]/g, ''));
    if (Number.isFinite(n)) budget[label] = n;
  }
  const items = Object.entries(budget).filter(([k]) => k !== '合计');
  const isum = items.reduce((a, [, v]) => a + v, 0);
  const decl = budget['合计'];
  console.log(`     ${items.map(([k, v]) => `${k} ${v}`).join(' + ')} = ${isum}`);
  if (decl === undefined) bad('预算表无合计行');
  else if (near(isum, decl, 5)) ok(`分项和 ${isum} vs 合计 ${decl}`, `差 ${isum - decl} <= 5`);
  else bad(`分项和 ${isum} vs 合计 ${decl}`, `差 ${isum - decl} > 5`);
}

/* ================= 6. 两份文件交叉比对 ================= */
if (html) {
  console.log('\n【6】路书 vs 路线图 HTML');
  const chips = [...html.matchAll(/里程\s*<b>\s*([\d,]+(?:\.\d+)?)\s*km\s*<\/b>/g)].map((m) => Number(m[1].replace(/,/g, '')));
  const hTotalM = html.match(/([\d,]+)\s*km\s*·\s*纯电/);
  const hNightsM = html.match(/·\s*(\d+)\s*晚\s*·/);
  const hTotalN = hTotalM ? Number(hTotalM[1].replace(/,/g, '')) : null;
  const order = ['9/30', '10/1', '10/2', '10/3', '10/4', '10/5', '10/6'];
  if (chips.length !== 7) bad(`HTML 只抽到 ${chips.length} 个「里程 <b>N km</b>」（应为 7）`);
  else {
    const mism = [];
    order.forEach((d, i) => { if (!near(chips[i], wantDaily[d], 0.05)) mism.push(`${d}: html ${chips[i]} vs md ${wantDaily[d]}`); });
    if (mism.length === 0) ok(`HTML 7 个每日里程与路书逐日完全一致: [${chips.join(', ')}]`);
    else bad(`HTML 与路书逐日不一致: ${mism.join('; ')}`);
    const csum = chips.reduce((a, b) => a + b, 0);
    if (hTotalN !== null && near(csum, hTotalN, 1.5)) ok(`HTML 逐日之和 ${csum.toFixed(1)} vs 副标题总里程 ${hTotalN}`);
    else bad(`HTML 逐日之和 ${csum.toFixed(1)} vs 副标题总里程 ${hTotalN}`);
  }
  if (hTotalN !== null && declaredTotal !== null && hTotalN === declaredTotal) ok(`HTML 总里程 ${hTotalN} = 路书总里程 ${declaredTotal}`);
  else bad(`总里程不一致: HTML ${hTotalN} vs 路书 ${declaredTotal}`);
  if (hNightsM && declaredNights !== null && Number(hNightsM[1]) === declaredNights) ok(`HTML 晚数 ${hNightsM[1]} = 路书晚数 ${declaredNights}`);
  else bad(`晚数不一致: HTML ${hNightsM ? hNightsM[1] : '?'} vs 路书 ${declaredNights}`);
}

/* ================= 7. 禁用值 ================= */
console.log('\n【7】历史错误值不得复现');
const FORBIDDEN = ['2,479', '342.1', '270.0', '277.3', '339.4', '111.067,39.028', '110.318493', '银川福锦', '343.5', '2,750', '1.5 小时'];
const files = [['路书', md], ...(html ? [['路线图', html]] : [])];
for (const [label, txt] of files) {
  const hits = FORBIDDEN.filter((f) => txt.includes(f));
  if (hits.length === 0) ok(`${label} 无禁用值`);
  else bad(`${label} 出现禁用值: ${hits.join(', ')}`);
}
const coordRe = /\d{2,3}\.\d{4,6}\s*,\s*\d{2,3}\.\d{4,6}/g;
for (const [label, txt] of files) {
  const c = [...txt.matchAll(coordRe)];
  if (c.length === 0) ok(`${label} 无裸经纬度坐标`);
  else bad(`${label} 出现 ${c.length} 处坐标: ${c.slice(0, 3).map((m) => m[0]).join(' / ')}`);
}

/* ================= 8. 关键实测数字在正文可查 ================= */
console.log('\n【8】关键实测数字在正文可查');
const MUST = ['141.5', '329.9', '339.0', '487.4', '449.2', '300.3', '230.9', '8.4', '296.2'];
for (const v of MUST) {
  if (md.includes(v)) ok(`路书含 ${v}`);
  else bad(`路书缺 ${v}`);
}

console.log(`\n${'='.repeat(52)}\n结果: ${pass} 通过 / ${fail} 失败\n${'='.repeat(52)}`);
process.exit(fail === 0 ? 0 : 1);

