// 把 AuraPolaris 统一入口接到 dsh 宿主上(幂等、先备份、可回滚)。零依赖。
//   node tools/apply-hook-dsh.mjs                      # 应用(默认: 本机 <DSH_HOME>/profiles/* 全部)
//   node tools/apply-hook-dsh.mjs --dry-run            # 只打印将写入的内容
//   node tools/apply-hook-dsh.mjs --remove             # 撤销(只移除本工具写的块与文件)
//   node tools/apply-hook-dsh.mjs --profiles web       # 指定 profile(--profiles web 与 --profiles=web 等价,逗号分隔)
//   node tools/apply-hook-dsh.mjs --sync-skill         # 把 skills/aurapolaris 刷新进 dsh 技能根(内容相同即跳过,先备份)
// 机制(2026-09-22 实测,证据见 state/host-injection-matrix.md):dsh profile 的补丁层 cordis.patch.yml 支持
//   insert 条目;@deepseek-ai/dsh-hooks-codex 是可运行的 Codex hooks 兼容桥(只支持 5 个 Codex 事件)。
// 为什么需要 --sync-skill:桥跑的是【安装态副本】(<DSH_HOME>/skills/aurapolaris/tools/hook.mjs),
//   内核登记(kernel/delegation.json)改了不同步 = 现场还是老登记(实测形态:kind=unknown/via=unmapped,只记录不注入)。
// 形状(事件名/命令/协议键)只在 adapters/ 目录里(模板 tools/adapters/dsh-hooks.json),本文件只做替换与写入。
// 落地:①<DSH_HOME>/aurapolaris-hooks.json = 模板 + 本机统一入口绝对路径 ②每个 profile 的 cordis.patch.yml 插一条 mount
//   ③--sync-skill 时把 skills/aurapolaris 的内容刷新进 <DSH_HOME>/skills/aurapolaris(桥跑的就是这一份)。
import fs from 'node:fs'
import path from 'node:path'
import crypto from 'node:crypto'
import { fileURLToPath } from 'node:url'

const ROOT = path.resolve(process.env.POLARIS_ROOT ?? path.join(path.dirname(fileURLToPath(import.meta.url)), '..'))
const args = process.argv.slice(2)
const has = (f) => args.includes(f) || args.some((a) => a.startsWith(`${f}=`))
// 空格写法(--profiles web)与等号写法(--profiles=web)必须等价:2026-09-22 反证显示等号值被吞掉后
// 静默回落成"全量 profile"(--dry-run --profiles=auratest 打出 profile=auratest,headless,web)。
const val = (n, d = null) => {
  const i = args.indexOf(n)
  if (i >= 0) return args[i + 1] ?? d
  const p = args.find((a) => a.startsWith(`${n}=`))
  return p ? p.slice(n.length + 1) : d
}
const dryRun = has('--dry-run')
const remove = has('--remove')
const HOME = process.env.USERPROFILE ?? process.env.HOME ?? ''
const DSH_HOME = path.resolve(val('--dsh-home', process.env.DSH_HOME ?? path.join(HOME, '.dsh')))
// 默认档 = 本机磁盘上的全部 profile:宿主里一切实际可启的 profile 都从 <DSH_HOME>/profiles/<name>/ 起,
//   并集域就是这个目录。写死名单会让"以后新增/改名"或"另一台机器"静默漏挂 —— 那正是本单要修的缺口。
//   判据必须与 dsh 自己对齐:profile = 目录里有 package.json(loadProfile 只认这个);补丁层文件本身是可选的
//   (loadProfileDirectory: 不存在就当空层),所以"有 package.json、还没有 cordis.patch.yml"的 profile 同样要挂,
//   只是对它是【新建】该文件(实测形态:新建前 dsh --dump-config exit=0 且无桥行,本工具此前直接跳过它)。
//   --profiles <name> 只用于故意收窄到某一个(逐 profile 排查)。
const listProfiles = () => {
  const dir = path.join(DSH_HOME, 'profiles')
  let entries = []
  try { entries = fs.readdirSync(dir, { withFileTypes: true }) } catch { return [] }
  return entries.filter((e) => e.isDirectory() && e.name !== 'node_modules')   // dsh 自己拿 node_modules 当非法 profile 名
    .filter((e) => fs.existsSync(path.join(dir, e.name, 'package.json')))
    .map((e) => e.name).sort()
}
// 收窄档:显式给了 --profiles 就只用它(值解析不出来=用法错,不许静默回落);没给才按全量,且全量必须打印 ! 告知。
const profilesGiven = has('--profiles')
const profilesArg = val('--profiles', null)
if (profilesGiven && (profilesArg === null || String(profilesArg).trim() === '')) {
