const TEMPLATE = path.join(ROOT, 'tools/adapters/dsh-hooks.json')
const CONFIG = path.join(DSH_HOME, 'aurapolaris-hooks.json')
const BEGIN = 'AuraPolaris 注入桥'
const ID = 'polaris-injection-bridge'
const BRIDGE = '@deepseek-ai/dsh-hooks-codex'
