const hookCandidates = [
  path.join(DSH_HOME, 'skills', 'aurapolaris', 'tools', 'hook.mjs'),
  path.join(ROOT, 'skills', 'aurapolaris', 'tools', 'hook.mjs'),
]
const HOOK_MJS = hookCandidates.find((p) => fs.existsSync(p)) ?? hookCandidates[1]

if (!fs.existsSync(TEMPLATE)) { console.error(`适配器模板不存在: ${TEMPLATE}`); process.exit(1) }
