const mountBlock = `# ${BEGIN}(写入者 tools/apply-hook-dsh.mjs;撤回: node tools/apply-hook-dsh.mjs --remove)\n` +
  `- insert:\n    - id: ${ID}\n      name: '${BRIDGE}'\n      config:\n        configPath: ${CONFIG.replace(/\\/g, '/')}\n`
// 块的范围:注释行(整行,含 "# " 前缀)+ 紧随其后的那一个顶层条目(- insert: ...),
