function blockRange(text) {
  const idx = text.indexOf(BEGIN)
  if (idx < 0) return null
  const start = text.lastIndexOf('\n', idx) + 1
  const nextTop = (from) => { const m = text.slice(from).match(/\n(?=-)/); return m ? from + m.index + 1 : text.length }
