function discoverDsh (env = process.env) {
  const sources = [`PATH 上找 dsh 入口(本次 PATH 目录数 ${String(env.PATH ?? '').split(path.delimiter).filter(Boolean).length})`]
  const candidates = []
  const notes = []
  const shim = findOnPath(['dsh.cmd', 'dsh.ps1', 'dsh'], env)
  if (shim) {
    candidates.push({ path: shim, dir: path.dirname(shim), kind: 'shim', mtimeMs: mtimeMs(shim), exists: true, why: 'PATH 上的 dsh shim(本次选它:直接敲命令行时命中的就是这一条)' })
    // shim 旁边就是包:同目录 node_modules/<包>/lib/bin.js —— 只作【佐证】列出来,不参与选择。
    const pkgBin = path.join(path.dirname(shim), 'node_modules', '@deepseek-ai', 'dsh', 'lib', 'bin.js')
    if (isFile(pkgBin)) candidates.push({ path: pkgBin, dir: path.dirname(pkgBin), kind: 'script', mtimeMs: mtimeMs(pkgBin), exists: true, why: 'shim 指向的包内入口(佐证 shim 落在同一份安装上,不参与选择)' })
  } else {
    notes.push('PATH 上没有 dsh / dsh.cmd / dsh.ps1')
  }
  return { host: 'dsh', sources, candidates, notes }
}



























