  }
  const d = adapter(env)
  const hostDirs = d.candidates.filter((c) => c.kind === 'exe')      // 候选"实例"= 枚举到的目录
  const picked = pick(d.candidates)
  const shim = d.candidates.find((c) => c.kind === 'shim' && c.path) ?? null
  const skippedNewer = picked ? hostDirs.filter((c) => !c.exists && c.dirMtimeMs > picked.winner.mtimeMs) : hostDirs.filter((c) => !c.exists)
  let reason, selected
  if (picked) {
    selected = picked.winner.path
    if (hostDirs.length > 1) {
      reason = `按 mtime 最新者胜:共 ${hostDirs.length} 个候选目录,选中 ${path.basename(picked.winner.dir)} (mtime ${iso(picked.winner.mtimeMs)})`
        + (skippedNewer.length ? `;跳过 ${skippedNewer.length} 个更新的目录(里面没有宿主 exe:${skippedNewer.map((c) => path.basename(c.dir)).join('/')})` : '')
        + (picked.rank.length > 1 ? `;次新 = ${path.basename(picked.rank[1].dir)} (mtime ${iso(picked.rank[1].mtimeMs)})` : '')
    } else {
      reason = `只有一个候选实例,直接选中(mtime ${iso(picked.winner.mtimeMs)})`
    }
  } else if (shim) {
    selected = shim.path
    // 措辞跟口径走:本宿主本来就是按 PATH shim 解析的(mode='path-shim')就不该说"回落"—— 那是另一回事。
    reason = (d.mode === 'path-shim')
      ? '本宿主按 PATH shim 解析(不枚举 exe 多实例):选中的就是命令行会命中的那一条'
      : `枚举不到可靠的宿主 exe${hostDirs.length ? `(${hostDirs.length} 个候选目录里都没有)` : ''},回落到 PATH 上的 shim —— 它是本机真正会命中的入口`
  } else {
    selected = null
    reason = `没找到可用的实例:${hostDirs.length ? `枚举到 ${hostDirs.length} 个候选目录,但里面都没有宿主 exe` : '一个候选目录都没有'}${d.notes.length ? ` (${d.notes.join('; ')})` : ''}`
  }
  return { host, ok: !!selected, why: selected ? (picked ? 'picked' : 'shim-only') : 'not-found', found: !!selected, selected, reason, candidates: d.candidates, notes: d.notes, sources: d.sources, mode: d.mode ?? 'enumerate-instances' }
}
































































