  process.exit(12)
//   才按图的 report_fields 判。缺图 / 图读不出 / 图没声明这个落点 ⇒ 一律落回台账档(§7 全查,不降级)。
const workorderMode = (() => {
  const relFile = path.relative(ROOT, file).split(path.sep).join('/')
  if (!/^\.polaris\/workorders\/[^/]+\.result\.json$/.test(relFile)) return null
  const woFile = file.replace(/\.result\.json$/, '.json')
  if (!fs.existsSync(woFile)) return null
  let wo = null
  try { wo = JSON.parse(fs.readFileSync(woFile, 'utf8')) } catch { return null }
  if (wo?.kind !== 'workorder') return null
  const declaredTo = String(wo?.compose?.report_to ?? '').split(path.sep).join('/')
  if (declaredTo !== relFile) return null
  const raw = Array.isArray(wo?.compose?.report_fields) ? wo.compose.report_fields.filter((x) => typeof x === 'string' && x.trim()) : []
  if (!raw.length) return null
  return { wo, woRel: path.relative(ROOT, woFile).split(path.sep).join('/'), raw }
})()

// ---- 自认三键(agent_contract,arch-v2.C51):口径单源 + 两档基准 + 逐条点名 --------------
// 口径单源 = 【本工具所在仓库】/skills/aurapolaris/kernel/delegation.json#agent_contract。
//   为什么不从 POLARIS_ROOT 读:本文件会被 taskctl 的自证当夹具检查器调用(cwd/POLARIS_ROOT=夹具根,
//   夹具根里没有 kernel)—— 契约是检查器自带的尺,不该随被检查的根漂;实测依据见 tests/taskctl-verify.jsonl
//   (三条 receipt_check 期望 0 的用例,夹具根里没有 skills/)。
const REPO = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..')
const AGENT_CONTRACT = (() => {
  const rel = 'skills/aurapolaris/kernel/delegation.json'
  try {
    const k = JSON.parse(fs.readFileSync(path.join(REPO, rel), 'utf8'))
    const ac = k?.agent_contract
    const t0 = Date.parse(ac?.effective_from ?? '')
    if (!ac || !Number.isFinite(t0)) return { ok: false, rel, why: '缺 agent_contract 节或 effective_from 不是时间戳' }
    const keys = Array.isArray(ac?.self_identification?.required_keys) && ac.self_identification.required_keys.length
      ? ac.self_identification.required_keys.map(String)
      : ['role', 'task_id', 'pointer_sha256']
    return { ok: true, rel, t0, iso: String(ac.effective_from), keys }
  } catch (e) { return { ok: false, rel, why: `读不到(${e?.code ?? e?.message})` } }
})()
// 台账档的【新生效契约】以派单为界:基准=任务指针的 created_at(taskctl 铸造必写;实测真实指针都有)。
//   读不出指针 / 缺 created_at ⇒ 返回 null ⇒ 按存量(不加码)。方向是可见的:输出里会点名这一条。
function pointerMintedAt(id) {
  try {
    const t = JSON.parse(fs.readFileSync(path.join(ROOT, 'state', 'tasks', `${id}.json`), 'utf8'))
    const ms = Date.parse(t?.created_at ?? '')
    return Number.isFinite(ms) ? ms : null
  } catch { return null }
}
// 自认三键检查(两档共用一份实现):返回 { problems[], legacy[], ok }
//   problems = 计入退出码的缺项/取值不合规(只可能来自新生效契约之后的回执);legacy = 存量,只点名计数。
function selfIdCheck(j, { newEra, basis }) {
  const problems = [], legacy = []
  if (!AGENT_CONTRACT.ok) return { problems, legacy, ok: false }
  for (const k of AGENT_CONTRACT.keys) {
function pointerMintedAt(id) {
  try {
    const t = JSON.parse(fs.readFileSync(path.join(ROOT, 'state', 'tasks', `${id}.json`), 'utf8'))
    const ms = Date.parse(t?.created_at ?? '')
    return Number.isFinite(ms) ? ms : null
  } catch { return null }
}
// 自认三键检查(两档共用一份实现):返回 { problems[], legacy[], ok }
//   problems = 计入退出码的缺项/取值不合规(只可能来自新生效契约之后的回执);legacy = 存量,只点名计数。
function selfIdCheck(j, { newEra, basis }) {
  const problems = [], legacy = []
  if (!AGENT_CONTRACT.ok) return { problems, legacy, ok: false }
  for (const k of AGENT_CONTRACT.keys) {
    if (k in j && j[k] !== null && j[k] !== '') continue
    const what = `缺顶层键 ${k}${k === 'role' ? '(=字面量 subagent)' : ''}:agent_contract 要求回执自认(${AGENT_CONTRACT.rel}#agent_contract.self_identification)`
    if (newEra) problems.push(`${what};基准 ${basis} ≥ effective_from=${AGENT_CONTRACT.iso} ⇒ 新生效契约之后的回执缺项即判红`)
    else legacy.push(`${what};基准 ${basis} < effective_from=${AGENT_CONTRACT.iso} ⇒ 按 AGENTS.md §0.4 不追溯判红,只点名计数`)
  }
  // 取值判定【只对新生效契约之后的回执】:存量一个字不判(缺项已单独点名)。
  if (newEra) {
    // 取值逐条对账走【下面那个纯函数】(唯一实现):此处只负责"哪些键该在"与"基准够不够新"。
    problems.push(...selfIdValueProblems(j, {
      contract: { keys: AGENT_CONTRACT.keys, rel: AGENT_CONTRACT.rel },
      readPointer: (pid) => JSON.parse(fs.readFileSync(path.join(ROOT, 'state', 'tasks', `${pid}.json`), 'utf8')),
    }).problems)
  }
  return { problems, legacy, ok: true }
}
// 【值对账·唯一实现(arch-v2.C61)】纯函数:自认三键的【取值】判定,不碰全局、不读现场件 ——
function printSelfIdNote(selfId, newEra) {
  if (!AGENT_CONTRACT.ok) { console.log(`  自认键: 未判 —— 契约单源读不出(${AGENT_CONTRACT.rel}: ${AGENT_CONTRACT.why});未加码也未静默放过`); return }
  if (selfId.legacy.length) {
    console.log(`  存量提示(不计入退出码,${selfId.legacy.length} 项): agent_contract 自认三键 —— 逐条点名如下`)
    for (const l of selfId.legacy) console.log('    - ' + l)
  }
  if (newEra && !selfId.problems.length) {
    console.log('  自认键(agent_contract): 齐备 —— role=subagent;task_id 与 pointer_sha256 均已与任务指针对账(64 位小写十六进制)')
  const raw = workorderMode.raw
  // 声明字符串的解析【只此一处】:"status=done|partial|blocked" → 键 status / 取值域 [done,partial,blocked];
  //   "evidence[]=命令/退出码/输出尾部" → 键 evidence(数组);"deviations[]" → 键 deviations。
  const decl = raw.map((s) => {
    const [name, ...rest] = String(s).split('=')
    const val = rest.join('=').trim()
    const item = /\[\]$/.test(name.trim())
    const key = name.trim().replace(/\[\]$/, '')
    return { key, item, values: val ? val.split('|').map((v) => v.trim()).filter(Boolean) : [] }
  })
  const require = decl.map((d) => d.key)
  for (const k of require) if (!(k in j)) woProblems.push(`缺顶层键 ${k}(施工单 ${workorderMode.woRel} 的 compose.report_fields 声明了它)`)
  const statusDecl = decl.find((d) => d.key === 'status')
  if ('status' in j) {
    const st = String(j.status)
    const legal = statusDecl?.values.length ? statusDecl.values : ['done', 'partial', 'blocked']
    if (!legal.includes(st)) woProblems.push(`status 非法: ${st}(施工单声明的取值域 ${legal.join('|')})`)
    if (/^done_\w+/.test(st) && !(Array.isArray(j.deviations) && j.deviations.length)) {
      woProblems.push(`status=${st} 但没有 deviations —— done_<后缀> 必须配一处已声明的偏离`)
    }
  }
  if (decl.some((d) => d.key === 'evidence') && 'evidence' in j) {
    if (!Array.isArray(j.evidence) || !j.evidence.length) woProblems.push('evidence 必须是非空数组(施工单声明了 evidence[])')
    else {
      // 【phase 不在施工单 schema 里 ⇒ 本档对它一字不判】(这不是放松:台账档的 phase 逐条判据在下面那段里一字未动)。
      //   实测依据:C31 的 phase 写的是 "known-red(并行 C32)" / "green(CONS-7)/known-red(CONS-16)" ——
      //   那是施工者自己的两相叙述,而施工单从没有过 phase 词表。拿台账档的词表去判它,等于给一份从未声明过该列的
      //   契约另加一条判据(加码,不是单源);"本档只判声明过的键"才是这份单要的单源形态。
      j.evidence.forEach((e, i) => {
        for (const k of ['cmd', 'exit', 'tail']) if (!(k in (e ?? {}))) woProblems.push(`evidence[${i}] 缺 ${k}`)
      })
    }
  }
  for (const k of ['artifacts', 'touched', 'deviations']) if (k in j && !Array.isArray(j[k])) woProblems.push(`${k} 必须是数组`)
  if (Array.isArray(j.artifacts)) {
    j.artifacts.forEach((a, i) => {
      if (a && typeof a === 'object' && !Array.isArray(a) && !('path' in a)) { woProblems.push(`artifacts[${i}] 缺 path`); return }
      if (a && typeof a === 'object' && !Array.isArray(a) && 'path' in a && !('sha256_16' in a)) woProblems.push(`artifacts[${i}] 缺 sha256_16`)
    })
  }
  // 自认三键(施工单档):基准=回执自身 mtime。为什么不是施工单文件的时间:施工单 schema 里
  //   没有时间字段(实测 49 张施工单与 .polaris/workorders/*.json 均无 created_at),
  //   盘上唯一关于"这份回执何时落的"的事实就是它自己的 mtime(与 pipeline-watch 的记龄基准同源)。
  const woMtime = (() => { try { return fs.statSync(file).mtimeMs } catch { return null } })()
  const woNewEra = AGENT_CONTRACT.ok && woMtime !== null && woMtime >= AGENT_CONTRACT.t0
  const woBasis = woMtime === null ? '回执 mtime 读不出' : `回执 mtime=${new Date(woMtime).toISOString()}`
  const woSelfId = selfIdCheck(j, { newEra: woNewEra, basis: woBasis })
  woProblems.push(...woSelfId.problems)
  const relWo = path.relative(ROOT, file).split(path.sep).join('/')
  if (woProblems.length) {
    console.log(`RECEIPT FAIL: ${relWo}`)
    console.log(`  档=施工单(schema 来源 ${workorderMode.woRel}#compose.report_fields = ${require.join('/')})`)
    for (const p of woProblems) console.log('  - ' + p)
    printSelfIdNote(woSelfId, woNewEra)   // 判红也把存量提示打全:两种性质的问题不许互相淹没
    process.exit(12)
  }
  console.log(`RECEIPT PASS: ${relWo}`)
  console.log(`  档=施工单(schema 来源 ${workorderMode.woRel}#compose.report_fields;台账档的 rollback/analyzer_boundary_check 不适用于本档)`)
  console.log(`  status=${j.status} evidence=${j.evidence.length}（phase 未参与判定:施工单 schema 无此列） artifacts=${(j.artifacts ?? []).length} touched=${(j.touched ?? []).length} deviations=${(j.deviations ?? []).length}`)
  printSelfIdNote(woSelfId, woNewEra)
  process.exit(0)
}

const keys = Object.keys(j)
const isVerifyArtifact = keys.includes('verified_at') && keys.includes('ok') && !keys.includes('status')
if (isVerifyArtifact && !allowVerifyArtifact) {
  console.log(`RECEIPT FAIL: ${path.relative(ROOT, file)} 是 taskctl verify 的产物(顶层键 ${keys.join(',')}),不是 §7 回执`)
  console.log('  说明:回执已被 verify 覆盖,或该单从未写回执。要查看该产物请加 --allow-verify-artifact。')
  process.exit(12)
}

const problems = []
const REQUIRE = ['status', 'evidence', 'artifacts', 'touched', 'deviations', 'rollback']
for (const k of REQUIRE) if (!(k in j)) problems.push(`缺顶层键 ${k}`)
// 【自认三键·台账档】基准=任务指针的 created_at(契约随派单生效;理由见文件头判据 8 与
//   agent_contract.boundary)。非规范名回执(只有存量才有;新铸造一律规范名,由 receiptNameGuard 拦)
//   算不出指针 ⇒ 基准 null ⇒ 按存量不加码 —— 方向可见(输出里点名"基准=指针 created_at 读不出")。
const selfId = (() => {
  const id = path.basename(file).replace(/\.result\.json$/, '')
  const minted = pointerMintedAt(id)
  const newEra = AGENT_CONTRACT.ok && minted !== null && minted >= AGENT_CONTRACT.t0
  const basis = minted === null ? '指针 created_at 读不出(非规范名回执/合成夹具/手工指针)' : `指针 created_at=${new Date(minted).toISOString()}`
  return { ...selfIdCheck(j, { newEra, basis }), newEra }
})()
problems.push(...selfId.problems)
// status 口径（2026-09-27 扩充，有实测依据）：
//   done / partial / blocked —— 契约原文三态；
//   done_<后缀> —— 施工者已交付、但主动声明了一处偏离（例：done_with_declared_deviation）。
// 为什么要收它：实测（T-20260927-docfacts）施工者把“按 brief 做完了但有一处偏离”写成 done_with_declared_deviation，
// 内容合规却被旧口径判非法 —— 那是**判据太窄**，会逼人把真话改成 done 反而丢失信息。
// 边界：partial / blocked 仍然不算完成；done_* 必须配 deviations 非空（否则就是拿后缀当免费通行证）。
if ('status' in j) {
  const st = String(j.status)
  const legal = ['done', 'partial', 'blocked'].includes(st) || /^done_\w+/.test(st)
  if (!legal) problems.push(`status 非法: ${st}(只认 done|done_<后缀>|partial|blocked)`)
  if (/^done_\w+/.test(st) && !(Array.isArray(j.deviations) && j.deviations.length)) {
    problems.push(`status=${st} 但没有 deviations —— done_<后缀> 必须配一处已声明的偏离`)
  }
}
if ('evidence' in j) {
  if (!Array.isArray(j.evidence) || !j.evidence.length) problems.push('evidence 必须是非空数组')
  else {
    const phases = new Set()
    j.evidence.forEach((e, i) => {
      for (const k of ['cmd', 'exit', 'phase', 'tail']) if (!(k in (e ?? {}))) problems.push(`evidence[${i}] 缺 ${k}`)
      if (e?.phase && !['red', 'green'].includes(e.phase)) problems.push(`evidence[${i}].phase 非法: ${e.phase}(只认 red|green)`)
      if (e?.phase) phases.add(e.phase)
    })
    if (j.status !== 'blocked') {
      if (!phases.has('green')) problems.push('evidence 里没有 phase=green')
      if (!phases.has('red')) problems.push('evidence 里没有 phase=red(只有 green = 假绿)')
    }
  }
}
for (const k of ['artifacts', 'touched']) if (k in j && !Array.isArray(j[k])) problems.push(`${k} 必须是数组`)
// 7) analyzer_boundary_check:条件必需 —— 判据条件只落在 touched 上(见上列判据 7),与 PROTOCOL.md §8 同源。
//   为什么条件看 touched 而不是 artifacts:artifacts 是产出物(state/** 报告类),touched 才是"本单改过的路径";
//   且两者都是回执自报的,能用同一份谓词机检。status=blocked 也不豁免:真改过产品件就得写出边界在哪。
const PRODUCT_TOUCHED = (Array.isArray(j.touched) ? j.touched : []).map(String).filter(isProductPath)
process.exit(0)
  if (PRODUCT_TOUCHED.length) {
    const head = PRODUCT_TOUCHED.slice(0, 3).join(', ')
    problems.push(`缺顶层键 analyzer_boundary_check: touched 含产品件 ${head}${PRODUCT_TOUCHED.length > 3 ? ` 等 ${PRODUCT_TOUCHED.length} 处` : ''} => 本单涉代码 diff,PROTOCOL.md §8 要求它条件必需(值=diff-audit 原始输出或其边界自报)`)
  }
} else if (typeof j.analyzer_boundary_check !== 'string' || !j.analyzer_boundary_check.trim()) {
  problems.push('analyzer_boundary_check 必须是非空字符串(空值/非字符串等于没写) —— 它自报的是 diff-audit 的粒度与豁免边界')
}
const rel = path.relative(ROOT, file).split(path.sep).join('/')
if (problems.length) {
  console.log(`RECEIPT FAIL: ${rel}`)
