//   PRODUCT_PREFIXES 也只 import 不重写(arch-v2.C116 闸②的制品集合来源之一:抄字面量 = 第二份真相)。
import { sha256 as sha, treeStamp, stampDiff, scopeStamp, SKIP_REL as DISPATCH_SKIP, DISPATCH_ARTIFACTS, matchesSkip, PRODUCT_PREFIXES } from './fingerprint.mjs'
// 【本模块可被 import】导出 isTaskFile / DERIVED_SUFFIXES / isDerivedArtifact / cli。
//   为什么:tools/pipeline-watch.mjs 消费【同一份】"什么算任务文件"谓词(F2 单源,2026-09-27)。在那之前两处各写一份
//   正则,pipeline-watch 那份漏了 .verify.json/.receipt.json —— 实测把 6 个派生件当成待领任务打出幻影指针
//   (QUEUE: T-20260927132158-89c6.receipt 待领),两口径任务数 176 vs 170 对不上。
//   import 不等于运行:非入口时本模块只定义、不跑 CLI(见文件尾 isEntry);以别的文件名当入口的调用方
//   (自证沙箱 shim)显式调 cli() —— 见 cmdSelftest 里写 shim 的那行。
// 【2026-09-29 arch-v2.C28 单源落点迁移】谓词族【唯一实现】已搬到 skills/aurapolaris/tools/task-files.mjs
//   (随技能包分发:技能包根 = polaris/,里面没有 tools/;谓词留在仓库侧时,单独装包的环境里任务层与
//    执行者层为空、包内 --selftest 还会 TypeError)。本模块改为 import 它,并把【同一个函数对象】再导出 ——
//   pipeline-watch / fractal-check 等既有消费者一行都不用改。
import {
  DERIVED_SUFFIXES as DERIVED_SUFFIXES_SRC,
  isDerivedArtifact as isDerivedArtifact_SRC,
  isTaskFile as isTaskFile_SRC, isWorkorderFile as isWorkorderFile_SRC,
  isVoidedIn as isVoidedIn_SRC,
  isVoided as isVoided_SRC,
  receiptDoneIn as receiptDoneIn_SRC,
  receiptDone as receiptDone_SRC,
  isReceiptShaped as isReceiptShaped_SRC,
  readJsonState as readJsonState_SRC,
  isPlainObject as isPlainObject_SRC,
  readJsonOrNull as readJsonOrNull_SRC,
  READ_OK as READ_OK_SRC,
  READ_MISSING as READ_MISSING_SRC,
  READ_BAD as READ_BAD_SRC,
} from '../skills/aurapolaris/tools/task-files.mjs'
// 【owner 消费】(arch-v2.C124):闸⑤ 判「写面 ∩ 单源门禁扫描面」要的那份遍历/在册集来自 owner 自己 ——
//   本模块不再写第二份遍历语义(C123 那份 scanFaceOf 已删)。import 它【不会】跑它的 CLI:
//   tools/single-source.mjs 在同一个 C124 里补了 CLI 守卫(realpath 比较),被 import 时只定义、不 process.exit;
//   改前/改后的 import 读数留在 state/reviews/ 的 C124 留档与本单回执里。
