//   receiptDoneIn / isVoidedIn 四个 typeof 断言都照旧)。
export {
  DERIVED_SUFFIXES_SRC as DERIVED_SUFFIXES,
  isDerivedArtifact_SRC as isDerivedArtifact,
  isTaskFile_SRC as isTaskFile,
  isVoidedIn_SRC as isVoidedIn,
  receiptDoneIn_SRC as receiptDoneIn,
  READ_OK_SRC as READ_OK,
  READ_MISSING_SRC as READ_MISSING,
  READ_BAD_SRC as READ_BAD,
}
// 本模块内的旧名字继续可用(下面的既有代码一行都不改):是同一批函数对象的别名,不是包装。
const isTaskFile = isTaskFile_SRC, isWorkorderFile = isWorkorderFile_SRC   // 后一个是施工单档枚举谓词(arch-v2.C119);同一函数对象,不是包装
