const isReceiptShaped = isReceiptShaped_SRC

const ROOT = path.resolve(process.env.POLARIS_ROOT ?? '.')
const TASKS = path.join(ROOT, 'state/tasks')
const relPath = (p) => path.relative(ROOT, p).split(path.sep).join('/')

// ---- selftest 夹具根:唯一落点 = 沙箱,不是真账本(arch-v2.C45,类级修复)----
// 病因(实测,同类缺陷今天第三次):selftest 的十一个夹具根原先逐处写成 path.join(ROOT, 'state/tasks', `.selftest-…`)
//   —— 夹具根【长在被校验的账本里】。实测:跑一趟真树,state/tasks 下瞬时冒出 9 个 .selftest-* 点目录;
//   被中断(Windows 上 process.kill(pid,'SIGINT') 是 TerminateProcess,JS 处理器不跑)时那批目录留在账本里
//   不退 —— 2026-09-28 留下的 8 目录/178 文件/48244 字节一直躺到 2026-09-29 由父线程手工清掉
//   (同族另两次:tests/range.ps1 写真树三件、gate 夹具实跑重写 state/state.json)。
// 类级口径:【自证夹具一律落沙箱根,真账本零写入】。
// 终态:夹具根 = SELFTEST_TMP_ROOT(= POLARIS_TMP_ROOT ?? 'E:/AuraPolaris-tmp' 下本工具专属子目录)里,
//   名字仍带 <pid>-<hex> 唯一后缀 —— 并发跑多份时各自只清自己那一份。
// 四条离开路径:正常结束 / 抛异常 / process.exit(N) → process.on('exit')(同步 rmSync);
//   POSIX 的 SIGINT/SIGTERM 另挂处理器;Windows 的 TerminateProcess【收不到】(JS 处理器不跑),
