//   所有者在跑的那一份【绝不碰】—— 宁可漏清一次,也不拿老化阈值去猜活人)。
const SELFTEST_PREFIX = '.selftest-'
const SELFTEST_TMP_BASE = process.env.POLARIS_TMP_ROOT || 'E:/AuraPolaris-tmp'
const SELFTEST_TMP_ROOT = path.join(SELFTEST_TMP_BASE, 'taskctl-selftest')
const SELFTEST_STALE_MS = 30 * 60 * 1000   // mtime 老化阈值:只用来把“所有者在跑但根已存在很久”当【疑泄漏】点名,不作删除依据
const selftestTag = () => `${process.pid}-${Math.random().toString(16).slice(2, 8)}`
const selftestRootsMade = new Set()        // 本进程建的夹具根(退出路径清理【只清这些】,别人的目录一概不碰)
let selftestRealDotBefore = null           // 真 state/tasks 下的 .selftest-* 清单(跑前基线)
const selftestRealDotsSeen = new Set()     // 跑动过程中在真树里【新出现】的 .selftest-*
const selftestRealDots = () => { try { return fs.readdirSync(TASKS).filter((n) => n.startsWith(SELFTEST_PREFIX)).sort() } catch { return [] } }
// 防复发判据的取数面:夹具根每次落地/清理时都瞄一眼真账本 —— 只看“跑完再瞄一眼”会漏掉“建了又删”那个形态,
//   而那正是回退成真树落点时的形态(阶段末的 rmSync 会把证据一起收走)。
const selftestRealDotProbe = () => {
  const now = selftestRealDots()
  if (selftestRealDotBefore) for (const n of now) if (!selftestRealDotBefore.includes(n)) selftestRealDotsSeen.add(n)
  return now
}
// 夹具根【唯一】构造入口:先清同名目录(每次都是干净的一间)、落沙箱、记账。
const selftestRoot = (name, tag) => {
  const root = path.join(SELFTEST_TMP_ROOT, `${SELFTEST_PREFIX}${name}-${tag}`)
  fs.rmSync(root, { recursive: true, force: true })
  fs.mkdirSync(root, { recursive: true })
  // 【C124】夹具根自持一份【可判】的单源登记表:闸⑤ 从 C124 起 fail-closed(判不了 ⇒ 拒派 exit 12),
  //   没有登记表的夹具会让所有跑 from-workorder/dispatch-guard 的夹具全部 exit 12(那不是它们的被测点)。
  //   这里的扫描面是【空面】(extensions 为空 = 没有任何文件在册)⇒ “写面不相交”是判得出来的结论,
  //   不是判不了;需要真扫描面的夹具(C123/C124 那两组)自己覆盖这一份(同目录同名,后写者覆盖)。
  //   放在【唯一构造入口】而不是每个 makeRoot 里:夹具数据只有一份,新夹具自动被覆盖(不写第二份)。
  fs.mkdirSync(path.join(root, 'tools'), { recursive: true })
  fs.writeFileSync(path.join(root, 'tools/single-source.json'), JSON.stringify({
    note: 'selftest 夹具登记表(C124 起闸⑤ 要一份可判的登记表):空扫描面', scan: { skipDirs: [], skipFilePatterns: [], extensions: [] }, allowedUnresolved: [], facts: [],
  }))
  selftestRootsMade.add(root)
  return root
}
// 夹具根【唯一】处置入口:动手前先取真账本读数(防复发判据),再删自己这一份。
const selftestDrop = (root) => {
  selftestRealDotProbe()
  try { fs.rmSync(root, { recursive: true, force: true }) } catch { /* 删不掉就留给下次启动清扫 */ }
  selftestRootsMade.delete(root)
}
// 退出路径清理:只清本进程建的那几份,再【只删空的】容器目录;POLARIS_TMP_ROOT 顶层任何情况下不删。
function selftestCleanup() {
  for (const r of [...selftestRootsMade]) { try { fs.rmSync(r, { recursive: true, force: true }) } catch { /* 已删或在用 */ } }
  selftestRootsMade.clear()
  try { fs.rmdirSync(SELFTEST_TMP_ROOT) } catch { /* 非空(并发那一份还在)/不存在:不碰 */ }
}
let selftestCleanupArmed = false
function selftestArmCleanup() {
  if (selftestCleanupArmed) return
  selftestCleanupArmed = true
