#   · 只想预演、一个字节都不写            : -DryRun   （零写入;实测 written=0,推荐先跑一遍）
#   · 想装到别处（沙箱／自定技能根）        : -SkillsRoot <目录>   （可给多个;给了就只写这些目录,不碰宿主根）
#   · 要写宿主根（家目录下的各个宿主根,名单见 hosts.tsv）: 必须 -Yes 或交互式回答 y —— 非交互管道下无人可确认,
#     为不阻塞自动化按既有语义继续（仍逐个备份）;所以「没传 -Yes」不等于「不会被写」。
#   · -Uninstall / -Rollback 同样只看上面这套目标根:POLARIS_ROOT 一样隔离不了它们,别拿它当沙箱。
#
[CmdletBinding()]
param(
  [Alias('root')]
  [string[]] $SkillsRoot = @(),
$ErrorActionPreference = 'Stop'

$SkillName = 'aurapolaris'
$HomeDir   = if ($env:USERPROFILE) { $env:USERPROFILE } else { $HOME }
$Utc       = (Get-Date).ToUniversalTime().ToString('yyyyMMddTHHmmssZ')

# $PSScriptRoot 不能作为 param 默认值（-File 调用时会为空），必须在脚本体内解析
if (-not $Source -or $Source.Trim() -eq '') {
  $psr = Get-Variable -Name PSScriptRoot -ErrorAction SilentlyContinue -ValueOnly
  if ($psr) { $Source = $psr }
  elseif ($MyInvocation.MyCommand.Path) { $Source = Split-Path -Parent $MyInvocation.MyCommand.Path }
  else { throw '无法确定脚本所在目录;请用 -Source <目录> 显式指定' }
}
$Source = (Resolve-Path -LiteralPath $Source).Path
$SrcSkill  = Join-Path $Source "skills/$SkillName"
$ManifestName = '.install-manifest.json'
# 标准输入句柄:进程启动时取一次(交互式终端下非 0;管道/重定向/< NUL 时可能为 0)。
# 纯自证入口(-SelfTest)排在 -Source 解析之前,所以这个函数必须先于下面那段解析定义。
function Get-ConsoleInputHandle {
  try { $h = [Console]::OpenStandardInput(); if ($h -and $h.CanRead) { return $h } } catch { }
  return $null
}

# 确认口径的纯函数面(四态:skip/no-confirm/proceed/cancel)。返回:
#   skip=-Yes 跳过确认(备份与隔离照旧) no-confirm=-DryRun 不写盘故不确认(也不打印确认行)
#   proceed=交互且答 y 或非交互无人可确认(不阻塞)   cancel=交互且答非 y/Y/yes → 调用方零写入
# 为什么必须是纯函数:交互与取消两条分支在自动化里走不到,抽成"输入 → 判定"后,一条无写盘命令(-SelfTest)
# 就能把四态各走一遍 —— 否则"取消"分支永远测不到 = 未实证。
function Get-ConfirmDecision {
  param([bool] $Yes, [bool] $DryRun, [bool] $Interactive, [string] $Answer = '')
  if ($Yes) { return 'skip' }                              # ① -Yes:跳过确认(备份与隔离照旧)
  if ($DryRun) { return 'no-confirm' }                     # ② -DryRun:不写盘,无人可确认
  if (-not $Interactive) { return 'proceed' }               # ④ 非交互:无人可确认,按既有语义继续(不阻塞)
  if (Test-ConfirmAnswer $Answer) { return 'proceed' }      # ③ 交互且答 y/Y/yes → 继续
  return 'cancel'                                           # ③ 交互且答非 y/Y/yes → 取消(调用方零写入)
}
# 回答口径与 install.sh:87 的 case "$ans" in y|Y|yes|YES|Yes) 逐条对齐
function Test-ConfirmAnswer([string] $Answer) {
  if ($null -eq $Answer) { return $false }
  $a = $Answer.Trim()
  return ($a -ceq 'y' -or $a -ceq 'Y' -or $a -ceq 'yes' -or $a -ceq 'YES' -or $a -ceq 'Yes')
}
# 交互性判定:以"标准输入是不是终端"为准,不用 [Environment]::UserInteractive ——
# 有桌面会话时它恒为 true,会把管道里跑误判成交互(然后 Read-Host 永久阻塞)。
function Test-InteractiveConsole {
  return ($ConsoleIn -and -not [Console]::IsInputRedirected)
}
$ConsoleIn = Get-ConsoleInputHandle

# 四态提示语的期望文本(自证与实现各写一份,不共用变量 —— 否则改错了实现会连带改绿期望)
$stDecisionLines = [ordered]@{
  skip    = '确认         : 已由 -Yes 跳过（备份与隔离照旧）'
  proceed = '确认         : 交互确认通过'
  cancel  = '已取消:未做任何写入（-Yes 可跳过确认）。'
}
$ConsoleIn = Get-ConsoleInputHandle

# ---- 隔离口径提示语:本文件里唯一的字面量来源(两个打印点都打这个变量) ----
# 为什么用变量:两处（将写入的宿主根前、自证断言）必须是同一句、逐字一致;
#   抄成两份的话改一处就会漂,而漂了的提示比没有提示更坏。
# 本行是字面量,全文只此一处;下面那个 $stIsolateMarker 是它的片段投影,
#   供自证在【裁剪点之后】的区域里搜打印点（同一句话的意义域与源码行号无关）。
$stIsolateLine   = '隔离口径 : 本安装器不看 POLARIS_ROOT;预演用 -DryRun(零写入),装到别处用 -SkillsRoot <目录>,写家目录下各个宿主根要 -Yes 或交互确认(名单见 hosts.tsv,实际目标见下面那段逐行列表)。'
# 上面那句刻意不写任何具体宿主根路径(./.dsh/skills 之类):名单的唯一来源是 hosts.tsv,
#   三个消费者都不许内嵌根字面量 —— 判据 tools/kernel-consistency.mjs 的 CONS-17 与
#   tools/host-matrix.mjs --check 逐条数这个(实测:前一版写了 -/.dsh/skills 路径,当场被判红)。
# 自证用的两个针 —— 都是【代码行原文】,不是提示语本身:
# 自证用的两个针 —— 都是【代码行原文】,不是提示语本身:
#   $stIsolateMarker = 那句打印调用的原文(代码):它在全文只出现一次，且不会被字面量定义
#   或任何注释冒充 —— 拿提示语本身当针的话,字面量定义（在裁剪点之前）与注释都会先命中,
#   真正的打印点摘掉后断言照样绿（实测踩过:注释里逐字拄了标题,先后断言就拿注释去比了）。
#   曾经还试过一个“硬话开头那段”的针:它与字面量同形,反而把断言带回搜字面量那条老路,已删。
$stIsolateMarker = 'Write-' + 'Output $st' + 'IsolateLine' + [char]13 + [char]10 + '#'   # 只认【独立成行的那个打印点】
# 尾部的 CRLF+# 是必要的:-Uninstall 分支里那句写在同一行的 if(...) { … } 里,
#   只截 'Write-Output $stIsolateLine' 的话它也会命中,把那个打印点摘掉后断言照样绿（实测踩过,一次）。
# 先后断言的宿主根那针:必须只命中【输出行】—— 光截标题“将写入的宿主根”会被本区的注释先命中
#   （实测:拄一句就会让先后断言拿注释去比,得到 prn 在 host 之后的假红/假绿）。
$stPromptTwin    = '将写' + '入的宿主根' + '(改前逐个'   # 输出行原文(标题 + 句子里那段),注释里不出现
# 自证裁剪锚点(逐字就等于源码里那串 nonce;分四段拼出,免得本行自己成为 IndexOf 的首个命中)。
# 定义在顶层:父子两个进程都要它 —— 父进程(自证)拿去切段,探针子进程拿去裁段,共用一个坐标。
$stSrcMark = 'AP' + 'CUT7F' + '3E91' + 'D2'

#   但不绑定 $Yes/$DryRun/$Interactive —— 它们要保持本探针从命令行收到的那组值。
Invoke-Expression ($stDefaults + $body.Substring($close + 1))
$d = Get-ConfirmDecision -Yes $stYes -DryRun $stDry -Interactive $stInter -Answer $Answer
# 只求值"函数定义 + 纯判定调用点"(裁剪点之前的全部);裁剪点之后是要目标/提问/写盘/汇总,一律不进本进程
# 必须把源文件顶部的 param(...) 块剥掉:否则求值时它会重新绑定 $Yes/$DryRun/$Interactive 这些同名变量,
#   把它们冲成默认值,再传给 Get-ConfirmDecision 就成了 string→bool 绑定失败(实测踩过)。
$stDefaults = '$SkillsRoot = @(); $Source = ''''; $ListHosts = $false; $Uninstall = $false; $Rollback = $false; $SelfTest = $false'
$body = $src.Substring(0, $Cut)
# 用 AST 精确定位 param 块的结束位置(手写括号配平会被 param 里的 () 骗到,实测踩过):
#   先解析成 AST,取顶层 ParamBlock 的 Extent.EndOffset,再求值它后面的部分。
$tok = $null; $perr = $null
$ast = [System.Management.Automation.Language.Parser]::ParseInput($src, [ref]$tok, [ref]$perr)
  if ($stCut -lt 0) { Test-St ("STATE $Name") $false '裁剪锚点失配:install.ps1 里找不到自证裁剪锚点 nonce'; return }
  $stL = if ($Yes) { '$true' } else { '$false' }
  $stD = if ($DryRun) { '$true' } else { '$false' }
$close = $pb.Extent.EndOffset - 1
# 用普通赋值替回 param 默认值(不能只删:后面 Set-StrictMode 下这些变量必须已定义),
#   但不绑定 $Yes/$DryRun/$Interactive —— 它们要保持本探针从命令行收到的那组值。
Invoke-Expression ($stDefaults + $body.Substring($close + 1))
$d = Get-ConfirmDecision -Yes $stYes -DryRun $stDry -Interactive $stInter -Answer $Answer
Write-Output ('DECISION=' + $d)
'@
function Test-StDecision {
  param([string] $Name, [bool] $Yes, [bool] $DryRun, [bool] $Interactive, [string] $Answer, [string] $Want)
  # 裁剪点在这里算好再传给探针。锚点分四段拼出来 —— 任何一段都不含完整 nonce,
  #   所以本函数(以及整个探针源码,它嵌在目标文件里)不会成为 IndexOf 的首个命中。
    Write-StLine ("      子进程原始输出: [" + (($stOut | Where-Object { $_ -notlike 'DECISION=*' }) -join ' / ') + "]")
    Test-St ("STATE $Name") ($stGot -eq $Want) ("期望 decision={0};实得 decision={1};提示语应逐字为 [{2}]" -f $Want, $stGot, $stDecisionLines[$Name])
  } finally {
    if (Test-Path -LiteralPath $stProbeFile) { Remove-Item -LiteralPath $stProbeFile -Force }
  }
}

# -SelfTest:被测件自带自证(本仓惯例:tools/round.mjs --selftest、tools/host-matrix.mjs --selftest)。
# 位置在 -Source 解析之前、任何写盘动作之前 —— 与 -ListHosts 同为早退路径,零写盘。
if ($SelfTest) {
  $stFail = @()
  # 被测件路径取本脚本自身:-File 调用下 $PSScriptRoot 可用;拿不到才报一条 FAIL(不静默变绿)
  # 取自己的真实路径(不硬编码文件名:本文件被复制/改名后自证仍要看自己那份,实测硬编码会报"找不到文件")
  $stSelf = $MyInvocation.MyCommand.Path
  if (-not $stSelf) { $stSelf = Join-Path (Get-Variable -Name PSScriptRoot -ErrorAction SilentlyContinue -ValueOnly) 'install.ps1' }
  function Write-StLine([string] $s) { Write-Host $s }
  function Test-St {
    param([string] $Name, [bool] $Ok, [string] $Detail)
    $mark = if ($Ok) { 'PASS' } else { 'FAIL' }
    Write-StLine ("[{0}] {1}: {2}" -f $mark, $Name, $Detail)
    if (-not $Ok) { $script:stFail += $Name }
  }


# -SelfTest:被测件自带自证(本仓惯例:tools/round.mjs --selftest、tools/host-matrix.mjs --selftest)。
# 位置在 -Source 解析之前、任何写盘动作之前 —— 与 -ListHosts 同为早退路径,零写盘。
if ($SelfTest) {
  $stFail = @()
  # 被测件路径取本脚本自身:-File 调用下 $PSScriptRoot 可用;拿不到才报一条 FAIL(不静默变绿)
  # 取自己的真实路径(不硬编码文件名:本文件被复制/改名后自证仍要看自己那份,实测硬编码会报"找不到文件")
  $stSelf = $MyInvocation.MyCommand.Path
  if (-not $stSelf) { $stSelf = Join-Path (Get-Variable -Name PSScriptRoot -ErrorAction SilentlyContinue -ValueOnly) 'install.ps1' }
  function Write-StLine([string] $s) { Write-Host $s }
  function Test-St {
    param([string] $Name, [bool] $Ok, [string] $Detail)
    $mark = if ($Ok) { 'PASS' } else { 'FAIL' }
    Write-StLine ("[{0}] {1}: {2}" -f $mark, $Name, $Detail)
    if (-not $Ok) { $script:stFail += $Name }
  }
  # 自证:隔离口径硬话必须在【裁剪点之后】、且排在「将写入的宿主根」那句前面。
  # 为什么锚在裁剪点之后:裁剪点之前是函数定义与纯判定调用点（探针要求值的那段）,
  #   提示语的字面量恰好也在那片 —— 只搜全文的话,字面量在,真正的打印被摘掉也照样绿
  #   （恒绿 = 假证据）。段界与裁剪点同源（同一个 nonce 拼法）,不另立第二个坐标。
  # 只搜字面量也还不够:活字变量比死字面量更常见 —— 加 positional 断言（必须排在宿主根那句之前）。
  function Test-StOutIsolation {
    if (-not $stSelf) { Test-St '隔离口径 -DryRun 输出含硬话' $false '取不到本脚本路径,无法自证'; return }
    $stCutIso = ([IO.File]::ReadAllText($stSelf)).IndexOf($stSrcMark)
  # 自证:隔离口径硬话必须在【裁剪点之后】、且排在「将写入的宿主根」那句前面。
  # 为什么锚在裁剪点之后:裁剪点之前是函数定义与纯判定调用点（探针要求值的那段）,
  #   提示语的字面量恰好也在那片 —— 只搜全文的话,字面量在,真正的打印被摘掉也照样绿
  #   （恒绿 = 假证据）。段界与裁剪点同源（同一个 nonce 拼法）,不另立第二个坐标。
  # 只搜字面量也还不够:活字变量比死字面量更常见 —— 加 positional 断言（必须排在宿主根那句之前）。
  function Test-StOutIsolation {
    if (-not $stSelf) { Test-St '隔离口径 -DryRun 输出含硬话' $false '取不到本脚本路径,无法自证'; return }
    $stCutIso = ([IO.File]::ReadAllText($stSelf)).IndexOf($stSrcMark)
    if ($stCutIso -lt 0) { Test-St '隔离口径 -DryRun 输出含硬话' $false '裁剪锚点失配:源码里找不到自证锚点 nonce'; return }
    # .ToCharArray() 是为绕开「字符串不能直接切数组」的坑(PS 5.1);-join 回拼后就是同一段文本
    $stTail = -join ([IO.File]::ReadAllText($stSelf).ToCharArray()[$stCutIso..(([IO.File]::ReadAllText($stSelf).Length) - 1)])
    # $stP 必须先命中【打印点】—— $stSentinel 与 $stIsolateLine 的字面量同形,
    #   而那个字面量定义在裁剪点之前,所以本扫描只可能在后面那行 Write-Output 上命中它。
    $stP = $stTail.IndexOf($stSentinel); $stH = $stTail.IndexOf($stIsolateMarker)
    $stOk = ($stP -ge 0) -and ($stH -ge 0) -and ($stP -lt $stH)   # $stP=硬话打印点 $stH=硬话变量在打印点上的出现
    Test-St '隔离口径 -DryRun 输出含硬话' $stOk ("期望 [{0}] 在裁剪点之后找得到且排在 [{1}] 之前;实得 at={2} / hostmark at={3}(-1=没找到)" -f $stIsolateMarker, $stPromptTwin, $stP, $stH)
  }
  Test-StOutIsolation

}
function Get-Version([string] $dir) {
  $f = Join-Path $dir 'kernel/index.json'
  if (Test-Path -LiteralPath $f) {
    # 必须显式按 UTF-8 读:PS 5.1 对无 BOM 的 UTF-8 会按 ANSI(GBK) 解码,导致 ConvertFrom-Json 失败
    try { return ([IO.File]::ReadAllText($f, [Text.Encoding]::UTF8) | ConvertFrom-Json).version } catch { }
  }
  return 'unknown'
}
$SourceVersion = Get-Version $SrcSkill

# 宿主根清单(唯一来源):脚本同级的 hosts.tsv,与 install.sh / cli/polaris.mjs 读同一份。
# 一致性由 tools/host-matrix.mjs --check 机械判定(任一处再抄一份名单即判红)。
function Get-HostManifest {
  $p = Join-Path $Source 'hosts.tsv'
  if (-not (Test-Path -LiteralPath $p)) { throw "找不到宿主根清单 hosts.tsv: $p(安装包不完整)" }
  # 显式按 UTF-8 读:PS 5.1 对无 BOM 的 UTF-8 会按 ANSI(GBK) 解码(与 Get-Version 同一坑)
  $rows = @()
  foreach ($line in ([IO.File]::ReadAllText($p, [Text.Encoding]::UTF8) -split "`n")) {
    $t = $line.Trim()
    if ($t -eq '' -or $t.StartsWith('#')) { continue }
    $c = $t.Split('|')
    if ($c.Count -ne 3) { throw "宿主根清单行格式应为 host|root|always,实际: $t" }
    $rows += @{ host = $c[0]; rootRel = $c[1]; always = ($c[2] -eq 'true') }
  }
  if ($rows.Count -eq 0) { throw "宿主根清单为空: $p" }
  return $rows
}

function Get-Targets {
  $all = @(Get-HostManifest | ForEach-Object { @{ host = $_.host; root = (Join-Path $HomeDir $_.rootRel); always = $_.always } })
  if ($SkillsRoot.Count -gt 0) {
    return $SkillsRoot | ForEach-Object { @{ host = 'custom'; root = $_; always = $true } }
  }
  return $all | Where-Object { $_.always -or (Test-Path -LiteralPath (Split-Path -Parent $_.root)) }
}

# 不依赖 Get-FileHash(部分环境下模块自动加载被禁用)与 -File 参数(旧版 PowerShell 没有)
function Get-Sha256([string] $p) {
  $sha = [System.Security.Cryptography.SHA256]::Create()
  $fs  = [System.IO.File]::OpenRead($p)
  try { ([BitConverter]::ToString($sha.ComputeHash($fs))).Replace('-', '') }
  finally { $fs.Close(); $sha.Dispose() }
}

function Get-RelFiles([string] $base) {
  Get-ChildItem -LiteralPath $base -Recurse |
    Where-Object { -not $_.PSIsContainer } |
    ForEach-Object { $_.FullName.Substring($base.Length).TrimStart('\', '/') }
}

# -ListHosts:只打印清单(不写盘,也不需要源技能目录) —— 输出须与 install.sh --list-hosts / cli/polaris.mjs hosts 逐行一致
if ($ListHosts) {
  foreach ($r in Get-HostManifest) { "$($r.host)|$($r.rootRel)|$(if ($r.always) { 'true' } else { 'false' })" }
  exit 0
}

