function Get-ConsoleInputHandle {
  try { $h = [Console]::OpenStandardInput(); if ($h -and $h.CanRead) { return $h } } catch { }
  return $null
}

# 确认口径的纯函数面(四态:skip/no-confirm/proceed/cancel)。返回:
#   skip=-Yes 跳过确认(备份与隔离照旧) no-confirm=-DryRun 不写盘故不确认(也不打印确认行)
#   proceed=交互且答 y 或非交互无人可确认(不阻塞)   cancel=交互且答非 y/Y/yes → 调用方零写入
# 为什么必须是纯函数:交互与取消两条分支在自动化里走不到,抽成"输入 → 判定"后,一条无写盘命令(-SelfTest)
# 就能把四态各走一遍 —— 否则"取消"分支永远测不到 = 未实证。
function Get-ConfirmDecision {
  param([bool] $Yes, [bool] $DryRun, [bool] $Interactive, [string] $Answer = '')
  if ($Yes) { return 'skip' }                              # ① -Yes:跳过确认(备份与隔离照旧)
  if ($DryRun) { return 'no-confirm' }                     # ② -DryRun:不写盘,无人可确认
  if (-not $Interactive) { return 'proceed' }               # ④ 非交互:无人可确认,按既有语义继续(不阻塞)
  if (Test-ConfirmAnswer $Answer) { return 'proceed' }      # ③ 交互且答 y/Y/yes → 继续
  return 'cancel'                                           # ③ 交互且答非 y/Y/yes → 取消(调用方零写入)
}
# 回答口径与 install.sh:87 的 case "$ans" in y|Y|yes|YES|Yes) 逐条对齐
function Test-ConfirmAnswer([string] $Answer) {
  if ($null -eq $Answer) { return $false }
  $a = $Answer.Trim()
  return ($a -ceq 'y' -or $a -ceq 'Y' -or $a -ceq 'yes' -or $a -ceq 'YES' -or $a -ceq 'Yes')
