function Get-Version([string] $dir) {
  $f = Join-Path $dir 'kernel/index.json'
  if (Test-Path -LiteralPath $f) {
    # 必须显式按 UTF-8 读:PS 5.1 对无 BOM 的 UTF-8 会按 ANSI(GBK) 解码,导致 ConvertFrom-Json 失败
    try { return ([IO.File]::ReadAllText($f, [Text.Encoding]::UTF8) | ConvertFrom-Json).version } catch { }
  }
  return 'unknown'
}
