import { fileURLToPath } from 'node:url'
import { spawnSync } from 'node:child_process'
import { createHash } from 'node:crypto'

const HERE = path.dirname(fileURLToPath(import.meta.url))
const REPO_FROM_TOOL = path.resolve(HERE, '..')          // 本工具所在仓库（清单与契约的【检查器自带尺】）
const ROOT = path.resolve(process.env.POLARIS_ROOT || REPO_FROM_TOOL)  // 被检查的树（可被 --root 覆盖）
const ROOT_FLAG = process.env.POLARIS_ROOT || REPO_FROM_TOOL

// ---- 退出码：与 kernel/fractal.json#tool_cli_contract 同款（0=ok / 12=红 / 1=用法错）----
const EXIT = { ok: 0, usage: 1, red: 12 }
// 超时是独立结局（GE 语义，照 run-sync.mjs 的 124），不与断言失败混用
const EXIT_TIMEOUT = 124
const DEFAULT_TIMEOUT_MS = 180_000

const argv = process.argv.slice(2)
const has = (f) => argv.includes(f)
const opt = (name) => {
  const hit = argv.find((a) => a === `--${name}` || a.startsWith(`--${name}=`))
  if (!hit) return null
  const eq = hit.indexOf('=')
  return eq === -1 ? (argv[argv.indexOf(hit) + 1] ?? '') : hit.slice(eq + 1)
}
// --root / POLARIS_ROOT：被检查的树（自证夹具与沙箱副本靠它；不设则 = 本工具所在仓库）
{
  const r = opt('root')
  if (r) process.env.POLARIS_ROOT = path.resolve(r)
}

const rel = (p) => path.relative(ROOT, p).replace(/\\/g, '/')
const sha16 = (buf) => createHash('sha256').update(buf).digest('hex').slice(0, 16)

const INVENTORY_REL = 'state/tests/feature-inventory.json'
const REPORT_REL = 'state/tests/feature-matrix.md'
const CONTRACT_REL = 'skills/aurapolaris/kernel/fractal.json'
const LAYERS_REL = 'skills/aurapolaris/tools/test-layers.json'
const DELEGATION_REL = 'skills/aurapolaris/kernel/delegation.json'

const readJson = (abs, what) => {
  if (!fs.existsSync(abs)) return { ok: false, why: `${what} 缺件: ${rel(abs)}` }
  try { return { ok: true, v: JSON.parse(fs.readFileSync(abs, 'utf8')) } }
  catch (e) { return { ok: false, why: `${what} 不可解析: ${rel(abs)} — ${e.message}` } }
}

function usage() {
  console.log(`用法: node tools/feature-matrix.mjs <子命令> [选项]

子命令（缺省 = --report）:
  selftest | --selftest       自证：合成夹具上证明本仪器【能红能绿】（不碰真树）
  --check                     逐条跑清单里每行的证据命令；退出码只被【红】影响（0 / 12）
  --report                    打印矩阵表；只打印，【恒 exit 0】（除非清单读不到）
  --json                      机读（含三桶计数、逐行读数、覆盖率自证）
  --explain                   判定口径说明（不跑任何东西，exit 0）

选项:
  --only=<id[,id...]>         只跑这些行（支持 id 前缀匹配）；同时作为覆盖率自证的取样面
  --root=<DIR>                被检查的树（缺省 = POLARIS_ROOT ?? 本工具所在仓库）
  --write-report              把矩阵表写到 ${REPORT_REL}（只有显式给才写）
  --timeout=<ms>              每行超时（缺省 ${DEFAULT_TIMEOUT_MS}；超时按 ${EXIT_TIMEOUT} 记，独立于断言失败）

三桶:
  绿       证据命令跑通【且】清单声明的成功信号命中
  红       跑不通（退出码不符 / 超时 / 清单缺 id）或信号不命中 —— 逐条点名「哪条功能/怎么触发/期望什么/实得什么」
  待交付   owner 仍是【在跑或未交付】的单 ⇒ 只列、不计红，并打印 owning 单 id
退出码: 0 全绿或只有待交付 / ${EXIT.red} 有红 / ${EXIT.usage} 用法错或清单读不到`)
}

// ---------------- 清单 ----------------
function loadInventory() {
  const r = readJson(path.join(ROOT, INVENTORY_REL), '功能清单')
  if (!r.ok) return { ok: false, why: r.why }
  const inv = r.v
  if (!Array.isArray(inv.rows)) return { ok: false, why: `${INVENTORY_REL} 缺 rows[]` }
  const seen = new Set()
  for (const row of inv.rows) {
    for (const k of ['id', 'name', 'trigger', 'signal', 'evidence', 'host', 'owner', 'status', 'source']) {
      if (row[k] === undefined || row[k] === null || row[k] === '') return { ok: false, why: `清单行缺字段 ${k}: ${JSON.stringify(row.id ?? row)}` }
    }
    if (seen.has(row.id)) return { ok: false, why: `清单 id 重复: ${row.id}（id 是 --only 与判红的唯一定位键）` }
    seen.add(row.id)
    for (const k of ['expect_exit', 'signal_re']) if (row[k] === undefined) return { ok: false, why: `清单行缺判定键 ${k}: ${row.id}` }
    if (!Array.isArray(row.expect_exit) || !row.expect_exit.length) return { ok: false, why: `expect_exit 必须是数组（可多值，如 gate 的 10/11）: ${row.id}` }
  }
  return { ok: true, inv }
}

// ---------------- 执行 ----------------
// 解释器白名单（照 tools/ 既有各工具的 interp 口径，只列真用得到的）
const INTERP = { node: process.execPath, pwsh: 'pwsh', powershell: 'powershell' }
function resolveArgv(evidence) {
  if (Array.isArray(evidence)) return { exe: INTERP.node, args: evidence }
  if (evidence && typeof evidence === 'object' && Array.isArray(evidence.argv)) {
    const exe = INTERP[evidence.interp || 'node']
    if (!exe) return { err: `未知 interp: ${evidence.interp}` }
    return { exe, args: evidence.argv, input: evidence.input ?? null }
  }
  return { err: `evidence 形态非法（要 argv 数组或 {interp,argv,input}）: ${JSON.stringify(evidence)}` }
}

function runOne(row, timeoutMs) {
  const r = resolveArgv(row.evidence)
  if (r.err) return { spawn_err: r.err }
  const t0 = Date.now()
  // 两条实测口径，都是被【假红】逼出来的（根因不在被测功能，在本工具的 spawn 选项）：
  //   ① 不给 encoding:'utf8'：拿 buffer 手动 toString('utf8')。带编码选项时，经 powershell 包装的命令
  //      （如 uninstall --dry-run）中文会按控制台码页转一遍，读回来是乱码（“未写入任何文件”→“δд���κ��ļ���”）。
  //   ② 【不给 windowsHide:true】：实测同一命令同一环境，windowsHide:true 会把子进程的控制台拿掉，
  //      于是 powershell 落到 OEM 码页输出 ⇒ 照样乱码；去掉它（Node CLI 不需要隐藏窗口）即正常。
  //   两项都用编码复现夹具逐项对照过：encoding-repro.mjs 里只有 no-windowsHide 那一路 match=true。
  const out = spawnSync(r.exe, r.args, {
    cwd: ROOT,
    input: r.input == null ? undefined : r.input,
    timeout: timeoutMs,
    maxBuffer: 64 * 1024 * 1024,
    env: { ...process.env, POLARIS_ROOT: ROOT },
  })
  const ms = Date.now() - t0
  const dec = (b) => (b == null ? '' : Buffer.isBuffer(b) ? b.toString('utf8') : String(b))
  if (out.error && out.error.code === 'ETIMEDOUT') return { timeout: true, ms, stdout: dec(out.stdout), stderr: dec(out.stderr) }
  const stdout = dec(out.stdout)
  const stderr = dec(out.stderr)
  const exit = out.status === null ? (out.signal ? -1 : 1) : out.status
  return { exit, ms, stdout, stderr, merged: stdout + stderr }
}

// 交叉核对（可选）：第二路只读观测，用来证明“触发了但静默”的事件真的落到了账上。
function runCross(row, timeoutMs) {
  if (!row.cross_check) return null
  const r = resolveArgv(row.cross_check.evidence)
  if (r.err) return { spawn_err: r.err, pass: false }
  const out = spawnSync(r.exe, r.args, { cwd: ROOT, timeout: timeoutMs, maxBuffer: 16 * 1024 * 1024, env: { ...process.env, POLARIS_ROOT: ROOT } })
  const dec = (b) => (b == null ? '' : Buffer.isBuffer(b) ? b.toString('utf8') : String(b))
  const text = dec(out.stdout) + dec(out.stderr)
  let pass = false
  try { pass = new RegExp(row.cross_check.signal_re, 'm').test(text) } catch { pass = false }
  return { pass, exit: out.status, tail: tailOf(text, 200), signal_re: row.cross_check.signal_re }
}

const tailOf = (s, n = 240) => {
  const flat = String(s).replace(/\r?\n/g, ' ⏎ ').replace(/\s+/g, ' ').trim()
  return flat.length <= n ? flat : '…' + flat.slice(flat.length - n)
}

function settle(row, timeoutMs) {
  const isInflight = row.status === 'inflight' || row.pending === true

  // 预检：清单声明的 depends_on 缺件时先报【缺件】，不去跑那条命令
  //   —— 命令的“Cannot find module”会把“依赖件被在跑单改了/删了”读成“功能随机坏了”（归因跑偏）
  if (!isInflight && row.depends_on && !fs.existsSync(path.join(ROOT, row.depends_on))) {
    return {
      id: row.id, name: row.name, trigger: row.trigger, evidence_cmd: cmdText(row.evidence),
      signal: row.signal, host: row.host, owner: row.owner, status: row.status, source: row.source,
      expect_exit: row.expect_exit, signal_re: row.signal_re, depends_on: row.depends_on || null,
      cli: row.cli || null, plane: row.plane || null, hook_event: row.hook_event || null,
      got_exit: null, ms: null, tail: '',
      bucket: '红', depends_on: row.depends_on,
      problems: [`依赖件缺件：${row.depends_on} 不在树里（这条不是功能坏，是它的依赖件被删/被改名）`],
      converge: `先确认 ${row.depends_on} 是否被并行单移动/改名；再跑 node tools/feature-matrix.mjs --only=${row.id} 复核回绿`,
    }
  }

  const got = runOne(row, timeoutMs)
  const cross = isInflight ? null : runCross(row, timeoutMs)

  const rec = {
    id: row.id, name: row.name, trigger: row.trigger, evidence_cmd: cmdText(row.evidence),
    signal: row.signal, host: row.host, owner: row.owner, owner_kind: row.owner_kind || null,
    status: row.status, source: row.source,
    // 判据本身也要进记录：否则 --json 的产物不足以重建清单（本单实测教训：state/tests/ 被外部清掉后，
    //   靠 --json 重建时缺 signal_re，整整 75 行都要靠猜 —— 读数必须自带判据）
    expect_exit: row.expect_exit, signal_re: row.signal_re, depends_on: row.depends_on || null,
    cli: row.cli || null, plane: row.plane || null, hook_event: row.hook_event || null,
    got_exit: got.exit ?? null, ms: got.ms ?? null,
    tail: tailOf(got.merged || got.spawn_err || ''),
  }

  // 待交付：不计红、【也不执行】—— 只列 + 打印 owning 单 id
  //   实测教训（本单）：这里回得太晚，去跑了 inflight 行的命令，而那种命令现在大多不存在或会卡到超时
  //   （实测 inflight-c68-attribution-hypothesis 的 taskctl verify 白跑 180s 超时），把整轮墙钟顶成两倍。
  //   “不计红”不等于“可以跑”：待交付的 owner 还在写，跑它的读数既不可归因也浪费时间。
  if (isInflight) {
    rec.bucket = '待交付'
    rec.why = row.pending_why || `owner 仍在跑或未交付`
    rec.got_exit = null
    rec.ms = 0
    rec.tail = '（未执行：owner 仍在跑或未交付，本仪器不替在跑功能取数）'
    return rec
  }

  const problems = []
  if (got.spawn_err) problems.push(`跑不通：${got.spawn_err}`)
  else if (got.timeout) problems.push(`跑不通：超时（${timeoutMs}ms）→ 记 ${EXIT_TIMEOUT}`)
  else if (!row.expect_exit.includes(got.exit)) problems.push(`退出码不符：期望 ${row.expect_exit.join('|')}，实得 ${got.exit}`)

  let sigOk = true
  try { sigOk = new RegExp(row.signal_re, 'm').test(got.merged || '') } catch (e) { sigOk = false; problems.push(`signal_re 不是合法正则：${e.message}`) }
  if (!sigOk && !got.spawn_err && !got.timeout) problems.push(`成功信号不命中：期望输出里出现 /${row.signal_re}/，实得尾部「${rec.tail}」`)

  let crossOk = true
  if (cross) {
    crossOk = cross.pass === true
    if (!crossOk) problems.push(`交叉核对不命中：期望 /${row.cross_check.signal_re}/，实得「${cross.tail}」`)
  }

  rec.cross = cross ? { pass: cross.pass, signal_re: cross.signal_re, tail: cross.tail } : null
  rec.bucket = problems.length ? '红' : '绿'
  if (problems.length) rec.problems = problems
  if (rec.bucket === '红') rec.converge = row.converge || convergeHint(row)
  return rec
}

function cmdText(evidence) {
  if (Array.isArray(evidence)) return 'node ' + evidence.join(' ')
  if (evidence && Array.isArray(evidence.argv)) return `${evidence.interp || 'node'} ${evidence.argv.join(' ')}` + (evidence.input ? '   # stdin<-清单内嵌载荷' : '')
  return JSON.stringify(evidence)
}

// 红条必须逐条给收敛动作：清单没写就按 owner_kind 给机械兜底（不猜语义）
function convergeHint(row) {
  const owner = row.owner_kind === 'path' ? `改 ${row.owner}` : `找 owner 单 ${row.owner}`
  return `${owner}；再跑 node tools/feature-matrix.mjs --only=${row.id} 复核回绿`
}




function enumerateSources() {
  const out = { cli_subcommands: [], test_planes: [], hook_events_dsh: [], skill_sections: [], errors: [] }

  const cliAbs = path.join(ROOT, 'cli/polaris.mjs')
  if (fs.existsSync(cliAbs)) {
    const txt = fs.readFileSync(cliAbs, 'utf8')
    const names = new Set()
    for (const line of txt.split(/\r?\n/)) {
      const bare = line.replace(/\/\/.*$/, '')
      const mTable = bare.match(/const table = \{(.*)\}/)
      if (mTable) for (const m of mTable[1].matchAll(/([A-Za-z_][\w]*)\s*:/g)) names.add(m[1])
      const mAsg = bare.match(/table\.([A-Za-z_][\w]*)\s*=/)
      if (mAsg) names.add(mAsg[1])
    }
    out.cli_subcommands = [...names].sort()
  } else out.errors.push(`cli/polaris.mjs 缺件（枚举不到子命令表）`)

  const lay = readJson(path.join(ROOT, LAYERS_REL), '测试层声明')
  if (lay.ok) out.test_planes = lay.v.layers.flatMap((L) => L.planes.map((p) => ({ id: p.id, layer: L.name })))
  else out.errors.push(lay.why)

  const dg = readJson(path.join(ROOT, DELEGATION_REL), 'hook 事件映射')
  if (dg.ok) {
    const em = dg.v?.host_capabilities?.hook_injection?.event_map
    out.hook_events_dsh = Object.keys(em?.dsh || {})
  } else out.errors.push(dg.why)

  const skAbs = path.join(ROOT, 'skills/aurapolaris/SKILL.md')
  if (fs.existsSync(skAbs)) {
    const lines = fs.readFileSync(skAbs, 'utf8').split(/\r?\n/)
    out.skill_sections = lines.map((l, i) => ({ line: i + 1, text: l }))
      .filter((x) => /^-\s+\*\*/.test(x.text) || /^\*\*/.test(x.text))
      .map((x) => x.line)
  } else out.errors.push('skills/aurapolaris/SKILL.md 缺件')

  return out
}

function coverage(inv) {
  const enumd = enumerateSources()
  const rows = inv.rows
  const mapped = (pred) => rows.filter(pred).map((r) => r.id)

  const cliMap = {}
  for (const s of enumd.cli_subcommands) {
    // 行的 cli 字段声明它覆盖哪个子命令（唯一登记处）；不看 evidence 文本猜
    cliMap[s] = rows.filter((r) => r.cli === s).map((r) => r.id)
  }
  const planeMap = {}
  for (const p of enumd.test_planes) planeMap[p.id] = rows.filter((r) => r.plane === p.id).map((r) => r.id)
  const hookMap = {}
  for (const e of enumd.hook_events_dsh) hookMap[e] = rows.filter((r) => r.hook_event === e).map((r) => r.id)
  const secMap = {}
  for (const ln of enumd.skill_sections) secMap[`SKILL.md:${ln}`] = rows.filter((r) => r.skill_line === ln).map((r) => r.id)

  const tally = (m) => ({
    total: Object.keys(m).length,
    mapped: Object.values(m).filter((v) => v.length).length,
    unmapped: Object.entries(m).filter(([, v]) => !v.length).map(([k]) => k),
    map: m,
  })

  return {
    method: {
      cli: '扫 cli/polaris.mjs 的派发表（const table = {...} + table.<name> = ...），逐个子命令在清单里找 cli 字段等于它的行',
      test_planes: `读 ${LAYERS_REL} 的 layers[].planes[].id，逐面在清单里找 plane 字段等于它的行`,
      hook_events: `读 ${DELEGATION_REL}#host_capabilities.hook_injection.event_map.dsh 的键，逐事件找 hook_event 字段等于它的行`,
      skill_sections: '扫 skills/aurapolaris/SKILL.md 里行首 ** 或 - ** 的功能段行号，逐段找 skill_line 字段等于它的行',
    },
    cli_subcommands: tally(cliMap),
    test_planes: { ...tally(planeMap), by_layer: [...new Set(enumd.test_planes.map((p) => p.layer))].map((L) => `${L}=${enumd.test_planes.filter((p) => p.layer === L).length}`).join(' ') },
    hook_events_dsh: tally(hookMap),
    skill_sections: tally(secMap),
    cli_dispatch_sample: enumd.cli_subcommands.slice(0, 8),
    errors: enumd.errors,
  }
}

// ---------------- 渲染 ----------------
const BUCKET_ORDER = ['绿', '红', '待交付']
function counts(recs) {
  const c = { 绿: 0, 红: 0, 待交付: 0 }
  for (const r of recs) c[r.bucket]++
  return c
}

function printTable(recs, meta, cov) {
  const c = counts(recs)
  console.log(`FEATURE-MATRIX  root=${ROOT}  清单=${INVENTORY_REL}`)
