// ---------------- 主流程 ----------------
function main() {
  if (has('selftest') || has('--selftest')) { if (argv.includes('--explain')) usage(); process.exitCode = selftest(); return }

  if (has('--explain')) {
    console.log(`feature-matrix 判定口径（不跑任何东西）

一、本仪器做什么: 逐条触发清单里的功能，读回 {退出码, 输出, 成功信号命中}，三桶落位。它不解释功能语义 ——
    「这个功能该不该这样」不归它判，归清单的 owner 与判据所有者。

二、每行判绿的两个必要条件（AND，缺一即红）:
    ① 证据命令【跑通】: 进程能起、未超时（超时记 ${EXIT_TIMEOUT}，独立结局）、退出码 ∈ 清单声明的 expect_exit
    ② 成功信号【命中】: 合并 stdout+stderr 里有清单声明的 signal_re 正则命中
    可选第三路 cross_check: 第二处只读观测（如 hook 事件的落账日志）也必须命中，用来证明“静默但已触发”的事件真的发生了。
    声明了自己“可用”却是空壳（退出码对、信号无）⇒ 判红 —— 这是本仪器存在的理由。

三、三桶:
    绿     = ①②都过
    红     = 任一条不过（跑不通 / 超时 / 退出码不符 / 信号不命中 / cross_check 不命中）
    待交付 = 该行 owner 是仍在跑或未交付的单（status=inflight 或 pending=true）⇒ 只列、不计红、打印 owner 单 id
    --check 的退出码只被【红】影响（待交付不参与）。

四、为什么不会恒绿（判据核心）:
    selftest 在合成夹具上同时证明四条能红路径（退出码不符 / 信号不命中 / 入口缺失 / 清单缺 source）
    与一条正例能绿；真树侧另有“沙箱副本破坏入口 → 该行变红 → 复原回绿”的反例留档。

五、只读约束（本仪器自己守）:
    清单里的证据命令一律取被测工具的【只读子命令】（--check/--status/--dry-run/--list/--explain/selftest/
    selftest 自证/--source=ledger 打印模式）。凡会起常驻服务或占端口的入口（--serve/--ensure-serve）不进清单；
    端口只用只读方式看（读 /api/health 或工具自己的 --status）。本工具自身不写盘，除非显式 --write-report。`)
    process.exitCode = EXIT.ok; return
  }

  const loaded = loadInventory()
  if (!loaded.ok) { console.error(`清单读不到：${loaded.why}`); process.exitCode = EXIT.usage; return }
  const inv = loaded.inv
  const meta = {
    task_id: inv.task_id, pointer_sha256: inv.pointer_sha256,
    inv_sha16: sha16(fs.readFileSync(path.join(ROOT, INVENTORY_REL))),
    timeout_ms: Number(opt('timeout') || DEFAULT_TIMEOUT_MS),
    layer_sample_note: inv.layer_sample_note || null,
  }

  // --only：只跑指定行（前缀匹配）
  let rows = inv.rows
  const only = opt('only')
  if (only) {
    const pats = String(only).split(',').map((s) => s.trim()).filter(Boolean)
    if (!pats.length) { console.error('--only= 后面没给 id'); process.exitCode = EXIT.usage; return }
    rows = inv.rows.filter((r) => pats.some((p) => r.id === p || r.id.startsWith(p)))
    const miss = pats.filter((p) => !inv.rows.some((r) => r.id === p || r.id.startsWith(p)))
    if (miss.length) { console.error(`清单里没有这些 id: ${miss.join(', ')}（--only 不会静默变成空集）`); process.exitCode = EXIT.usage; return }
    if (!rows.length) { console.error('--only 选中的行数为 0：判红口径不许把空集读成通过'); process.exitCode = EXIT.usage; return }
  }

  const t0 = Date.now()
  const recs = []
  for (const row of rows) {
    // 逐行打【行首时刻 + 该行耗时】：墙钟对不上行耗时的和时，这一行读数就是定位依据
    //   （本单实测第一版墙钟 463s / 行耗时之和 103s，靠它定位到“待交付行被真跑了”）
    const rs = Date.now()
    process.stderr.write(`… ${row.id} @+${((rs - t0) / 1000).toFixed(1)}s\n`)
    const rec = settle(row, meta.timeout_ms)
    rec.wall_offset_ms = rs - t0
    recs.push(rec)
    process.stderr.write(`   ${row.id} → ${rec.bucket} ${rec.ms}ms\n`)
  }
  const wallMs = Date.now() - t0
  const cov = only ? null : coverage(inv)   // 覆盖率自证只在整轮跑时有意义（取样轮会假报未映射）

  const mode = has('--json') ? 'json' : has('--check') ? 'check' : 'report'
  if (mode === 'json') {
    console.log(JSON.stringify(toJson(recs, meta, cov), null, 1))
  } else {
    printTable(recs, meta, cov)
    const c = counts(recs)
    console.log(`墙钟 ${(wallMs / 1000).toFixed(1)}s；三桶 绿=${c['绿']} 红=${c['红']} 待交付=${c['待交付']}`)
    if (c['红']) console.log(`红条 ${c['红']} 条 —— 逐条收敛动作见上（每条都点名 功能/触发/期望/实得）`)
  }

  if (has('--write-report') && mode !== 'json') {
    fs.mkdirSync(path.dirname(path.join(ROOT, REPORT_REL)), { recursive: true })
    fs.writeFileSync(path.join(ROOT, REPORT_REL), renderMarkdown(recs, meta, cov, wallMs))
    console.log(`已写 ${REPORT_REL}`)
  }

  const c = counts(recs)
  // --report / --json：只打印，恒 exit 0（除非清单读不到，那已在上面 exit 1）；--check 只被红影响
  if (mode === 'check') process.exitCode = c['红'] ? EXIT.red : EXIT.ok
  else process.exitCode = EXIT.ok
}

main()

