/* ---------------- 首屏视口（arch-v2.C47 补） ----------------
   径向布局把焦点放在**画布正中**。真实快照的画布能到 6300×6200（218 节点），
   而 100% 缩放下的视口只看得到左上角 (0,0)-(1600,900) —— 焦点和整个环都在视口外，
   打开页面就是一片空白（演示夹具只有 8~21 个节点、画布比视口小，所以看不出来）。
   所以：数据就绪后的第一次渲染把视口居中到焦点，缩放到「焦点 + 第一圈子节点基本可见」。
   缩放**下限 = 60/86 ≈ 0.7**：既有契约「1600×900 下卡片渲染高度中位 ≥60px」在缩放后
   也必须成立（卡片高 86px），0.7 是这个契约能给的最低倍率；再小就真的看不清楚了。 */
var VIEW_MIN_ZOOM = 0.7;

function focusBox() {
  var L = state.layout, d = state.data;
  if (!L || !d) return null;
  var fid = focusIdOf(d);
  if (fid == null) return null;
  var f = null, i;
  for (i = 0; i < L.nodes.length; i++) if (L.nodes[i].id === String(fid)) { f = L.nodes[i]; break; }
  if (!f) return null;
  var minX = f.x, minY = f.y, maxX = f.x + f.w, maxY = f.y + f.h;
  var kids = archChildMap(d.nodes, d.edges)[String(fid)] || [];
  var seen = {}, n;
  for (i = 0; i < kids.length; i++) seen[String(kids[i])] = 1;
  for (i = 0; i < L.nodes.length; i++) {
    n = L.nodes[i];
    if (seen[n.id] !== 1) continue;
    if (n.x < minX) minX = n.x;
    if (n.y < minY) minY = n.y;
    if (n.x + n.w > maxX) maxX = n.x + n.w;
    if (n.y + n.h > maxY) maxY = n.y + n.h;
  }
  return { x: f.x + f.w / 2, y: f.y + f.h / 2, minX: minX, minY: minY, maxX: maxX, maxY: maxY };
}

function defaultViewport() {
  var box = focusBox(), st = $('stageWrap');
  if (!box || !st) return null;
  var availW = Math.max(200, st.clientWidth - 48);
  var availH = Math.max(200, window.innerHeight - 220);
  var spanW = Math.max(260, box.maxX - box.minX + 60);
  var spanH = Math.max(200, box.maxY - box.minY + 60);
  var z = Math.min(availW / spanW, availH / spanH, 1);
  if (!isFinite(z) || !(z > 0)) z = 1;
  z = Math.max(VIEW_MIN_ZOOM, Math.min(1, z));
  return { zoom: z, x: box.x, y: box.y };
}

