//   所有破坏/触写都发生在沙箱副本上;跑完删除沙箱并核对真树 git status 行数。
// 【沙箱】本机 %TEMP% = C:\Users\cxk\... 落在派单的 forbid 前缀下 → 沙箱根改用仓库外
//   E:\AuraPolaris-tmp\r7-ranges\(可用 R7_SANDBOX_BASE 覆盖)。沙箱根若落在仓库内 → 拒绝运行。
// 【退出码】0 = 12 条全绿;12 = 有红;1 = runner 自身无法开工(沙箱/拷贝校验失败)。
//
// 用法: node state/ranges/R7-A-round-mechanism/run.mjs
// =============================================================================
import fs from 'node:fs'
import os from 'node:os'
import path from 'node:path'
import crypto from 'node:crypto'
import { spawnSync } from 'node:child_process'
import { fileURLToPath } from 'node:url'

