const SUT_REL = 'tools/round.mjs'
const SUT_REPO = path.join(ROOT, SUT_REL)
const REQUIRED_RANGES = 3
const FORBID = ['C:\\Users\\cxk']          // 派单 forbid_paths(本机 %TEMP% 前缀)

const sha256 = (b) => crypto.createHash('sha256').update(b).digest('hex')
