const argv = process.argv.slice(2)
const flag = (n, d = null) => { const p = argv.find((a) => a.startsWith(`--${n}=`)); return p ? p.slice(n.length + 3) : (argv.includes(`--${n}`) ? true : d) }
const only = flag('only', null)
