#!/usr/bin/env node
// 把 AuraPolaris 统一入口接到 dsh 宿主上(幂等、先备份、可回滚)。零依赖。
//   node tools/apply-hook-dsh.mjs                      # 应用(默认: 本机 <DSH_HOME>/profiles/* 全部)
//   node tools/apply-hook-dsh.mjs --dry-run            # 只打印将写入的内容
//   node tools/apply-hook-dsh.mjs --remove             # 撤销(只移除本工具写的块与文件)
//   node tools/apply-hook-dsh.mjs --profiles web       # 指定 profile(--profiles web 与 --profiles=web 等价,逗号分隔)
//   node tools/apply-hook-dsh.mjs --sync-skill         # 把 skills/aurapolaris 刷新进 dsh 技能根(内容相同即跳过,先备份)
//   node tools/apply-hook-dsh.mjs --sync-skill=<rel,..> # 窄档:只刷新点名的仓库相对路径(相对 skills/aurapolaris),其余不动
//     (实测必要:2026-09-29 整份刷新会带上 6 个【别的单正在改】的文件 —— 只改内核登记时用窄档,别把半成品推进安装态)
// 机制(2026-09-22 实测,证据见 state/host-injection-matrix.md):dsh profile 的补丁层 cordis.patch.yml 支持
//   insert 条目;@deepseek-ai/dsh-hooks-codex 是可运行的 Codex hooks 兼容桥(桥支持 5 个 Codex 事件:
//   SessionStart/UserPromptSubmit/PreToolUse/PostToolUse/Stop)。
// 事件键【唯一来源】= kernel/delegation.json 的 host_capabilities.hook_injection.event_map.dsh:
//   本文件按它投影出落地配置的 hooks 键(模板只出【形状】:组/条目/字段名/命令串/超时/提示语)。
//   登记了而模板缺该条 → 按【内核事件类别】补形状;模板多出未登记事件 → 不落地(只警告)。
//   ⇒ 加/减一个事件只改登记表一处,不必再改模板第二处(2026-09-29 前的实测缺口:登记表没登记 Stop、模板也没有,
//     于是落地配置永远是 3 键,而桥白空着 Stop 这个交付前自检的接线点)。
// Stop 接线(交付前自检闸门,2026-09-29 接上):默认档 notice = 给一条提示但不打断 —— 不阻断用户回合。
//   切推回: node <skill>/tools/hook.mjs delivery-gate push-back  # 无结构交付时推回一次(每会话上限 1)
//          查看 = node <skill>/tools/hook.mjs delivery-gate;临时覆盖 = env POLARIS_DELIVERY_GATE=push-back(压过档位文件)
//   回退: 闸门回 notice(或 off=只记录);整条接线撤销 = node tools/apply-hook-dsh.mjs --remove(先备份,见下)
// 为什么需要 --sync-skill:桥跑的是【安装态副本】(<DSH_HOME>/skills/aurapolaris/**),
//   内核登记(kernel/delegation.json)改了不同步 = 现场还是老登记(实测形态:kind=unknown/via=unmapped,只记录不处理)。
//   ★只 apply 不 sync 时本工具打 ! 警告并点名缺哪些事件 —— 落地配置扩了键、路由那份没扩,等于没接。
// 形状(命令/协议键)只在 adapters/ 目录里(模板 tools/adapters/dsh-hooks.json),本文件只做投影与写入。
// 落地:①<DSH_HOME>/aurapolaris-hooks.json = 模板形状 + event_map.dsh 投影 + 本机统一入口绝对路径 ②每个 profile 的 cordis.patch.yml 插一条 mount
//   ③--sync-skill 时把 skills/aurapolaris 的内容刷新进 <DSH_HOME>/skills/aurapolaris(桥跑的就是这一份)。
import fs from 'node:fs'
import path from 'node:path'
import crypto from 'node:crypto'
import { fileURLToPath, pathToFileURL } from 'node:url'

const ROOT = path.resolve(process.env.POLARIS_ROOT ?? path.join(path.dirname(fileURLToPath(import.meta.url)), '..'))
const args = process.argv.slice(2)
const has = (f) => args.includes(f) || args.some((a) => a.startsWith(`${f}=`))
// 空格写法(--profiles web)与等号写法(--profiles=web)必须等价:2026-09-22 反证显示等号值被吞掉后
// 静默回落成"全量 profile"(--dry-run --profiles=auratest 打出 profile=auratest,headless,web)。
const val = (n, d = null) => {
  const i = args.indexOf(n)
  if (i >= 0) return args[i + 1] ?? d
  const p = args.find((a) => a.startsWith(`${n}=`))
  return p ? p.slice(n.length + 1) : d
}
  const p = args.find((a) => a.startsWith(`${n}=`))
  return p ? p.slice(n.length + 1) : d
}
const dryRun = has('--dry-run')
const remove = has('--remove')
// ── 只读自检入口(arch-v2.C113)────────────────────────────────────────────────────────────
// 为什么需要它:网页宿主的启动目录若不在工作区里,合成树里 sandbox-policy.workspaceRoot 就是那个目录;
//   Windows ACL 后端要求自己的 temp root 在 workspace【之外】,而家目录正好把 %TEMP% 包在里面 ⇒
//   后端不可用 ⇒ 沙箱档拒绝非受限执行 ⇒【每条钩子命令都没起】。这个失败是完全静默的:钩子照常
//   invoked、转录里 hook/result 也照常落(只是没有 exitCode),台账一行都不多 —— 人只会读成
//   「钩子没触发」,而不是「钩子被拦死了」。本入口把那段读数变成一条可行动的红。
// 默认档的行为与输出一个字节都不变:本入口只认显式旗标。
