#!/usr/bin/env node
// F2 家族对账门禁:按 tools/single-source.json 的登记,校验每个"事实"只有一份实现。
//   ① owner 可解析(file#symbol:代码文件查 function/const/class 定义,JSON 查点号路径);
//   ② dupPatterns 扫在册文件(排除表见登记表 scan.skipWhy):命中非 owner 文件即红并点名 file:line;
//   ③ 登记为 known-dup 的 fact 只许命中自己声明的 secondSites,且必须逐条列进 allowedUnresolved 白名单(带理由);
//   ④ 登记的 secondSites 必须与实测对上:声明的 file 得真有命中(这条【永远】成立);
//      声明了 line 的,line 得正好是命中的那行(2026-09-27 R7 553a1a4889b7:此前只按 file 匹配 ——
//      行号是装饰品,F2-2 声明 :225 而实测 :269 仍绿,登记表烂掉没人知道。漂移一律 FAIL,只许刷新成实测值);
//      【2026-09-29 arch-v2.C39:line 改成“可选”】不声明 line = 只断言“该文件里确实还有该模式的命中”。
//      为什么:行号是“与实现文本耦合”的另一种形态 —— 只要有人编辑那个文件(哪怕只是上方插几行),
//      门禁就为一条【与语义无关】的漂移变红,而且红在【别人】的改动上(实测:并行单改 cli/polaris.mjs
//      +44/−2,F2-9 当场从 0 变 12;同一文件在几十分钟内从 :235 漂到 :240、:241)。
//      为什么这样改【不是】放宽语义(三条真实保护一字未动):
//        ① “声明处已无命中”→ 仍 FAIL(登记的第二个实现消失了/被人收敛了,登记表该改);
//        ② “命中不在声明的文件里”→ 仍 FAIL(真出现第三处实现立刻红);
//        ③ 声明了 line 的仍逐字核对 —— 既有 F2-2/F2-3/F2-4 的判定与输出【一字未变】。
//      只去掉“必须写一个会漂的数字”这一条形式要求;证据面不受影响:输出里的 file:line 取自 hits(实测),
//      从来不取自 secondSites。
//   ⑤ 白名单就是"未收敛预算":列了却没有对应未收敛项(冗余预算)、或列了不在 facts 里的 id,一律 FAIL 只许删
//      —— 这正是 P2 之前"预算比实测多 1 就整类放行"的那个洞。
//   node tools/single-source.mjs --check [--root=DIR] [--json]   # 0=全部单源(未收敛项都被点名放行) / 12=有 FAIL / 1=用法错
//   node tools/single-source.mjs --selftest                       # 沙箱自证:复制 owner 实现→必红点名;删掉→回绿
import fs from 'node:fs'
import path from 'node:path'
import { spawnSync } from 'node:child_process'
import { fileURLToPath } from 'node:url'
// 临时箱【唯一入口】:清理挂在退出路径上(exit 钩子 + SIGINT/SIGTERM)。
//   旧形态把 rmSync 放在 process.exit 之前 —— 一旦自证在读到登记表之后抛错(如 fact.owner),
//   那一行根本走不到,箱就留在 %TEMP%。
import { mkbox } from '../skills/aurapolaris/tools/tmpbox.mjs'
// 宿主可执行路径的 hash 目录形态【正则唯一来源】= host-resolve 的 HASH_DIR_RE_SRC(arch-v2.C63)。
//   为什么不把模式字符串写在本文件里:同一份判定若写两处,它们会漂 —— 而这里的判定对象正是"路径写死"这一类。
//   工具文件被 import 是安全的:它有 CLI 守卫(IS_MAIN),import 不会跑 CLI、不会 process.exit。
import { HASH_DIR_RE_SRC } from '../skills/aurapolaris/tools/host-resolve.mjs'

export const HERE = path.dirname(fileURLToPath(import.meta.url))
export const ROOT = path.resolve(process.env.POLARIS_ROOT ?? path.join(HERE, '..'))
export const REGISTRY_REL = 'tools/single-source.json'
const readJson = (p) => JSON.parse(fs.readFileSync(p, 'utf8'))

// owner 解析:file#symbol —— 文件必须存在,符号必须真的定义在那(缺符号=登记表烂了,不是"没重复")。
export function resolveOwner(root, owner) {
  const i = String(owner ?? '').indexOf('#')
  if (i <= 0) return { ok: false, why: `owner 必须写成 file#symbol,收到 ${JSON.stringify(owner)}` }
  const rel = owner.slice(0, i), sym = owner.slice(i + 1)
  const abs = path.join(root, rel)
  if (!fs.existsSync(abs)) return { ok: false, why: `owner 文件不存在: ${rel}` }
  const src = fs.readFileSync(abs, 'utf8')
  if (rel.endsWith('.json')) {
    let cur
    try { cur = JSON.parse(src) } catch (e) { return { ok: false, why: `${rel} 不是合法 JSON(${e.message})` } }
    for (const seg of sym.split('.')) {
      if (cur && typeof cur === 'object' && seg in cur) { cur = cur[seg]; continue }
      return { ok: false, why: `JSON 路径 ${sym} 在 ${rel} 里解析不到(缺 "${seg}")` }
    }
    return { ok: true, kind: 'json' }
  }
  const name = sym.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')
  const re = new RegExp(`(^|\\n)[ \\t]*(export[ \\t]+)?(async[ \\t]+)?(function|const|let|var|class)[ \\t]+${name}\\b`)
  if (!re.test(src)) return { ok: false, why: `符号 ${sym} 在 ${rel} 里找不到定义(function|const|class)` }
  return { ok: true, kind: 'code' }
}

// 在册文件 = 全仓减去 scan.skipDirs / scan.skipFilePatterns,只留 scan.extensions 里的文本后缀。
export function inScopeFiles(root, scan = {}) {
  const skip = scan.skipDirs ?? []
  const skipFile = (scan.skipFilePatterns ?? []).map((p) => new RegExp(p))
  const exts = new Set(scan.extensions ?? [])
  const out = []
  const walk = (d) => {
    let entries = []
    try { entries = fs.readdirSync(d, { withFileTypes: true }) } catch { return }
    for (const e of entries) {
      const abs = path.join(d, e.name)
      const rel = path.relative(root, abs).split(path.sep).join('/')
      if (skip.some((s) => rel === s || rel.startsWith(s + '/'))) continue
      if (e.isDirectory()) { walk(abs); continue }
      if (!exts.has(path.extname(e.name)) || skipFile.some((r) => r.test(rel))) continue
      out.push(rel)
    }
  }
  walk(root)
  return out.sort()
}

// ============================================================================
// HOST-1(arch-v2.C63):仓库文本里【不许出现宿主可执行路径的 hash 目录形态】
// ----------------------------------------------------------------------------
// 【判什么】实测教训(2026-09-29):Codex 自更新会把 %LOCALAPPDATA%\OpenAI\Codex\bin\<hash>\codex.exe
//   换成新的 hash 目录(实测 d23520d1e41bfb24 → faa963e871dd422c,旧目录直接消失)。只要有人在派单、
//   文档或脚本里【手写】一次那种路径,自更新后就静默失效 —— 旧路径"看着还在",只是永远不再被命中。
//   所以判定不看"写得对不对",只看"有没有写":仓储文本里出现 hash 目录形态就是红;路径必须在运行时发现
//   (唯一发现入口 = skills/aurapolaris/tools/host-resolve.mjs;它的正则源 HASH_DIR_RE_SRC 就是本判据的模式)。
// 【不抓什么(诚实边界)】① 只扫本文件同一份在册文件集(inScopeFiles):state/** dist/** plugins/** 这些
//   被登记表整目录排除的地方【扫不到】(那里允许出现"坏例子"文本)—— 所以本判据是【防新写】,不是"全仓干净"。
//   ② 它判形态不判语义:一段【用来解释这个缺陷】的文本里真写了完整 hash 路径,照样红(转述时用占位/拆字)。
//   ③ 它抓不住"把路径拼出来"的规避写法(字符拼接/多行拼装/编码后再解码)——那种写法仍是同一个问题,
//      只是本判据看不见(与 F2-9 那条"内联谓词变体"的边界同款)。
// 【怎么免责】HOSTPATH_WHITELIST 逐条列明(file + why),【不允许静默豁免】:
//   · why 太短(少于 MIN_WHY 字)= FAIL:白名单不是"关掉这条判据"的开关,得写清楚为什么这里非写路径不可;
//   · 列了却没有任何命中 = FAIL(冗余白名单):白名单只许等于实测,不许预留着给将来放行;
//   · 真需要写路径的场合,正确做法是【改成走 host-resolve 的输出】(如 node tools/host-resolve.mjs --resolve codex),
//     而不是加一条白名单 —— 白名单是给"非写不可"的例外留的,不是给图省事留的。
// ============================================================================
export const HOSTPATH_WHITELIST = [
  // { file: '相对路径', why: '为什么这里非写 hash 路径不可(不少于 8 字)' },
]
const MIN_WHY = 8

// 扫一遍在册文件:命中 = {file,line,text}。只读,不写盘。

























































































  const unknownAllowed = [...allowed.keys()].filter((id) => !factIds.has(id))
  // HOST-1:宿主可执行路径的 hash 目录形态(见本文件头那一节)。它的红【不受】上面 F2 家族的任何白名单影响:
  //   免责只有 HOSTPATH_WHITELIST 一条路,且那条路自己要被机械审(理由太短/冗余都判红)。
  const hostPath = scanHostPaths(root, files, new RegExp(HASH_DIR_RE_SRC))
  const ok = fails === 0 && deadAllowed.length === 0 && unknownAllowed.length === 0
    && hostPath.unexempt.length === 0 && hostPath.problems.length === 0
  return { root, files: files.length, rows, unresolved, allowed: [...allowed.keys()], unlisted, deadAllowed, unknownAllowed, fails, ok, hostPath }
}
const named = (h) => `${h.file}:${h.line}`

function print(report) {
  for (const r of report.rows) {
    const label = r.status === 'PASS' ? 'PASS     ' : r.status === 'KNOWN-DUP' ? 'KNOWN-DUP' : 'FAIL     '
    console.log(`${label} ${r.id} ${r.fact.slice(0, 34)}`)
    console.log(`          owner=${r.owner} consumers=${r.consumers} 命中=${r.hits.length}${r.detail ? ` | ${r.detail}` : ''}`)
  }
  console.log(`\n单源对账: ${report.rows.length} 事实 / 扫描 ${report.files} 文件 / FAIL ${report.fails} / 未收敛 ${report.unresolved}(白名单 ${report.allowed.length}: ${report.allowed.join(',') || '(空)'})`)
  const dead = [...(report.deadAllowed ?? []), ...(report.unknownAllowed ?? [])]
  if (dead.length) console.log(`白名单冗余(预算只许等于实测,只许删): ${dead.join(',')}`)
  // HOST-1 逐行点名:命中要能直接复核(file:line + 那行原文),报错里指路运行时发现入口。
  const hp = report.hostPath ?? { hits: [], exempt: [], unexempt: [], problems: [], ownerExcluded: [] }
  console.log(`\nHOST-1 宿主可执行路径 hash 目录形态: 命中 ${hp.hits.length} / 放行 ${hp.exempt.length} / 未放行 ${hp.unexempt.length}`)
  for (const h of hp.hits) console.log(`  命中 ${h.file}:${h.line}${hp.exempt.includes(h) ? '(白名单放行)' : ''} → ${h.text}`)
  for (const p of hp.problems) console.log(`  白名单问题: ${p}`)
  console.log(`  扫描面: ${hp.scanned ?? '?'} 个文件(在册集减去判据自身: ${(hp.ownerExcluded ?? []).join(' / ') || '(空)'})`)
  if (hp.unexempt.length) {
    console.log('  怎么改: 路径一律在运行时发现,不要在仓库文本里手写 ——')
    console.log('    node tools/host-resolve.mjs --resolve codex      # 打印将被使用的绝对路径(仓库侧转发器)')
    console.log('    node skills/aurapolaris/tools/host-resolve.mjs --list   # 候选实例 + 选中理由(技能包内真实现)')
    console.log('  非写不可的例外: 加进 tools/single-source.mjs 的 HOSTPATH_WHITELIST 并逐条写明理由(理由太短/冗余都判红)')
  }
  console.log(report.ok
    ? '单源门禁 PASS: 每个事实只有一份实现(未收敛项逐条白名单放行);宿主路径无 hash 目录硬编码'
    : `单源门禁 FAIL: 有第二处实现 / 登记与实测不符 / 未列进白名单的 known-dup${report.unlisted.length ? `(${report.unlisted.join(',')})` : ''}${dead.length ? ` / 白名单冗余(${dead.join(',')})` : ''}${hp.unexempt.length ? ` / HOST-1 宿主路径硬编码(${hp.unexempt.map((h) => `${h.file}:${h.line}`).join(',')})` : ''}${hp.problems.length ? ` / HOST-1 白名单问题(${hp.problems.length} 条)` : ''}`)
}

// 沙箱自证:往副本里复制一份 owner 实现 → 门禁必须红并点名它;删掉 → 必须回绿(反例红 + 撤销再绿)。
function selftest() {
  const tmpBox = mkbox('polaris-single-source-')
  const tmp = tmpBox.dir
  const reg = readJson(path.join(ROOT, REGISTRY_REL))
  const copy = (rel) => {
    fs.mkdirSync(path.dirname(path.join(tmp, rel)), { recursive: true })
    fs.copyFileSync(path.join(ROOT, rel), path.join(tmp, rel))
  }
  copy(REGISTRY_REL)
  // 副本必须自带临时箱实现:副本里的 single-source.mjs 会 import 它;漏了这条副本就跑不起来 → 自证假红。
  // 同理必须带上 host-resolve.mjs:副本里的 HOST-1 要 import 它的 HASH_DIR_RE_SRC(arch-v2.C63)。
  for (const rel of [...inScopeFiles(ROOT, reg.scan ?? {}), 'tools/single-source.mjs', 'skills/aurapolaris/tools/tmpbox.mjs', 'skills/aurapolaris/tools/host-resolve.mjs']) copy(rel)
  // 【副本必须钉住自己的根: POLARIS_ROOT 只在这一次 spawn 里被改成盒子】(arch-v2.C95 ①)
  //   实测代价(2026-10-06):本函数把整棵在册树复制进盒子,再在盒子里跑 5 次 --check —— 但 `run()` 没给
  //   子进程钉根,而副本里 `ROOT = process.env.POLARIS_ROOT ?? path.join(HERE, '..')`(本文件第 37 行)。
  //   独立跑时 POLARIS_ROOT 没设 ⇒ 副本读的是盒子 ⇒ 8/8;一进 `test-layers.mjs --layer=<层>`,
  //   runPlane 会传 `env: { ...process.env, POLARIS_ROOT: root }` ⇒ 副本里每一次 --check 读的都是【真树】,
  //   盒子那份 fixture 一个字节都没被读。对照读数(同一个盒子、同一条命令、只改这一个环境变量):
  //     POLARIS_ROOT=<盒子> → 扫描 3 文件 / FAIL(owner 文件不存在: skills/aurapolaris/tools/visibility.mjs) / exit 12
  //     POLARIS_ROOT=<真树> → 扫描 147 文件 / PASS / exit 0        ← 盒子没被读,泄漏成立
  //   后果不是"副本脏了",而是【自证在对现场下断言】:现场被兄弟面改写(实测同刻另一张单在反复重写
  //   skills/aurapolaris/tools/agent-graph.view.selftest.mjs,185674→186441→186807 字节)时,5 次读跨 ~4s
  //   落在现场不同状态上 ⇒ 同一批"必须绿"的用例读数不一致 ⇒ 层内 6/8(红的两例正是读到脏现场的那两跑)。
  //   口径:自证的每一次判定都必须落在【同一个时刻的同一个副本】上 —— 根由本函数钉死,不再随调用环境漂。
  const run = () => {
    const r = spawnSync(process.execPath, [path.join(tmp, 'tools/single-source.mjs'), '--check'],
      { encoding: 'utf8', maxBuffer: 8 << 20, env: { ...process.env, POLARIS_ROOT: tmp } })
    return { code: r.status ?? 1, out: `${r.stdout ?? ''}${r.stderr ?? ''}` }
  }
  const results = []
  const before = run()
  results.push(['副本原样 --check 必须绿', before.code === 0, `exit=${before.code}`])
  const fact = (reg.facts ?? []).find((f) => f.status === 'single')
  // 夹具的素材也取自【盒子里那份快照】,不回读真树: 同一份自证里两次读现场 = 两个时刻两种状态。
  const ownerLines = fs.readFileSync(path.join(tmp, fact.owner.split('#')[0]), 'utf8').split(/\r?\n/)
  const picked = ownerLines.filter((l) => (fact.dupPatterns ?? []).some((p) => new RegExp(p).test(l)))
  const plantedRel = 'tools/__selftest-second-impl.mjs'
  fs.writeFileSync(path.join(tmp, plantedRel), `// 自证用:把 ${fact.owner} 的实现原样复制一份\n${picked.join('\n')}\n`)
  const red = run()
  results.push(['复制 owner 实现后必须红并点名', red.code === 12 && red.out.includes(plantedRel) && red.out.includes(fact.id), `exit=${red.code} 点名=${red.out.includes(plantedRel)}/${fact.id}`])
  fs.unlinkSync(path.join(tmp, plantedRel))
  const after = run()
  results.push(['删掉副本后必须回绿', after.code === 0, `exit=${after.code}`])

  // ---- HOST-1(arch-v2.C63):宿主可执行路径的 hash 目录形态 → 先红、撤销再绿、白名单也要被审 ----
  // 夹具文本按【真形态】拼出来:写死一个假 hash 目录 + exe 名(不指向任何真实路径,只是文本)。
  const fixtureRel = 'tools/__selftest-hostpath.mjs'
  const fakeHex = 'd23520d1e41bfb24'
  const fixtureText = '// 自证用夹具:下面这行就是"把宿主可执行路径写死"的形态\n'
    + 'export const BAD = ' + JSON.stringify('C:\\Users\\someone\\AppData\\Local\\OpenAI\\Codex\\bin\\' + fakeHex + '\\codex.exe') + '\n'
  fs.writeFileSync(path.join(tmp, fixtureRel), fixtureText)
  const hostRed = run()
  results.push(['HOST-1 红相:夹具文本写死 hash 目录路径 → 必须判红并点名 file:line',
    hostRed.code === 12 && hostRed.out.includes(fixtureRel) && /HOST-1/.test(hostRed.out), `exit=${hostRed.code} 点名=${hostRed.out.includes(fixtureRel)}`])
  fs.unlinkSync(path.join(tmp, fixtureRel))
  const hostGreen = run()
  results.push(['HOST-1 绿相:移除夹具后必须回绿', hostGreen.code === 0, `exit=${hostGreen.code}`])

  // 反档:白名单机制不许被静默绕过 —— 在副本里往 HOSTPATH_WHITELIST 塞一条【理由太短】的条目,门禁必须红。
  const toolRel = 'tools/single-source.mjs'
  const toolPath = path.join(tmp, toolRel)
  const pristine = fs.readFileSync(toolPath, 'utf8')
  const anchorLine = "  // { file: '相对路径', why: '为什么这里非写 hash 路径不可(不少于 8 字)' },"
  results.push(['反档前提:副本里能定位白名单锚点(定位不到=夹具失效,不许静默跳过)', pristine.includes(anchorLine), `anchor=${pristine.includes(anchorLine)}`])
  if (pristine.includes(anchorLine)) {
