const SCAN_REGISTRY_REL = 'tools/single-source.json'
function scanFaceOf(root = ROOT) {
  const reg = readJsonOrNull(path.join(root, SCAN_REGISTRY_REL))
  const scan = reg?.scan
  if (!isPlainObject(scan)) return { ok: false, why: `${SCAN_REGISTRY_REL} 读不出或没有 scan 段` }
  const skip = Array.isArray(scan.skipDirs) ? scan.skipDirs : []
  const skipFile = (Array.isArray(scan.skipFilePatterns) ? scan.skipFilePatterns : []).map((p) => new RegExp(p))
  const exts = new Set(Array.isArray(scan.extensions) ? scan.extensions : [])
  const out = []
  const walk = (d) => {
    let entries = []
    try { entries = fs.readdirSync(d, { withFileTypes: true }) } catch { return }
    for (const e of entries) {
      const abs = path.join(d, e.name)
      const rel = path.relative(root, abs).split(path.sep).join('/')
      if (skip.some((s) => rel === s || rel.startsWith(s + '/'))) continue
      if (e.isDirectory()) { walk(abs); continue }
      if (!exts.has(path.extname(e.name)) || skipFile.some((r) => r.test(rel))) continue
      out.push(rel)
    }
  }
  walk(root)
  return { ok: true, files: out }
}
