// ---- 版本 +1 的连锁锚点(2026-09-29 arch-v2.C62)----
// 是哪一类缺陷:内核版本的单源是 skills/aurapolaris/kernel/index.json#version,但版本 +1 会牵动【九处】文档锚点
//   (INSTALL.md 四处:两条 [fact] + 两条表格行;RELEASE.md 两处:标题 + [fact];HANDOVER.md 两处:[fact] + 速览行;
//   DEPLOY.md 一处:实测读数)。此前全靠人记 —— 第一轮漏 INSTALL.md 三处、第二轮漏 RELEASE/HANDOVER/DEPLOY 五处,
//   两次都靠 doc-facts 抓到两条、再靠人工 grep 补齐其余。根因不是粗心,是【漏了不必然红】:九处里 DEPLOY.md
//   不在 tools/doc-facts.mjs#DEFAULT_DOCS 的扫描面内(那是白名单),漏改它静默过期、没有机械判据兜底。
// 锚点声明【不许散成脚本里的裸字符串】:唯一来源 = skills/aurapolaris/tools/bump-anchors.json。
//   每条 = 文件 + 定位片段({version}=改动前内核版本) + 替换模板({target}=新版本) + 期望命中次数 + 是否被 doc-facts 覆盖。
//   本段只【消费】那张表 —— 表里加一处锚点,这里的代码一行都不用动。
// fail-closed:任一处【命中数 ≠ 声明值】即报错并列出行号,且在【写任何文件之前】离场(一个文件都不许改)。
//   0 次 = 该处已被改成别的值(上一轮漏改或被手改);>1 次 = 定位片段不唯一,替换会误伤别处。两种都不许猜、不许静默跳过。
const BUMP_REL = path.join('skills', 'aurapolaris', 'tools', 'bump-anchors.json')
const BUMP_USAGE = 'node cli/polaris.mjs bump <x.y.z> [--dry-run]'
const BUMP_SELF = fileURLToPath(import.meta.url)
// 命中行号(1-based)。needle 为空串时短路 —— 否则 indexOf('') 恒为 0、循环不前进(死循环)。
function bumpHitLines(text, needle) {
  const out = []
  if (!needle) return out
  let i = text.indexOf(needle)
  while (i >= 0) { out.push(text.slice(0, i).split('\n').length); i = text.indexOf(needle, i + needle.length) }
  return out
}
const bumpFill = (tpl, cur, target) => String(tpl).split('{version}').join(cur).split('{target}').join(target)
function bumpDeclBad(id, m) { console.error(`锚点声明有问题(${id}): ${m}\n  声明文件 = ${BUMP_REL};${BUMP_USAGE}`); process.exit(1) }
function bumpDecl() {
  const p = path.join(ROOT, BUMP_REL)
  if (!fs.existsSync(p)) { console.error(`锚点声明不存在: ${BUMP_REL}\n  版本 +1 的落点必须【单源声明】,不许写死在脚本里;${BUMP_USAGE}`); process.exit(1) }
  let d
  try { d = JSON.parse(fs.readFileSync(p, 'utf8')) } catch (e) { console.error(`锚点声明不是合法 JSON: ${BUMP_REL} —— ${e.message}`); process.exit(1) }
  const vs = d && d.version_source
  if (!vs || typeof vs.file !== 'string' || typeof vs.pointer !== 'string' || typeof vs.locator !== 'string' || typeof vs.replace !== 'string') { console.error(`锚点声明缺 version_source 的 file/pointer/locator/replace: ${BUMP_REL}`); process.exit(1) }
  if (!Array.isArray(d.anchors) || !d.anchors.length) { console.error(`锚点声明 anchors 为空: ${BUMP_REL}(空表 = 静默什么都不改,按 fail-closed 拒跑)`); process.exit(1) }
  return d
}
function bumpPtr(obj, ptr) {
  let cur = obj
  for (const seg of String(ptr).split('/')) { if (!seg) continue; if (!cur || typeof cur !== 'object') return undefined; cur = cur[seg] }
  return cur
}
// 一条锚点的计划(纯函数,不写盘):命中行号、命中数是否等于声明值、替换后的全文。
//   text 由调用方给 —— 同一文件的多条锚点按声明顺序【串行】,后一条看到的是前一条改过的文本。
function bumpAnchorPlan(a, cur, target, text) {
  const id = a && a.id ? a.id : '(缺 id)'
  if (!a || typeof a.file !== 'string' || typeof a.locator !== 'string' || typeof a.replace !== 'string') bumpDeclBad(id, '每条必须有 file / locator / replace')
  if (!Number.isInteger(a.expect_hits) || a.expect_hits < 1) bumpDeclBad(id, 'expect_hits 必须是不小于 1 的整数(留空 = 不判,等于把断言关掉)')
  if (!a.locator.includes('{version}')) bumpDeclBad(id, 'locator 必须含 {version} —— 不含就锚不住"改动前版本",也就抓不到被改成旧值的那一处')
  if (a.locator.includes('{target}')) bumpDeclBad(id, 'locator 里不许出现 {target}(它是替换模板的占位符)')
  const needle = bumpFill(a.locator, cur, target)
  const replacement = bumpFill(a.replace, cur, target)
  if (needle === replacement) bumpDeclBad(id, 'locator 与 replace 填完是同一个值(这条锚点不改任何东西)')
  const lines = bumpHitLines(text, needle)
  // 0 次时给一条人可行动的线索:定位片段里【{version} 之前那半截】现在出现在哪几行。
  const head = a.locator.slice(0, a.locator.indexOf('{version}'))
  const near = lines.length || head.trim().length < 4 ? [] : bumpHitLines(text, head).slice(0, 5).map((n) => ({ n, t: text.split('\n')[n - 1].trim().slice(0, 110) }))
  return { id, file: a.file, doc_facts: a.doc_facts ?? '(未声明)', needle, replacement, lines, expect: a.expect_hits, ok: lines.length === a.expect_hits, near, newText: text.split(needle).join(replacement) }
}
// 整份计划:版本单源排第一(它也是一条锚点,同样受命中数断言约束),其余按声明顺序串行。
function bumpPlan(target) {
  const decl = bumpDecl()
  const specs = [Object.assign({ id: 'version_source', doc_facts: 'covered', expect_hits: 1 }, decl.version_source), ...decl.anchors]
  const vAbs = path.join(ROOT, ...decl.version_source.file.split('/'))
  if (!fs.existsSync(vAbs)) { console.error(`版本单源不存在: ${decl.version_source.file}`); process.exit(1) }
  let vObj
  try { vObj = JSON.parse(fs.readFileSync(vAbs, 'utf8')) } catch (e) { console.error(`版本单源不是合法 JSON: ${decl.version_source.file} —— ${e.message}`); process.exit(1) }
  const cur = bumpPtr(vObj, decl.version_source.pointer)
  if (typeof cur !== 'string' || !cur) { console.error(`版本单源取不到字符串版本: ${decl.version_source.file}${decl.version_source.pointer}`); process.exit(1) }
  if (cur === target) { console.error(`用法错误: 目标版本 ${target} 与当前内核版本相同(没有可 +1 的东西);${BUMP_USAGE}`); process.exit(1) }
  const texts = new Map()
  const read = (rel) => {
    if (!texts.has(rel)) {
      const abs = path.join(ROOT, ...rel.split('/'))
      if (!fs.existsSync(abs)) bumpDeclBad('(文件)', `声明点名的文件不存在: ${rel}`)
      texts.set(rel, fs.readFileSync(abs, 'utf8'))
    }
    return texts.get(rel)
  }
  const entries = []
  for (const a of specs) {
    const e = bumpAnchorPlan(a, cur, target, read(a.file))
    entries.push(e)
    if (e.ok) texts.set(e.file, e.newText)
  }
  return { cur, target, entries, bad: entries.filter((e) => !e.ok), texts, changed: [...new Set(entries.filter((e) => e.ok).map((e) => e.file))] }
}
// 串跑一档:输出捕获下来(要解析 doc-facts 的红线),尾部转贴给用户。超时仍走 run-sync 的唯一实现。
function bumpRun(label, scriptRel, args) {
  const script = scriptRel === null ? BUMP_SELF : path.join(ROOT, ...scriptRel.split('/'))
  const r = runSync(process.execPath, [script, ...args], { cwd: ROOT, stdio: ['ignore', 'pipe', 'pipe'], encoding: 'utf8', env: { ...process.env, POLARIS_ROOT: ROOT }, timeoutMs: DEFAULT_TIMEOUT_MS })
  const status = r.status ?? 1
  const out = `${r.stdout ?? ''}${r.stderr ?? ''}`
  console.log(`  ${status === 0 ? 'PASS' : 'FAIL'} ${label}  exit=${status}`)
  for (const l of out.split(/\r?\n/).filter((x) => x.trim()).slice(-6)) console.log(`      ${l}`)
  return { label, status, out }
}
// ---- 收口判据:doc-facts 红线【相对基线增量 0】(2026-09-29 arch-v2.C74)----
// 为什么改:C62 交的闸写成「doc-facts 非 DESIGN.md 红线 = 0」——【绝对 0】。本树存量非 DESIGN 红线 15 条
//   (C74 开工实测:CONS-17 名单内嵌 / audit 棘轮 / injection-matrix / doctor / INSTALL.md 产物数 310 …,
//   全是别人的账),bump 自己的增量 0 ⇒ 真跑必然停在【别人的红】上,判据不可达(与 C61 那次同类)。
//   现在:写盘【前】取一次读数、跑完再取一次,增量必须为 0 —— 判据从「全世界一条红都不许有」收紧成
//   「本命令引入的红 0 条」(前者不是本命令能保证、也不该由它保证的事:存量债是别人的账)。
// 指纹 = `文件:行|类型|期望`,取【声明面】:类型 = 该红的档位(fact / 未绑定(<类>) / 绑定未覆盖计数 /
//   JSON 数值绑定* / 排除面过期 …),期望 = 绑定自己写下的 expect 文本(计数守卫取被守卫的那个数字)。
// 刻意【不取观察面】(复跑命令的 exit 码与输出尾部):本命令的链上本就要重跑生成器(kernel-pack /
//   build-plugin / cli build),观察面必然移动 —— 实测同一条 fact 红线(INSTALL.md:9,expect="310 个产物")





















































function bumpSayBase(base) {
  const design = base.reds.filter((r) => bumpIsDesign(r.at)).length
  console.log(`  基线 ${base.reds.length} 条存量红（不计入判定）:DESIGN.md ${design} 条 / 其余 ${base.reds.length - design} 条;判据 = 跑前跑后两次读数的【增量 0】(新增红或红因变化即停,存量债不背在本命令账上)`)
}
function cmdBump() {
  const target = argv.slice(1).find((a) => !a.startsWith('--')) ?? null
  const dry = flag('dry-run')
  if (!target) { console.error(`用法: ${BUMP_USAGE}`); process.exit(1) }
  if (!/^\d+\.\d+\.\d+$/.test(target)) { console.error(`用法错误: 版本号必须形如 x.y.z(实得 ${JSON.stringify(target)});${BUMP_USAGE}`); process.exit(1) }
