        : `      该处现在长什么样(0 次 = 已被改成别的值,或声明本身过期): ${e.near.length ? e.near.map((x) => `${x.n}: ${x.t}`).join(' | ') : '连片段头都找不到'}`)
    }
    console.error(`  先修文件或修声明,再重跑 —— 不许猜、不许静默跳过。${BUMP_USAGE}`)
    process.exit(12)
  }
  const uncovered = plan.entries.filter((e) => e.doc_facts !== 'covered')
  console.log(`\n${dry ? '干跑(不写盘)' : '真跑'}:内核版本 ${plan.cur} → ${plan.target};锚点 ${plan.entries.length - 1} 处 + 版本单源 1 处,逐处命中恰好 1 次`)
  for (const e of plan.entries) console.log(`  将改 ${e.file}:${e.lines.join(', ')}   [命中 ${e.lines.length}/${e.expect} · doc-facts ${e.doc_facts}]   ${e.id}`)
