  bumpSayBase(base)
  if (dry) {
    // 第 5 档也走干跑(arch-v2.C129):登记入口自带 --dry-run,干跑时把它真跑一遍(--register --dry-run,
    //   零写入)并把预报打在下面 —— 干跑因此【看得见链条多了一档】,而不是只听到一句承诺。
    bumpRun('evolve --register --dry-run', 'tools/evolve.mjs', ['--register', '--dry-run'])
    console.log('  干跑结束:未写任何文件。真跑还会串跑 kernel-pack → build-plugin → cli build → doc-facts --check(生成器在前、build 在后 —— 它要哈希生成物),判据 = 相对上面这条基线的【增量 0】,任一红即停并打印逐文件回滚命令。')
    console.log('  干跑预报第 5 档:真跑还会串跑 evolve --register —— 把本命令改过的内核字节按 EVO-1 链语义补登候选行、并把前驱的 superseded_by 指过来(链语义只有一份实现,在 tools/evolve.mjs 里;本命令只调用,不算 sha、不判链尾)。')
    process.exit(0)
  }
  for (const [rel, text] of plan.texts) fs.writeFileSync(path.join(ROOT, ...rel.split('/')), text)
  console.log(`\n已写 ${plan.changed.length} 个文件;开始串跑:`)
  // 顺序有讲究,不是随手排的:cli build 把 PACK_ROOTS 里每个文件的哈希写进 desired_state.json ——
  //   两个生成器(kernel-pack 重建 kernel/{hot,cold,warm}.json、build-plugin 重建 plugins/**)必须排在它【之前】。
  //   本单沙箱实测代价:按"build → kernel-pack → build-plugin → doc-facts"的字面顺序跑,cold.json 重建后哈希变了,
  //   build --check 当场 12(「已过期: skills/aurapolaris/kernel/cold.json」),而 build --check 又是 doc-facts 的
  //   一条绑定(INSTALL.md 的 [fact] expect="spec …")—— 链上凭空多两条红,且那两条与本命令要保证的事无关。
  const steps = [
    bumpRun('kernel-pack', 'tools/kernel-pack.mjs', []),
    bumpRun('build-plugin', 'tools/build-plugin.mjs', []),
    bumpRun('cli build', null, ['build']),
    bumpRun('doc-facts --check', BUMP_DF_SCRIPT, BUMP_DF_ARGS),
  ]
  const reds = []
  for (const s of steps.slice(0, 3)) if (s.status !== 0) reds.push(`${s.label} exit=${s.status}`)
  const df = steps[3]
  // 收口判据 = 【相对上面那条基线的增量 0】(C74):存量红(别人的账)不判本命令的红,新出现的指纹才判。
  const now = { status: df.status, reds: bumpReds(df.out) }
  const delta = bumpRedDelta(base.reds, now.reds)
  console.log(`  doc-facts 红线:基线 ${base.reds.length} 条 → 结果 ${now.reds.length} 条,增量 ${delta.added.length} 条(判据 = 增量 0)`)
  if (delta.moved) console.log(`    观察面移动 ${delta.moved} 条(同位置同声明面,只有复跑命令的 exit/输出尾部变了 —— 链上本就重跑生成器,不计入判定)`)
  if (delta.gone.length) console.log(`    消失 ${delta.gone.length} 条存量红(不计入判定,前 5 条):${delta.gone.slice(0, 5).map((r) => r.key).join(' | ')}`)
  if (delta.added.length) {
    console.error(`  新增红/红因变化 ${delta.added.length} 条 —— 逐条点名(存量基线里没有这些指纹):`)
    for (const r of delta.added.slice(0, 20)) console.error(`      ✗ ${r.key}   ${r.why.slice(0, 160)}`)
  }
  if (df.status !== 0 && df.status !== 12) reds.push(`doc-facts --check 异常退出 exit=${df.status}`)
  else if (delta.added.length) reds.push(`doc-facts 相对基线新增红/红因变化 ${delta.added.length} 条`)
  // 第 5 档(arch-v2.C129):登记内核演化的候选行。为什么排在四档之后:前三档会改内核字节(kernel-pack /
  //   build-plugin 重建 kernel/*.json),而 doc-facts 判的是「相对基线增量 0」;登记只写台账 state/rounds/R9/
  //   candidates.jsonl,不碰生成物 —— 排最后既不扰动前四档的读数,又保证「本命令改过的字节一定被登记」。
  //   链语义(前驱/superseded_by/after_sha256)只有一份实现,在 tools/evolve.mjs 的 --register 里;这里只调用。
  const reg = bumpRun('evolve --register', 'tools/evolve.mjs', ['--register'])
  if (reg.status !== 0) reds.push(`evolve --register exit=${reg.status}`)
  if (reds.length) {
    console.error(`\n★ 链上有红 —— 已停:${reds.join('; ')}`)
    console.error('  内核版本与锚点【已写入】(本命令不自动回滚);逐文件回滚命令(回到改动前):')
    // 诚实边界(本单沙箱实测):git checkout 回到的是【索引/HEAD】的版本,不是本命令改动前的工作区版本 ——
    //   实测 skills/aurapolaris/kernel/index.json 在本命令之前就有未提交改动,checkout 后拿到的是索引里的旧版
    //   (6ab135d83fc9a650),而不是改动前的 b7b810d2e666de13;四份文档逐字复原成功。根治=落盘前自存底片
    //   (要写本单写面外的备份件),留父线程另派 —— 这里只把边界说出来,不假装它一定能复原。
    console.error('  注意:`git checkout --` 回到的是【索引/HEAD】的版本,不是本命令改动前的工作区版本;若这些文件在改动前就有未提交改动,它会多回退。')
    for (const f of plan.changed) console.error(`    git checkout -- ${f}`)
    process.exit(12)
  }
  console.log(`\nBUMP PASS: 内核版本 ${plan.cur} → ${plan.target};改 ${plan.changed.length} 个文件;串跑${steps.length + 1}档全绿(doc-facts 红线【相对基线增量 0】:基线 ${base.reds.length} → 结果 ${now.reds.length})。`)
  process.exit(0)
}
