// ---- 参数(<root> 与开关可任意次序;未知开关当场拒,不让它被当成目录名) ----
//   本文件【本来就有】未知参数守卫(KNOWN_FLAGS + 下面 badFlags);2026-09-29 arch-v2.C42 只补缺的那一个档:
//   --help/-h 打用法 + exit 0,且【不执行默认动作、不写盘】(此前 --help 被当成未知参数 exit 1 —— 不危险但也不达意)。
//   补法是最小 diff:只往 KNOWN_FLAGS 加两个名字 + 在 badFlags 之前插一段 help 短路;既有档行为与输出一字未动。
const ARGV = process.argv.slice(2)
const KNOWN_FLAGS = ['--check', '--allow-dirty', '--selftest', '--honesty-selftest', '--help', '-h']
if (ARGV.includes('--help') || ARGV.includes('-h')) { console.log(USAGE); process.exit(0) }
const badFlags = ARGV.filter((a) => a.startsWith('--') && !KNOWN_FLAGS.includes(a))
if (badFlags.length) {
  console.error(`未知参数: ${badFlags.join(' ')}`)
  console.error(USAGE)
  process.exit(1)
}
const CHECK_ONLY = ARGV.includes('--check')
const ALLOW_DIRTY = ARGV.includes('--allow-dirty')
const SELFTEST_ONLY = ARGV.includes('--selftest')
// 版本号诚实闸(arch-v2.C125)的夹具自证入口:与 --selftest 同款,单独一档 —— 它【自持夹具】
//   (git init 一个新仓,不克隆、不依赖外层根是不是 git 工作区),所以能不能跑不取决于本树形状。
const HONESTY_ONLY = ARGV.includes('--honesty-selftest')
if (HONESTY_ONLY && (CHECK_ONLY || ALLOW_DIRTY || SELFTEST_ONLY)) {
  console.error('--honesty-selftest 不能与 --check / --allow-dirty / --selftest 同用(它自带夹具与用例)')
  console.error(USAGE)
  process.exit(1)
}
if (SELFTEST_ONLY && (CHECK_ONLY || ALLOW_DIRTY)) {
  console.error('--selftest 不能与 --check / --allow-dirty 同用(自证器自带这三条用例)')
  console.error(USAGE)
  process.exit(1)
}
const ROOT = path.resolve(ARGV.find((a) => !a.startsWith('--')) ?? '.')
const OUT = path.join(ROOT, 'dist')
// 自证器要把"本次运行的这个工具"装进夹具:夹具里那份是 HEAD 的旧版本,拿它自证等于没证
const SELF = (() => {
  const a = process.argv[1]
  return a && !a.startsWith('-') && fs.existsSync(a) ? path.resolve(a) : path.join(ROOT, 'tools/package.mjs')
})()
// 自证沙箱根(AGENTS.md §0.5):临时件只落 <tmp root>/ 下的自己那一层,收工只删自己造的叶子目录
const TMP_ROOT = process.env.POLARIS_TMP_ROOT || (process.platform === 'win32' ? 'E:\\AuraPolaris-tmp' : path.join(os.tmpdir(), 'aurapolaris-tmp'))
const SELFTEST_BASE = process.env.POLARIS_PKG_SELFTEST_ROOT || path.join(TMP_ROOT, 'package-selftest')
let sandboxDir = null

// ---- 打包域【单一定义】= tools/pack-domain.mjs(§0.4 单源) ----
//   域根清单 / zip 内前缀 / 根内例外 / 排除规则(.removed-* 隔离目录、*.bak*、*.log、*.tmp*)全在那一个文件里;
//   本文件的脏树判定、--check 计数与 collect() 都只 import 它,不再自留第二份域清单。
//   口径 = "这个相对路径会不会落进 zip":被排除规则命中的路径既不打进包、也不算脏。
const codeLabel = (c) => (c === '??' ? '未跟踪' : c === '!!' ? '被忽略' : c.includes('D') ? '已删除' : c.includes('A') ? '已暂存新增' : c.includes('U') ? '冲突未解' : c.includes('T') ? '类型变化' : '已改动')

function git(args, cwd) {
  return spawnSync('git', args, { cwd, encoding: 'utf8', windowsHide: true, maxBuffer: 64 * 1024 * 1024 })
}


















































































//      最常见的场景里静默失效,而那正是它最该说话的场合;
//   ④ --allow-dirty(开发档)跳过本闸并明写一行;--selftest / --honesty-selftest 不走本闸。
// 【单源】打包域枚举只用 listPackDomainFiles(ROOT)(工作树侧清单),域判定只用 inPackDomain —— 本文件不自留
//   第二份域清单、也不自留第二份遍历。tag 那一侧的树只能由 git 枚举(git ls-tree -r <tag>):它给的是
//   「那个提交里的文件」,不是第二份域清单;逐条仍要过 inPackDomain 才算域内 ⇒「什么算打包域」仍然只有一处。
const VERSION_SRC = 'skills/aurapolaris/kernel/index.json'
const HONESTY_ID = 'VH-1'
function readPkgVersion(root) {
  try { return String(JSON.parse(fs.readFileSync(path.join(root, VERSION_SRC), 'utf8')).version) } catch { return null }
}
// 打包域指纹:只从 listPackDomainFiles 枚举出来的那一份清单现算(每条 = 相对路径 + 内容 sha256)
const domainFp = (rows) => sha256(rows.map((r) => `${r.rel}\u0000${r.oid}`).join('\n')).slice(0, 16)
// 工作树侧:域内文件清单【只来自 listPackDomainFiles】+ 逐文件内容 oid。
//   【为什么用 git 的内容 oid 而不是自己读字节算 sha256】本仓 core.autocrlf=true 且带 .gitattributes ⇒
//   同一个文件在「工作树字节」与「提交里的字节」之间本来就允许纯行尾差异(实测:夹具里 install.cmd 工作树
//   CRLF / blob LF)。客户拿到的字节由 checkout 规则决定,行尾不是版本号能改变的东西 ⇒ 拿原始字节比会把这类
//   差异报成「同一个版本号两份字节」(假红)。git 的 oid 是 filter-aware 的内容同一性,正好是「这份内容提交
//   之后是什么」的唯一定义;真的改行尾并提交,oid 照旧变(照旧判得出)。
//   一次 hash-object --stdin-paths 拿全部(不逐文件起进程);它是 filter-aware(已实测与 --path= 同值)。
function worktreeDomain(root, top, relTop) {
  const files = listPackDomainFiles(root)
  if (!files.length) return []
  const paths = files.map((f) => (relTop ? `${relTop}/${f.rel}` : f.rel))
  const r = spawnSync('git', ['hash-object', '--stdin-paths'], { cwd: top, input: `${paths.join('\n')}\n`, encoding: 'utf8', maxBuffer: 64 * 1024 * 1024, windowsHide: true })
  if (r.error || r.status !== 0) return null
  const oids = String(r.stdout ?? '').split('\n').map((s) => s.trim()).filter(Boolean)
  return oids.length === files.length ? files.map((f, i) => ({ rel: f.rel, oid: oids[i] })) : null
}
// tag 侧的同一份域:ls-tree 枚举该提交的树 → 只留域内 blob → cat-file --batch 取字节算 sha256
//   为什么逐文件取字节而不比 git 的 blob oid:要证的是【逐字节可复现】。oid 会随行尾过滤/属性规则变形状,
//   比字节就没有这个口径空间(两边用同一个 sha256)。
function tagDomain(top, tag, relTop) {
  const ls = git(['ls-tree', '-r', '-z', tag], top)
  if (ls.error || ls.status !== 0) return null
  const rows = []
  for (const rec of String(ls.stdout ?? '').split('\u0000')) {
    const m = rec.match(/^\d+ blob ([0-9a-f]+)\t(.+)$/)
    if (!m) continue
    const p = toPosix(m[2])
    const rel = relTop ? (p.startsWith(`${relTop}/`) ? p.slice(relTop.length + 1) : null) : p
    if (rel === null || !inPackDomain(rel)) continue
    rows.push({ rel, oid: m[1] })   // 按 rel 收:内容相同的两个文件 oid 相同(插件目录里成片是技能目录的副本),按 oid 收会丢条
  }
  return rows
}
// 本闸的全部判定:工作树打包域 ⇔ tag v<version> 的那一份域
function honestyVerdict(root) {
  const ver = readPkgVersion(root)
  const n = listPackDomainFiles(root).length
  if (!ver) return { kind: 'no-version', ver: null, tag: null, count: n, diffs: [], why: `读不到版本单源 ${VERSION_SRC} 的 version` }
  const tag = `v${ver}`
  const top = repoTop(root)
  if (!top) return { kind: 'no-git', ver, tag, count: n, diffs: [], why: `${root} 不是 git 工作区(或本机没有 git) —— 本闸靠 git 找 tag,判定不了` }
  const relTop = toPosix(path.relative(top, root))
  const wt = worktreeDomain(root, top, relTop)
  if (wt === null) return { kind: 'no-git', ver, tag, count: n, diffs: [], why: 'git hash-object 读工作树内容失败(干净与否判不了)' }
  const base = { ver, tag, wt, count: wt.length, fp: domainFp(wt), diffs: [] }
  const has = git(['rev-parse', '--verify', '--quiet', `refs/tags/${base.tag}^{commit}`], top)
  if (has.error || has.status !== 0) return { ...base, kind: 'no-tag', why: `本仓库里查不到 tag ${base.tag}` }
  const tg = tagDomain(top, base.tag, relTop)
  if (tg === null) return { ...base, kind: 'no-git', why: `git ls-tree 读 tag ${base.tag} 的那一份域失败` }
  const tmap = new Map(tg.map((r) => [r.rel, r.oid]))
  const wmap = new Map(wt.map((r) => [r.rel, r.oid]))
  const diffs = []
  for (const r of wt) if (tmap.get(r.rel) !== r.oid) diffs.push({ rel: r.rel, how: tmap.has(r.rel) ? '内容不同' : `tag ${base.tag} 里没有这个文件` })
  for (const r of tg) if (!wmap.has(r.rel)) diffs.push({ rel: r.rel, how: '工作树里没有这个文件(tag 里有)' })
  diffs.sort((a, b) => (a.rel < b.rel ? -1 : a.rel > b.rel ? 1 : 0))
  return { ...base, tg, diffs, tagFp: domainFp(tg), kind: diffs.length ? 'mismatch' : 'ok' }
}
// 拒的读数:读到的要能自证(命令/退出码/读数),两条修法要能整条抄走
function honestyReject(v, head) {
  const L = []
  if (v.kind === 'no-version') {
    L.push(`${head}:版本号诚实闸(${HONESTY_ID})判不了 —— ${v.why}`)
    L.push('  修法: 把版本单源恢复成合法 JSON(它就是 version 的唯一来源)后重跑')
    return L
  }
  if (v.kind === 'no-git') {
    L.push(`${head}:版本号诚实闸(${HONESTY_ID})判不了 —— ${v.why}`)
    L.push('  修法: 在 git 工作区里打包(本闸靠 git 找 tag 与那一份字节);确属开发用途可加 --allow-dirty')
    return L
  }
  if (v.kind === 'no-tag') {
    L.push(`${head}:版本号诚实闸(${HONESTY_ID})—— 尚无 tag ${v.tag}`)
    L.push(`  版本单源 ${VERSION_SRC} 的 version = ${v.ver};目标 tag 名 = ${v.tag};本仓库里查不到它(${v.why})`)
    L.push('  为什么拒:本闸要的性质是「这份产物能从某个 tag 复现」;没有 tag 就没有可复现的锚点。')
    L.push('  把「没 tag」读成「首次出货、放行」,会让本闸恰好在『忘了打 tag』这个最常见的场景里静默失效 —— 那正是它最该说话的场合。')
    L.push('  怎么补: ① git add -A && git commit -m "<说明>"  ② git tag ' + v.tag + '  ③ 重新打包: node tools/package.mjs .')
    return L
  }
  const shown = v.diffs.slice(0, 12)
  L.push(`${head}:版本号诚实闸(${HONESTY_ID})—— 一个版本号只许对应一份字节`)
  L.push(`  tag ${v.tag} 与工作树打包域【不一致】: ${v.diffs.length} 个文件(域内 ${v.count} 个;tag 侧指纹 ${v.tagFp} / 工作树指纹 ${v.fp})`)
  for (const d of shown) L.push(`  [${d.how}] ${d.rel}`)
  if (v.diffs.length > shown.length) L.push(`  …还有 ${v.diffs.length - shown.length} 条未列出`)
  L.push(`  为什么拒:tag ${v.tag} 那一份字节与当前工作树不是同一份;同一个版本号能对应两份字节,客户手里的 SHA256SUMS 就成了一次性的。`)
  L.push('  修法①(这一版确实要出货): 先升版本 —— node cli/polaris.mjs bump <x.y.z>(它会串跑 kernel-pack → build-plugin → cli build → doc-facts),再打包')
  L.push(`  修法②(这些改动不该出货): 回滚到 tag 那一份 —— git checkout ${v.tag} -- ${v.diffs.map((d) => d.rel).join(' ')}`)
  return L
}
// 干净档必经的一道:放行打一行读数(域内文件数 + tag 名 + 打包域指纹),否则逐条报并 exit 12
function honestyGate(head) {
  const v = honestyVerdict(ROOT)
  const reject = v.kind !== 'ok'   // <-- 【唯一判定行】本闸的全部判定;变异成恒假 ⇒ 本闸失效(登记表里的破坏方式打的就是这一行)
  if (reject) {
    for (const l of honestyReject(v, head)) console.error(l)
    process.exit(EXIT_DIRTY)
  }
  console.log(`版本号诚实闸(${HONESTY_ID}):tag ${v.tag} 与打包域逐字节一致 → 放行(域内 ${v.count} 个文件,打包域指纹 ${v.fp})`)
}

// ---- 闸①:打包域是否干净(默认拒脏;--check 只判不打包) ----
const scan = scanPackedDirty(ROOT)
if (SELFTEST_ONLY) runSelftest()           // 自证器自带夹具与清场,不受本树状态影响
if (HONESTY_ONLY) runHonestySelftest()     // 版本号诚实闸的自持夹具自证(不依赖外层根是不是 git 工作区)
if (!scan.ok) {
  console.error(`${CHECK_ONLY ? '--check 判红' : '拒绝打包'}:${scan.reason}`)
  console.error('指引: 在 git 工作区里打包(本闸靠 git status 判定干净);确认是开发用途可加 --allow-dirty(产物带 DIRTY 标记)')
  process.exit(EXIT_DIRTY)
}
if (CHECK_ONLY) {























































































































































































































































































      return
    }
    fs.rmSync(target, { recursive: true, force: true })
  } catch (e) {
    console.error(`沙箱清理失败(需人工删): ${dir} — ${e.message}`)
  }
}

// ---- --selftest:沙箱自证(干净夹具→成功无标记 / 脏夹具→拒绝并点名 / 脏夹具+--allow-dirty→成功且带标记) ----
function runSelftest() {
  // 四条离开路径都要自清:正常返回 / 判红 process.exit(12) / 抛异常 / 被中断(信号)
  process.on('exit', cleanupSandbox)
  for (const sig of ['SIGINT', 'SIGTERM', 'SIGHUP', 'SIGBREAK']) {
    try { process.on(sig, () => { cleanupSandbox(); process.exit(130) }) } catch { /* 本平台不支持该信号 */ }
  }
  const res = []
  const rec = (name, ok, detail) => { res.push({ name, ok: !!ok }); console.log(`${ok ? 'GREEN' : 'RED  '} ${name} — ${detail}`) }
  const finish = () => {
    const red = res.filter((r) => !r.ok)
    console.log(`自证小结: ${res.length - red.length}/${res.length} 绿;夹具 ${sandboxDir} 在退出路径上自清`)
    if (red.length) {
      console.log(`红: ${red.map((r) => r.name).join(', ')}`)
      console.log('判定: 自证未过 —— 脏树用例必须真能把打包挡下来,判据才算有效')
      process.exit(EXIT_DIRTY)
    }
    console.log('判定: 三类夹具用例全绿 —— 干净出包(无标记) / 脏树拒绝并点名 / --allow-dirty 成功且带 DIRTY 标记')
    process.exit(0)
  }
  const top = repoTop(ROOT)
  if (!top) { console.error(`--selftest 需要 git 工作区(要克隆夹具):${ROOT} 不是 git 仓库`); process.exit(1) }
  sandboxDir = path.join(SELFTEST_BASE, `fixtures-${process.pid}`)
  fs.rmSync(sandboxDir, { recursive: true, force: true })
  fs.mkdirSync(sandboxDir, { recursive: true })
  console.log(`自证沙箱: ${sandboxDir}(POLARIS_TMP_ROOT / POLARIS_PKG_SELFTEST_ROOT 可改根;收工自清)`)
  const clean = path.join(sandboxDir, 'clean')
  const dirty = path.join(sandboxDir, 'dirty')
  const distOf = (d) => path.join(d, 'dist')
  const runIn = (dir, args) => spawnSync(process.execPath, args, { cwd: dir, encoding: 'utf8', env: { ...process.env, POLARIS_ROOT: dir }, maxBuffer: 256 * 1024 * 1024 })
  const oneLine = (r) => String(r.stdout ?? '').trim().split('\n').filter(Boolean)[0]?.slice(0, 90) ?? ''
  const out2 = (r) => `${r.stdout ?? ''}${r.stderr ?? ''}`
  // 夹具①干净:克隆 HEAD + 装入本次运行的工具 + 终态按夹具内容重算后提交(HEAD 的 desired_state 可能本就过期)
  const clone = git(['clone', '-q', '--depth', '1', pathToFileURL(top).href, clean], sandboxDir)
  if (clone.status !== 0) {
    rec('fixture-clone(克隆夹具)', false, `exit=${clone.status} ${String(clone.stderr ?? clone.error?.message ?? '').trim().split('\n')[0] ?? ''}`)
    return finish()
  }
  {
    fs.copyFileSync(SELF, path.join(clean, 'tools/package.mjs'))
    // 打包域模块也要装进夹具:夹具克隆的是 HEAD,而它是本次运行的 package.mjs 的 import
    fs.copyFileSync(path.join(path.dirname(SELF), 'pack-domain.mjs'), path.join(clean, 'tools/pack-domain.mjs'))
    const b = runIn(clean, ['cli/polaris.mjs', 'build'])
    git(['add', '-A'], clean)
    const cm = git(['-c', 'user.name=pkg-selftest', '-c', 'user.email=selftest@local', '-c', 'commit.gpgsign=false', 'commit', '-q', '-m', 'selftest fixture: normalize'], clean)
    const st = String(git(['status', '--porcelain', '-uall'], clean).stdout ?? '').trim()
    const cout = `${cm.stdout ?? ''}${cm.stderr ?? ''}`   // 状态②要靠 git 自己的话正面认,不能只看退出码(理由见下)
    // 归一提交是【达成这条腿判据的手段,不是判据本身】——判据 = 夹具干净 ∧ 终态一致,即下面 st === '' && bc.status === 0。
    //   commit 的读数做成三态可辨:`git commit` 在【没有东西可提交】时本来就以 exit 1 退出(git 原话:
    //   nothing to commit, working tree clean)—— 夹具克隆出来的内容与终态一致时这是正常结果,不是失败。
    //   三态:① exit 0 = 真的提交了;② 无事可提交(放行);③ 提交真失败 ⇒ 判红。
    //   【为什么状态②必须认 git 自己的话,不能只认「exit 1 ∧ 工作树干净」】本平台实测:commit 的【每一种失败】
    //   都被 git 归一成 exit 1(失败 hook / 非法配置 / 未知选项 各跑各得 1,退出码不区分),所以「只看退出码」的
    //   写法会把「提交真失败且事后工作树恰好干净」当成「无事可提交」放行 —— 恰好在它最该说话的时候静默。git 在
    //   无事可提交时会自己打出 nothing (to commit|added to commit),这是可正面核对的证据;③ 不去要求证伪那句话,
    //   否则非 git 的失败(命令根本起不来)会被误放行,而这条腿存在的意义就是「提交真失败要红」。
    //   ② 的 `st === ''` 仍然必需:commit 退 0 但树仍脏(`git add -A` 漏了东西、hook 又改了文件)⇒ 照红。
    const cst = cm.status === 0 ? 'real-commit'
      : (cm.status === 1 && st === '' && /nothing (to commit|added to commit)/i.test(cout)) ? 'nothing-to-commit(放行)' : 'failed(判红)'
    // 版本号诚实闸(arch-v2.C125):夹具必须【自己打】v<夹具版本> —— git clone --depth 1 不保证带得回 tag
    //   (本仓 v1.0.10 指的不是 HEAD),而下面九相里每一相打包/判 check 都要先过本闸。
    //   -f:克隆万一带回了同名 tag,也必须指向本夹具自己这个提交(否则旧那份字节会判成不一致)。
    const vFx = JSON.parse(fs.readFileSync(path.join(clean, 'skills/aurapolaris/kernel/index.json'), 'utf8')).version
    git(['tag', '-f', `v${vFx}`, 'HEAD'], clean)
    const bc = runIn(clean, ['cli/polaris.mjs', 'build', '--check'])
    // 判据 = 夹具干净(st === '')∧ 终态一致(bc.status === 0);b.status === 0 是前置(cli build 没跑成则后面无意义)。
    //   【不把 cm.status === 0 写进谓词】它就是状态②要放行的那个值(② 的 commit 退出码必然是 1);写上就等于要求
    //   「必须有东西可提交」才算过 —— 而「有没有东西可提交」不是这条腿的判据。状态③ 由 cst 的表达兜住:退出码非 0
    //   且认不出「无事可提交」那句话 ⇒ failed(判红),所以把 commit 写成能静默失败的样子不会漏。
    rec('fixture-clean(干净夹具:无未提交改动 + 终态一致)', b.status === 0 && st === '' && bc.status === 0 && cst !== 'failed(判红)',
      `build=${b.status} commit=${cm.status} git-status=${st === '' ? 'clean' : JSON.stringify(st).slice(0, 80)} build--check=${bc.status} 本次走=${cst}`)
  }
  fs.cpSync(clean, dirty, { recursive: true })   // 夹具②=同一夹具的副本,随后改成脏树
  const verF = JSON.parse(fs.readFileSync(path.join(clean, 'skills/aurapolaris/kernel/index.json'), 'utf8')).version
  const zips = [`aurapolaris-skill-${verF}.zip`, `aurapolaris-${verF}.zip`, `installers-${verF}.zip`]
  const dirtyFile = 'plugins/aurapolaris/README.md'   // 进完整包;且不在 desired_state 产物里 → 能拦它的只有脏检查本身
  rec('fixture-domain(选中的脏文件确实落在打包域内,判据非空转)', inPackDomain(dirtyFile), `${dirtyFile} inPackDomain=${inPackDomain(dirtyFile)}`)
  // ① 干净夹具:--check 判绿,且不写盘
  const r1 = runIn(clean, ['tools/package.mjs', '--check'])
  rec('check-clean(--check 干净夹具 → exit 0,不写盘)', r1.status === 0 && !fs.existsSync(distOf(clean)),
    `exit=${r1.status} dist=${fs.existsSync(distOf(clean)) ? '被创建(不该)' : '未创建'} 结论=${oneLine(r1)}`)











  fs.writeFileSync(path.join(dirty, extra), '// selftest: 未跟踪文件,落在打包域内\n')
  const r5 = runIn(dirty, ['tools/package.mjs', '--check'])
  const said5 = out2(r5).includes(extra)
  rec('check-dirty-untracked(未跟踪文件进打包域 → exit 12 且点名)', r5.status === EXIT_DIRTY && said5, `exit=${r5.status} 点名=${said5}`)
  // ⑥ 回归:干净夹具打过大包之后仍判绿(dist/ 不在打包域,不会把自己搞脏)
  const r7 = runIn(clean, ['tools/package.mjs', '--check'])
  rec('check-clean-after-pack(打完包后干净夹具仍 exit 0:dist/ 不算脏)', r7.status === 0, `exit=${r7.status}`)
  // ⑦ 版本号诚实闸(arch-v2.C125):三相都在【同一个真夹具】上跑 —— 夹具自持 tag ⇒ 放行;tag 之后又提交了一处
  //   域内改动 ⇒ 拒并点名;把夹具自持的 tag 删掉 ⇒ 拒且读数为「尚无 tag」。
  //   与 --honesty-selftest 同一份实现(唯一一处:honestyTagCases),不写第二份。
  for (const c of honestyTagCases(clean)) rec(c.name, c.ok, c.detail)
  finish()
}

// ---- 版本号诚实闸的夹具自证(arch-v2.C125) -----------------------------------------------------
// 【为什么单独一个入口】tools/judge-registry.mjs 的深档(--mutate)在【副本】里跑判据命令,而副本按 copy_skip
//   不含 .git ⇒ "克隆本仓当夹具"的 --selftest 在副本里跑不起来(exit 1「需要 git 工作区」),本闸就无法登记成
//   一条『破坏→红、复原→绿』可实证的判据。--honesty-selftest 为此【自持夹具】:把本根的打包域复制成一个新目录
//   + git init + 自己提交 + 自己打 v<版本> —— 不克隆、也不依赖外层根是不是 git 工作区。
// 【判据只有一份实现】三相都在 honestyTagCases 里:--selftest 拿克隆夹具里的那一个根,--honesty-selftest 拿这里
//   自造的根,两处断言同一件事(不写第二份判据、不写第二份打包域清单)。
function honestyTagCases(root) {
  const out = []
  const tool = path.join(root, 'tools/package.mjs')
  const run = (args) => spawnSync(process.execPath, [tool, root, ...args], { cwd: root, encoding: 'utf8', env: { ...process.env, POLARIS_ROOT: root }, maxBuffer: 64 * 1024 * 1024 })
  const txt = (r) => `${r.stdout ?? ''}${r.stderr ?? ''}`
  const firstLine = (r) => String(r.stdout ?? '').trim().split('\n').filter(Boolean)[0]?.slice(0, 100) ?? ''
  const ver = readPkgVersion(root)
  const tag = `v${ver}`
  const okLine = `版本号诚实闸(${HONESTY_ID}):tag ${tag} 与打包域逐字节一致 → 放行(域内 `
  // ① 夹具自持的 tag 与工作树逐字节一致 ⇒ 放行(exit 0 + 读数含 tag 名 / 域内文件数 / 指纹)
  const r1 = run(['--check'])
  const o1 = txt(r1)
  out.push({
    name: `${HONESTY_ID} tag-consistent(夹具自持 tag ${tag} 且逐字节一致 → --check exit 0 并打印放行读数)`,
    ok: r1.status === 0 && o1.includes(okLine) && /打包域指纹 [0-9a-f]{16}\)/.test(o1),
    detail: `exit=${r1.status} 放行行=${o1.includes(okLine)} 读数=${firstLine(r1)}`,
  })
  // ② tag 之后又提交了一处域内改动 ⇒ 拒 + 点名不一致文件 + 两条现成修法
  const post = 'plugins/aurapolaris/README.md'   // 进包、且不在 desired_state 产物里 ⇒ 改动它只会惊动本闸
  fs.appendFileSync(path.join(root, post), '\n<!-- honesty fixture: tag 之后又改了一行(同一个版本号两份字节) -->\n')

