// 【C134】相对说明符的解析分两步:先把"非代码"屏蔽成等长空白(mask),再只在 mask 上匹配。
//   旧版是一发正则直接扫原文,靠 `[\s\S]{0,400}?` 这个窗口顺带压住注释/字符串里的假边;代价是
//   `tools/taskctl.mjs` 第 76–91 行那条跨 16 行、600+ 字符的命名 import 整条漏掉(arch-v2.C126 实测:
//   闭包缺 `skills/aurapolaris/tools/task-files.mjs`)。窗口既然是病灶,就不能再拿它挡假边 ⇒ 换成屏蔽:
//   ① `codeOnlyMask` 把注释 / 字符串 / 模板 / 正则字面量替成空白(字符串与模板的引号定界符保留、换行逐字保留);
//   ② 匹配只在 mask 上做 —— 窗口不再限长,仅剩两道界:分号,以及"不许跨到下一条 import/export"(防吞掉中间那条边);
//   ③ 说明符原文按 group 的 index 回原文切(mask 里字符串内容是空白,直接读 group 拿不到真名字)。
const IMPORT_SPEC_RE = /(?:^|[\s;])import\s*\(\s*(['"])([^'"]+)\1\s*\)|(?:^|[\s;])import\s*(['"])([^'"]+)\3|(?:^|[\s;])(?:import|export)\b(?!\s*[.(])(?:(?!\b(?:import|export)\b)[^;])*?\bfrom\s*(['"])([^'"]+)\5|(?:^|[\s;])require\s*\(\s*(['"])([^'"]+)\7\s*\)/gd
const SPEC_GROUPS = [2, 4, 6, 8]   // 四个分支各自的"说明符内容"捕获组(1/3/5/7 是它那对引号定界符)
const isRelSpec = (s) => s.startsWith('./') || s.startsWith('../') || s.startsWith('/')
// 判 `/` 是除号还是正则字面量的起头:标识符/数字/)/]/} 之后是除号;`return /re/`、`typeof /re/` 这类
//   关键字之后仍是正则 —— 只看字符会把它们读成除号,而正则里可以出现引号(`/['"]/`),漏屏蔽就会从那里
//   起一个"假字符串",把本行后半段真代码吃掉(漏边)。保守方向:判不准时按除号(损害只限本行)。
const REGEX_AFTER_WORD = /[\w$)\]}]/
const REGEX_PREV_KEYWORDS = new Set(['return', 'typeof', 'case', 'in', 'of', 'instanceof', 'new', 'delete', 'void', 'do', 'else', 'yield', 'await', 'throw'])
// 等长屏蔽:注释、'…'、"…"、模板 `…`(只屏蔽正文,${} 里的代码保留)、正则字面量 → 空白。
function codeOnlyMask(src) {
  const out = src.split('')
  const n = src.length
  const blank = (i) => { if (i >= 0 && i < n && src[i] !== '\n' && src[i] !== '\r') out[i] = ' ' }
  const stack = []                 // 模板正文 'tmpl' / 插值花括号 {depth}
  let last = ''                    // 上一个有效代码字符
  let word = ''                    // 上一个标识符词(只用于认出 return / typeof 这类关键字)
  let i = 0
  while (i < n) {
    const c = src[i]
    const top = stack[stack.length - 1]
    if (top === 'tmpl') {          // 模板正文:一律屏蔽;` 收尾、${ 回代码态
      if (c === '\\') { blank(i); blank(i + 1); i += 2; continue }
      if (c === '`') { stack.pop(); i++; continue }
      if (c === '$' && src[i + 1] === '{') { stack.push({ depth: 1 }); i += 2; continue }
      blank(i); i++; continue
    }
    if (c === '/' && src[i + 1] === '/') { while (i < n && src[i] !== '\n') { blank(i); i++ } continue }
    if (c === '/' && src[i + 1] === '*') {
      blank(i); blank(i + 1); i += 2
      while (i < n && !(src[i] === '*' && src[i + 1] === '/')) { blank(i); i++ }
      blank(i); blank(i + 1); i += 2
      continue
    }
    if (c === "'" || c === '"') {  // 单/双引号不许跨行:未闭合就当它到行尾 —— 屏蔽范围绝不越过换行
      i++
      while (i < n && src[i] !== c && src[i] !== '\n') { if (src[i] === '\\') { blank(i); blank(i + 1); i += 2; continue } blank(i); i++ }
      if (i < n && src[i] === c) i++
      last = c; word = ''
      continue
    }
    if (c === '`') { stack.push('tmpl'); i++; last = c; word = ''; continue }
    if (c === '/' && !(REGEX_AFTER_WORD.test(last) && !REGEX_PREV_KEYWORDS.has(word))) {
      const start = i
      i++
      let cls = false
      while (i < n && src[i] !== '\n') {
        if (src[i] === '\\') { i += 2; continue }
        if (src[i] === '[') cls = true
        else if (src[i] === ']') cls = false
        else if (src[i] === '/' && !cls) break
        i++
      }
      for (let k = start; k <= Math.min(i, n - 1); k++) blank(k)
      if (i < n && src[i] === '/') i++
      last = '/'; word = ''
      continue
    }
    if (c === '{') { if (top && typeof top === 'object') top.depth++; i++; last = c; word = ''; continue }
    if (c === '}') { if (top && typeof top === 'object') { top.depth--; if (top.depth <= 0) stack.pop() } i++; last = c; word = ''; continue }
    if (/\s/.test(c)) { i++; continue }
    if (/[\w$]/.test(c)) word += c
    else word = ''
    last = c
    i++
  }
