}
// 一个模块里的相对说明符(按出现顺序、去重)。导出=回执/登记表可以复用同一份规则,不再写第二份解析。
export function relImportsOf(file) {
  const src = fs.readFileSync(file, 'utf8')
  const mask = codeOnlyMask(src)
  const out = []
  IMPORT_SPEC_RE.lastIndex = 0
  let m
  while ((m = IMPORT_SPEC_RE.exec(mask))) {
    for (const g of SPEC_GROUPS) {
      const span = m.indices[g]
      if (!span) continue
      const s = src.slice(span[0], span[1])   // 原文切:mask 里这段是空白
      if (s && isRelSpec(s) && !out.includes(s)) out.push(s)
      break
    }
  }
  return out
}

