function cmdCheck(rootArg) {
  const root = path.resolve(rootArg ?? ROOT)
  let res
  try { res = checkHosts(root) } catch (e) { console.error(`HOSTS-MATRIX FAIL: 清单不可用: ${e.message}`); process.exit(12) }
  console.log(`宿主根清单: ${HOSTS_REL} (${res.rows.length} 根);根目录 ${root}`)
  for (const [f, o] of Object.entries(res.observed)) {
    console.log(`  ${f.padEnd(16)} ${o.unverified ? `unverified(${o.why})` : `exit=${o.exit} 行数=${o.lines.length} via=${o.via}`}`)
  }
  if (res.problems.length) {
    console.error(`\nHOSTS-MATRIX FAIL: ${res.problems.length} 处 —— 名单只有一份(${HOSTS_REL}),三处必须逐行一致`)
    for (const p of res.problems) console.error(`  [${p.kind}] ${p.detail}`)
    process.exit(12)
  }
  // PASS 行必须带实跑计数:一条 PASS 里混着"没跑"的消费者,读的人会把 unverified 当已验证(P2-9 反证)。
  //   未跑项逐条点名到 PASS 行上 —— 不靠读者往上翻,也不把"本机没有 sh"升级成失败(那会让这条门禁在本机永远红)。
  const entries = Object.entries(res.observed)
  const ran = entries.filter(([, o]) => !o.unverified)
  const unver = entries.filter(([, o]) => o.unverified)
  console.log(`\nHOSTS-MATRIX PASS: 三消费者列根输出与 ${HOSTS_REL} 逐行一致,且无内嵌名单 (${ran.length}/${entries.length} 实跑,${unver.length} 未验证${unver.length ? `: ${unver.map(([f, o]) => `${f} unverified(${o.why})`).join(';')}` : ''})`)
  process.exit(0)
}

