//   `import ... from '../skills/aurapolaris/tools/run-sync.mjs'` 后,沙箱里的消费者直接 ERR_MODULE_NOT_FOUND,
//   把门禁自己的反向验证打成了常红 —— 红相看着像"判据坏了",实际是夹具坏了)。规则两步,都不含手写文件名:
//   ① 数据种子:清单本身 + 三个消费者入口 —— 它们不是 import,模块图看不见,只能按"消费者是谁"登记
//      (而"消费者是谁"的单一来源就是上面的 CONSUMERS/HOSTS_REL,不是第二份文件名单);
//   ② 从 .mjs 种子出发,递归解析【相对】说明符的静态 import / export-from 与字面量 import()/require(),
//      闭包内文件全拷(含 ../skills/... 与 ../tools/...)。tools/host-matrix.mjs 也当种子,便于在沙箱里独立复跑 --check。
// 为什么不会再过期:消费者新增任何相对 import 都自动进闭包。闭包看不见的只剩三类 —— 运行时按路径读的数据文件、
//   裸包名(要 node_modules)、非字面量动态 import —— 这三类缺了都由 FIXTURE-STALE 前置判定自报
//   (点名消费者 + 缺失路径),不再伪装成"名单不一致"或"判红未点名"。
const FIXTURE_SEEDS = [HOSTS_REL, 'install.ps1', 'install.sh', 'cli/polaris.mjs', 'tools/host-matrix.mjs']
const IMPORT_SPEC_RE = /(?:^|[\s;])(?:import|export)\b[\s\S]{0,400}?\bfrom\s*['"]([^'"]+)['"]|(?:^|[\s;])import\s*\(\s*['"]([^'"]+)['"]\s*\)|(?:^|[\s;])import\s*['"]([^'"]+)['"]|(?:^|[\s;])require\s*\(\s*['"]([^'"]+)['"]\s*\)/g
const isRelSpec = (s) => s.startsWith('./') || s.startsWith('../') || s.startsWith('/')
// 一个模块里的相对说明符(按出现顺序、去重)。导出=回执/登记表可以复用同一份规则,不再写第二份解析。
export function relImportsOf(file) {
  const src = fs.readFileSync(file, 'utf8')
  const out = []
  IMPORT_SPEC_RE.lastIndex = 0
  let m
  while ((m = IMPORT_SPEC_RE.exec(src))) { const s = m[1] ?? m[2] ?? m[3] ?? m[4]; if (s && isRelSpec(s) && !out.includes(s)) out.push(s) }
  return out
}
// 夹具文件集 = 种子 + 种子的相对 import 传递闭包。missing = 闭包解析到但磁盘上没有的文件。
export function fixtureFiles(root = ROOT, seeds = FIXTURE_SEEDS) {
  const seen = new Set()
  const files = []
  const missing = []
  const queue = seeds.map((s) => s.replace(/\\/g, '/'))
  while (queue.length) {
    const rel = queue.shift()
    if (seen.has(rel)) continue
    seen.add(rel)
    if (!/\.(?:mjs|cjs|js)$/.test(rel)) { files.push(rel); continue }
    const abs = path.join(root, rel)
    if (!fs.existsSync(abs)) { missing.push(rel); continue }
    files.push(rel)
    for (const s of relImportsOf(abs)) queue.push(path.posix.normalize(path.posix.join(path.posix.dirname(rel), s)))
  }
  return { files, missing }
}
function sandboxReset(skip = []) {
  if (!path.resolve(SANDBOX).startsWith(path.resolve(ROOT) + path.sep)) throw new Error(`拒绝清理工作区外的路径: ${SANDBOX}`)
  fs.rmSync(SANDBOX, { recursive: true, force: true })
  const { files, missing } = fixtureFiles()
  // fail-closed:闭包解析到不存在的文件 = “消费者的 import 悬空”(真 bug)或“本工具的解析规则要跟着语法走”——
  //   两种都不许静默跳过(旧 COPY 的静默跳过正是这次常红的形状)。
  if (missing.length) throw new Error(`夹具闭包解析到不存在的文件: ${missing.join(', ')} —— 要么消费者 import 悬空,要么 fixtureFiles 的解析规则要跟着语法走`)
  const skipSet = new Set(skip)
  for (const rel of files) {
    if (skipSet.has(rel)) continue
    const dst = path.join(SANDBOX, rel)
    fs.mkdirSync(path.dirname(dst), { recursive: true })
    fs.copyFileSync(path.join(ROOT, rel), dst)
  }
}
function patch(rel, from, to, expect = 1) {
  const abs = path.join(SANDBOX, rel)
  const src = fs.readFileSync(abs, 'utf8')
  const hits = src.split(from).length - 1
  if (hits !== expect) throw new Error(`沙箱补丁锚点失配(${rel}):找到 ${hits} 处,期望 ${expect} 处 —— 消费者实现变了就该同步改自证`)
  fs.writeFileSync(abs, src.split(from).join(to))
}
function cmdSelftest() {
  const cases = []
  const run = (name, fn) => { try { const d = fn(); cases.push({ name, ok: true, detail: d ?? '' }) } catch (e) { cases.push({ name, ok: false, detail: e.message }) } }
  // 夹具过期是【夹具】的问题,不是【判据】的问题(2026-09-27 R8):旧 COPY 停在 2026-09-24,消费者新增 import
  //   后沙箱里根本加载不了 → D4a/D4b 常红,而红相长得像"判据坏了"(下一个来修的人会去改判据,那才是真危险)。
  //   命中就当场说"夹具过期"并点名缺失路径,既不算成"名单不一致"(kind:mismatch),也不算成"判红未点名" ——
  //   与上面 install.sh 那格(缺 sh 记 unverified 并点名,不判 FAIL)同一口径:判不了就说判不了,不伪装。
  const staleProblems = (r) => r.problems.filter((p) => p.kind === 'fixture-stale')
  const staleError = (phase, st) => new Error(`${phase}: 夹具过期（FIXTURE-STALE）—— ${st.map((p) => p.detail).join(' | ')};夹具覆盖面该跟着模块图走(规则=fixtureFiles:种子[${FIXTURE_SEEDS.join(' ')}] + 相对 import 传递闭包),沙箱 COPY/闭包规则该更新`)
  const assertNoStale = (phase, r) => { const st = staleProblems(r); if (st.length) throw staleError(phase, st) }

