// skills/aurapolaris/tools/task-files.mjs — 任务文件枚举谓词族【唯一实现】(随技能包分发)。
//
// 为什么在这个落点(2026-09-29,施工单 arch-v2.C28;AGENTS.md §0.4):
//   谓词原先住在仓库侧 tools/taskctl.mjs。而本仓库的【可分发单元是 skills/aurapolaris/】——
//   技能包(aurapolaris-skill-0.8.0.zip,根 = polaris/)解压进任意 skills 根就算装完,那里【没有 tools/】。
//   实测代价:装到别的宿主后,ledger 源的任务层与执行者层为空(只剩蓝图 + 组件),
//   在包内跑 --selftest 直接 TypeError。所以谓词的落点必须跟着包走:包内这一份是唯一实现,
//   仓库侧 tools/taskctl.mjs 改为 import 本文件并【再导出】,既有消费者(pipeline-watch / fractal-check /
//   agent-graph)一行都不用改。
//
// 本文件是叶子模块:零依赖(只用 node 内置模块)、不读 POLARIS_ROOT、不在 import 期做任何 IO 或副作用。
//   "根作用域版(In)" 一律把 tasksDir 作为第一个参数收进来 —— 对账工具要在【自证夹具根】里判状态,
//   不能把它钉死在某个进程级根上。

import fs from 'node:fs'
import path from 'node:path'

// ---- 读 JSON:三态 ok / missing / bad ----
// 口径与 tools/audit.mjs 的 read/readBuf/readJson 同款:【读】容忍(不崩),【缺/坏】必须点名;
//   为什么带 why:坏输入要能"一行点名 + exit 12",调用侧拿不到 why 就只能甩栈或静默。
//   与 tools/taskctl.mjs 里那一份【逐字同源】:该模块的读任务文件链(readTaskFile/lint/verify)整条消费本实现,
//   所以"这文件读得出来吗"全仓只有这一处判。
const READ_OK = 'ok', READ_MISSING = 'missing', READ_BAD = 'bad'
const isPlainObject = (j) => !!j && typeof j === 'object' && !Array.isArray(j)
function readJsonState(p) {
  let raw
  try { raw = fs.readFileSync(p, 'utf8') } catch (e) { return { kind: READ_MISSING, why: e?.code === 'ENOENT' ? '文件不存在' : `读不到(${e?.code ?? e?.message})` } }
  if (!raw.trim()) return { kind: READ_BAD, why: 'JSON 解析失败(空文件)' }
  try { return { kind: READ_OK, value: JSON.parse(raw), raw } } catch (e) { return { kind: READ_BAD, why: `JSON 解析失败(${e.message})` } }
}
// 派生物(不是第二条读路径):只把三态压成"值 / null",供"读不到就按缺省走"的调用侧用。
const readJsonOrNull = (p) => { const r = readJsonState(p); return r.kind === READ_OK ? r.value : null }
export { READ_OK, READ_MISSING, READ_BAD, isPlainObject, readJsonState, readJsonOrNull }

// ---- 任务文件谓词【唯一一份】 ----
// 真任务文件 = T-*.json 且不是六种派生产物。派生产物各自都是"某次命令的落盘",不是可领任务:
//   .claim.json   某次【认领】的落盘(子代理开工前写)
//   .result.json  某次【回执】的落盘(协议 §7 交付物)
//   .void.json    某次【作废】的落盘(记账用,不伪造验收)
//   .verify.json  某次【复核】的落盘(taskctl verify 的派生数据,允许覆盖)
//   .receipt.json verify 的【自保副本】落点(preserveReceipt:轮次判不出时写 state/tasks/<id>.receipt.json)
//   .close.json   某次【收口】的落盘(taskctl recycle --close-partial 的收口流程写,父线程收口用)
//   漏掉任何一个,按文件名枚举 state/tasks 的消费者就会把它当成一张任务:实测漏 .verify.json 时
//   tools/pipeline-watch.mjs 多输出一行幻影任务 QUEUE: T-20260927111319-59fe.verify;
//   实测 .receipt.json 被 lint 当成一张任务并判红"缺 brief(不是任务文件?)" ——
//   verify 自己写的产物把门禁弄红。所以这一份【只许有一处】,消费者一律 import 它
//   (历史上 pipeline-watch 自带一份,少了两个后缀 → 两口径任务数 176 vs 170)。
//   【arch-v2.C137】.close.json 为什么归进本表 = 【派生件】,与 .claim.json 同类(不是"为让某条判据变绿而豁免"):
//     它跟 .claim.json 一样是【账务机械件】—— 由工具写、记的是"某一次流程动作发生了什么"、不是可领取的任务。
//     键集 {id,at,reason_file,reason_sha256_16,acceptance,drift,receipt_status,deviations,by} 里
//     天生没有 brief / evidence_required —— 那两个是【任务指针】才有的键(指针=可派单的规格);
//     .close.json 只是收口那一刻的账面读数,把它当任务记录读,读到的是"它没有指针的键",不是"它缺件"。
//     实测代价(本表未含 .close.json 时):tools/fractal-check.mjs 的 FRACTAL-1 分母现算按 isTaskFile 取件
//     ⇒ .close.json 被当成任务记录参与现算 ⇒ 判红 "task.declaration 键=brief 在 3/369 份记录里缺位:
//     state/tasks/T-wo-arch-v2-C125.close.json, state/tasks/T-wo-arch-v2-C127.close.json,
//     state/tasks/T-wo-arch-v2-C135.close.json" ⇒ `fractal-check --check --round=R9` 与 `--selftest` 双双
//     exit 12(unit 层与 e2e-fractal 都到不了绿)。修法落点就是本表【这一处】:那三份 .close.json 一个字节不改,
//     判据侧(tools/fractal-check.mjs)一行也不动 —— 它们由红转绿靠的是【归类正确】而不是【改读数】。
export const DERIVED_SUFFIXES = ['.claim.json', '.result.json', '.void.json', '.verify.json', '.receipt.json', '.close.json']
export const isDerivedArtifact = (name) => DERIVED_SUFFIXES.some((s) => String(name).endsWith(s))
export const isTaskFile = (name) => /^T-.*\.json$/.test(String(name)) && !isDerivedArtifact(name)

// 施工单档枚举谓词【唯一实现】(arch-v2.C119 加入同一导出面;AGENTS.md §0.4 枚举单源)。
//   用途:`.polaris/workorders/` 下"哪些文件是施工单(待派的规格)" —— 工具侧原先在 orphanWorkorders()
//   里内联写 `endsWith('.json') && !endsWith('.result.json')`,那就是这一族事实的第二处实现。
//   口径:.json 结尾 ∧ 不是派生物(回执/认领/作废/复核/自保副本/收口六种后缀全部由上面的 DERIVED_SUFFIXES 回答)。
//   为什么复用 isDerivedArtifact 而不是照抄".result.json":施工单目录里同样会落 .claim/.void 等派生件
//   (认领与作废都写在对应目录下),只排回执会把它们当成"没有指针的施工单"记一笔幻影孤儿 ——
//   与 §0.4 记下的 pipeline-watch 少排两个后缀、两口径 176 vs 170 是同一个失效形态。
//   边界:只看文件名,不看内容、不判目录(调用方给的就是施工单目录里的条目名);
//   这里不写 T- 前缀 —— 施工单档名是 <id>.json(如 arch-v2.C119.json),与 state/tasks 的 T-*.json 不同族。
export const isWorkorderFile = (name) => String(name).endsWith('.json') && !isDerivedArtifact(name)

// ---- 作废记录谓词【唯一一份】= 终态之一 ----
//   口径来源与 tools/pipeline-watch.mjs 的 status 谓词【逐字对齐】:
//     `hasResult ? 'done' : voided ? 'void' : claim ? 'inflight' : 'open'`,
//   以及它文件头"在跑的集合 = claim ∧ ¬result ∧ ¬void:作废(.void.json)与回执都是终态产物,不进 STALE 面"。
//   本谓词之前租约闸只读了"有回执"这一半终态,已作废单的 claim 继续占着写权 —— 实测 T-20260927161014-849a
//   代理已死、已写 void,它的租约仍把接手单的 lint 摁在 exit 12(lint 自述的红就是"写权相交(在跑)")。
//   边界如实声明:① "有回执"那一半【不换】—— receiptDone 比 pipeline-watch 的 hasResult 更宽
//   (多认"自声明非规范名 ∧ §7 形态",那是修过的真缺口 8f06),换成窄的反而会放宽在跑集合,属放宽;
//   ② 读得到 ∧ 顶层是对象才算作废记录:半写的 .void.json 不释放写权(fail-closed,宁可误报一次),
//   与"预算/时间解析不出就当在跑"同款取舍。
export const isVoidedIn = (tasksDir, id) => isPlainObject(readJsonOrNull(path.join(tasksDir, `${id}.void.json`)))
