export const DEFAULTS = {
  sleepMs: 120,
  retries: 2,
  timeoutMs: 9000,
}

export class Warmup {
  constructor(opts = {}) {
    this.opts = { ...DEFAULTS, ...opts }
  }

  delay() {
    return this.opts.sleepMs
  }
}

export async function warmPool(pool, opts = {}) {
  const cfg = { ...DEFAULTS, ...opts }
  for (const worker of pool) {
    await worker.ready(cfg.sleepMs)
    if (cfg.retries > 0) await worker.retry(cfg.retries)
  }
  return pool.length
}

