# prepare.ps1 —— 准备第四轮对照实验的装置（幂等、不跑任何模型会话）
#
# 第四轮的变化（前三轮的教训都写在这里）：
#   · 夹具换成"有区分力"的：300+ 行、含重复文本、改动会改变行数（前三轮的夹具两种寻址都全对，量不出差别）
#   · 去掉两处已证伪的干预（提示行 / 符号目录行），改为两个新开关：
#       AURA_EXPERIMENT_MAPFIRST=1  —— 两段式读：先回符号目录，第二次读才给正文（模拟"默认先看结构"）
#       AURA_EXPERIMENT_POLICY=1    —— 软策略：行号寻址但目标落在"同名重复块"时拒一次，回执说明原因并给符号名
#   · 所有臂仍共用同一份字节，差别只在环境变量

[CmdletBinding()]
param(
    [switch]$Force,
    [switch]$StripReadPrompt
)

$ErrorActionPreference = 'Stop'
$Here = Split-Path -Parent $MyInvocation.MyCommand.Path
$DshHome = $env:DSH_HOME
if (-not $DshHome) { throw 'DSH_HOME 未设置' }
$Src = 'C:\Users\cxk\.aura\pkg\node_modules\aura-tools'
if (-not (Test-Path $Src)) { throw "找不到安装态包：$Src" }
$PkgDir = Join-Path $Here 'pkg\node_modules'
$Dst = Join-Path $PkgDir 'aura-tools'
$ProfileDir = Join-Path $DshHome 'profiles\aura-exp'
$HeadlessDir = Join-Path $DshHome 'profiles\headless'
$HeadlessModules = Join-Path $HeadlessDir 'node_modules'

function Say($m) { Write-Host $m }
function Step($m) { Write-Host "`n== $m" -ForegroundColor Cyan }

# ── 1. 克隆 ────────────────────────────────────────────────────────────────
Step "1/4 克隆安装态包 → $Dst"
if (Test-Path $Dst) {
    if (-not $Force) { Say '已存在（跳过克隆；要重来加 -Force）' }
    else { Remove-Item -Recurse -Force $Dst; Say '已删除旧副本' }
}
if (-not (Test-Path $Dst)) {
    New-Item -ItemType Directory -Force -Path $PkgDir | Out-Null
    Copy-Item -Recurse -Force $Src $Dst
    Say ('克隆完成：' + ((Get-ChildItem -Recurse -File $Dst | Measure-Object).Count) + ' 个文件')
}

# ── 2. 实验钩子（全部用单引号 here-string：内部 JS 有 < > 与 $，双引号会被 PS 解析）──
Step '2/4 给克隆件加实验钩子'
$ReadIndex = Join-Path $Dst 'aura-read\index.js'
$text = Get-Content -Raw -LiteralPath $ReadIndex
$nl = if ($text -match "`r`n") { "`r`n" } else { "`n" }

$MUTATION = @'
// ── 实验钩子（不是产品代码）────────────────────────────────────────────────
//   AURA_EXPERIMENT_MAPFIRST=1 ⇒ 大文件的两段式读：首次请求正文时回符号目录，第二次才给正文
//   AURA_EXPERIMENT_POLICY=1   ⇒ 行号寻址但目标落在同名重复块时拒一次（软策略）
const experimentReadsSeen = new Map()

function experimentTok(source, line) {
  const lines = String(source).split(/\r?\n/)
  const text = lines[line - 1] ?? ''
  return text.trim().replace(/["'`]/g, '').slice(0, 40)
}

function experimentRepeatInfo(source, start) {
  const tok = experimentTok(source, start)
  if (tok.length < 4) return null
  const lines = String(source).split(/\r?\n/)
  let idx = 0
  for (let i = 0; i < lines.length; i += 1) {
    if (lines[i].trim().replace(/["'`]/g, '').startsWith(tok)) idx += 1
  }
  if (idx <= 1) return null
  // 回找“所属符号”时只认函数/类：若把 `const parts = …` 也算符号，会报出 `inside parts` 这种没用的名字（实测踩到）。
  const rx = /^\s*(?:export\s+)?(?:async\s+)?(?:function|def|class)\s+([A-Za-z_$][\w$]*)/
  let name = null
  // 从目标行的上一行起往回找：否则目标行自己（如 `let name = null`）会被当成所属符号
  for (let i = Math.min(start, lines.length) - 2; i >= 0; i -= 1) {
    const m = rx.exec(lines[i] ?? '')
    if (m) {
      name = m[1]
      break
    }
  }
  const line = lines[start - 1] ?? ''
  const cue = (line.match(/[A-Za-z_$][\w$]{5,}/) || [])[0] ?? null
  return { count: idx, name, cue }
}

function experimentDirectory(source, filePath) {
  const lines = String(source).split(/\r?\n/)
  const rx = /^\s*(?:export\s+)?(?:async\s+)?(?:function|def|class|interface|type|const|let|var|public|private|static)\s+([A-Za-z_$][\w$]*)/
  const syms = []
  for (let i = 0; i < lines.length; i += 1) {
    const m = rx.exec(lines[i] ?? '')
    if (m) syms.push(`${m[1]}@${i + 1}`)
  }
  const file = String(filePath ?? '').split(/[\\/]/).pop()
  const head = `two-stage read: showing the symbol directory of ${file} (${lines.length} lines, ${syms.length} symbols) instead of the body`
  const tail = 'request the same lines again to get the body (the next read returns it in full)'
  const budget = 1400
  let body = head
  for (const s of syms) {
    if (body.length + s.length + 3 > budget) {
      body += ` … (+${syms.length - syms.indexOf(s)} more)`
      break
    }
    body += ` | ${s}`
  }
  return `${body} | ${tail}`
}

function experimentReadNote(source, request, filePath, displayPath) {
  if (process.env.AURA_EXPERIMENT_MAPFIRST !== '1') return undefined
  const pair = request?.lines
  if (Array.isArray(pair) && pair.length === 2) {
    if (String(source).split(/\r?\n/).length < 200) return undefined
    const key = String(displayPath ?? '')
    const n = (experimentReadsSeen.get(key) ?? 0) + 1
    experimentReadsSeen.set(key, n)
    if (n >= 2) return undefined
    return `__DIRECTORY__${experimentDirectory(source, filePath)}`
  }
  if (request?.mode === 'full' && String(source).split(/\r?\n/).length >= 200) return undefined
  return undefined
}

function experimentEditPolicy(args, source) {
  if (process.env.AURA_EXPERIMENT_POLICY !== '1') return undefined
  const hunks = Array.isArray(args?.hunks) ? args.hunks : []
  for (const h of hunks) {
    const raw = h?.lines ?? (h?.start_line !== undefined ? [h.start_line, h.end_line ?? h.start_line] : undefined)
    if (raw === undefined || raw === null) continue
    const start = Array.isArray(raw) ? Number(raw[0]) : Number(raw.start)
    if (!Number.isInteger(start)) continue
    const info = experimentRepeatInfo(source, start)
    if (info === null) continue
    const where = info.name === null ? 'somewhere in this file' : `inside ${info.name}`
    const how = info.cue === null ? 'a more specific anchor' : `anchor=${JSON.stringify(info.cue)}`
    return `PATCH_AMBIGUOUS_REGION: ${info.count} regions in this file begin with the same text as line ${start}, so a line number cannot tell them apart — the target is ${where}; retry with ${how} (or target=<symbol>)`
  }
  return undefined
}
'@

$ANCHOR_READ = '        const env = readWith(source, request)'
$INSERT_READ = @'
        const experimentReadLine = experimentReadNote(source, request, target.displayPath, target.displayPath)
        if (experimentReadLine !== undefined && experimentReadLine.startsWith('__DIRECTORY__')) {
          const dirText = experimentReadLine.slice('__DIRECTORY__'.length)
          return {
            path: target.displayPath,
            mode: 'map',
            totalLines: env.totalLines,
            text: dirText,
          }
        }
'@

$ANCHOR_APPLY = 'export function apply(ctx) {'
$COUNT_READ = ([regex]::Matches($text, [regex]::Escape($ANCHOR_READ))).Count
$COUNT_APPLY = ([regex]::Matches($text, [regex]::Escape($ANCHOR_APPLY))).Count
if ($COUNT_READ -ne 1) { throw "定位失败：readWith 锚点出现 $COUNT_READ 次" }
if ($COUNT_APPLY -ne 1) { throw "定位失败：apply 锚点出现 $COUNT_APPLY 次" }

if ($text -match 'function experimentEditPolicy') {
    Say '钩子已存在（跳过打读侧钩子）'
} else {
    $text = $text.Replace($ANCHOR_READ, $ANCHOR_READ + $nl + $INSERT_READ.TrimEnd())
    $text = $text.Replace($ANCHOR_APPLY, $MUTATION.TrimEnd() + $nl + $nl + $ANCHOR_APPLY)
    Say '已插入读侧钩子'
}

if ($StripReadPrompt) {
    $start = $text.IndexOf('  ctx.systemPrompt.section({')
    if ($start -lt 0) { throw 'StripReadPrompt：找不到 aura_read 的提示段起点' }
    $tail = $text.Substring($start)
    $endRel = $tail.IndexOf("$nl  })$nl")
    if ($endRel -lt 0) { throw 'StripReadPrompt：找不到提示段结尾' }
    $text = $text.Remove($start, $endRel + "$nl  })$nl".Length)
    Say '已删除 aura_read 的 systemPrompt 段'
}

Set-Content -LiteralPath $ReadIndex -Value $text -NoNewline -Encoding utf8
Say '写回 aura-read/index.js'
$null = & node --check $ReadIndex 2>&1
if ($LASTEXITCODE -ne 0) { throw "克隆件语法检查失败：$ReadIndex" }
Say 'node --check 通过'

# 写侧钩子：软策略（必须在参数校验之后、定位之前：那里才拿得到 source 与 args）
Step '2b/4 给克隆件的 aura_edit 加软策略钩子'
$EditIndex = Join-Path $Dst 'aura-edit\index.js'
$etext = Get-Content -Raw -LiteralPath $EditIndex
$eanchor = '        const env = readWith(source, request)'
if ($etext -match 'experimentEditPolicy\(args, source\)') {
