/* AuraBridge - dialog state and the frozen-renderer recovery path.
 * (epsilonCk & Chaos)
 *
 * Loaded by background.js via importScripts(): same global scope as the worker, so
 * `getSettings()`, `scripted()` and `withBudget()` - which live in background.js - are
 * reachable from here. They are only ever touched at CALL time, never while this file
 * is being evaluated, so the load order does not matter. Nothing here is ever injected
 * into a page.
 *
 * WHY THIS FILE EXISTS
 *     A native dialog blocks ONE renderer, and it used to be handled by two
 *     module-level singletons (`dialogLog`, `dialogIntent`) guarded by a "who owns the
 *     log" caller string. Two commands from the SAME caller - the normal case, since
 *     one agent runs several actions in parallel - share that string, so:
 *       * command B's start did `dialogLog.length = 0`, wiping the entries A had
 *         already recorded, and A's reply then reported B's dialogs as its own;
 *       * a command with no `dialog` argument set the shared intent to null WHILE A
 *         was still running, so A's per-call intent was silently dropped, or worse,
 *         A's dialog was answered with B's accept/dismiss.
 *     Both are claims about what happened that the reply cannot back up (A.3.4).
 *
 *     `chrome.debugger.onEvent` says which tab a dialog came from, so the tab is the
 *     key both sides already have. All state here is keyed by tab and bounded.
 *
 * THE RECOVERY GUARD (single-flight + cooldown)
 *     In the lanes that hold no debugger session, a frozen renderer is answered by
 *     attaching the debugger, dismissing per policy, and detaching. That is right once
 *     per command and catastrophic inside a loop: measured (2026-09-15) the readiness
 *     poll and the navigate loop each ran a recovery-carrying inject every few hundred
 *     ms, ~50 attach/dismiss/detach cycles raced each other, and a single
 *     `aura_navigate` burned the daemon's whole 90s budget without returning. A bound
 *     on each attempt is not a bound on their sum; this is.
 *
 *     While the cooldown holds, a frozen tab is refused FAST (after one short probe)
 *     instead of re-attempting - which is also what lets the refusal reach the daemon
 *     so its OS-keystroke fallback can fire. The probe still runs every time, so a page
 *     that recovers on its own is noticed immediately.
 */

const dialogLogByTab = new Map();      // tabId -> [{type, message, defaultPrompt}]
const dialogIntentByTab = new Map();   // tabId -> {action:'accept'|'dismiss', text}

/* All four of this file's tables are keyed by TAB, so all four are cleared by the one per-tab
 * lifecycle registry (lib/constants.js) and their own size caps are gone.
 *
 * WHY THE CAPS WENT (audit finding, 2026-09-20): `DIALOG_STATE_MAX`/`recoveryByTab.size > 20` were a
 * second answer to the question the registry already answers - "is this tab still alive?" - and a
 * worse one: they evicted by insertion order, so a live tab's dialog log could be thrown away to make
 * room for a new one, and the botched first version of that eviction (`if (first !== tabId)`) had
 * already needed its own fix. Chrome reuses tab ids; that is a lifecycle fact, and it is handled where
 * the lifecycle is known. */
function forgetDialogTab(tabId) {
  const key = dialogKey(tabId);
  if (key == null) return;
  dialogLogByTab.delete(key);
  dialogIntentByTab.delete(key);
  dialogCommandTabs.delete(key);
  recoveryByTab.delete(key);
}
onTabClosed('dialog state (log, intent, command, recovery)', forgetDialogTab,
            () => [...new Set([...dialogLogByTab.keys(), ...dialogIntentByTab.keys(),
                               ...dialogCommandTabs, ...recoveryByTab.keys()])]);

function dialogKey(tabId) {
  return tabId == null ? null : Number(tabId);
}

function dialogLogFor(tabId) {
  const key = dialogKey(tabId);
  if (key == null) return [];
  if (!dialogLogByTab.has(key)) dialogLogByTab.set(key, []);
  return dialogLogByTab.get(key);
}

function dialogIntentOf(tabId) {
  const intent = dialogIntentByTab.get(dialogKey(tabId));
  return intent && (intent.action === 'accept' || intent.action === 'dismiss') ? intent : null;
}

function setDialogIntent(tabId, intent) {
  const key = dialogKey(tabId);
  if (key == null) return;
  if (intent) dialogIntentByTab.set(key, intent);
  else dialogIntentByTab.delete(key);
}

/* Which tab will this command act on? The same key laneKey() uses: an explicit
 * tab_id wins, otherwise the tab frozen at dispatch. It is also the only key the
 * CDP event handler shares with the command wrapper. */
function dialogTabOf(args, tabHint) {
  const raw = (args || {}).tab_id;
  if (raw != null && Number.isFinite(Number(raw))) return Number(raw);
  return tabHint && tabHint.id != null ? tabHint.id : null;
}

/* Which tabs are answering a dialog themselves right now, so the standing policy handler
 * stays out of the way while a caller answers its own.
 *
 * WHY A SET AND NOT ONE TAB ID (measured 2026-09-16, and the guard that should have caught
 * it was one name short - tests/contract_test.py listed `dialogLog`/`dialogIntent`/
 * `dialogLogOwner` and not this one):
 *
 *   tab1's caller starts `aura_dialog`  -> active = 1
 *   tab2's caller starts `aura_dialog`  -> active = 2   (one slot: tab1 is forgotten)
 *   a dialog NOW opens on tab1          -> `2 === 1` is false, so attachWatcher's listener
 *                                          does not stand aside, and the PANEL POLICY
 *                                          (default auto-dismiss) answers the dialog tab1's
 *                                          caller was answering itself: accept+promptText
 *                                          became a silent dismiss.
 *
 * The reverse works too: whichever command finishes first clears the slot and exposes the
 * other one. Two concurrent callers on two tabs is a supported configuration - lib/lanes.js
 * runs up to `parallel` (default 3) actions at once, on different tabs.
 *
 * A Set is enough rather than a refcount because lanes.js guarantees never two actions on
 * the SAME tab, so one tab cannot be in here twice.
 */
const dialogCommandTabs = new Set();   // tabId -> answering its own dialog

function dialogCommandActiveOn(tabId) {
  return dialogCommandTabs.has(Number(tabId));
}

function beginDialogCommand(tabId) {
  dialogCommandTabs.add(Number(tabId));
}

function endDialogCommand(tabId) {
  dialogCommandTabs.delete(Number(tabId));   // delete, never clear(): that is the bug above
}

const RECOVERY_COOLDOWN_MS = 8000;
const recoveryByTab = new Map();   // tabId -> {inflight: bool, until: ms, error: str}

function recoveryStateOf(tabId) {
  return recoveryByTab.get(tabId) || null;
}

function recoveryBusy(tabId) {
  const st = recoveryStateOf(tabId);
  if (!st) return false;
  return st.inflight || Date.now() < st.until;
}

function recoveryNote(tabId, patch) {
  const cur = recoveryStateOf(tabId) || { inflight: false, until: 0, error: '' };
  recoveryByTab.set(tabId, { ...cur, ...patch });
  // No size cap any more: the entry belongs to a TAB, and the per-tab lifecycle registry removes it
  // when that tab closes (see the registration above). The cap that used to live here - and whose
  // first version could not evict anything whenever the oldest key happened to be the tab being
  // updated - was a weaker answer to a question the lifecycle already answers.
}

/* Last-resort dialog recovery for the lanes that do not hold a debugger session.
 * Attach, answer per the caller's intent (or the panel policy), detach. It costs a
 * debugger attach on that one tab, which is the price of not leaving the page dead.
 * Called ONLY from inject() (contract_test.py enforces the single caller), so the
 * single-flight guard cannot be bypassed by a second caller. */
async function clearStuckDialog(tabId) {
  const target = { tabId };
  recoveryNote(tabId, { inflight: true });
  try {
    await chrome.debugger.attach(target, '1.3');
  } catch (e) {
    const why = 'debugger refused: ' + String((e && e.message) || e);
    recoveryNote(tabId, { inflight: false, until: Date.now() + RECOVERY_COOLDOWN_MS, error: why });
    return { ok: false, error: why };
  }
  try {
    const s = await getSettings();
    const policy = String(s.dialogPolicy || 'auto-dismiss');
    const intent = dialogIntentOf(tabId);
    // THE ANSWER ITSELF IS `lib/sentinel.js`'s `sentinelAnswerFor` (R29 batch 5): one rule, one
    // place. It used to be written out here as well, which made three copies of "the caller's intent
    // first, else the panel policy" (the dialog listener, the pre-existing-dialog probe, and this
    // recovery). `''` is THIS lane's own answer to "is there a defaultPrompt to forward": a recovery
    // has no dialog params to read one from, and an empty prompt is what it always sent.
    await chrome.debugger.sendCommand(target, 'Page.handleJavaScriptDialog',
                                       sentinelAnswerFor(intent, policy, ''));
    dialogLogFor(tabId).push({ type: 'recovered', message: '页面被原生弹窗冻住，桥代为应答（DOM 车道恢复路径）', defaultPrompt: '' });
    recoveryNote(tabId, { inflight: false, until: 0, error: '' });
    return { ok: true };
  } catch (e) {
    const why = String((e && e.message) || e);
    recoveryNote(tabId, { inflight: false, until: Date.now() + RECOVERY_COOLDOWN_MS, error: why });
    return { ok: false, error: why };
  } finally {
    try { await chrome.debugger.detach(target); } catch (e) {}
  }
}

