 * `reason` IS THE ANSWER, the wording is only how it reads (R32). Callers used to decide what an
 * outcome MEANT by matching regexes on these sentences - `/no dialog|not showing/i` - and a sentence
 * that says "no dialog event can arrive" (the sentinel's attach refusal) matches that regex while
 * meaning the opposite of "there is no dialog". Every return below therefore says which of the four
 * things happened, and the wording may change without silently changing a claimed fact.
 *
 * AND `not-showing` IS NOT "there is no dialog" (R32, measured): this function can only ever attach
 * AFTER the renderer froze, and Chrome answers `-32602 No dialog is showing` to such a session even
 * while a dialog is blocking the renderer (measured 2026-09-16 on /s13/double, and again 2026-10-12 on
 * an alert that no window ever displayed). That is the whole reason the sentinel exists (DEFECTS.md
 * P1-7), so the answer cannot also be the evidence that no dialog is there. */
async function clearStuckDialog(tabId) {
  const target = { tabId };
  recoveryNote(tabId, { inflight: true });
  try {
    await chrome.debugger.attach(target, '1.3');
  } catch (e) {
    const why = 'debugger refused: ' + String((e && e.message) || e);
    recoveryNote(tabId, { inflight: false, until: Date.now() + RECOVERY_COOLDOWN_MS, error: why });
    return { ok: false, reason: 'attach-refused', error: why };
  }
  try {
    const s = await getSettings();
    const policy = String(s.dialogPolicy || 'auto-dismiss');
    const intent = dialogIntentOf(tabId);
    // THE ANSWER ITSELF IS `lib/sentinel.js`'s `sentinelAnswerFor` (R29 batch 5): one rule, one
    // place. It used to be written out here as well, which made three copies of "the caller's intent
    // first, else the panel policy" (the dialog listener, the pre-existing-dialog probe, and this
    // recovery). `''` is THIS lane's own answer to "is there a defaultPrompt to forward": a recovery
    // has no dialog params to read one from, and an empty prompt is what it always sent.
    await chrome.debugger.sendCommand(target, 'Page.handleJavaScriptDialog',
                                       sentinelAnswerFor(intent, policy, ''));
    dialogLogFor(tabId).push({ type: 'recovered', message: '页面被原生弹窗冻住，桥代为应答（DOM 车道恢复路径）', defaultPrompt: '' });
    recoveryNote(tabId, { inflight: false, until: 0, error: '' });
    return { ok: true, reason: 'answered' };
  } catch (e) {
    const why = String((e && e.message) || e);
    recoveryNote(tabId, { inflight: false, until: Date.now() + RECOVERY_COOLDOWN_MS, error: why });
    // Chrome's own "nothing is showing" is its OWN case, not a proof of absence: the session this
    // function just attached is exactly the one that cannot see a dialog opened before it.
    const reason = /no dialog|not showing/i.test(why) ? 'not-showing' : 'answer-failed';
    return { ok: false, reason, error: why };
  } finally {
    try { await chrome.debugger.detach(target); } catch (e) {}
  }
}

