/* AuraBridge popup — 一句话说清状态，其余收进抽屉。(epsilonCk & Chaos)
 *
 * 2026-09-16 重排（用户要求"优化插件页面显示"；唯一不许动的是右下角的 ε 标记）。
 * 三条改动都对着同一个判据（AGENTS.md A.1.2：主产品是信任层，"agent 声称做成的事可被
 * 独立验证"）——用户看不见的事实，等于不存在：
 *   ① 权限条：只读/读写、站点策略、真实输入、暂停，这四件事决定了 agent 能做什么，
 *      原来全在折叠抽屉里，顶部只说"已连接"；
 *   ② 当前动作：原来只显示"忙碌 · 2 件"，现在说出**在跑什么**（`running` 由扩展在派发前
 *      记下名字，不是靠猜）；
 *   ③ Power mode 的可见代价（Chrome 的"正在调试"信息条）就地解释。
 */

/* DEFAULTS 是存储 schema。autoMaximize / tabGroup / tabGroupTitle 三个键必须在这里：
 * `chrome.storage.local.get(obj)` 只返回 obj 里列过的键，少了它们就读不到真实值，
 * 而 `s.tabGroup !== false` 于是永远为 true——用户关掉的开关一重开面板又显示成开着的。
 * 三个默认值与 lib/constants.js 的 BASE_DEFAULTS 一致（worker 用的是那一份）。 */
const DEFAULTS = { token: '', port: 8765, paused: false, mode: 'allow-all', allowlist: [], powerMode: true, access: 'readwrite', parallel: 3, pairCode: '', notify: true, autoMaximize: true, tabGroup: true, tabGroupTitle: 'AuraBridge' };

const $ = (id) => document.getElementById(id);

/* WHICH CODE THIS PANEL IS RUNNING IS A QUESTION THE PANEL CANNOT ANSWER - which is why the
 * "this panel is an older generation" comparison is not here any more (R5 单 T, T-2).
 *
 * It used to read `const CODE_FINGERPRINT = (typeof EXT_FINGERPRINT === 'string' ? EXT_FINGERPRINT : '')`
 * and compare it with the worker's `fingerprint` frame field. `EXT_FINGERPRINT` has exactly ONE
 * declaration (`lib/constants.js:20`) and `popup.html` does not load that file - its script list is
 * `popup.js` alone, and `importScripts('lib/constants.js', …)` belongs to the WORKER's scope. So the
 * constant was `''` on every real panel, and the branch guarding on it could never fire: a panel with
 * no way to know its own generation was comparing against a value it had invented. Nothing stamps it
 * into this file either - `bridge/ext_fingerprint.py` writes `lib/constants.js` only.
 *
 * DELETING IT IS NOT SILENCE, IT IS THE HONEST HALF: a panel that cannot know must not guess (A.3.4),
 * and the half that CAN be answered - "the browser runs different code than the files on disk", which
 * only the daemon can know and publishes as `code_fingerprint` - is right below and still speaks.
 * `tests/type_connected_test.py` derives this from the real script graph instead of trusting a
 * comment, and fails the day `popup.html` loads the stamped constants file, naming the branch to
 * put back. (That harness used to hand this script its OWN `EXT_FINGERPRINT`, which is exactly why
 * the dead half read as covered.)
 */

/* IS THE CODE BEHIND THIS PANEL THE CODE THAT IS ACTUALLY RUNNING?
 * The worker reports a fingerprint that is not what is on disk (`code_fingerprint`, which only the
 * daemon can know - it is the side that reads the files) -> the browser is running old code.
 * An unknown value says nothing rather than guessing (A.3.4). */
function codeFingerprintGap(status) {
  if (!status) return '';
  const running = String(status.fingerprint || '');
  const stamped = String(status.code_fingerprint || '');
  if (running && stamped && running !== stamped) {
    // TWO SOURCES, TWO REMEDIES (R7-20): the extension folder the user installed (`install` reloads it
    // in place) and the COPY `setup --auto` stages in the state dir for its dedicated browser
    // (`bridge/setup_wizard.py:605,636` - `install` rewrites a folder that browser never loads), which
    // is stale on purpose and needs nothing.
    //
    // THE ANSWER A PERSON NEEDS IS TWO QUESTIONS LONG (R7c-11): "does it still work" and "do I have
    // to do something now". The sentence this replaces opened with `浏览器跑的不是磁盘上的代码
    // （扩展 … / 磁盘 …）` and named four concepts plus two hex fingerprints. It shows up during an
    // ORDINARY upgrade - the files are swapped first and the extension reloads second, so between the
    // two the condition is true while nothing is wrong - and it never said whether anything was
    // broken, so a person who had just pressed "upgrade" read it as "the upgrade broke it".
    // NEITHER hex value goes in the sentence: a build id is not something its reader can use, and the
    // version line right above already carries the one build token this panel does show. `running`
    // still decides WHETHER this branch fires - it is the comparison, not the copy.
    return '浏览器里跑的扩展是之前那一版。现在还照常用，智能体的事不受影响；'
      + '只是新的修改还没生效——重载一次扩展就换过来了（就是安装时那个文件夹）。'
      + '如果那是 `python bridge.py setup --auto` 起的专用浏览器（它加载的是暂存副本），不用管它。';
  }
  return '';
}

/* 状态字变了才闪一下（首帧文字没变，所以首帧不动画）；
 * halo 只在上线/忙碌时带上 .live——呼吸是「它活着」这个状态的表现，不是一个开场动画。 */
function say(state, ok, busy) {
  const el = $('state');
  const changed = el.textContent !== state && el.textContent !== '';
  el.textContent = state;
  if (changed) {
    // 同一个动画要重放，只能「摘掉 → 读一次布局 → 挂上」；读的是这一个 14px 元素
    el.classList.remove('flash');
    void el.offsetWidth;
    el.classList.add('flash');
  }
  $('dot').className = 'dot' + (busy ? ' busy' : ok === true ? ' ok' : ok === false ? ' bad' : '');
  const halo = $('dot').parentElement;
  if (halo) halo.className = 'halo' + (busy ? ' busy' : '') + (busy || ok === true ? ' live' : '');
}

/* 权限条：四个决定"agent 能做什么"的事实，永远在第一屏，也是"现在是什么模式"的答案。
 * 颜色只说两件事：强调色=这个方向是打开的，红=真的有东西被挡住（暂停、窗口不在最前）。
 * 其余靠字说——一屏只有一个强调色（Aura 系列）。 */
function renderCaps(status, s) {
  const el = $('caps');
  if (!el) return;
  el.innerHTML = '';
  // 每一维先说名字再说值（"权限 读写" 而不是光一个 "读写"）：两个裸值并排时，
  // 读的人得自己猜哪个是权限、哪个是站点
  const add = (dim, text, cls) => {
    const span = document.createElement('span');
    span.className = 'cap' + (cls ? ' ' + cls : '');
    const label = document.createElement('span');
    label.className = 'dim';
    label.textContent = dim;
    span.append(label, document.createTextNode(text));
    el.appendChild(span);
  };
  if (s.paused) add('状态', '已暂停 · 拒绝一切操作', 'stop');
  add('权限', s.access === 'readonly' ? '只读 · 仅观察' : '读写 · 可操作页面',
      s.access === 'readonly' ? '' : 'strong');
  add('站点', s.mode === 'allowlist' ? `仅白名单 · ${(s.allowlist || []).length} 项` : '全部站点',
      s.mode === 'allowlist' ? 'strong' : 'caution');
  // 开着和关着都说：四个模式里，「没写」不能是用户唯一能拿到的答案
  const power = status ? !!status.powerMode : s.powerMode !== false;
  add('输入', power ? '真实鼠标键盘（Power）' : '只做页面内操作（Power 关）', power ? 'strong' : '');
  add('分组', s.tabGroup !== false ? '智能体标签进组' : '不标记标签页',
      s.tabGroup !== false ? 'strong' : '');
  if (status && status.connected && status.window && status.window.focused === false) {
    add('注意', '窗口不在最前 · 真实输入会被丢弃', 'stop');
  }
  if (status && status.agentTabId != null) add('工作标签', `#${status.agentTabId}`);
  // 代价跟着开关走，而不是只在抽屉里等着被发现
  const costPower = $('costPower');
  if (costPower) costPower.hidden = !power;
  const costFocus = $('costFocus');
  if (costFocus) costFocus.hidden = s.autoMaximize === false;
}

/* "在跑什么"。running 是扩展在派发**之前**记下的名字（不是事后猜的），所以这一行
 * 在命令还在飞的时候就是对的；跑完后退回"最近一次"。 */
function renderNow(status) {
  const el = $('now');
  if (!el) return;
  el.innerHTML = '';
  if (!status) return;
  const running = Array.isArray(status.running) ? status.running : [];
  if (running.length) {
    const head = document.createElement('span');
    head.className = 'pulse';
    head.textContent = '正在执行：';
    el.appendChild(head);
    running.slice(0, 3).forEach((r, i) => {
      if (i) el.appendChild(document.createTextNode('、'));
      const b = document.createElement('b');
      b.textContent = String(r.action || '').replace(/^aura_/, '');
      el.appendChild(b);
      el.appendChild(document.createTextNode(`（${r.caller || 'agent'} · ${r.ageS}s）`));
    });
    if (running.length > 3) el.appendChild(document.createTextNode(` 等 ${running.length} 件`));
    return;
  }
  const last = status.lastAction;
  if (last && last.action) {
    const ago = last.ageS <= 2 ? '刚刚' : last.ageS < 60 ? `${last.ageS} 秒前` : `${Math.round(last.ageS / 60)} 分钟前`;
    const b = document.createElement('b');
    b.textContent = String(last.action).replace(/^aura_/, '');
    el.appendChild(document.createTextNode('最近一次：'));
    el.appendChild(b);
    el.appendChild(document.createTextNode(` · ${ago}${last.ok === false ? ' · 未成功' : ''}`));
  }
}

