  const accNote = $('accessNote');
  if (accNote) {
    // 原来的读写说明让人去 `bridge.py status` 看动作日志，而它并不打印动作（审计 §4）。
    // 真的能看的东西有两个：面板顶部这一行（实时），和一次录制成文后的交付文件夹。
    const note = status.access === 'readonly'
      ? '只读：智能体只能看。读页面、截图、读结构都可以。点、输入、导航、提交一律被拒，并说明原因。'
      : '读写：智能体可以点击、输入、导航、提交表单。它此刻在做什么，面板顶部实时显示。要一份能留存的记录，让智能体开一次录制（aura_record_start），再用 aura_report 成文。';
    if (accNote.textContent !== note) accNote.textContent = note;
