/* 只读回执的一个子集：顶上那几个字、pill、错误行、抽屉里的读数。
 *
 * R33 把它们从 `renderStatus` 里拆出来，因为面板开着的时候**只有它们会变**：原来的 1 Hz
 * 轮询只重画「在跑什么」，于是状态字和 pill 会一直停在打开面板那一刻（agent 已经忙起来了，
 * 面板还说「已连接」）。它们不含任何设置驱动的 DOM（权限条/白名单那两块留在完整渲染里）。
 * 出参：这一轮真的改了页面上的字没有——轮询拿它算降档。 */
function renderVitals(status, s) {
  let changed = false;
  const setText = (el, text) => { if (el && el.textContent !== text) { el.textContent = text; changed = true; } };
  if (!status) {
    changed = say('扩展未响应', false) || changed;
    setText($('next'), '点「刷新状态」再试一次。');
    return changed;
  }
  const inflight = Number(status.inflight || 0) + Number(status.queued || 0);
  if (s.paused) {
    changed = say('已暂停', false) || changed;
  } else if (!status.connected) {
    changed = say('未连接', false) || changed;
  } else if (inflight > 0) {
    changed = say(`忙碌 · ${inflight} 件`, true, true) || changed;
  } else {
    changed = say('已连接', true) || changed;
  }
  /* 「下一步点哪里」：只有真的要人动手时才有字。连上了就安静——面板话越少，它说话时越有人听。 */
  const next = $('next');
  if (next) {
    if (s.paused) setText(next, '智能体的动作现在全部被拒。取消勾选下面的「暂停」就恢复。');
    else if (!status.connected) setText(next, '没连上本机服务。下一步：在终端里跑 python bridge.py serve，再点「连接 / 重新配对」。');
    else setText(next, codeFingerprintGap(status));
  }
  // 运行时读数搬进抽屉（标题下面那行会换行，而且它不属于"状态"）
  const bits = [`运行于 ${status.browser || '?'}`, `端口 ${s.port}`];
  if (status.mode === 'allowlist') bits.push(`白名单 ${status.allowlistCount} 项`);
  // never overwrite #meta wholesale: textContent= destroys the nested #ver span,
  // and the next load() then dies on $('ver') being null (measured live)
  setText($('ver'), status.version || '?');
  setText($('metabits'), bits.length ? bits.join(' · ') : '');
  // the pill is the toolbar badge, in words - same `status.badge.state` the worker uses
  const pill = $('badge');
  if (pill) {
    const st = (status.badge && status.badge.state) || (status.connected ? 'connected' : 'offline');
    const words = { paused: '已暂停', running: '执行中', readonly: '只读', connected: '空闲', offline: '未连接' };
    const cls = 'pill' + (st === 'paused' ? ' stop' : st === 'running' ? ' busy' : st === 'connected' ? ' ok' : '');
    if (pill.textContent !== (words[st] || st)) { pill.textContent = words[st] || st; changed = true; }
    if (pill.className !== cls) { pill.className = cls; changed = true; }
  }
  // 这一行是扩展自己报的错，原文一句人话都没有的时候至少要说清它是什么
  setText($('err'), status.lastError ? '出错原因：' + status.lastError : '');
}
  /* 「下一步点哪里」：只有真的要人动手时才有字。连上了就安静——面板话越少，它说话时越有人听。 */
  const next = $('next');
  if (next) {
    if (s.paused) next.textContent = '智能体的动作现在全部被拒。取消勾选下面的「暂停」就恢复。';
    else if (!status.connected) next.textContent = '没连上本机服务。下一步：在终端里跑 python bridge.py serve，再点「连接 / 重新配对」。';
    else next.textContent = codeFingerprintGap(status);
  }
  // 运行时读数搬进抽屉（标题下面那行会换行，而且它不属于"状态"）
  const bits = [`运行于 ${status.browser || '?'}`, `端口 ${s.port}`];
  if (status.mode === 'allowlist') bits.push(`白名单 ${status.allowlistCount} 项`);
  // never overwrite #meta wholesale: textContent= destroys the nested #ver span,
  // and the next load() then dies on $('ver') being null (measured live)
  const verEl = $('ver');
  if (verEl) verEl.textContent = status.version || '?';
  const bitsEl = $('metabits');
  if (bitsEl) bitsEl.textContent = bits.length ? bits.join(' · ') : '';
  // the pill is the toolbar badge, in words - same `status.badge.state` the worker uses
  const pill = $('badge');
  if (pill) {
    const st = (status.badge && status.badge.state) || (status.connected ? 'connected' : 'offline');
    const words = { paused: '已暂停', running: '执行中', readonly: '只读', connected: '空闲', offline: '未连接' };
    pill.textContent = words[st] || st;
    pill.className = 'pill' + (st === 'paused' ? ' stop' : st === 'running' ? ' busy' : st === 'connected' ? ' ok' : '');
  }
  // 这一行是扩展自己报的错，原文一句人话都没有的时候至少要说清它是什么
  $('err').textContent = status.lastError ? '出错原因：' + status.lastError : '';
  renderCaps(status, s);
}

