 *   • 单飞：上一条还没回来就不再发下一条。旧的 `setInterval` 不管有没有在飞，worker 一忙
 *     就会把消息堆起来，堆到后面每一条都只读到旧状态；
 *   • 两档：连着 `POLL_IDLE_ROUNDS` 轮什么都没变就降到 5 秒，一变立刻回 1 秒；
 *   • 看不见就慢档：`document.hidden` 的面板不值得每秒重画。
 * 改前量的（空闲 6 秒）：6 条消息 / 24 次 DOM 变更，而其中绝大多数字节和上一轮一样。 */
const POLL_FAST_MS = 1000;
const POLL_SLOW_MS = 5000;
const POLL_IDLE_ROUNDS = 3;
function pollDelayMs(idleRounds, inflight, hidden) {
  if (hidden) return POLL_SLOW_MS;
  if (inflight > 0) return POLL_FAST_MS;   // 还在飞：不加速，但也不堆第二条（调度器不会再发）
  return idleRounds >= POLL_IDLE_ROUNDS ? POLL_SLOW_MS : POLL_FAST_MS;
}
let ticker = null;
let pollIdle = 0;
let pollInFlight = false;
function startTicker() {
  if (ticker !== null) return;
  ticker = 0;
  schedulePoll(0);
}
function schedulePoll(delayMs) {
  if (ticker === null) return;
  ticker = setTimeout(async () => {
    if (pollInFlight) { schedulePoll(POLL_FAST_MS); return; }
    pollInFlight = true;
    let st = null;
    try { st = await chrome.runtime.sendMessage({ type: 'aura-status' }); } catch (e) { st = null; }
    pollInFlight = false;
    // 只有"真的改了页面"才算有事发生，没连上/没回答都不能把降档卡在快档上
    const changed = st ? refreshFrom(st) : false;
    pollIdle = changed ? 0 : pollIdle + 1;
    schedulePoll(pollDelayMs(pollIdle, 0, document.hidden === true));
  }, delayMs);
}
/* 出参：这一轮真的有东西变了吗（降档靠它，不靠猜）。 */
