source.text:
 * "改动前"的行为 = 每次调用都落在一个**空缓存**的引擎实例上。ESM 的模块表按完整 URL 索引，
 * 因此 `import('./struct-core.mjs?fresh=N')` 拿到的是一个缓存必然为空的新实例——段C 拿它当
 * 基线做全量深比较，段D 拿它量"改前等价"的每次代价。段C 会先证明这个基线真的无缓存
 * （新实例连调两次，载荷不同一）。
 *
 * ## 判据（段）
 *
 *   A  同一内容调 `indexStructure` 100 次 ⇒ 底层解析只发生 1 次（载荷身份 + CPU 时间）
 *   A2 同上，对 `indexFile`
 *   B  内容改一个字节（**等长**）⇒ 必须重新解析，且索引如实反映新内容
 *   B2 同上，对 `indexFile`
 *   C  有缓存 / 无缓存两条路径的返回值**逐字段深比较**（符号、token、配平表、逐偏移 lineAt、
 *      逐行 bigram、倒排桶……全量，不是抽样）


















































































































































































































































// ── 段D：命中率读数 + 真实大文件 100 次耗时 ────────────────────────────────
say('')
say('=== 段D. 命中率读数 + 真实大文件连续 100 次的耗时（改前等价 vs 改后实测）===')
{
  // D1 命中率：在空缓存实例上跑一段脚本化序列，用载荷身份数命中/未命中
  const mod = await freshModule('struct-core.mjs')
  const modLang = mod.langOf(BIG_FILE)
  const stat = { hit: 0, miss: 0 }
  const seen = new Map()
  const call = (content) => {
    const idx = mod.indexStructure(content, modLang)
    const payload = structPayload(idx)
    const prev = seen.get(content)
    if (prev !== undefined && samePayload(prev, payload)) stat.hit += 1
    else {
      stat.miss += 1
      seen.set(content, payload)
    }
    return idx
  }
  const A = SRC
  const B = `${SRC}\n// 末尾多一行\n`
  for (let i = 0; i < 40; i += 1) call(A)
  for (let i = 0; i < 10; i += 1) call(B)
  for (let i = 0; i < 20; i += 1) call(i % 2 === 0 ? A : B)
  const total = stat.hit + stat.miss
  say(`  序列：A×40 + B×10 + 交错 A/B×20 = ${total} 次调用，A 与 B 是两份不同内容`)
  say(`  命中率读数：命中 ${stat.hit} / ${total} = ${((100 * stat.hit) / total).toFixed(1)}%，未命中 ${stat.miss} 次（两份内容各第一次）`)
  check(stat.miss === 2, '未命中恰好 2 次（A、B 各一次），其余全部命中', `miss=${stat.miss}`)

  // D2 耗时：改前等价 = 每次调用落在一个空缓存实例（=改动前的每次重建）
  say(`  文件 ${BIG_NAME}：${SRC.length} B / ${SRC.split('\n').length} 行（本仓最大的引擎文件）`)
  const COLD = 8
  let coldTotal = 0
  for (let i = 0; i < COLD; i += 1) {
    const m = await freshModule('struct-core.mjs')
    const l = m.langOf(BIG_FILE)
    coldTotal += timeIt(() => m.indexStructure(SRC, l)).ms
  }
  const coldPer = coldTotal / COLD
  const warmMod = await freshModule('struct-core.mjs')
  const warmLang = warmMod.langOf(BIG_FILE)
  warmMod.indexStructure(SRC, warmLang) // 第一次必然是未命中（冷解析），不计入
  for (let i = 0; i < 10; i += 1) call(B)
  for (let i = 0; i < 20; i += 1) call(i % 2 === 0 ? A : B)
  const total = stat.hit + stat.miss
  say(`  序列：A×40 + B×10 + 交错 A/B×20 = ${total} 次调用，A 与 B 是两份不同内容`)
  say(`  命中率读数：命中 ${stat.hit} / ${total} = ${((100 * stat.hit) / total).toFixed(1)}%，未命中 ${stat.miss} 次（两份内容各第一次）`)
  check(stat.miss === 2, '未命中恰好 2 次（A、B 各一次），其余全部命中', `miss=${stat.miss}`)

  // D2 耗时。三条读数都在**同一份已热**的模块上量（见文件头）：
  //   · 未命中（真解析 + 入缓存）≈ 改动前同一份内容**每一次**调用的代价（改动前没有缓存，
  //     第 100 次与第 1 次同价）；
  //   · 命中（同一字符串对象）= 复核用下限；
  //   · 命中（每次都是新字符串、内容相同）= **真实调用方的形态**（每次都 readFileSync ⇒ 新字符串，
  //     命中代价里含字符串哈希与比对）。
  const MISS_N = 8
  const variants = Array.from({ length: MISS_N }, (_, i) => `${SRC}${'\n'.repeat(i + 1)}`)
  say(`  文件 ${BIG_NAME}：${SRC.length} B / ${SRC.split('\n').length} 行（本仓最大的引擎文件）`)

  const sMod = await freshModule('struct-core.mjs')
  const sLang = sMod.langOf(BIG_FILE)
  sMod.indexStructure(SRC, sLang) // 预热：下面的读数都不含首次解析
  const sMiss = timeIt(() => {
    for (const v of variants) sMod.indexStructure(v, sLang)
  }).ms / MISS_N
  const sHit = timeIt(() => {
    for (let i = 0; i < 100; i += 1) sMod.indexStructure(SRC, sLang)
  }).ms / 100
  const strs = Array.from({ length: 100 }, () => Buffer.from(SRC, 'utf8').toString('utf8'))
  const sHitFresh = timeIt(() => {
    for (const c of strs) sMod.indexStructure(c, sLang)
  }).ms / 100
  say(`  indexStructure：未命中（真解析 + 入缓存，≈ 改动前每次的代价）${sMiss.toFixed(1)} ms/次`)
  say(
    `                  命中（同一字符串对象）${(sHit * 1000).toFixed(1)} µs/次｜命中（每次新字符串，真实形态）${(sHitFresh * 1000).toFixed(1)} µs/次 ⇒ 真实形态 ${(sMiss / Math.max(sHitFresh, 1e-6)).toFixed(0)}x`,
  )
  check(sHitFresh * 10 < sMiss, 'indexStructure：真实形态的命中比未命中快一个数量级以上', `${(sHitFresh * 1000).toFixed(1)}µs vs ${sMiss.toFixed(1)}ms`)

  const fMod = await freshModule('anchor-core.mjs')
  fMod.indexFile(SRC) // 预热
  const fMiss = timeIt(() => {
    for (const v of variants) fMod.indexFile(v)
  }).ms / MISS_N
  const fHit = timeIt(() => {
    for (let i = 0; i < 100; i += 1) fMod.indexFile(SRC)
  }).ms / 100
  const fHitFresh = timeIt(() => {
    for (const c of strs) fMod.indexFile(c)
  }).ms / 100
  say(`  indexFile     ：未命中（真重建 + 入缓存，≈ 改动前每次的代价）${fMiss.toFixed(1)} ms/次`)
  say(
    `                  命中（同一字符串对象）${(fHit * 1000).toFixed(1)} µs/次｜命中（每次新字符串，真实形态）${(fHitFresh * 1000).toFixed(1)} µs/次 ⇒ 真实形态 ${(fMiss / Math.max(fHitFresh, 1e-6)).toFixed(0)}x`,
  )
  check(fHitFresh * 10 < fMiss, 'indexFile：真实形态的命中比未命中快一个数量级以上', `${(fHitFresh * 1000).toFixed(1)}µs vs ${fMiss.toFixed(1)}ms`)

  // 端到端：用户真正关心的那条路（locateAnchor 内部就是 indexFile + 匹配）
  const anchor = 'export function resolveTarget(index, target, near = null) {'
  const aMod = await freshModule('anchor-core.mjs')
  aMod.locateAnchor(SRC, anchor)
  const aMiss = timeIt(() => {
    for (const v of variants) aMod.locateAnchor(v, anchor)
  }).ms / MISS_N
  const aHit = timeIt(() => {
    for (let i = 0; i < 100; i += 1) aMod.locateAnchor(SRC, anchor)
  }).ms / 100
  const aHitFresh = timeIt(() => {
    for (const c of strs) aMod.locateAnchor(c, anchor)
  }).ms / 100
  say(`  locateAnchor  ：未命中（每次现建索引）${aMiss.toFixed(1)} ms/次｜命中 ${(aHit * 1000).toFixed(0)} µs/次｜命中（新字符串）${(aHitFresh * 1000).toFixed(0)} µs/次`)
  check(aHitFresh * 10 < aMiss, 'locateAnchor：真实形态的命中比未命中快一个数量级以上', `${(aHitFresh * 1000).toFixed(0)}µs vs ${aMiss.toFixed(1)}ms`)
}

// ── 段E：负向不变量 ────────────────────────────────────────────────────────
say('')
say('=== 段E. 负向不变量：缓存不得让"改动后的内容"拿到旧索引 ===')

