function emptyTally() {
  return {
    entries: 0,
    replayable: 0,
    drifted: 0,
    sourceMix: { log: 0, receipt: 0, disk: 0 },
    exact: 0,
    old: { ok: 0, fail: 0, needsChoice: 0, na: 0 },
