          ? replayNew(entry, content, copyPath, evidenceText)
          : { outcome: OUTCOME.unrepresentable, detail: '无实证原文' }
      }
      bump(tally.evidenceNeu, evRes.outcome)

      if (details.length < (options.show ?? 0)) {
        details.push({
          id: entry.id,
          klass: entry.klass,
          file: entry.file,
          source: `${entry.source.kind}/${entry.source.fidelity}`,
