          neu: `${neuRes.outcome}${neuRes.detail ? ` (${neuRes.detail})` : ''}`,
          evidenceNeu: `${evRes.outcome}${evRes.detail ? ` (${evRes.detail})` : ''}`,
          receipt: entry.receiptFirstLine,
